window.BIZ_PAPERS = [{"id":"U3-1706","unit":3,"key":"2017-06","series":"June 2017","date":"Thursday 25 May 2017","title":"Nikolina · Nitin · Daniel · Max","source":"pearson","kind":"exam","total":100,"parsedTotal":100,"sec":{"A":36,"B":64},"items":[{"q":1,"sub":null,"marks":2,"section":"A","ctx":["Centre Number Learner Registration Number","Write your name here","Surname Other names","Total Marks","Paper Reference","Thursday 25 May 2017 – Afternoon","Time: 2 hours","You must have:","Calculator","Pearson BTEC","Level 3 Nationals","Extended","Certificate","31463H","Business / Enterprise and Entrepreneurship","Unit 3: Personal and Business Finance","Instructions","• Use black ink or ball-point pen.","• Fill in the boxes at the top of this page with your name,","centre number and learner registration number.","• Answer all questions.","• Answer the questions in the spaces provided","– there may be more space than you need.","• Show your working when requested.","Information","• The total mark for this paper is 100.","• The marks for each question are shown in brackets","– use this as a guide as to how much time to spend on each question.","• There are two sections: Section A Personal Finance and Section B","Business Finance.","Advice","• Read each question carefully before you start to answer it.","• Try to answer every question.","• Check your calculations and the steps you have used.","• Check your answers if you have time at the end.","Section A – Personal Finance","Many people have a bank account. The way in which customers are in contact with","banks has changed significantly over time."],"ctxb":[{"t":"flow","x":["Centre Number Learner Registration Number","Write your name here","Surname Other names","Total Marks","Paper Reference","Thursday 25 May 2017 – Afternoon","Time: 2 hours","You must have:","Calculator","Pearson BTEC","Level 3 Nationals","Extended","Certificate","31463H","Business / Enterprise and Entrepreneurship","Unit 3: Personal and Business Finance","Instructions"]},{"t":"p","x":"• Use black ink or ball-point pen. • Fill in the boxes at the top of this page with your name, centre number and learner registration number. • Answer all questions. • Answer the questions in the spaces provided – there may be more space than you need. • Show your working when requested. Information • The total mark for this paper is 100. • The marks for each question are shown in brackets – use this as a guide as to how much time to spend on each question. • There are two sections: Section A Personal Finance and Section B Business Finance. Advice • Read each question carefully before you start to answer it. • Try to answer every question. • Check your calculations and the steps you have used. • Check your answers if you have time at the end. Section A – Personal Finance Many people have a bank account. The way in which customers are in contact with banks has changed significantly over time."}],"text":"Give two ways that customers can contact and interact with their bank.","qTotal":2,"ms":{"body":"Award one mark for any of the following up to a\nmaximum of two marks:\nFace to face/branch (1) online chat (1) online forum (1)\ntelephone (1) mobile app (1) postal (1) email (1)\nDo not accept online with online chat/online forum as two\nvalid items.\nAccept any other appropriate response.\n2","levels":null}},{"q":2,"sub":null,"marks":2,"section":"A","ctx":[],"ctxb":[],"text":"Identify two sources of advice and guidance about personal finance.","qTotal":2,"ms":{"body":"Award one mark for any of the following up to a\nmaximum of two marks:\nCitizens Advice (1) independent financial advisers (IFA)\n(1) Money Advice Service (1) comparison websites (1)\ndebt counsellors (1) websites e.g. ‘MoneySavingExpert.com’ (1)\nbanks (1) building societies (1) accountants (1) Financial\nOmbudsmen Service (FOS) (1)\n2","levels":null}},{"q":3,"sub":null,"marks":4,"section":"A","ctx":[],"ctxb":[],"text":"Outline two benefits of planning financial expenditure.","qTotal":4},{"q":4,"sub":null,"marks":6,"section":"A","ctx":["Nikolina has just passed her driving test. Her parents have bought her a car for £2 000","as an 18th birthday present. She now needs to purchase car insurance.","Nikolina has been advised that different types of car insurance can be purchased."],"ctxb":[{"t":"p","x":"Nikolina has just passed her driving test. Her parents have bought her a car for £2 000 as an 18th birthday present. She now needs to purchase car insurance. Nikolina has been advised that different types of car insurance can be purchased."}],"text":"Discuss which type of car insurance would be best for Nikolina.","qTotal":6},{"q":5,"sub":null,"marks":10,"section":"A","ctx":["Nitin is 38 years old and has recently been made redundant. He has received a","redundancy payment of £20 000. He wants to save or invest this money for his","future. He is considering either putting the money into a savings account or","investing in shares."],"ctxb":[{"t":"p","x":"Nitin is 38 years old and has recently been made redundant. He has received a redundancy payment of £20 000. He wants to save or invest this money for his future. He is considering either putting the money into a savings account or investing in shares."}],"text":"Assess which of these two options is more suitable for Nitin.","qTotal":10,"ms":{"body":"Indicative content could include:\nSavings\n• Typically for short-term goals – often three years or\nless\n• Can be for emergency or ‘rainy day’\n• Money can usually be accessed easily but affects\nthe interest rate and return\n• Some accounts limit the number of times you can\naccess money or notice period to increase the\ninterest rate and return\n• Could save money in an ISA tax free, which\nincreases return\n• Risk free as sums up to £75 000 are covered by FSA\ndeposit limit guarantee\nShares\n• Typically for more long-term goals – four years or\nmore\n• Not easy to access money if it is invested – might\nhave to sell the shares and could lose money\n• Investments always involve risk – you could lose all\nof your investment\n• Share prices can go up or down\n• Rewards are greater than returns on savings\nbecause of the risk\n• Could receive dividend on each share\n• Dividends may not be paid depending on the\ndiscretion of the company\n10","levels":10}},{"q":6,"sub":null,"marks":12,"section":"A","ctx":["Daniel is married with a young family. He is a homeowner with a mortgage and","has two personal loans and outstanding balances on three credit cards. One of the","personal loans is secured on his house. His personal circumstances have changed","since he took on these debts.","He now earns significantly less than he did and he can no longer afford the debt","repayments. As a result, he is in arrears on all of his debts. He has been served with","default notices demanding repayment in full. Daniel has been advised to either apply","for an IVA (Individual Voluntary Arrangement) or to apply for bankruptcy."],"ctxb":[{"t":"p","x":"Daniel is married with a young family. He is a homeowner with a mortgage and has two personal loans and outstanding balances on three credit cards. One of the personal loans is secured on his house. His personal circumstances have changed since he took on these debts. He now earns significantly less than he did and he can no longer afford the debt repayments. As a result, he is in arrears on all of his debts. He has been served with default notices demanding repayment in full. Daniel has been advised to either apply for an IVA (Individual Voluntary Arrangement) or to apply for bankruptcy."}],"text":"Evaluate whether Daniel should apply for an IVA or apply for bankruptcy.","qTotal":12,"ms":{"body":"Indicative content could include:\nIVA Advantages\n• Debts are frozen, you sign up to a financial plan for\nfive to six years and know at the end of it you’ll be\ndebt free\n• A monthly repayment is agreed depending\non circumstances (usually at least £200)\n• After 5-6 years the rest of the debt is written off\n• After the IVA has ended, the restrictions are less\nsevere than they are for someone who has been\nbankrupt\n• You are likely to keep your house and other assets,\nsuch as your car.\nIVA Disadvantages\n• As a form of insolvency an IVA is still publicly\nrecorded on the Insolvency Register\n• IVAs can last up to six years, three years longer\nthan most bankruptcies\n• Your spending will be restricted while the IVA is\nactive\n• High costs in setting up an IVA\n• Your credit history will be affected for six years\n• Could still lead to bankruptcy\n• Doesn’t cover secured debt\n12\n• Could be forced to remortgage to free up equity and\nsell high value assets such as cars.\nBankruptcy Advantages\n• It is often the quickest way to get debt free\n• There is a cost involved but this is significantly\nless than IVA\n• It is possible to be discharged from bankruptcy\nafter 12 months\n• If your property is in negative equity you may\nbe\nable to retain it\n• Bankruptcy advice is free if you get it from\nthe\nCitizens Advice Bureau\n• You do not need creditor approval to go bankrupt.\nBankruptcy Disadvantages\n• It is recorded publicly on the Insolvency Register\n• Your bank account will be frozen for a period of time\n• You hand control of your finances over to an\nofficial receiver\n• You could lose your assets, such as your house\n• Certain job roles will be affected, e.g.\naccountants\nand solicitors\n• Your credit history will be affected for six years\n• Secured debts can be included.","levels":12}},{"q":7,"sub":null,"marks":2,"section":"A","ctx":["Section B – Business Finance","Max has been running his party planning business, To the Max, for a year now. He","plans birthday parties and small business events. He has built a good reputation and","has a growing number of customers. He is trying to expand his business by breaking","into the wedding planning market although he knows this is very competitive.","Max knows he is not good at finance and he has asked you to give him some advice","and guidance.","Businesses such as To the Max face many different costs and payments."],"ctxb":[{"t":"p","x":"Section B – Business Finance Max has been running his party planning business, To the Max, for a year now. He plans birthday parties and small business events. He has built a good reputation and has a growing number of customers. He is trying to expand his business by breaking into the wedding planning market although he knows this is very competitive. Max knows he is not good at finance and he has asked you to give him some advice and guidance. Businesses such as To the Max face many different costs and payments."}],"text":"Outline what a ‘semi-variable cost’ is.","qTotal":2,"ms":{"body":"Award one mark for any identification or definition of semi-\nvariable cost and a further mark for development/appropriate\nexample up to a maximum of two marks.\nCosts that are composed of a mixture of fixed (1) and\nvariable (1) components\nCosts such as electricity have a standing charge (1) and a\ncharge per unit used (1)\nAccept any other appropriate response.\n2","levels":null}},{"q":8,"sub":null,"marks":2,"section":"A","ctx":[],"ctxb":[],"text":"Outline what is meant by the term ‘drawings’ in a financial document.","qTotal":2,"ms":{"body":"Award one mark for any of the following up to a maximum\nof two marks:\nDrawings are assets/money which are taken out (1) of a\ncompany by its owners/ for personal use (1)\nAccept any other appropriate response.\n2","levels":null}},{"q":9,"sub":"i","marks":2,"section":"A","ctx":[],"ctxb":[],"text":"the contribution per unit","qTotal":8},{"q":9,"sub":"ii","marks":3,"section":"A","ctx":["£"],"ctxb":[],"text":"the total costs","qTotal":8},{"q":9,"sub":"b","marks":3,"section":"A","ctx":["£"],"ctxb":[],"text":"Complete the break-even graph below by plotting and labelling: • total revenue • total cost • break-even point. Refer to Figure 1 for additional information.","qTotal":8,"ms":{"body":"Correctly plot and label TR 0 – 84 000 (1 mark)\nCorrectly plot and label TC from the fixed cost line to the\ntotal cost calculated in question 9a(ii) (OFR) (1 mark)\nIf both correctly plotted but not labelled then 1 mark\nmaximum.\nCorrectly identify BE point (1 mark)\nAccept alternative wording in labels, e.g. total\nrevenue, sales, revenue, sales revenue, total costs.\n3","levels":null}},{"q":10,"sub":"a","marks":4,"section":"A","ctx":["0 40 80 120 160 200 240 280","90 000","80 000","70 000","60 000","50 000","40 000","30 000","20 000","10 000","0","No. of events","Costs","and","revenues","(£)","Fixed costs","11","Max has given you the following additional financial information.","Second extract of financial information for To the Max","Cash sales £65 303","Credit sales £13 609","Wages and salaries £19 500","Cash purchases £286","Credit purchases £10 080","Rent and business rates £25 600","Utilities £6 200","Other costs £4 580","Trade receivables £1 400","Closing inventories £712","Opening inventories £0","Trade payables £472","Figure 2"],"ctxb":[{"t":"flow","x":["0 40 80 120 160 200 240 280","90 000","80 000","70 000","60 000","50 000","40 000","30 000","20 000","10 000","0","No. of events","Costs","and","revenues","Fixed costs","11"]},{"t":"p","x":"Max has given you the following additional financial information."},{"t":"cap","x":"Second extract of financial information for To the Max"},{"t":"cap","x":"Second extract of financial information for To the Max"},{"t":"grid","head":null,"rows":[["Cash sales","£65 303"],["Credit sales","£13 609"],["Wages and salaries","£19 500"],["Cash purchases","£286"],["Credit purchases","£10 080"],["Rent and business rates","£25 600"],["Utilities","£6 200"],["Other costs","£4 580"],["Trade receivables","£1 400"],["Closing inventories","£712"],["Opening inventories","£0"],["Trade payables","£472"],["Figure","2"]]}],"text":"Calculate the gross profit of To the Max using the information given in Figure 2.","qTotal":16},{"q":10,"sub":"b","marks":8,"section":"A","ctx":["£","Max has produced an outline statement of financial position for the year up to","31 December 2016 but it is incomplete. He has listed his assets and liabilities, which","are shown in Figure 2. He has advised you to depreciate the non-current assets by","10% using the straight line method."],"ctxb":[{"t":"p","x":"Max has produced an outline statement of financial position for the year up to 31 December 2016 but it is incomplete. He has listed his assets and liabilities, which are shown in Figure 2. He has advised you to depreciate the non-current assets by 10% using the straight line method."}],"text":"Complete the statement of financial position for Max.","qTotal":16},{"q":10,"sub":"i","marks":2,"section":"A","ctx":[],"ctxb":[],"text":"the trade receivable days ratio","qTotal":16},{"q":10,"sub":"ii","marks":2,"section":"A","ctx":["£"],"ctxb":[],"text":"the trade payable days ratio","qTotal":16},{"q":11,"sub":null,"marks":6,"section":"A","ctx":["£","Max has looked at his statement of financial position and is slightly concerned about","the liquidity of his business."],"ctxb":[{"t":"p","x":"Max has looked at his statement of financial position and is slightly concerned about the liquidity of his business."}],"text":"Discuss why businesses like To the Max need to manage their net current assets/liabilities.","qTotal":6,"ms":{"body":"• Need money to pay suppliers, failure may lead to\nrefusal to supply, leads to inability to make products\n• Need money to pay wages, or staff will leave, which\nleads to reduction in sales and poor service\n• Could lead to cash flow problems, need money for\nunexpected expenses, if no liquid capital then could\nlead to production halting\n• Could lead to gaining a poor reputation with suppliers\nand customers and so impact on future business and\nsales\n• Too much cash in the bank/business could be\ninefficient, not gaining interest, could be used\nelsewhere to fund expansion.\n6","levels":6}},{"q":12,"sub":null,"marks":8,"section":"A","ctx":["Max is unsure about the benefits of completing the more detailed ratio analysis of","his accounts."],"ctxb":[{"t":"p","x":"Max is unsure about the benefits of completing the more detailed ratio analysis of his accounts."}],"text":"Analyse how effective ratios are as a means of assessing business performance.","qTotal":8,"ms":{"body":"Advantages\n• Encourages a systematic approach to analysing\nperformance\n• It simplifies the interpretation of financial\nstatements\n• It helps in comparing companies of different sizes with\neach other\n• It highlights important information in a simple form\n• A user can judge a company by just looking at a few\nnumbers instead of reading the whole financial\nstatements.\nDisadvantages\n• Ratios deal in numbers – they do not address issues\nlike product quality, customer service etc. which can\naffect financial performance\n• Ratios look at the past, not the future\n• Ratios are most useful when they are used to compare\nperformance over a long period of time or against\ncomparable businesses and an industry – this\ninformation is not always available\n• Financial information can be manipulated in several\nways to make the figures used for ratios more or\nless attractive. For example, businesses can delay\npayments to trade creditors at the end of the financial\nyear to make the cash balance higher than normal and\nthe creditor days figure higher too\n• Financial accounting information is affected by\nestimates and assumptions. Accounting standards\nallow different accounting policies, which impairs\ncomparability and hence ratio analysis is less useful in\nsuch situations.\n8","levels":8}},{"q":13,"sub":null,"marks":10,"section":"A","ctx":[],"ctxb":[],"text":"Max is well established in the party planning business. He is expanding into the very competitive wedding planning market. In order to establish himself Max is considering reducing the average price of all his events by 20% so that he is cheaper than his competitors. Current Event Bookings Weddings Projected Figures Fixed costs £16 800 without weddings £19 200 for all events Variable cost per event £140 £1 800 Average fee charged for each event £300 £4 000 Number of events planned 280 25 Assess the effects on To the Max if Max lowers the price of each event.","qTotal":10,"ms":{"body":"• Lower price on existing events would be £240 and £3200\nfor weddings\n• Lower price may attract more customers, higher sales and\npossibly profit\n• However, it might not lead to more sales and revenue,\ndepends whether customers are not loyal to other\nbusinesses, how customers view the product (they may see\nit as cheap and inferior)\n• Lowering the price could make any losses bigger\n• Useful strategy when trying to enter a new market, help\ngain market position and achieve objective of growth\n• Means the business has to sell more events to break even\nas it reduces the contribution per unit to £240 – £140 =\n£100 on existing events\n• Contribution of weddings would have been £4000 – £1800\n= £2200 before the price drop and now £3200 – £1800 =\n£1400\n• The wedding market is highly competitive and may incur\nadditional costs, e.g. advertising\n• Although fixed costs will increase by £1 200 this is more\nthan compensated for by increases in revenue\n• The increase in revenue more than compensates for the\nloss in income by reducing the fee for existing events by\n20%.\n10","levels":10}},{"q":14,"sub":null,"marks":12,"section":"A","ctx":[],"ctxb":[],"text":"Max has given you this extract from his cash flow forecast for his existing events. He is worried about the negative net cash flow and closing balances in some months. July August September October November December Income Sales 48 000 49 800 62 900 30 000 30 000 31 250 Total Income 48 000 49 800 62 900 30 000 30 000 31 250 Expenditure Purchases 21 500 22 000 22 000 12 750 12 750 10 750 Loan payments 1 000 1 000 1 000 1 000 1 000 1 000 Wages 5 000 5 000 5 000 5 000 5 000 5 000 Rent 3 917 3 917 3 917 3 917 3 917 3 917 Utilities 680 680 680 680 680 680 Other expenditure 7 960 8 060 32 840 6 210 6 210 19 990 Advertising 110 610 110 110 610 110 Total Expenditure 40 167 41 267 65 547 29 667 30 167 41 447 Opening balance -10 360 -2 527 6 006 3 359 3 692 3 525 Net Cash Flow 7 833 8 533 -2 647 333 -167 -10 197 Closing Balance -2 527 6 006 3 359 3 692 3 525 -6 672 Evaluate suitable actions that Max could take to improve his cash flow position.","qTotal":12,"ms":{"body":"Negotiate 30 days credit terms with his supplier\n• No cost to the business\n• Will help clear the negative balances\n• However, new business so may not be in a\nposition to negotiate this.\nIncrease his bank loan\n• This increases his income and is aimed at\nclearing the balance\n• However, this will increase monthly outgoings as it\nwill increase loan repayments\n• He is currently paying off a loan so he may not\nbe able to get another loan.\nReduce his outgoings such as wages, rent etc.\n• This will reduce his expenditure, however\nsome items may not be negotiable, e.g.\nwages if they fall below minimum wage\n• May not be able to negotiate rent if signed a\nlonger- term lease.\nIncrease price of events\n• Generates more income, however this may\nlead to a fall in sales so might be\ncounterproductive\n• Negative closing balance at the end of the year is\nnot too large and may not need action if next\nyear’s forecast is good.\n12","levels":12}}],"msMatched":11},{"id":"U3-1801","unit":3,"key":"2018-01","series":"January 2018","date":"Wednesday 17 January 2018","title":"There · Jamie · Arabella · Bella","source":"pearson","kind":"exam","total":100,"parsedTotal":100,"sec":{"A":36,"B":64},"items":[{"q":1,"sub":null,"marks":2,"section":"A","ctx":[],"ctxb":[],"text":"Identify two different types of current accounts.","qTotal":2,"ms":{"body":"Award one mark for any of the following up to a maximum\nof two marks:\nStandard (1) packaged (1) premium (1) basic (1) student /\ngraduate (1)\nAccept any other appropriate response.\n2\nBTEC Next Generation Mark Scheme Template\nBusiness L3 U3","levels":null}},{"q":2,"sub":null,"marks":2,"section":"A","ctx":[],"ctxb":[],"text":"Identify two features of travel insurance.","qTotal":2,"ms":{"body":"Award one mark for any of the following up to a maximum\nof two marks:\n- specific activities (1)\n- loss / theft of belongings (1)\n- damage to belongings (1)\n- illness (1)\n- cancellation of holiday (1)\n- cancelled / missed flight (1)\n- medical emergencies (1)\n- protects individuals or groups (1)\n- single / annual / multi (1)\nAccept any other appropriate response.\n2","levels":null}},{"q":3,"sub":null,"marks":4,"section":"A","ctx":[],"ctxb":[],"text":"Outline two advantages to the consumer of using a price comparison website.","qTotal":4,"ms":{"body":"Award 1 mark for each advantage – maximum 2 marks.\nAward 1 mark for each appropriate development of the\nadvantage – maximum 2 marks.\nAdvantages include:\nEasy to access / easy to use / saves time / saves money\nDevelopments include:\nAvailable 24/7 / clear display of summary of options / only\nhave to put details in once / multiple comparisons in one\nsearch / no need to contact providers separately / allows\nnegotiation of deal / find a better deal / free to use\nDo not accept the same development twice.\nAccept any other appropriate response.\n4","levels":null}},{"q":4,"sub":null,"marks":6,"section":"A","ctx":["There has been recent growth in the use of contactless payments."],"ctxb":[{"t":"p","x":"There has been recent growth in the use of contactless payments."}],"text":"Discuss the benefits to consumers of this method of payment. 5","qTotal":6,"ms":{"body":"Indicative content could include:\nBenefits\n- Convenient payment method, increasingly accepted\nat many outlets\n- Don’t need to remember a PIN\n- Offers the same protection as chip and pin, don’t\nneed to worry about fraudulent use\n- Quick and convenient payments, speeds up\ntransaction time\n- More convenient, can use app on mobile phone\n(e.g. apple pay), / don’t need to carry a card\n- Maximum of £30 per transaction and 4 transactions\na day can limit spending\nDrawbacks\n- Consumers may be more likely to spend more as it\nis so easy to do which could give increased debt and\nfees for them\n- May be a greater risk of fraud for small values if the\ncard is stolen; up to 4 transactions of up to £30\neach per day\n- Maximum of £30 per transaction reduces the\nflexibility\n6","levels":6}},{"q":5,"sub":null,"marks":10,"section":"A","ctx":["Jamie has a full time job earning £400 a week. He has booked a holiday costing","£1 400 and he will have to pay for it in full by the end of the month. He does not","have enough money to do this at the moment. Usually after paying his bills he has","around £100 for personal spending. He is unsure whether to apply for an overdraft or","a personal loan to make this payment for his holiday."],"ctxb":[{"t":"p","x":"Jamie has a full time job earning £400 a week. He has booked a holiday costing £1 400 and he will have to pay for it in full by the end of the month. He does not have enough money to do this at the moment. Usually after paying his bills he has around £100 for personal spending. He is unsure whether to apply for an overdraft or a personal loan to make this payment for his holiday."}],"text":"Assess whether an overdraft or a personal loan would be better for Jamie. 7","qTotal":10,"ms":{"body":"Indicative content could include:\nOverdraft – advantages\n- interest is only charged on the amount outstanding\n- can be repaid without any penalties\n- it’s flexible - you only borrow what you need at the time\n- Cheaper than a loan if repaid quickly\n- Quick and easy to arrange\nOverdraft – disadvantages\n- there will usually be a charge if you want to extend your\noverdraft\n- you could be charged if you go over your overdraft limit\n- the bank can ask for the money back at any time\n- you can only get an overdraft from the bank that you\nhold your current account with\nPersonal loan - advantages\n- Regular payments make budgeting easier\n- Interest is fixed and built into the repayments\n- Interest rate is lower than an overdraft\n- Can spread the cost over a longer period\n- Not repayable on demand\n- Easy to apply for, can be online\n- Don’t have to bank with the loan provider so can search\nfor cheapest deal\nPersonal loan - disadvantage\n10\n- Not flexible – usually penalty for early re-payment\n- Will include charges and penalty for late / missed\npayments\n- Can be more expensive than overdraft if taken over a\nlong period","levels":10}},{"q":6,"sub":null,"marks":12,"section":"A","ctx":["Malik wants to buy a house in five years’ time. He recently inherited £8 000 which","could be used towards a mortgage deposit. He would like to increase the value of","his inheritance before he purchases a property. He has no other savings. He feels he","could save a further £50 a month. Malik is aware that the interest rates on savings","accounts are low and that they may change in the future. He has done some research","and found the following financial products.","This table gives some information about products from different organisations.","Provider and product Interest and charges Features","QZZ Investments","Stocks and","shares ISA","Charge of £60 plus VAT","per annum","Dealing charge of 0.2%","on sales and purchases","No guaranteed return –","previously averaged 7%","Minimum investment £500","No more than 3 withdrawals a year","Monthly savings facility","Tracks the top 100 UK companies","Devon Building","Society","Cash ISA","No charges","1.5% AER return","Minimum investment £100","Instant access","No notice period","Variable interest rate","Westshire Bank","Fixed Rate Bond","1.95% AER return Minimum investment £5 000","No withdrawals for 5 years","Five-year bond","End of term bonus £100","Interest can be withdrawn annually","Ashridge Bank","Fixed Rate Bond","1.7% AER return Minimum investment £1 000","No withdrawals for 2 years","Two-year bond","No bonus","Interest can be withdrawn monthly"],"ctxb":[{"t":"p","x":"Malik wants to buy a house in five years’ time. He recently inherited £8 000 which could be used towards a mortgage deposit. He would like to increase the value of his inheritance before he purchases a property. He has no other savings. He feels he could save a further £50 a month. Malik is aware that the interest rates on savings accounts are low and that they may change in the future. He has done some research and found the following financial products. This table gives some information about products from different organisations. Provider and product Interest and charges Features"},{"t":"flow","x":["QZZ Investments","Stocks and","shares ISA","Charge of £60 plus VAT","per annum","Dealing charge of 0.2%","on sales and purchases","No guaranteed return –","previously averaged 7%","Minimum investment £500","No more than 3 withdrawals a year","Monthly savings facility","Tracks the top 100 UK companies","Devon Building","Society","Cash ISA","No charges","1.5% AER return","Minimum investment £100","Instant access","No notice period","Variable interest rate","Westshire Bank","Fixed Rate Bond","1.95% AER return Minimum investment £5 000","No withdrawals for 5 years","Five-year bond","End of term bonus £100","Interest can be withdrawn annually","Ashridge Bank","Fixed Rate Bond","1.7% AER return Minimum investment £1 000","No withdrawals for 2 years","Two-year bond","No bonus","Interest can be withdrawn monthly"]}],"text":"Evaluate which financial products would be the most suitable for Malik.","qTotal":12,"ms":{"body":"Indicative content could include:\nConsiderations of the advantages and disadvantages\n- Interest rates QZZ Investments has the highest by far\nbut not guaranteed. Westshire Bank is best\nguaranteed rate\n- Level of risk / return QZZ Investments gives best\nreturn but also greatest risk to loss of capital.\n- £50 per month could be added to QZZ Investments\naccount\n- Fixed / Flexible time period Devon Building Society\ngives most flexible product with instant access.\nWestshire Bank is least flexible with no withdrawals\n- Minimum level of initial investment Devon Building\nSociety will allow to put the least in. However all will\naccept the 8 000 as even the highest (Westshire Bank)\nonly needs £5 000\n- Notice period Devon Building Society is the only one\nwith no notice period\n- Bonuses paid Ashridge Bank is the only one to offer a\nbonus which could give them more return overall than\nsome of the ones with higher interest rates\n- Flexibility of withdrawal of interest on bonds –\nAshridge Bank allows you to take out the interest\nearned on a monthly basis whist Westshire Bank is\nonly at the end of each year\n- Level of management in stocks and shares ISA – QZZ\nInvestments managing the account may lead to them\nbeing more proactive in getting a better return for\nMalik\n12","levels":12}},{"q":7,"sub":null,"marks":2,"section":"B","ctx":["Arabella owns a small business, Bella’s Bean Bags, making and selling bean bag chairs.","Arabella sells these bean bag chairs at various markets each Thursday, Friday and","Saturday. She buys the covering material and filling from a wholesaler. She employs","a member of staff to make the bean bags.","The bean bags are made and stored in a small rented unit. She uses social media to","promote the business.","Arabella regularly sells out her stock and is struggling to keep up with demand. She is","looking to expand her business and has asked for your help.","Businesses such as Bella’s Bean Bags incur revenue expenditure."],"ctxb":[{"t":"p","x":"Arabella owns a small business, Bella’s Bean Bags, making and selling bean bag chairs. Arabella sells these bean bag chairs at various markets each Thursday, Friday and Saturday. She buys the covering material and filling from a wholesaler. She employs a member of staff to make the bean bags. The bean bags are made and stored in a small rented unit. She uses social media to promote the business. Arabella regularly sells out her stock and is struggling to keep up with demand. She is looking to expand her business and has asked for your help. Businesses such as Bella’s Bean Bags incur revenue expenditure."}],"text":"Identify two different types of revenue expenditure that a small business is likely to have.","qTotal":2,"ms":{"body":"Award one mark for any of the following up to a maximum of\ntwo marks:\nInventory (1) heating (1) lighting (1) rent (1) rates (1)\ninsurance (1) telephone (1) marketing (1) bank charges (1)\nwages (1)\nAccept utilities (1) but do not then reward heating or lighting\nas a second answer\nAccept any other appropriate response.\n2","levels":null}},{"q":8,"sub":null,"marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Give two examples of capital income that a small business is likely to have.","qTotal":2,"ms":{"body":"Award one mark for any of the following up to a maximum of\ntwo marks:\nloan (1) owner’s capital (1) mortgage (1)\nshares (1) debentures (1) venture capital (1)\nAccept any other appropriate response.\n2","levels":null}},{"q":9,"sub":"a","marks":3,"section":"B","ctx":["Arabella has given you the following financial information:","Bean bag chair","size","Weekly","production","target/sales","Selling price Materials","per bag","Filling","per bag","Large 36 £18 £2.75 £3.50","She pays her employee a weekly wage of £190 for 20 hours of work. Each bean bag chair","takes 30 minutes to complete. She has annual fixed costs of £3 780."],"ctxb":[{"t":"p","x":"Arabella has given you the following financial information:"},{"t":"flow","x":["Bean bag chair","size","Weekly","production","target/sales","Selling price Materials","per bag","Filling","per bag","Large 36 £18 £2.75 £3.50"]},{"t":"p","x":"She pays her employee a weekly wage of £190 for 20 hours of work. Each bean bag chair takes 30 minutes to complete. She has annual fixed costs of £3 780."}],"text":"Calculate the variable cost of each large bean bag chair.","qTotal":16,"ms":{"body":"Method one – Wages as a Variable Cost\n£11 (3)\nOR\nMaterials and filling = £2.75 + £3.50 = £6.25 (1)\nWages = £190/20 = £9.50 per hour\nEach bean bag chair takes 30 mins so £9.50/2 = £4.75 per\nchair (1)\nMethod two – Wages as a Fixed Cost\n£6.25 (3)\nOR\nMaterials and filling = £2.75 (1) + £3.50 (1)\nOFR (maximum 2 marks)\n3","levels":null}},{"q":9,"sub":"b","marks":4,"section":"B","ctx":["Arabella has a weekly production target of 36 bean bag chairs."],"ctxb":[{"t":"p","x":"Arabella has a weekly production target of 36 bean bag chairs."}],"text":"Calculate the margin of safety for the year.","qTotal":16},{"q":9,"sub":"c","marks":9,"section":"B","ctx":["Bella’s Bean Bags has completed its first year of trading. The following financial","information has been provided for you to complete Bella’s Bean Bags statement of","comprehensive income.","£","Cash sales 37 596","Cost of materials purchased 13 575","Credit sales 1 500","Discount allowed 120","Rent 2 360","Wages 18 900","Trade payables 2 100","Utilities 381","Additional information","1 Bella’s Bean Bags has non-current assets of an industrial sewing machine and","a trailer which together originally cost £2 835. She has decided to depreciate her","non-current assets by 20% using the straight line method.","2 Rent of £280 has been paid in advance for the next financial year."],"ctxb":[{"t":"p","x":"Bella’s Bean Bags has completed its first year of trading. The following financial information has been provided for you to complete Bella’s Bean Bags statement of"},{"t":"cap","x":"comprehensive income."},{"t":"grid","head":null,"rows":[["Cash sales","37 596"],["Cost of materials purchased","13 575"],["Credit sales","1 500"],["Discount allowed","120"],["Rent","2 360"],["Wages","18 900"],["Trade payables","2 100"],["Utilities","381"]]},{"t":"p","x":"Additional information 1 Bella’s Bean Bags has non-current assets of an industrial sewing machine and a trailer which together originally cost £2 835. She has decided to depreciate her non-current assets by 20% using the straight line method. 2 Rent of £280 has been paid in advance for the next financial year."}],"text":"Complete Bella’s Bean Bags statement of comprehensive income for the financial year ending 31 December 2016.","qTotal":16,"ms":{"body":"Award 1 mark for each correct answer as per grid below\nNB Appropriate answers (ie those where figurer is in line\nwith the mark scheme) should be accepted regardless of\nwhich column of the table the answer has been placed in\nor if the row has been labelled.\n9\n£ £\nSales 39 096 (2) W1\nCost of sales 13 575\nGross profit 25 521 (1 OFR) *\nExpenses","levels":null}},{"q":10,"sub":"a","marks":3,"section":"B","ctx":["Bella’s Bean Bags","Statement of comprehensive income for the year ending","31 December 2016","£ £","Sales revenue","Cost of sales 13 575","Gross profit","Expenses","Wages 18 900","Utilities 381","Total expenses","Arabella has been offered a contract with a local retailer to provide 500 small bean","bag chairs. The retailer will pay only £12 for a small bean bag chair. Arabella has","estimated that it would still take 30 minutes to produce each bean bag chair. She","plans to employ a less experienced member of staff who she would pay a lower rate","of £8.50 per hour. She would also have the following variable costs for the small bean","bag chair:","Bean bag chair size Selling price Material per bag Filling per bag","Small £12 £2.25 £3.00"],"ctxb":[{"t":"p","x":"Bella’s Bean Bags Statement of comprehensive income for the year ending"},{"t":"flow","x":["31 December 2016","£ £","Sales revenue","Cost of sales 13 575","Gross profit","Expenses","Wages 18 900","Utilities 381","Total expenses"]},{"t":"p","x":"Arabella has been offered a contract with a local retailer to provide 500 small bean bag chairs. The retailer will pay only £12 for a small bean bag chair. Arabella has estimated that it would still take 30 minutes to produce each bean bag chair. She plans to employ a less experienced member of staff who she would pay a lower rate of £8.50 per hour. She would also have the following variable costs for the small bean bag chair: Bean bag chair size Selling price Material per bag Filling per bag Small £12 £2.25 £3.00"}],"text":"(i) Calculate the total contribution for this order if Arabella accepts this contract.","qTotal":8,"ms":{"body":"(i) Method one – Wages as a Variable Cost\n£1 250 (3)\nOR\nTotal sales revenue – Total variable cost (TVC) (1)\nOR\nTotal sales = 500 x £12 = £6 000 (1)\nTVC = (2.25 +3.00 + 4.25) x 500 = £4750 (1)\nOR\nSelling price – Variable cost per unit x sales (1)\nOR\n12 – (2.25 +3.00 + 4.25) = 2.50 (1)\n2.50 x 500 (1)\nMethod two – Wages as a Fixed Cost\n£3 375 (3)\nTotal sales revenue – Total variable cost (TVC) (1)\nOR\nTotal sales = 500 x £12 = £6 000 (1)\nTVC = (2.25 +3.00 ) x 500 = £2 625 (1)\nOR\nSelling price – Variable cost per unit x sales (1)\nOR\n12 – (2.25 +3.00 ) = 6.75 (1)\n6.75 x 500 (1)\n3","levels":null}},{"q":10,"sub":"ii","marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Calculate the gross profit margin percentage for this order if Arabella accepts this contract.","qTotal":8},{"q":10,"sub":"b","marks":3,"section":"B","ctx":["%","17","Arabella has approached a different supplier who can supply the materials and fillings","more cheaply. Her wage costs remain at £8.50 per hour. It will still take 30 minutes to","produce each bean bag chair and she will still be able to sell these small bean bag","chairs for £12.","Bean bag chair size Selling price Material per bag Filling per bag","Small £12 £2.10 £2.90"],"ctxb":[{"t":"p","x":"% 17 Arabella has approached a different supplier who can supply the materials and fillings more cheaply. Her wage costs remain at £8.50 per hour. It will still take 30 minutes to produce each bean bag chair and she will still be able to sell these small bean bag chairs for £12. Bean bag chair size Selling price Material per bag Filling per bag Small £12 £2.10 £2.90"}],"text":"Calculate the mark-up percentage achieved per bean bag chair if Bella’s Bean Bags uses this alternative supplier.","qTotal":8,"ms":{"body":"Method one – Wages as a variable Cost\n29.729% (3)\naccept 29.7%, 29.73% and rounding up to 30%\nOR\n2.75/9.25*100 (2)\nOR\n(Gross profit / Cost of sales) x 100 (1)\n2.75 (1)\nAccept answers without % sign\nMethod two – Wages as a Fixed Cost\n140% (3)\nOR\n7/5*100 (2)\nOR\n(Gross profit / Cost of sales) x 100 (1)\n7 (1)\nAccept answers without % sign\n3","levels":null}},{"q":11,"sub":null,"marks":6,"section":"B","ctx":["Arabella has been advised to produce a cash-flow forecast but she is unsure why she","needs one. She says that her business is short of money and that she cannot afford","to spend extra time doing unnecessary paper work. She argues that she must make","sure orders are fulfilled on time and there is enough stock available to meet customer","demand."],"ctxb":[{"t":"p","x":"Arabella has been advised to produce a cash-flow forecast but she is unsure why she needs one. She says that her business is short of money and that she cannot afford to spend extra time doing unnecessary paper work. She argues that she must make sure orders are fulfilled on time and there is enough stock available to meet customer demand."}],"text":"Discuss how useful a cash-flow forecast can be to a small business such as Bella’s Bean Bags.","qTotal":6,"ms":{"body":"Indicative content:\nBenefits\n• Planning for the future – can make better decisions or\nplan for unforeseen occurrences\n• Monitoring performance – can help identify times when\nfinancial support is needed\n• Control of cash in and out of the business – plan\npayments and collections more effectively to reduce\npressure\n• Target setting for the future\n• Required by investors if seeking a loan / finance\n• Can identify where / when additional finances may be\nrequired\nLimitations\n• It is only a prediction / forecast\n• Forecasted inflows and / or outflows may be incorrect\n• Inflows and / or outflows may change depending on\nexternal factors\n6","levels":6}},{"q":12,"sub":null,"marks":8,"section":"B","ctx":["Arabella is considering expanding the business by moving to larger premises, buying","new machines and employing more staff. She has estimated that this will cost her","approximately £100 000. She has no further capital to invest. A friend has suggested","that she should consider approaching a venture capitalist to fund the expansion."],"ctxb":[{"t":"p","x":"Arabella is considering expanding the business by moving to larger premises, buying new machines and employing more staff. She has estimated that this will cost her approximately £100 000. She has no further capital to invest. A friend has suggested that she should consider approaching a venture capitalist to fund the expansion."}],"text":"Analyse the potential impact of using venture capital as a source of finance on a small business. 21","qTotal":8,"ms":{"body":"Indicative content:\nAdvantages\n• May offer business expertise\n• Additional resources in a number of areas e.g. legal,\ntax, personnel\n• Connections / Networking could benefit the business\n• No interest payable\n• Potential to negotiate terms\nDisadvantages\n• Loss of control / Greater scrutiny\n• May result in minority ownership status\n• Business may be too small to attract venture capital\n• Potential conflict\n• Cost of legal and accounting fees even if funds are not\nsecured\n• May take some time for it all to be finalised\n8","levels":8}},{"q":13,"sub":null,"marks":10,"section":"B","ctx":["Arabella is considering accepting a contract from a large retailer called Libby","Furniture. She is unsure how the terms of this contract will affect her business. Libby","Furniture will place a regular monthly order for 30 large bean bag chairs and 60 small","ones. They are insisting on 60 days credit terms. Arabella usually pays her suppliers","for all raw materials within 7 days."],"ctxb":[{"t":"p","x":"Arabella is considering accepting a contract from a large retailer called Libby Furniture. She is unsure how the terms of this contract will affect her business. Libby Furniture will place a regular monthly order for 30 large bean bag chairs and 60 small ones. They are insisting on 60 days credit terms. Arabella usually pays her suppliers for all raw materials within 7 days."}],"text":"Assess the potential impact that this new contract could have on a small business such as Bella’s Bean Bags.","qTotal":10,"ms":{"body":"Indicative content:\nPositive impact\n• Regular and guaranteed income\n• Small chairs make some contribution to fixed costs but\nit is lower than the large chairs\n• Increase in sales of large chairs will make greater\ncontribution to break-even and profit\n• Could reduce time / days spent at the markets\n• Could reduce time needed to update social media /\npromotion\n• Widening customer base spreads risk\n• Could increase profitability significantly\nNegative impact\n• Can’t produce that number on her own so will need to\nexpand\n• Expansion has additional costs such as employment,\nmachinery, premises\n• Additional production costs will put pressure on cash\nflow given she pays her suppliers after 7 days\n• 60 day credit terms will reduce cash flow / additional\ncosts going out well before payment is received\n• May need to focus on contract over market customers,\ncould lose market slot if she does not have enough\ngoods to sell\n• Short term impact on cash flow buying additional\nmaterials and paying staff.\n10","levels":10}},{"q":14,"sub":null,"marks":12,"section":"B","ctx":["Arabella has obtained the following information from a similar-sized competitor called","Comfychair, which has been trading for 4 years. She wants to compare the performance","of Bella’s Bean Bags against that of Comfychair’s.","Financial ratios for year ending 31 December 2017","Comfychair Bella’s Bean Bags","Gross profit margin 36 25","Profit margin 22 9","Inventory turnover 23 days 8 days","Trade receivable days 14 40","Trade payable days 60 7","Liquid capital ratio 0.9 1.2"],"ctxb":[{"t":"p","x":"Arabella has obtained the following information from a similar-sized competitor called Comfychair, which has been trading for 4 years. She wants to compare the performance of Bella’s Bean Bags against that of Comfychair’s."},{"t":"grid","head":null,"rows":[["Financial ratios for year ending 31 December","2017"],["Comfychair Bella’s Bean Bags Gross profit margin","36","25"],["Profit margin","22","9"]]},{"t":"cap","x":"Inventory turnover 23 days 8 days"},{"t":"cap","x":"Inventory turnover 23 days 8 days"},{"t":"grid","head":null,"rows":[["Trade receivable days","14","40"],["Trade payable days","60","7"],["Liquid capital ratio","0.9","1.2"]]}],"text":"Evaluate, using the ratios provided, the financial performance of Bella’s Bean Bags compared to Comfychair’s.","qTotal":12,"ms":{"body":"Indicative content:\n• Comfychair has proportionally higher gross profit and\nnet profit figures although Bella’s Bean Bags has\nproportionally lowed running costs (16% compared to\n14% for Comfychair)\n• Comfychair turns stock over more slowly. However,\nBella’s Bean Bags might not always be able to meet\ndemand which could be reducing sales and profits.\n• Comfychair collects payments from debtors quicker and\ntakes longer to pay for materials which helps cash flow.\n• Comfychair is established and can negotiate better\ntrading terms. Bella’s Bean Bags pays creditors too\nquickly so could delay this and use the money more\neffectively in the business. This affects cash flow and\nliquidity. Could be because Arabella is trying to build a\nreputation for Bella’s Bean Bags so she can negotiate\nbetter terms of trade\n• Bella’s Bean Bags’ liquid capital ratio is better than\nComfychair’s which means Bella’s Bean Bags are able to\nmeet their liabilities more easily than Comfychair\n12","levels":12}}],"msMatched":16},{"id":"U3-1806","unit":3,"key":"2018-06","series":"June 2018","date":"Friday 25 May 2018","title":"Morna · Liam · Tomasz · He","source":"pearson","kind":"exam","total":100,"parsedTotal":94,"sec":{"A":36,"B":64},"items":[{"q":1,"sub":null,"marks":2,"section":"A","ctx":[],"ctxb":[],"text":"Give two different types of financial institution.","qTotal":2,"ms":{"body":"Award one mark for any of the following up to a\nmaximum of two marks:\n• Bank of England\n• Banks\n• Building societies\n• Credit unions\n• National Savings and Investments\n• Insurance companies\n• Pension companies\n• Pawnbrokers\n• Payday loan companies\nAccept any other appropriate response.\n2\nBTEC Next Generation Mark Scheme Template\nBusiness L3 U3 1806","levels":null}},{"q":2,"sub":null,"marks":2,"section":"A","ctx":[],"ctxb":[],"text":"State two ways the Financial Conduct Authority (FCA) can protect consumers in relation to personal finance.","qTotal":2,"ms":{"body":"Award one mark for any of the following up to a\nmaximum of two marks:\n• Authorising which firms/individuals can enter\nthe financial markets\n• Setting standards for the industry\n• Monitoring how firms/individuals work\n• Close down/impose penalties on\nfirms/individuals that do not meet the FCA\nstandards\n• Help resolve complaints from consumers\n• Protect consumers against fraud\n• Ensure (the market provides) fair deals\nAccept any other appropriate response.\n2\nAnswer Mark\n3a Award one mark for each advantage up to a\nmaximum of two marks\n• can help you budget\n• can get discounts\n• immediate refunds are available for payment\nerrors\n• the supplier cannot change the amount\nwithout notice\n• convenient/easy to set up/efficient payment\nmethod\n• transactions completed automatically\n• payments will be paid on time\n• avoids late payment fees\nAccept any other appropriate response.\n2","levels":null}},{"q":3,"sub":"a","marks":2,"section":"A","ctx":[],"ctxb":[],"text":"Give two advantages to the consumer of paying monthly bills by direct debit.","qTotal":4},{"q":3,"sub":"b","marks":2,"section":"A","ctx":[],"ctxb":[],"text":"Give two disadvantages to the consumer of paying monthly bills by direct debit.","qTotal":4,"ms":{"body":"Award one mark for each disadvantage up to a\nmaximum of two marks\n• Could be more expensive\n• Could result in over payments\n• May forget payment is due to go out\n• Payee can change the payment amount/date\n• Errors can occur\n• Cancellation is required by the payer\nAccept any other appropriate response.\n2","levels":null}},{"q":4,"sub":null,"marks":6,"section":"A","ctx":["Personal attitudes towards the role of money will differ according to the individual’s life","stage."],"ctxb":[{"t":"p","x":"Personal attitudes towards the role of money will differ according to the individual’s life stage."}],"text":"Discuss the personal attitudes of people in old age towards borrowing and saving.","qTotal":6,"ms":{"body":"Answers will be credited according to the\nlearner’s demonstration of knowledge and\nunderstanding of the material, using the\nindicative content and levels descriptors below.\nThe indicative content that follows is not\nprescriptive. Answers may cover some or all of\nthe indicative content but learners should be\nrewarded for other relevant answers.\nIndicative content includes:\nBorrowing\n• Less likely to borrow but may need to do\nso:\no to pay for expensive products\no Smaller income/ live on pension\no Support dependents\no Care home fees\n• Willingness to release equity in property\n• Culture\n• Personal values\n• Financial knowledge limited\n• Assumption that they cannot access\nborrowing\nSaving\n• More likely to spend less\n• Likely to have savings\n• Less disposable income\n• May downsize to reduce expenditure/\ncreate savings\n• Fewer dependents so lower outgoings\n• Desire to protect inheritance for\ndependents\nThe competing arguments/pros and cons in\ncontext may be from:\n• Scale –\nincome/assets/pension/dependents\n• Old versus young\n6","levels":6}},{"q":5,"sub":null,"marks":10,"section":"A","ctx":["Morna has a full-time job. She has a standard bank account, a small amount of","savings, a mortgage and a basic workplace pension. She does not have any life","insurance. Morna believes she will benefit from reviewing the financial products","she currently has and is considering taking financial advice from an Independent","Financial Advisor."],"ctxb":[{"t":"p","x":"Morna has a full-time job. She has a standard bank account, a small amount of savings, a mortgage and a basic workplace pension. She does not have any life insurance. Morna believes she will benefit from reviewing the financial products she currently has and is considering taking financial advice from an Independent Financial Advisor."}],"text":"Assess whether Morna should use an Independent Financial Advisor as a source of financial advice.","qTotal":10},{"q":6,"sub":null,"marks":12,"section":"A","ctx":["Liam has a partner and two children and works full time. The family takes two","holidays a year, usually in Europe or in the UK. He and his partner have each recently","purchased the latest iPhone without insurance. Liam is regularly overdrawn on his","bank account by around £300. He is about to open a packaged current account.","This table gives some information about products from different financial organisations.","Financial","organisation","Product","Annual","cost","Travel insurance Mobile phone","insurance","Interest-free","overdraft limit","Westshire Bank","Flexplus","£120 Europe family Up to £1 000 for","account holder","only","£100","Ashridge Bank","Ultimate Rewards","£160 Worldwide family Replacement","phone for","account holder","only","£300","Shirevale Bank","Travel Plus Pack","£186 Europe family +","winter sports","Cover for","account holder","and partner only","£200","The Royal Bank","Select Platinum","£192 Worldwide family","+ winter sports","Up to £2 000 for","the family","£250"],"ctxb":[{"t":"p","x":"Liam has a partner and two children and works full time. The family takes two holidays a year, usually in Europe or in the UK. He and his partner have each recently purchased the latest iPhone without insurance. Liam is regularly overdrawn on his bank account by around £300. He is about to open a packaged current account. This table gives some information about products from different financial organisations."},{"t":"flow","x":["Financial","organisation","Product","Annual","cost","Travel insurance Mobile phone","insurance","Interest-free","overdraft limit","Westshire Bank","Flexplus","£120 Europe family Up to £1 000 for","account holder","only","£100","Ashridge Bank","Ultimate Rewards","£160 Worldwide family Replacement","phone for","account holder","only","£300","Shirevale Bank","Travel Plus Pack","£186 Europe family +","winter sports","Cover for","account holder","and partner only","£200","The Royal Bank","Select Platinum","£192 Worldwide family","+ winter sports","Up to £2 000 for","the family","£250"]}],"text":"Evaluate which packaged current account would be the most suitable for Liam.","qTotal":12,"ms":{"body":"Answers will be credited according to the learner’s\ndemonstration of knowledge and understanding of\nthe material, using the indicative content and levels\ndescriptors below. The indicative content that\nfollows is not prescriptive. Answers may cover some\nor all of the indicative content but learners should\nbe rewarded for other relevant answers.\nIndicative content could include:","levels":12}},{"q":7,"sub":null,"marks":1,"section":"B","ctx":["Tomasz has a pet grooming business for small animals called Pet Boutique.","Tomasz previously rented a space in a local pet parlour but is about to move into his","own premises as his client list has increased significantly and he is struggling to keep","up with demand. He has used all his savings and borrowed some money from family","to purchase his equipment and a small van."],"ctxb":[{"t":"p","x":"Tomasz has a pet grooming business for small animals called Pet Boutique. Tomasz previously rented a space in a local pet parlour but is about to move into his own premises as his client list has increased significantly and he is struggling to keep up with demand. He has used all his savings and borrowed some money from family to purchase his equipment and a small van."}],"text":"Give one reason for recording financial transactions.","qTotal":1,"ms":{"body":"Award one mark for any of the following:\n• Record/track income/inflows\n• Record/track expenditure/outflows\n• ensure all payments are collected\n• ensure all bills are paid\n• ensure accounts are reported accurately\n• ensure compliance with the law\n• ensure correct taxes are paid\n• measure performance\n• predict future performance based on past\ndata\nAccept any other appropriate response.\n1","levels":null}},{"q":8,"sub":null,"marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Identify two variable costs that a business such as Pet Boutique could have.","qTotal":2,"ms":{"body":"Award one mark for any of the following up to a\nmaximum of two marks:\n• stock\n• consumables/shampoo\n• utilities\n• wages\n• petrol/diesel\nDO NOT ACCEPT MORE THAN ONE UTILITY\nDO NOT ACCEPT RAW MATERIALS UNLESS\nQUANTIFIED WITH A RELEVANT EXAMPLE\nAccept any other appropriate response.\n2","levels":null}},{"q":9,"sub":"a","marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Calculate the gross profit margin.","qTotal":13,"ms":{"body":"Award two marks for the correct response of\n72.15%\nAccept:\n• rounded down to 72% or up to 72.2%\n• figure without percentage sign\nOR\nAward one mark for giving the correct calculation in\neither words or numbers:\n• Gross Profit Margin = (Gross profit/sales) x 100\n• Gross Profit Margin = (22 512/31 200) x 100\n2","levels":null}},{"q":9,"sub":"b","marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Calculate the liquid capital ratio.","qTotal":13,"ms":{"body":"Award two marks for the correct response of\n•0.91:1\n•0.91\n•0.9:1\n•0.9\nAccept any of the above conventions where the\nfigure is given to a more accurate decimal place\n(eg 0.91003:1)\nOR\nAward one mark for the correct formula in words\nor numbers:\n• Liquid capital ratio = (Current assets–\ninventory) / current liabilities\n• Liquid capital ratio = (7 796 – 2 496) / 5 824\n2","levels":null}},{"q":9,"sub":"c","marks":2,"section":"B","ctx":["Tomasz realises that he has made some errors in the financial information given in","Figure 1 and Figure 2.","Error 1","He forgot to depreciate his equipment. This is to be depreciated by 15% using the","straight line method."],"ctxb":[{"t":"p","x":"Tomasz realises that he has made some errors in the financial information given in"},{"t":"grid","head":null,"rows":[["Figure 1 and Figure","2"],["Error","1"]]},{"t":"p","x":"He forgot to depreciate his equipment. This is to be depreciated by 15% using the straight line method."}],"text":"(i) Calculate the new net book value for his equipment.","qTotal":13,"ms":{"body":"(i) Award two marks for the correct response of\n7 225\nOR\nAward one mark for any one of the correct\nformula in words or numbers:\n• NBV = Current value of equipment -\n(Current value of equipment * rate of\ndepreciation (%))\n• 8 500 – (8 500 x 15%)\n• 8 500 - 1275\n• 8 500 * 85%\n• 8 500 * 0.85\n2","levels":null}},{"q":9,"sub":"ii","marks":3,"section":"B","ctx":["Error 2","He has incorrectly included his overdraft of £800 in his bank figure."],"ctxb":[{"t":"p","x":"Error 2 He has incorrectly included his overdraft of £800 in his bank figure."}],"text":"Calculate his new Net Current Assets/Liabilities figure taking into account this error.","qTotal":13},{"q":9,"sub":"iii","marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Calculate the new Net Asset figure taking into account Errors 1 and 2.","qTotal":13},{"q":9,"sub":"d","marks":2,"section":"B","ctx":["Error 3","He forgot to include his accrued quarterly payment of £1 280 for utilities in his","Financial Statements given in Figure 1 and Figure 2."],"ctxb":[{"t":"p","x":"Error 3 He forgot to include his accrued quarterly payment of £1 280 for utilities in his Financial Statements given in Figure 1 and Figure 2."}],"text":"Calculate the new Net Profit figure to account for Errors 1, 2 and 3.","qTotal":13,"ms":{"body":"Award two marks for the correct response of\n£2 357 (accept 2 357)\nOR\nAward one mark for the correct formula in words\nor numbers:\n• New Net Profit = Original net profit –\n(equipment value x 15% depreciation) –\naccrued utilities payment\n• New Net Profit = 4 912 – (8500 x 15%) –\n1 280\nNew Net Profit = 4 912 – 1 275 – 1 280\n2","levels":null}},{"q":10,"sub":"a","marks":1,"section":"B","ctx":["Tomasz has produced a cash flow forecast but it is incomplete."],"ctxb":[{"t":"p","x":"Tomasz has produced a cash flow forecast but it is incomplete."}],"text":"Complete the outlined boxes labelled (i) to (viii) in the cash flow forecast for Pet Boutique. January February March April £ £ £ £ Income Sales 2 700 950 3 650 2 940 Other income 200 (iii) 0 0","qTotal":12,"ms":{"body":"Award one mark for each box correctly\ncompleted\n8\nJanuary February March April\n£ £ £ £\nIncome\nSales 2 900 950 3 650 2 940\nOther income (iii) 200 (1)\n(i) Total Income OR\nTotal Revenue OR\nTotal Inflow (1)\n2 900 1 150 3 650 2 940\nExpenses\nStock 1 102 1 102 815 (vi) 1 127 (1)\nMarketing 80 520 80 80\nUtilities 1 280 1 280\nOther 1 020 840 1 200 1 450\nTotal expenditure 3 482 (iv) 2 462\n2 095 3 937\nNet cash flow –582 (v) –1 312\n(1) OFRa\n1 555 (vii) –997(1)\nOpening balance (ii) 2 140\n1 558 246 1 801\nClosing balance 1 558 246 1 801 (viii) 804 (1)\nOFRb\nOFRa = Own Figure Rule applied (error carried forward) from incorrect\ncalculation of Total Expenditure for February\nOFRb = Own Figure Rule applied (error carried forward) from incorrect\ncalculation of Net Cash Flow for April","levels":null}},{"q":10,"sub":"i","marks":1,"section":"B","ctx":[],"ctxb":[],"text":"2 900 1 150 3 650 2 940","qTotal":12},{"q":10,"sub":"b","marks":4,"section":"B","ctx":["Expenses","Stock 1 102 1 102 815 (vi) (1)","Marketing 80 520 80 80","Utilities 1 280 0 0 1 280","Other 1 020 840 1 200 1 450","Total expenditure 3 482 (iv) 2 095 3 937 (1)","Net cash flow –582 (v) 1 555 (vii) (1) (1)","Opening balance (ii) 1 558 246 1 801 (1)","Closing balance 1 558 246 1 801 (viii) (1)","21","Tomasz is considering offering a pet-sitting service in his shop.","He wants to know if he will at least break even if he offers this service.","He estimates his costs and revenue for this service as:","• fixed costs £5 640","• total variable costs £11 640","• total revenue £17 460","He expects to have 970 customers."],"ctxb":[{"t":"cap","x":"Expenses"},{"t":"cap","x":"Expenses"},{"t":"grid","head":null,"rows":[["Stock","1 102","1 102 815","(vi)","1"],["Marketing","80 520","80","80"],["Utilities","1 280","0","0","1 280"],["Other","1 020 840","1 200","1 450"],["Total expenditure","3 482","(iv)","2 095","3 937","1"],["Net cash flow –582","(v)","1 555","(vii)","1","1"],["Opening balance","(ii)","1 558 246","1 801","1"],["Closing balance","1 558 246","1 801","(viii)","1"]]},{"t":"p","x":"21 Tomasz is considering offering a pet-sitting service in his shop. He wants to know if he will at least break even if he offers this service."},{"t":"cap","x":"He estimates his costs and revenue for this service as:"},{"t":"cap","x":"He estimates his costs and revenue for this service as:"},{"t":"grid","head":null,"rows":[["• fixed costs","£5 640"],["• total variable costs","£11 640"],["• total revenue","£17 460"]]},{"t":"p","x":"He expects to have 970 customers."}],"text":"Calculate the break-even point for this service at Pet Boutique.","qTotal":12,"ms":{"body":"Award four marks for the correct response of 940\nIf the incorrect answer is provided then credit\nworkings out as follows:\nAward one mark for correct formula in words\n• Break even = fixed costs / Contribution per\nunit\n• Break even = fixed costs/(selling price per\nunit – variable cost per unit)\n• Break even = fixed costs/(selling price –\nvariable cost)\n• BE = FC/(SP-VC)\nAND\nAward one mark for correctly calculating selling\nprice per unit\n• Selling price per unit = total revenue /\nnumber of customers\n• Selling price : 17 460 / 970 = £18\nAND\nAward one mark for correctly calculating variable\ncost per unit\n• Variable cost per unit = total variable costs\n/ number of customers\n• Variable cost per unit : 11 640 / 970 =\n£12\nOR\nAward three marks for formula in numbers:\n• Break even = 5640 / (18-12)\n• Break even = 5640 / 6\n• Break even = 5640 / ((17 460 / 970) – (11\n640 / 970))\n4","levels":null}},{"q":11,"sub":null,"marks":6,"section":"B","ctx":["Tomasz understands that some businesses can benefit from undertaking break-even","analysis but he is not sure why he should do this for Pet Boutique."],"ctxb":[{"t":"p","x":"Tomasz understands that some businesses can benefit from undertaking break-even analysis but he is not sure why he should do this for Pet Boutique."}],"text":"Discuss the advantages and disadvantages to a small business of using break-even analysis.","qTotal":6,"ms":{"body":"Answers will be credited according to the learner’s\ndemonstration of knowledge and understanding of\nthe material, using the indicative content and\nlevels descriptors below. The indicative content\nthat follows is not prescriptive. Answers may\ncover some or all of the indicative content but\nlearners should be rewarded for other relevant\nanswers.\nIndicative content could include:\nAdvantages\n• He will know how many customers he\nneeds to have/items he needs to sell to\nbreak even\n• It can inform decisions about what price to\ncharge\n• He can use it to set targets for the\nbusiness and for any staff he may have\n• It allows him to identify his fixed and\nvariable costs\n• He can identify if costs are too high and\ntake action to lower them\n• It is a simple way of calculating profit and\nloss at different levels of output\n• It allows for ‘what if’ scenarios\n• Identifies margin of safety so he knows\nhow many units sales can fall by without\nmaking a loss\nDisadvantages\n• Break-even theory only applies to one\nproduct\n• Assumes all products made/bought can be\nsold\n• Assumes that all products are bought/sold\nat the same price\n• Assumes that fixed costs will stay fixed\nregardless of output, which may not be the\ncase\n• Assumes that variable cost per unit stays\nthe same\n• It is only a prediction\n6","levels":6}},{"q":12,"sub":null,"marks":8,"section":"B","ctx":["Tomasz needs to replace the vehicle for his business. He is unsure how he can finance","this and is considering leasing the vehicle."],"ctxb":[{"t":"p","x":"Tomasz needs to replace the vehicle for his business. He is unsure how he can finance this and is considering leasing the vehicle."}],"text":"Analyse the advantages and disadvantages to a small business such as Pet Boutique of leasing a vehicle.","qTotal":8,"ms":{"body":"Answers will be credited according to the learner’s\ndemonstration of knowledge and understanding of\nthe material, using the indicative content and levels\ndescriptors below. The indicative content that\nfollows is not prescriptive. Answers may cover some\nor all of the indicative content but learners should\nbe rewarded for other relevant answers.\nIndicative content could include:\nAdvantages\n• May be a tax efficient way of purchasing the\nvehicle\n• Lease costs may be lower in the short run –\nno upfront costs\n• Could include a service/repair plan in the\ncost of the lease\n• The vehicle can changed on a regular basis\nby taking out a new lease\n• Sometimes an option to purchase at the end\nof the lease\n• Spreads the costs/ helps to budget\n• Usually new vehicle\nDisadvantages\n• He can’t modify the vehicle to suit his needs/\nhis needs may change\n• He will never own the vehicle during the\nterm of the lease\n• Service/repair costs may not be included\n• Locked into an agreement\n• Loss of vehicle if fail to make the payments\n8","levels":8}},{"q":13,"sub":null,"marks":10,"section":"B","ctx":["Tomasz often experiences cash flow problems, which causes his business account to","become overdrawn.","His customers usually pay for his services in full within 30 days of receiving the","service. He is considering introducing annual payment plans for his customers where","they will pay a fixed amount each month. To do this he will calculate his customer’s","total spend for the previous year and divide it into 12 equal monthly payments. He","believes this will help customers since they will know how much they will be paying","every month. No other groomer in the area offers this facility."],"ctxb":[{"t":"p","x":"Tomasz often experiences cash flow problems, which causes his business account to become overdrawn. His customers usually pay for his services in full within 30 days of receiving the service. He is considering introducing annual payment plans for his customers where they will pay a fixed amount each month. To do this he will calculate his customer’s total spend for the previous year and divide it into 12 equal monthly payments. He believes this will help customers since they will know how much they will be paying every month. No other groomer in the area offers this facility."}],"text":"Assess whether introducing annual payment plans would help improve Tomasz’s cash flow.","qTotal":10,"ms":{"body":"Answers will be credited according to the learner’s\ndemonstration of knowledge and understanding of\nthe material, using the indicative content and levels\ndescriptors below. The indicative content that\nfollows is not prescriptive. Answers may cover some\nor all of the indicative content but learners should\nbe rewarded for other relevant answers.\nIndicative content could include:\nAdvantages\n• protecting inflows by locking customers into\nan agreement\n• It will bring in regular amounts of money\ntherefore evening out cashflow\n• Could bring in new customers and so\nincrease inflow\n• Have enough regular inflows to cover regular\npayments/outflows so will reduce potential\noverdraft and reduce bank charges\n• Helps budget to give a positive net cashflow\n/ arrange overdrafts\n• Inflows are spread over 12 months whilst\ncosts occur at point of treatment and so may\nimpact positively on predicted cashflows\nDisadvantages\n• Could lose customers and so decrease inflow\n• Potentially discourages additional/impulse\nspending and so reduce potential inflows\n• Using last year’s data doesn’t account for\ninflation/increases in consumables costs so\npayment plan may not cover increased\noutflow\n• The business may have to absorb increased\ncosts that will have a negative impact on\ncashflow.\n• Customers may cancel payments without\nadvising Tomasz, reducing cash flow\n• Inflows are spread over 12 months whilst costs\noccur at point of treatment and so may impact\nnegatively on predicted cashflows\n10","levels":10}},{"q":14,"sub":null,"marks":12,"section":"B","ctx":["After moving to his new premises, Tomasz has realised that he has a lot of space that he","is not utilising. He would like to increase his overall profit and has researched two options","that could make use of the space and increase his profit.","Options Costs and revenues","1 – Allow another dog groomer to have","space in his shop in return for rent and an","additional fee each month.","Initial contract would be for six months.","The additional dog groomer would be","responsible for his/her own purchases and","some equipment but the rent payment","would include the use of all utilities. The","additional groomer has the potential to","match Tomasz’s forecast sales for the year.","Rent £600 per month + an additional fee","of 14% of the groomer’s takings each","month, which is paid to Tomasz.","10% increase in overhead costs that","Tomasz has to pay.","15% increase in depreciation of fixtures","and fittings.","2 – Start to sell pet food and accessories.","This would need a large display area and","storage space.","His research shows there will be demand","for this option. He has based his inventory","turnover forecast on information from a","similar business.","£3 500 average stock, which would be","purchased and then maintained.","Mark-up is 100%.","Inventory turnover forecast is 92 days","(or 4 times a year).","5% increase in overhead costs.","£2 000 initial cost of purchasing display","equipment.","Forecast financial information for the coming year before","options are applied","Item £","Sales","Cost of sales","Net profit before tax","Overhead costs","Fixtures and fittings","34 574","11 616","5 808","17 150","9 140"],"ctxb":[{"t":"p","x":"After moving to his new premises, Tomasz has realised that he has a lot of space that he is not utilising. He would like to increase his overall profit and has researched two options that could make use of the space and increase his profit. Options Costs and revenues 1 – Allow another dog groomer to have space in his shop in return for rent and an additional fee each month. Initial contract would be for six months. The additional dog groomer would be responsible for his/her own purchases and some equipment but the rent payment would include the use of all utilities. The additional groomer has the potential to match Tomasz’s forecast sales for the year. Rent £600 per month + an additional fee of 14% of the groomer’s takings each month, which is paid to Tomasz. 10% increase in overhead costs that Tomasz has to pay. 15% increase in depreciation of fixtures and fittings. 2 – Start to sell pet food and accessories. This would need a large display area and storage space. His research shows there will be demand for this option. He has based his inventory turnover forecast on information from a similar business. £3 500 average stock, which would be purchased and then maintained. Mark-up is 100%. Inventory turnover forecast is 92 days (or 4 times a year). 5% increase in overhead costs. £2 000 initial cost of purchasing display equipment. Forecast financial information for the coming year before"},{"t":"flow","x":["options are applied","Item £","Sales","Cost of sales","Net profit before tax","Overhead costs","Fixtures and fittings","34 574","11 616","5 808","17 150","9 140"]}],"text":"Evaluate which option would be the most profitable for Pet Boutique.","qTotal":12,"ms":{"body":"Answers will be credited according to the\nlearner’s demonstration of knowledge and\nunderstanding of the material, using the\nindicative content and levels descriptors below.\nThe indicative content that follows is not\nprescriptive. Answers may cover some or all of\nthe indicative content but learners should be\nrewarded for other relevant answers.\nIndicative content could include:\nOption 1 Advantages\n• Income from rent would be £7 200 plus\n14% of takings, giving increased revenue\n• Rent for 6 months is guaranteed (£3 600)\n• Increase flexibility\n• No risk involved\nOption 1 Disadvantages\n• Increased overhead costs of £1 715\n• Increased depreciation of fixtures and\nfittings £1 371\n• Might not get increase in sales that are\nforecast\n• No additional fee payable if other groomer\nis not working\n• Contract only for 6 months, may not be\nrenewed by either party so profit would be\nlower than forecast\n• Other groomer could poach customers\nreducing Tomasz’s revenue\nPotential profit increase with a reduction in non-\ncurrent assets of £1 371. But only 6 months’\nrent, £3 600, is guaranteed.\n12\nOption 2 Advantages\n• Profit is £3 500 on his initial stock and all\nsubsequent stock purchased\n• Inventory turnover is 4 so profit will be\n4 x £3 500 = £14 000 on stock\nOption 2 Disadvantages\n• Initial outlay for stock of £3 500 will affect\nhis cash flow\n• Initial cost of display equipment will affect\ncash flow\n• He may need to borrow to cover the initial\noutlay, which will reduce his profit and\naffect cash flow\n• Inventory turnover may not be correct and\naccessories/food may not sell as quickly as\nhe expects, which would impact on his\nforecast profit\n• Storage space for goods and display space\nneeded, which has an impact on cost and\nworking area available\nPotential increase in revenue of £28 000 less\ncosts of £14 000 for stock and £2 000 display\nequipment and £857.50 increase in overhead\ncosts gives potential increase in profit of\n£11 142.50\nOption 2 offers the best potential profit but has a\nlarge outlay that Tomasz may not be able to\nafford without undertaking borrowing. Option 1\noffers less risk in the first 6 months only but sales\nmay still not reach forecast.","levels":12}}],"msMatched":17},{"id":"U3-1901","unit":3,"key":"2019-01","series":"January 2019","date":"January 2019","title":"Mike · Dara","source":"pearson","kind":"exam","total":100,"parsedTotal":95,"sec":{"A":36,"B":64},"items":[{"q":1,"sub":null,"marks":2,"section":"A","ctx":[],"ctxb":[],"text":"State two types of payment card.","qTotal":2,"ms":{"body":"Award 1 mark for each type of payment card stated up to a maximum\nof 2 marks:\n• Debit card (1)\n• Credit card (1)\n• Pre-paid card (1)\n• Store card (1)\n• Charge card (1)\n• Reward cards / Points cards (1) eg Boots , Nectar\n• Contactless cards (1)\nAccept any other appropriate answer.","levels":null}},{"q":2,"sub":null,"marks":2,"section":"A","ctx":[],"ctxb":[],"text":"State two disadvantages to the holder of using Premium Bonds as a form of saving and investment.","qTotal":2,"ms":{"body":"Award 1 mark for each disadvantage of a Premium Bond stated, up to a\nmaximum of 2 marks:\n• Minimum purchase amount is £100 / Minimum purchase is £50 if\npaid by standing order (1)\n• Little chance of winning the top prizes (1)\n• Maximum amount reviewed annually (1)\n• Have to be over 16 to buy them (1)\n• No guaranteed return (1)\n• No interest earned (1)\n• Loses real value due to inflation / loses value due to inflation (1)\n• Total amount limited to £50,000 / Maximum amount limited to\n£50,000\nAccept any other appropriate answer.","levels":null}},{"q":3,"sub":null,"marks":4,"section":"A","ctx":[],"ctxb":[],"text":"Explain two features of a credit union.","qTotal":4,"ms":{"body":"Award 1 mark for identification of a feature of a credit union and 1 mark for an appropriate development of feature. • Credit union is protected by FSCS (1) which means savers will not lose money up to £85 000 (1) • Members have a common interest (1) so decisions made should benefit all members (1) • Credit unions usually offer lower interest rates to borrowers (1) so can offer better deals to customers (1) • as they do not have shareholders to pay dividends to (1). • Offers a range of financial products/services (1) which means customers do not have to use other financial providers (1) • Credit unions are able to help people in specific communities (1) because they are locally based (1) • They do not have shareholders to pay dividends to (1) because they are non-profit making organisations (1). • They are cooperatives (1) because they are controlled by members (1) Accept any other appropriate answer.","levels":null}},{"q":4,"sub":null,"marks":6,"section":"A","ctx":["Over the last three years Darika has used credit cards, an overdraft and a personal","loan to make high cost purchases such as holidays, televisions and a used car. She","now has debts of nearly £8 000 and cannot meet her monthly repayments. Darika has","decided to get help from debt counselling."],"ctxb":[{"t":"p","x":"Over the last three years Darika has used credit cards, an overdraft and a personal loan to make high cost purchases such as holidays, televisions and a used car. She now has debts of nearly £8 000 and cannot meet her monthly repayments. Darika has decided to get help from debt counselling."}],"text":"Discuss the advantages and disadvantages of Darika using debt counselling to help manage her personal debts.","qTotal":6,"ms":{"body":"Points candidates may use are: Advantages • Debt counsellors can inform debt collectors on the client’s behalf, which can give up to 30 days breathing space • Advice is given by professionals • Advice given to help manage current debts • Advice given on how to avoid getting into future debt • Advice is independent so is, therefore, unbiased • Regulated by FCA and FOS, which set standards • Debt counsellors can create a debt management plan • Can be a free service • Can be more personal with a named person (either face to face, via telephone or online • Can help support with managing psychological/mental health related to being in debt Disadvantages • The repayment plans will take longer to repay than the debts – up to seven years • Debt counselling is not free – debt counsellors receive a monthly fee • You cannot get credit while you are undertaking debt counselling • All debt counselling agreements end up in court to get a consent order • You still have to demonstrate to the court that you are making changes to manage your money • Creditors may still not agree to your proposals • Could lose time at work, and therefore, further earnings. Accept any other appropriate answer.","levels":6}},{"q":5,"sub":null,"marks":10,"section":"A","ctx":[],"ctxb":[],"text":"Anita has a standard bank account. Her wages are paid directly into her bank account each month. She pays all her monthly household and utility bills by logging onto her accounts online and using her debit card to pay. She also usually pays for all her weekly shopping using her debit card. 5 Assess the factors that Anita should consider when using a debit card as a method of payment. Your response should: • provide a careful consideration of the factors that apply to Anita’s situation • identify which factors are the most important • provide a supported conclusion.","qTotal":10,"ms":{"body":"Potential factors that learners may consider in their response: Learners may discuss the significance of the relative advantages and disadvantages of using a debit card as a method of payment in the context of the question. Advantages of using debit cards • Can be a convenient and quick method of payment • Can be a secure method of payment with lower risk of theft than some other types of payment • Widely accepted • Can offer some protection on purchases • Suitable for online transactions • Customer knows how much they are spending on each transaction and so can control their expenditure from their account • Debit cards can be cancelled if lost • You cannot spend money that you have not got available in the account Disadvantages of using debit cards • Short time period between transaction and money leaving account • May not be accepted for small transactions or by some • Some retailers have a minimum spend or charge for small amounts • May lose track and spend more than you wanted to unless you check your account balance regularly • May lose track of payment deadlines and could forget which could lead to other problems such as debt or impacting on credit rating • May be more expensive than other methods (such as direct debit) which often offer a discount • May waste time for regular bills such as utilities which could be done automatically so no logging on or contacting the provider to pay • If the card is contactless could be stolen and used • Other methods of payments may offer other benefits that debit cards do not\n28","levels":10}},{"q":6,"sub":null,"marks":12,"section":"A","ctx":["Mike works as a lawyer. He lives with his wife and two teenage children, aged 13 and","17. Both of his children have keys to the house. He has recently had his renewal quote","for his building’s insurance. He feels he can achieve a more competitive quote for a","policy which will better suit his needs.","This table gives some information about products from different insurance organisations.","Insurance","Provider","Annual","Premium £","Compulsory","Excess £","Legal","Assistance","Replacement","Keys","Alternative","Accommodation","Westshire","Insurance","222 200 Included Not included Included","Ashridge","Insurance","175 100 Not included Not included Not included","Shirevale","Insurance","178 150 Not included Included Not included","The Royal","Insurance","253 150 Included Included Included"],"ctxb":[{"t":"p","x":"Mike works as a lawyer. He lives with his wife and two teenage children, aged 13 and 17. Both of his children have keys to the house. He has recently had his renewal quote for his building’s insurance. He feels he can achieve a more competitive quote for a policy which will better suit his needs. This table gives some information about products from different insurance organisations."},{"t":"flow","x":["Insurance","Provider","Annual","Premium £","Compulsory","Excess £","Legal","Assistance","Replacement","Keys","Alternative","Accommodation","Westshire","Insurance","222 200 Included Not included Included","Ashridge","Insurance","175 100 Not included Not included Not included","Shirevale","Insurance","178 150 Not included Included Not included","The Royal","Insurance","253 150 Included Included Included"]}],"text":"Evaluate which insurance package would be the most suitable for Mike.","qTotal":12,"ms":{"body":"Considerations of cost vs benefits offered Annual Premium • Royal Insurance is most expensive • Ashridge Insurance is cheapest Compulsory Excess • Ashridge has lowest excess • Westshire has highest excess • Learners could consider impact of multiple claims Legal Assistance • Learners might consider the benefit of legal assistance given that Mike is a qualified lawyer Replacement Keys • Consideration of the number of key holders which increases likelihood of a lost key • If replacement locks and keys are needed, cost saving will be greater if they are covered Alternative accommodation • If alternative accommodation is needed, the cost of alternative accommodation could be expensive and so greater benefit to have this included.","levels":12}},{"q":7,"sub":null,"marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Identify two types of revenue income for a small business.","qTotal":2,"ms":{"body":"Award 1 mark for each source identified, up to a maximum of 2\nmarks:\n• Cash sales\n• Credit sales\n• Sales*\n• Rent received\n• Commission received\n• Interest received\n• Discount received\n* NB If a mark is given for either of ‘cash sales’ or ‘credit sales’\ndo NOT reward ‘sales’.","levels":null}},{"q":8,"sub":null,"marks":2,"section":"B","ctx":[],"ctxb":[],"text":"State two types of intangible non-current asset that a business could have.","qTotal":2,"ms":{"body":"Award 1 mark for each type identified up to a maximum of 2\nmarks:\n• Goodwill/customer loyalty\n• Patents\n• Copyrights\n• Intellectual property\n• Trademarks\n• Brand name\n• Logo\n• Reputation\n• Business/company name\nAccept any other reasonable answer.","levels":null}},{"q":9,"sub":"a","marks":3,"section":"B","ctx":[],"ctxb":[],"text":"(i) inventory turnover","qTotal":13},{"q":9,"sub":"ii","marks":3,"section":"B","ctx":[],"ctxb":[],"text":"current ratio","qTotal":13},{"q":9,"sub":"iii","marks":2,"section":"B","ctx":[],"ctxb":[],"text":"profit margin","qTotal":13},{"q":9,"sub":"b","marks":3,"section":"B","ctx":["Dara is expanding his range and wants to sell sandwiches to take advantage of the","lunchtime demand.","Dara has produced the following information relating to the production of the","sandwiches:","Selling price of each sandwich £3.80","Cost of filling for each sandwich 50p","Cost of bread for each sandwich 40p","Packaging cost for each sandwich 20p","Sales, in units, to break-even 3 500"],"ctxb":[{"t":"p","x":"Dara is expanding his range and wants to sell sandwiches to take advantage of the lunchtime demand. Dara has produced the following information relating to the production of the sandwiches: Selling price of each sandwich £3.80 Cost of filling for each sandwich 50p Cost of bread for each sandwich 40p Packaging cost for each sandwich 20p Sales, in units, to break-even 3 500"}],"text":"Calculate the annual total fixed cost for making the sandwiches.","qTotal":13},{"q":9,"sub":"c","marks":2,"section":"B","ctx":["Dara is expecting to sell 70 sandwiches a week."],"ctxb":[{"t":"p","x":"Dara is expecting to sell 70 sandwiches a week."}],"text":"Calculate the annual total revenue that selling 70 sandwiches a week would generate for the business.","qTotal":13},{"q":10,"sub":"a","marks":1,"section":"B","ctx":["Dara has produced a cash flow forecast but it is incomplete."],"ctxb":[{"t":"p","x":"Dara has produced a cash flow forecast but it is incomplete."}],"text":"Complete the cash flow forecast for DC’s Coffee. DC’s Coffee Cash flow forecast January 2019 February 2019 March 2019 April 2019 Inflows Sales 5 920 6 200 (iv) 10 100","qTotal":11},{"q":10,"sub":"b","marks":5,"section":"B","ctx":["Bank interest received 0 0 180 0","Total inflow 5 920 6 200 7 130 10 100","Outflows","Wages 1 600 1 600 1 600 1 600","Coffee (i) 1 032 1 194 1 692 (1)","Other inventory 355 372 428 606","Other outflows 1 400 1 507 1 356 1 754","Total outflow 4 081 (iii) 4 578 5 652 (1)","Net cash flow 1 839 1 689 (v) 4 448 (1)","Opening balance (ii) 2 685 4 374 6 926 (1)","Closing balance 2 685 4 374 6 926 (vi) (1)","17","Increases in the cost of his stock items and wages mean that Dara will need to amend","his forecast statement of comprehensive income for the financial year ending","December 2019.","He already has the following information for the year:","£","Sales 101 500","Utilities 4 200","Purchases 39 664","Lease of shop premises 18 000","Wages 19 200","Other costs 1 656","Closing inventory 214","Opening inventory 162","The new forecast statement of comprehensive income will need to take into account:","• a planned 4% increase in wages for the last six months from July to","December 2019","• a prepayment of £3 000 for lease of the shop premises has been made for the","financial year 2020."],"ctxb":[{"t":"grid","head":null,"rows":[["Bank interest received","0","0 180","0"],["Total inflow","5 920","6 200","7 130","10 100"],["Outflows Wages","1 600","1 600","1 600","1 600"],["Coffee","(i)","1 032","1 194","1 692","1"],["Other inventory","355 372 428 606"],["Other outflows","1 400","1 507","1 356","1 754"],["Total outflow","4 081","(iii)","4 578","5 652","1"],["Net cash flow","1 839","1 689","(v)","4 448","1"],["Opening balance","(ii)","2 685","4 374","6 926","1"],["Closing balance","2 685","4 374","6 926","(vi)","1"]]},{"t":"p","x":"17 Increases in the cost of his stock items and wages mean that Dara will need to amend his forecast statement of comprehensive income for the financial year ending December 2019."},{"t":"cap","x":"He already has the following information for the year:"},{"t":"cap","x":"He already has the following information for the year:"},{"t":"grid","head":null,"rows":[["Sales","101 500"],["Utilities","4 200"],["Purchases","39 664"],["Lease of shop premises","18 000"],["Wages","19 200"],["Other costs","1 656"],["Closing inventory","214"],["Opening inventory","162"]]},{"t":"p","x":"The new forecast statement of comprehensive income will need to take into account: • a planned 4% increase in wages for the last six months from July to December 2019 • a prepayment of £3 000 for lease of the shop premises has been made for the financial year 2020."}],"text":"Complete this extract from the new forecast statement of comprehensive income for DC’s Coffee for the year ended 31 December 2019.","qTotal":11,"ms":{"body":"Allocate marks as indicated in the table below NB Accept ‘closing inventory’ as either a positive or negative figure. (5) £ £ Notes for markers Sales 101 500 Opening inventory 162 Purchases 39 664 Closing inventory (i) (214) (1) Accept closing inventory as either positive or negative. Cost of sales 39 612 Gross profit (ii) 61 888 (1) Expenses Lease (iii) 15 000 (1) Wages (iv) 19 584 (1) Utilities 4 200 Other costs 1 656 Total Expenses 40 440 Profit/loss for the year (v) 21 448 ECF (1) ECF applied where error carried forward from calculation of gross profit","levels":null}},{"q":11,"sub":null,"marks":6,"section":"B","ctx":["DC’s Coffee","Forecast statement of comprehensive income for the year ended 31 December 2019","£ £","Sales 101 500","Opening inventory 162","Purchases 39 664","Closing inventory (i) (1)","Cost of goods sold/Cost of sales 39 612","Gross profit/loss (ii) (1)","Expenses","Lease of shop premises (iii) (1)","Wages (iv) (1)","Utilities 4 200","Other costs 1 656","Total expenses 40 440","Profit/Loss for the year (v) (1)","19","Dara is concerned he may have a dishonest employee as he thinks some cash has","gone missing. He is considering buying some computer equipment and software","to give him greater control of the finances of the business. All transactions will be","recorded automatically including those to his credit suppliers and credit customers."],"ctxb":[{"t":"p","x":"DC’s Coffee Forecast statement of comprehensive income for the year ended 31 December 2019"},{"t":"cap","x":"£ £"},{"t":"cap","x":"£ £"},{"t":"grid","head":null,"rows":[["Sales","101 500"],["Opening inventory","162"],["Purchases","39 664"],["Closing inventory","(i)","1"],["Cost of goods sold/Cost of sales","39 612"],["Gross profit/loss","(ii)","1"],["Expenses Lease of shop premises","(iii)","1"],["Wages","(iv)","1"],["Utilities","4 200"],["Other costs","1 656"],["Total expenses","40 440"],["Profit/Loss for the year","(v)","1"]]},{"t":"p","x":"19 Dara is concerned he may have a dishonest employee as he thinks some cash has gone missing. He is considering buying some computer equipment and software to give him greater control of the finances of the business. All transactions will be recorded automatically including those to his credit suppliers and credit customers."}],"text":"Discuss the advantages and disadvantages to a small business of recording financial transactions to help improve the control of the business’ finances.","qTotal":6,"ms":{"body":"Advantages • Record the amount of cash the business should have at any one time which can be compared with the actual amount to reduce the risk of theft • Keep a record of trade payables/ expenses to ensure the correct amounts are paid by the due date • Produce financial statements throughout the year which can then be used to measure performance • Keeps track of stock so orders can be placed when required and to assist with stock takes and reduce loss by theft • Maintain control of expenses so that profit level can be maximized • To be aware of how much Dara owes / is owed • Help comply with any legal requirements Disadvantages • Cost of purchasing and setting up the system • Cost of training the staff • Time spent changing from old system to the new one • Errors in transferring data to the new system • Cost of virus protection/updates Accept any other reasonable response.","levels":6}},{"q":12,"sub":null,"marks":8,"section":"B","ctx":["Dara is considering selling coffee machines to widen his product range. He expects","that this will attract new customers to the coffee shop. He will have to use some of","the coffee shop floor space to display the machines. This will reduce the number","of tables available to customers. He has done some research and estimated the","following figures.","Estimated figures for coffee machines","Selling price of each coffee machine £90","Purchase price of each coffee machine £60","Annual fixed costs £9 000","Estimated annual demand in units 340"],"ctxb":[{"t":"p","x":"Dara is considering selling coffee machines to widen his product range. He expects that this will attract new customers to the coffee shop. He will have to use some of the coffee shop floor space to display the machines. This will reduce the number of tables available to customers. He has done some research and estimated the"},{"t":"cap","x":"following figures. Estimated figures for coffee machines"},{"t":"cap","x":"Estimated figures for coffee machines"},{"t":"grid","head":null,"rows":[["Selling price of each coffee machine","£90"],["Purchase price of each coffee machine","£60"],["Annual fixed costs","£9 000"],["Estimated annual demand in units","340"]]}],"text":"Analyse, using these estimated figures, the impact on profitability of Dara selling coffee machines.","qTotal":8,"ms":{"body":"Advantages • Positive contribution of £30 per coffee machine • Increased contribution of £10 200 • Profit of £1 200 if sales and costs are accurate • Margin of safety of 40 units so the coffee machines should break even if sales are accurate • Increased number of new customers which may increase sales of related goods • Business is less reliant on smaller range of goods Disadvantages • Loss of floor space which may reduce sales of coffee • Small margin of safety which means if sales fall a loss could be made • Customers may be put off by sales displays whilst using the coffee shop • Staff may not have the knowledge/may need training to sell the goods • May not be able to accommodate new customers due reduced floor space • Additional staff may be required • 340 sales is a prediction and may not be accurate","levels":8}},{"q":13,"sub":null,"marks":10,"section":"B","ctx":["Dara has the opportunity to purchase a mobile coffee van in March 2019, which he","can take to markets and events to sell coffee. He is aware that if he buys the van it will","increase his non-current assets. He is worried about the effect this will have on the","liquidity of the business.","He has produced new forecast information to take into account the cost of the van.","Extract of Financial Information for DC’s Coffee","December 2018","(excluding van)","March 2019","(including van)","£ £","Non-current assets 26 108 40 108","Inventory 162 680","Bank 6 847 0","Cash 790 400","Trade receivables 0 80","Bank overdraft 0 2 140","Trade payables 9 136 10 996"],"ctxb":[{"t":"p","x":"Dara has the opportunity to purchase a mobile coffee van in March 2019, which he can take to markets and events to sell coffee. He is aware that if he buys the van it will increase his non-current assets. He is worried about the effect this will have on the liquidity of the business. He has produced new forecast information to take into account the cost of the van."},{"t":"cap","x":"Extract of Financial Information for DC’s Coffee"},{"t":"cap","x":"Extract of Financial Information for DC’s Coffee"},{"t":"grid","head":null,"rows":[["December","2018"],["(excluding van) March","2019"]]},{"t":"cap","x":"(including van) £ £"},{"t":"cap","x":"(including van) £ £"},{"t":"grid","head":null,"rows":[["Non-current assets","26 108","40 108"],["Inventory","162 680"],["Bank","6 847","0"],["Cash","790 400"],["Trade receivables","0","80"],["Bank overdraft","0","2 140"],["Trade payables","9 136","10 996"]]}],"text":"Assess, using the new forecast information produced by Dara, the impact the purchase of the van could have on the liquidity of his business. Your response should: • provide a careful consideration of the factors that apply to Dara’s situation • identify which factors are the most important • provide a supported conclusion.","qTotal":10,"ms":{"body":"Observations In March 2019, the current ratio is forecast to be 0.09:1 and liquid capital ratio is forecast to be 0.04:1. In December 2018, current ratio was 0.85:1 and liquid capital ratio was 0.84:1. Liquidity is compromised and could be a significant concern. It might have been more appropriate to finance the purchase via other methods rather than leave the business short of funds in the short term. There is no expectation of learners to perform calculations although there is an expectation that learners will observe trends. Negative impact • Between December 2018 and forecast March 2019 non-current assets will have increased considerably by the planned purchase of the van, reducing liquidity. • Lower amount of cash in hand. • Trade receivables have increased meaning customers have been given more credit and reducing amount of cash in the business. • Increase in overdraft is predicted possibly due to cash shortages following the purchase of the van. Bank has reduced by £6 847 (£8 987 including overdraft) • Higher inventories forecast in March 2019 spending more cash in order to stock the van • Overdraft fees may be charged • Interest may be charged on any overdraft Positive impact • Trade payables have increased by £1 860 meaning he has extended credit with his suppliers • the business could be working more efficiently/making better use of its resources The biggest impact of the planned purchase of the van will be on non-current assets, reducing liquidity, however other trends such as trade payables will have a positive impact. However improved profits should help increase cash flow in the longer term","levels":10}},{"q":14,"sub":null,"marks":12,"section":"B","ctx":["Dara has decided to buy the van at a cost of £12 000. He has decided to use an","external source of finance to fund this purchase. Dara has read about a business that","successfully used crowdfunding to raise finance for a similar venture."],"ctxb":[{"t":"p","x":"Dara has decided to buy the van at a cost of £12 000. He has decided to use an external source of finance to fund this purchase. Dara has read about a business that successfully used crowdfunding to raise finance for a similar venture."}],"text":"Evaluate whether Dara should use crowdfunding to finance the purchase of the van.","qTotal":12,"ms":{"body":"Advantages of crowdfunding • Can be a quick way to raise finance with no upfront fees • Can be a valuable form of marketing and result in media attention • Get feedback on your idea and expert guidance on how to improve it • Good way to test the public’s reaction to your product/idea • Investors can track your progress, which can help to promote the brand through their networks • Ideas that may not appeal to conventional investors can often get financed more easily • Investors can often become loyal customers through the financing process Disadvantages of crowdfunding • Can take a very long time to raise finance • Some types of crowdfunding involves giving something away (eg equity crowdfunding involves giving away part of the ownership/control/equity of the business in return for funds) • Not all projects that apply to crowdfunding platforms get onto them • You need to do a lot of work in building up interest before the project launches • If you don’t reach your funding target, any finance that has been pledged will usually be returned to your investors and you will receive nothing • Failed projects risk damage to the reputation of your business and people who have pledged money to you • Can be difficult to set the rewards for investors - getting the rewards or returns wrong can mean giving away too much of the business to investors • May be too small an amount to consider using crowdfunding Accept any other appropriate response.\n42","levels":12}}],"msMatched":13},{"id":"U3-1906","unit":3,"key":"2019-06","series":"June 2019","date":"June 2019","title":"Hakim · Lowri","source":"pearson","kind":"exam","total":100,"parsedTotal":101,"sec":{"A":36,"B":64},"items":[{"q":1,"sub":null,"marks":2,"section":"A","ctx":["The Financial Services Compensation Scheme (FSCS) covers business conducted by firms","authorised by UK financial regulators."],"ctxb":[{"t":"p","x":"The Financial Services Compensation Scheme (FSCS) covers business conducted by firms authorised by UK financial regulators."}],"text":"Give two types of financial business that are protected by the Financial Services Compensation Scheme (FSCS).","qTotal":2,"ms":{"body":"Award one mark for each type of financial business, up to a maximum of two marks. • Banks • Building societies • Credit unions • Debt management • Accept Financial products dealing with: o Endowments o Home finance (including mortgage advice) o Insurance o Investments o Payment protection insurance (PPI) o Pensions o Loans","levels":null}},{"q":2,"sub":null,"marks":2,"section":"A","ctx":[],"ctxb":[],"text":"Give two advantages to the consumer of using pawnbrokers.","qTotal":2,"ms":{"body":"Award one mark for each advantage identified, up to a maximum of two marks. • Borrow money against an asset • Quickly sell unwanted assets • Asset can be reclaimed once loan and interest are repaid • Fast method of credit/receiving cash • Do not need a credit check • Will not affect credit score • Receive the money in cash • Items available to purchase below market value • Regulated / protected form of credit Accept any other appropriate response.","levels":null}},{"q":3,"sub":null,"marks":4,"section":"A","ctx":[],"ctxb":[],"text":"Explain two benefits to the consumer of using the Clearing House Automated Payment System (CHAPS).","qTotal":4,"ms":{"body":"Award one mark for identification of a benefit of CHAPS (up to maximum of two marks) and one mark for a reason why it is a benefit to the consumer (up to maximum of two marks). • There is no upper limit to the amount (1) so large amounts of money can be transferred in one payment (1) • It is a fast way of transferring payments (1) as transactions are normally guaranteed to be made in a short time scale/same day (1) • It can be accessed online /branch / telephone (1) so it is a convenient method of payment (1) • Fee may be fixed (1) so can be cost effective method (1) • Guaranteed against fraud (1) so it is secure/safe to use (1) Accept any other appropriate answer.","levels":null}},{"q":4,"sub":null,"marks":6,"section":"A","ctx":[],"ctxb":[],"text":"Discuss the advantages and disadvantages to the consumer of using Citizens Advice as a source of financial advice.","qTotal":6,"ms":{"body":"Indicative content may include: Advantages • Free to use • Located in most major towns • Face to face as well as online • Wide range of financial advice can be provided • Staffed by impartial volunteers. • Not linked to any financial institution Disadvantages • May not be specialists in field • Knowledge may be limited • Advice may be incorrect • Limited hours of operation/may have to wait for an appointment • Advice given is general guidance not legal advice\nLevel Mark Award up to six marks. Refer to the guidance on the cover of this document for how to apply levels–based mark schemes 0 No rewardable material. 1 1–2 • Demonstrates knowledge and understanding of relevant information; there may be major gaps or omissions. • Provides little evidence of weighing up of competing arguments/pros and cons in context; discussion likely to consist of basic description of information. • Meaning may be conveyed but in a non-specialist way; response lacks clarity and fails to provide an adequate answer to the question. 2 3-4 • Demonstrates accurate knowledge and understanding of relevant information with a few gaps or omissions. • Discussion is partially developed, but will be imbalanced. Evidences the weighing up of competing arguments/pros and cons in context. • Demonstrates the use of logical reasoning, clarity, and appropriate specialist technical language. 3 5-6 • Demonstrates accurate and thorough knowledge and understanding of relevant information; any gaps or omissions are minor. • Displays a well-developed and balanced discussion, demonstrating a thorough grasp of competing arguments/pros and cons in context. • Logical reasoning evidenced throughout response which is clear and uses specialist technical language consistently.","levels":null}},{"q":5,"sub":null,"marks":10,"section":"A","ctx":[],"ctxb":[],"text":"Sam regularly shops at his favourite department store. He spends at least £50 per transaction. His annual spend in the store totals approximately £1 500. However, for any large purchases Sam researches prices across different retailers and purchases the goods from whichever retailer offers the best deal. Sam’s favourite department store has offered him the opportunity to sign up for a store card to pay for goods. 5 Assess whether Sam should sign up for a store card as a method of payment. Your response should: • provide a careful consideration of the factors that apply to Sam’s situation • identify which factors are the most important • provide a supported conclusion.","qTotal":10,"ms":{"body":"Indicative content may include: Advantages • Discounts or money-off vouchers often available when using the store card • Get access to promotional events: pre-sales, VIP events • Could build up loyalty points • Access to other promotions such as extended warranties • Build up a credit rating • Instant access to the goods and pay later Disadvantages • Inflexible - can only use store cards to pay for things within that particular department store • Often sold by sales assistants, not financial experts • Higher interest charged if not repaid in full each month • Store cards often charge much higher interest than an average credit card","levels":10}},{"q":6,"sub":null,"marks":12,"section":"A","ctx":["Hakim has inherited £5 000 which he would like to use to start his own business when","he finishes his education in two years’ time. He will need at least this £5 000 to pay for his","start-up costs.","As a student, he is not in a position to add to the £5 000 on a regular basis but he may","receive additional money for birthdays and Christmas that he can add to his savings.","He has researched several options for his savings, which are listed below:","Investment type Minimum/","maximum","opening","amounts","Interest rate Conditions","for","withdrawal","Conditions","for","additional","deposits","Account","access","Shirevale Bank","Fixed Rate","Cash ISA","Minimum –","£100","Maximum –","£5 000","2.35% fixed","for one year","then variable","1 withdrawal","per year but","will incur loss","of 60 days’","interest","No additional","deposits","allowed","In branch","only","Westshire Bank","Fixed Rate","Cash ISA","Minimum –","£100","Maximum –","£20 000","1.75% fixed","for one year","then variable","£50 fee","for any","withdrawal","within first","two years","Funds can be","added at any","time","Internet only","Ashridge Bank","Regular","Saver ISA","Minimum –","£2 000","Maximum –","£20 000","Variable rate","currently","1.75% per","annum","No","penalties for","withdrawals","Must deposit","between £25","and £200","each month","In branch,","telephone or","internet","The Royal Bank","Cash ISA","Minimum –","£1","Maximum –","£20 000","Variable rate","currently","1.6%","No","penalty for","withdrawals","Unlimited","withdrawals","Funds can be","added at any","time","Telephone","and in branch"],"ctxb":[{"t":"p","x":"Hakim has inherited £5 000 which he would like to use to start his own business when he finishes his education in two years’ time. He will need at least this £5 000 to pay for his start-up costs. As a student, he is not in a position to add to the £5 000 on a regular basis but he may receive additional money for birthdays and Christmas that he can add to his savings. He has researched several options for his savings, which are listed below:"},{"t":"flow","x":["Investment type Minimum/","maximum","opening","amounts","Interest rate Conditions","for","withdrawal","Conditions","for","additional","deposits","Account","access","Shirevale Bank","Fixed Rate","Cash ISA","Minimum –","£100","Maximum –","£5 000","2.35% fixed","for one year","then variable","1 withdrawal","per year but","will incur loss","of 60 days’","interest","No additional","deposits","allowed","In branch","only","Westshire Bank","Fixed Rate","Cash ISA","Minimum –","£100","Maximum –","£20 000","1.75% fixed","for one year","then variable","£50 fee","for any","withdrawal","within first","two years","Funds can be","added at any","time","Internet only","Ashridge Bank","Regular","Saver ISA","Minimum –","£2 000","Maximum –","£20 000","Variable rate","currently","1.75% per","annum","No","penalties for","withdrawals","Must deposit","between £25","and £200","each month","In branch,","telephone or","internet","The Royal Bank","Cash ISA","Minimum –","£1","Maximum –","£20 000","Variable rate","currently","1.6%","No","penalty for","withdrawals","Unlimited","withdrawals","Funds can be","added at any","time","Telephone","and in branch"]}],"text":"Evaluate which Individual Savings Account (ISA) will be most suitable for Hakim.","qTotal":12,"ms":{"body":"Shirevale • Can open with any amount between £100 and £5 000 but cannot add in any further deposits beyond £5 000 • Has the best interest rate of 2.35%, which is fixed and thus guaranteed for the first year. It is unlikely that the variable rate will be higher than this within the first year. However we do not know the rate after the first year • Limited access to money – only once a year, which has an interest penalty • Only one that does not allow additional deposits to be made, even if not reached maximum opening amount, which he wants to do • Access is only via branch, which could be inconvenient Westshire Bank Fixed Rate Cash ISA • Maximum deposit is £20 000 , so can continue adding funds up to this amount • 1.75% fixed for one year so return is smaller than Shirevale and could be worse than Ashridge if variable rates were to rise before the end of the first year • Penalty for withdrawals although this may not be an issue as the funds are not to be used for at least two years • Can add to the funds at any time, which could increase the final balance • Internet only, which may not be suitable for his needs although may also be very convenient Ashridge Bank Regular Saver ISA • Maximum deposit is £20 000, so can continue adding funds up to this amount. Minimum deposit is £2 000, which is the highest. • 1.75% interest is highest variable rate but still lower than the best fixed rate • No penalty for withdrawals will allow some flexibility in times of emergency • Additional funds must be added monthly. However, he does not appear to be able to put any extra in which may prevent this option being chosen • It has the best access to the funds – branch, telephone and internet The Royal Bank Cash ISA • Low minimum initial investment. However he wants to put much more in so this may not be a benefit. Maximum deposit is £20 000 , so can continue adding funds up to this amount • 1.6% interest is the lowest but this is most flexible account for adding and withdrawing funds • No restrictions on additional deposits which could help increase the final balance • Unlimited withdrawals may be beneficial in times of emergency • Good access to funds apart from internet (which could be an issue as this might be the most convenient method)","levels":12}},{"q":7,"sub":null,"marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Identify two inflows which could be recorded in a cash flow forecast.","qTotal":2,"ms":{"body":"Award one mark for each inflow identified, up to a maximum of two marks. • Cash sales • Credit sales • Sales/revenue* • Loans • Bank interest received • Capital introduced • Sale of assets • Commission received • Grant • Rental income received *Accept ‘sales’ or ‘revenue’ for one mark where the learner has not used ‘cash sales’ or ‘credit sales’ as their other answer. Accept any other appropriate answer. Graduate Accept any other reasonable response","levels":null}},{"q":8,"sub":null,"marks":2,"section":"B","ctx":[],"ctxb":[],"text":"State two examples of intangible capital expenditure.","qTotal":2,"ms":{"body":"Award one mark for each item up to a maximum of two marks. • Trademark • Goodwill/customer loyalty • Patent • Copyrights • License • Intellectual property • Branding/brand name • Logo • Reputation • Business/company name • Website/domain name Accept any other appropriate answer.","levels":null}},{"q":9,"sub":"a","marks":4,"section":"B","ctx":["Lowri leases a unit on an industrial estate where she prints the sweatshirts that are sold","by her business which is called Lowri Printz. In her first year of trading, her output was","25 000 sweatshirts.","Lowri produced the following financial information for her second year of trading.","Extract of financial information at 31 December 2018","Salaries £133 136","Selling price of each sweatshirt £30","Lease of business premises £40 000","Variable costs per unit £14","Rent £3 064","Other fixed costs £87 800"],"ctxb":[{"t":"p","x":"Lowri leases a unit on an industrial estate where she prints the sweatshirts that are sold by her business which is called Lowri Printz. In her first year of trading, her output was 25 000 sweatshirts. Lowri produced the following financial information for her second year of trading."},{"t":"grid","head":null,"rows":[["Extract of financial information at 31 December","2018"],["Salaries","£133 136"],["Selling price of each sweatshirt","£30"],["Lease of business premises","£40 000"],["Variable costs per unit","£14"],["Rent","£3 064"],["Other fixed costs","£87 800"]]}],"text":"Calculate how many sweatshirts needed to be sold for Lowri Printz to break-even.","qTotal":10,"ms":{"body":"Award four marks for the correct answer • 16 500 units OR Award a maximum of three marks for ECF for any one of the following break-even figures: • 14 000 units (lease not included in fixed costs) • 8 179 units (salaries not included in fixed costs) • 16 309 units (rent not included in fixed costs) • 11 013 units (other fixed costs not included in fixed costs) OR Award a maximum of three marks for ECF where fixed costs have been correctly shown but incorrectly calculated - reward the final answer if the rest of the calculation is correct OR Award a maximum of three marks for ECF where the contribution has been correctly shown but incorrectly calculated - reward the final answer if the rest of the calculation is correct OR Award one mark for formula in words or numbers. • Break-even = Fixed costs / selling price per unit – variable cost per unit OR • Break-even = Fixed costs / contribution per unit OR • Break-even = £133 136 + £40 000 + £3 064 + £87 800 £30 - £14 AND Award one mark for correct calculation of fixed costs • £264 000 AND Award one mark for correct calculation or identification of contribution per unit • £30 - £14 OR • £16 Accept figures with or without the label ‘units’","levels":null}},{"q":9,"sub":"i","marks":4,"section":"B","ctx":[],"ctxb":[],"text":"the total current liabilities (ii) net current assets / liabilities (iii) net assets (iv) capital employed.","qTotal":10},{"q":9,"sub":"i","marks":1,"section":"B","ctx":["Lowri Printz","Statement of financial position at 31 December 2018","£ £ £","Non-current assets Cost Depreciation Net book value (NBV)","Non-current assets","(machinery and","vehicles) 135 800 13 580 122 220","122 220","Current assets","Inventory 5 100","Trade receivables 4 600","Bank 6 240","Cash 780","16 720","Current liabilities","Trade payables 17 300","Accrued expenses 1 400"],"ctxb":[{"t":"p","x":"Lowri Printz Statement of financial position at 31 December 2018 £ £ £ Non-current assets Cost Depreciation Net book value (NBV)"},{"t":"flow","x":["Non-current assets","(machinery and","vehicles) 135 800 13 580 122 220","122 220","Current assets","Inventory 5 100","Trade receivables 4 600","Bank 6 240","Cash 780","16 720","Current liabilities","Trade payables 17 300","Accrued expenses 1 400"]}],"text":"","qTotal":10},{"q":9,"sub":"c","marks":2,"section":"B","ctx":["Net current assets/","liabilities (ii)  (1)","Non-current","liabilities","Bank loan 80 000","Net assets (iii)  (1)","Financed by","Capital 51 040","Retained profit 14 200","Less drawings 25 000","Capital employed (iv)  (1)","Lowri depreciates her non-current assets using the reducing balance method at a rate of","10% per annum."],"ctxb":[{"t":"flow","x":["Net current assets/","liabilities (ii)  (1)","Non-current","liabilities","Bank loan 80 000","Net assets (iii)  (1)","Financed by","Capital 51 040","Retained profit 14 200","Less drawings 25 000","Capital employed (iv)  (1)"]},{"t":"p","x":"Lowri depreciates her non-current assets using the reducing balance method at a rate of 10% per annum."}],"text":"Using the 31 December 2018 net book value (NBV) of £122 220, calculate the expected net book value of her non-current assets at 31 December 2019. Assume that no other non-current assets are bought and that none are sold.","qTotal":10,"ms":{"body":"Award two marks for £109 998 OR Award one mark for calculating the depreciation = £12 222 Accept all answers with or without £ sign.","levels":null}},{"q":10,"sub":"a","marks":2,"section":"B","ctx":["Lowri is now considering making and selling a new product, personalised notebooks. She","believes she can use the existing machinery to produce the notebooks but she will have","to employ an extra part-time member of staff. She has given you the following forecast","information for the notebooks only.","Forecast financial information for the notebooks","All figures relate only to the production of the notebooks","Sales* £43 200","Cost of sales £14 400","Capital employed £21 120","Total expenses £22 360","Current liabilities","Bank","Trade receivables","*50% of all sales were on credit","£2 842","£6 105","£1 406","Using only the forecast financial information for notebooks shown above calculate the","following ratios."],"ctxb":[{"t":"p","x":"Lowri is now considering making and selling a new product, personalised notebooks. She believes she can use the existing machinery to produce the notebooks but she will have to employ an extra part-time member of staff. She has given you the following forecast"},{"t":"cap","x":"information for the notebooks only. Forecast financial information for the notebooks All figures relate only to the production of the notebooks"},{"t":"cap","x":"Forecast financial information for the notebooks All figures relate only to the production of the notebooks"},{"t":"grid","head":null,"rows":[["Sales*","£43 200"],["Cost of sales","£14 400"],["Capital employed","£21 120"],["Total expenses","£22 360"]]},{"t":"grid","head":["Current liabilities","Bank"],"rows":[["£2","842"],["£6","105"],["£1","406"]]},{"t":"p","x":"Using only the forecast financial information for notebooks shown above calculate the following ratios."}],"text":"Calculate the mark-up ratio.","qTotal":14,"ms":{"body":"Award two marks for the correct answer of 200 or 200% OR Award one mark for formula in words or numbers. • Gross profit / cost of sales x 100 • 28 800 / 14 400 x 100 Accept all answers with or without % sign.","levels":null}},{"q":10,"sub":"b","marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Calculate the gross profit margin ratio.","qTotal":14,"ms":{"body":"Award two marks for the correct answer of 66.67%. Accept 67% or any variation on the number of decimal places, e.g. 66.6%, 66.7%, 66.6667%. Do not accept 66% OR Award one mark for formula in words or numbers. • Gross profit / sales x 100 • 28 800 / 43 200 x 100 Accept all answers with or without % sign. Accept formula with ‘revenue’, ‘sales revenue’, or ‘turnover’ instead of ‘sales’.","levels":null}},{"q":10,"sub":"c","marks":4,"section":"B","ctx":[],"ctxb":[],"text":"Calculate the return on capital employed ratio.","qTotal":14,"ms":{"body":"Award four marks for the correct answer of: • 30.49% • 30.5% Also accept 30.4% Accept answer with or without % sign. OR Award one mark for formula of Return on Capital Employed in words • Profit / Capital Employed x 100 AND Award one mark for formula of profit for the year in words or numbers • Gross profit – Total expenses • 28 800 – 22 360 AND Award one mark for correct calculation of profit • 6 440 OR Award three marks for formula of Return on Capital Employed in numbers • 6 440 / 21 120 x 100","levels":null}},{"q":10,"sub":"d","marks":3,"section":"B","ctx":[],"ctxb":[],"text":"Calculate the trade receivable days.","qTotal":14,"ms":{"body":"Award three marks for the correct answer of 24 days Accept the following: • 23.8 days • 23.76 days • 23.758 days OR Award one mark for formula in words • Trade receivables / credit sales x 365 AND Award one mark for calculation of credit sales of • 21 600 OR Award two marks for formula in numbers: • 1 406 / 21 600 x 365 Accept all answers with or without ‘days’.","levels":null}},{"q":10,"sub":"e","marks":3,"section":"B","ctx":["The annual insurance cost for the company costs £840. Three months of this has been","paid for the next financial year."],"ctxb":[{"t":"p","x":"The annual insurance cost for the company costs £840. Three months of this has been paid for the next financial year."}],"text":"Calculate the amount which has been paid for the next financial year.","qTotal":14,"ms":{"body":"Award three marks for the correct answer of 210. OR Award one mark for: • 840 / 12 OR • 70 OR Award two marks for: • 70 * 3 OR • 840 / 12 * 3 OR • 840 / 4","levels":null}},{"q":11,"sub":null,"marks":6,"section":"B","ctx":["At the end of January 2019, Lowri discovers that she cannot use the existing machinery","to produce the notebooks. She will have to purchase new machinery.","She knows that the business had £14 200 retained profit at 31 December 2018. She also","knows that half of her sales are credit sales of up to 60 days."],"ctxb":[{"t":"p","x":"At the end of January 2019, Lowri discovers that she cannot use the existing machinery to produce the notebooks. She will have to purchase new machinery. She knows that the business had £14 200 retained profit at 31 December 2018. She also knows that half of her sales are credit sales of up to 60 days."}],"text":"Discuss the advantages and disadvantages of using retained profit to purchase the new machine.","qTotal":6,"ms":{"body":"• Advantages • It is a method of finance which does not incur interest and does not need to be repaid • It is flexible, owners have complete control over how the retained profits are reinvested and what proportion is kept rather than taken as drawings • Retained profits are less risky than borrowing - loans often require security • Finance may be available immediately – no need for alternative sources of finance Disadvantages • Once used, there will be less capital to use in the business • May take cash which could be better used elsewhere i.e. opportunity cost • The £14 200 of retained profit may not be enough to purchase the machinery • Cash and profits are not the same: o Whilst the company may have made some profit it may have already reinvested it elsewhere o Lowri appears to have taken a great deal of the profit for her own personal use (£25 000) based on the amount of retained profit left o Half of her sales are on credit so this money has not been received despite it increasing profits o They only have £6 240 in the bank and £780 in cash which may not be enough to purchase the machinery or may leave them short of cash in the future\nLevel Mark Award up to six marks. Refer to the guidance on the cover of this document for how to apply levels–based mark schemes 0 No rewardable material. 1 1–2 • Demonstrates isolated knowledge and understanding of relevant information; there may be major gaps or omissions. • Provides little evidence of weighing up of competing arguments/pros and cons in context; discussion likely to consist of basic description of information. • Meaning may be conveyed but in a non-specialist way; response lacks clarity and fails to provide an adequate answer to the question.\n2 3–4 • Demonstrates accurate knowledge and understanding of relevant information with a few gaps or omissions. • Discussion is partially developed, but will be imbalanced. Evidences the weighing up of competing arguments/pros and cons in context. • Demonstrates the use of logical reasoning, clarity, and appropriate specialist technical language. 3 5–6 • Demonstrates accurate and thorough knowledge and understanding of relevant information; any gaps or omissions are minor. • Displays a well-developed and balanced discussion, demonstrating a thorough grasp of competing arguments/pros and cons in context. • Logical reasoning evidenced throughout response which is clear and uses specialist technical language consistently.","levels":null}},{"q":12,"sub":null,"marks":8,"section":"B","ctx":["Lowri has calculated that the break-even point for the sale of notebooks is 3 200 units. She","has forecast sales of 3 600 notebooks. She is concerned that the margin of safety is low."],"ctxb":[{"t":"p","x":"Lowri has calculated that the break-even point for the sale of notebooks is 3 200 units. She has forecast sales of 3 600 notebooks. She is concerned that the margin of safety is low."}],"text":"Analyse possible actions that a small business can take to improve the break-even point and margin of safety.","qTotal":8,"ms":{"body":"Possible actions • Increase selling price, which would increase revenue. • Find a cheaper supplier, which would reduce variable costs. • Reduce staff costs, which would reduce variable costs. • Reduce premises cost/renegotiate lease, which would reduce fixed costs. Reduce expenses, e.g. rent, which would reduce fixed costs. • Reduce other costs, which would reduce variable costs. Do not reward increase sales as forecasted sales are given as 3 600. Potential issues with actions taken • Revenue will only increase if sales levels are maintained. • Revenue may decrease if increased prices cause a fall in sales. • May already have cheapest supplier/other suppliers may not be available. • Existing suppliers may not be willing to negotiate reduced prices. • A cheaper supplier may result in poorer quality products, which could upset customers • May be paying minimum wage so may not be able to reduce this cost further. • Reducing staff costs may result in reduced output. • May be mid-lease and cannot renegotiate further. • Reducing utilities (if possible) may only have limited impact on overall costs.","levels":8}},{"q":13,"sub":null,"marks":10,"section":"B","ctx":["Lowri has decided to go ahead with the production of notebooks. She has updated the","forecast financial information for Lowri Printz to include the notebooks in 2019.","Financial information for Lowri Printz","2017 2018","2019","(Forecast","including","notebooks)","Sales 480 420 750 000 1 039 920","Gross profit 250 315 400 000 582 355","Expenses 136 189 176 200 307 422","Profit for the year 114 126 223 800 274 933","Gross profit margin 52% 53% 56%","Profit margin 24% 30% 26%","Current ratio 1.4:1 1.2:1 1:1","Liquid capital ratio 0.9:1 0.72:1 0.55:1"],"ctxb":[{"t":"p","x":"Lowri has decided to go ahead with the production of notebooks. She has updated the forecast financial information for Lowri Printz to include the notebooks in 2019."},{"t":"flow","x":["Financial information for Lowri Printz","2017 2018","2019","(Forecast","including","notebooks)","Sales 480 420 750 000 1 039 920","Gross profit 250 315 400 000 582 355","Expenses 136 189 176 200 307 422","Profit for the year 114 126 223 800 274 933","Gross profit margin 52% 53% 56%","Profit margin 24% 30% 26%","Current ratio 1.4:1 1.2:1 1:1","Liquid capital ratio 0.9:1 0.72:1 0.55:1"]}],"text":"Assess the impact that producing and selling the notebooks will have on the profitability of the business. Your response should: • provide a careful consideration of the factors that apply to Lowri’s situation • identify which factors are the most important • provide a supported conclusion.","qTotal":10,"ms":{"body":"Indicative content may include: • Sales have increased and are forecast to continue to increase by £289 920, which means the business is gaining more customers/sales so can increase market share. • Gross profit has increased and has a significant increase forecast for 2019 by £182 355, which means the sales of the notebooks will add to the gross profit of the business. • Expenses increased by £40 011 and are forecast to increase by £131 222 as a result of selling the notebooks. This will reduce the profit margin. • Profit for the year increased by £109 674 and is forecast to continue to increase by £51 133, which means that adding the notebooks is forecast to improve profitability. • Gross profit margin had a small increase but then is forecast to increase by 3%. This shows that the notebooks are forecast to help with an increase the overall gross profit margin. • Profit for the year ratio is forecast to fall significantly by 4%. This shows that the notebooks are forecast to add significantly to the running costs of the business. • Overall, the notebooks are forecast to increase sales revenue and profitability. However, it is a forecast and the figures may not be accurate.","levels":10}},{"q":14,"sub":null,"marks":12,"section":"B","ctx":["Lowri feels that offering 60 days’ credit to her customers has been important in increasing","sales. Many of her competitors offer 30 days’ credit and she is wondering if she should","do the same. She has noticed that the business goes overdrawn frequently. She has","negotiated an agreed £5 000 overdraft with her bank. The interest rate on the overdraft is","12.5% with no other fees charged."],"ctxb":[{"t":"p","x":"Lowri feels that offering 60 days’ credit to her customers has been important in increasing sales. Many of her competitors offer 30 days’ credit and she is wondering if she should do the same. She has noticed that the business goes overdrawn frequently. She has negotiated an agreed £5 000 overdraft with her bank. The interest rate on the overdraft is 12.5% with no other fees charged."}],"text":"Evaluate whether Lowri should reduce her customers credit period from 60 days to 30 days or continue to use an overdraft in order to manage her cash flow.","qTotal":12,"ms":{"body":"Benefits of reducing the credit period • Less risk of bad debts • Improved cash flow as not waiting as long for customer payments • May save in bank charges and overdraft interest • May help avoid being late with any payments if funds are not available Drawbacks of reducing the credit period • May lose sales as the credit period might be a strong USP for her customers Benefits of using the overdraft • Only paying interest on the amount overdrawn • Flexibility of overdraft being used when needed Drawbacks of using bank overdraft • Agreed overdraft does not appear to be enough for her needs • Repayable on demand • Interest rates are quite high • Additional charges and interest reduce profit • Temptation to overspend","levels":12}}],"msMatched":19},{"id":"U3-2001","unit":3,"key":"2020-01","series":"January 2020","date":"January 2020","title":"James · Ruksana · Silva","source":"pearson","kind":"exam","total":100,"parsedTotal":101,"sec":{"A":36,"B":64},"items":[{"q":1,"sub":null,"marks":2,"section":"A","ctx":[],"ctxb":[],"text":"Give two functions of money.","qTotal":2,"ms":{"body":"Award one mark for each function of money given, up to a maximum of two marks: • Unit of account (1) • Store/unit/measure of value/deposit (1) • Legal tender (1) • Basis of credit/loans/borrowing (1) • Pay for goods / services / means of exchange (1) Accept any other appropriate response.","levels":null}},{"q":2,"sub":null,"marks":2,"section":"A","ctx":[],"ctxb":[],"text":"State two advantages to the consumer of using the Financial Ombudsman Service (FOS) for support in a complaint against a financial organisation.","qTotal":2,"ms":{"body":"Award one mark for each advantage of using the Financial Ombudsman Service (FOS) stated, up to a maximum of two marks: • Free to use (1) • Unbiased / impartial (1) • Help/advice in resolving the issue (1) • Expert / professional / trained advisors (1) • Accessible to anyone (1) • Makes the final decision on cases (1) Accept any other appropriate response.","levels":null}},{"q":3,"sub":null,"marks":4,"section":"A","ctx":[],"ctxb":[],"text":"Explain two disadvantages to the consumer of using pre-paid cards.","qTotal":4,"ms":{"body":"Award one mark for identification of a disadvantage to the consumer of using a pre-paid card and one mark for a reason why it is a disadvantage: • Can be expensive (1) because different fees associated with getting and using the card (1) • Purchases are limited to the amount on the card (1) therefore spending is limited (1) • Some cards have maximum amounts which can be loaded onto the card (1) which limits its use (1) • Less protection than credit cards (1) because pre-paid cards are not covered by Consumer Credit Act (1) • Inconvenient/time consuming (1) because money has to be added to the card (1) • Some prepaid cards have an expiry date (1) which means any money left on the card after expiry could be lost/unused (1) • Some prepaid cards only work for one specific store (1) which limits its use (1) , Accept any other appropriate response.","levels":null}},{"q":4,"sub":null,"marks":6,"section":"A","ctx":["Consumers often use price comparison websites before purchasing electrical items."],"ctxb":[{"t":"p","x":"Consumers often use price comparison websites before purchasing electrical items."}],"text":"Discuss the advantages and disadvantages to the consumer of using price comparison websites.","qTotal":6,"ms":{"body":"Advantages • Quick / easy to access • Can be accessed anywhere with internet connection • Available 24/7 • Can make multiple comparisons of different retailers in one search • Saves money by finding cheapest option • Use of filter can allow like for like comparisons • Can use the reviews to support decision to buy • Further discounts/offers/incentives may be available Disadvantages • Not all retailers will be shown • Not all products may be listed • Product might be unavailable/discontinued • No opportunity to negotiate • Specialist advice unavailable • May not compare like-for-like features such as guarantees • Could be other costs not shown in the headline price (e.g. delivery) • Information could be outdated • Could be biased if companies are able to pay to have their products given priority • Product information might be more limited Accept any other appropriate response.","levels":6}},{"q":5,"sub":null,"marks":10,"section":"A","ctx":[],"ctxb":[],"text":"Rob has recently inherited £10 000. He is considering investing it into shares. Rob has two children aged three and five. He wants to provide £30 000 to contribute towards any future university fees. 5 Assess the suitability of Rob investing his inheritance by purchasing shares. Your response should: • provide a careful consideration of the factors that apply to Rob’s situation • identify which factors are the most important • provide a supported conclusion.","qTotal":10,"ms":{"body":"Benefits • The value of shares tend to go up in value over the long term • Companies may pay dividends each year which will increase the value of his inheritance • Any dividends can have a higher return than the interest received on savings • Shares may offer the opportunity of short-term rapid increase in value • If the shares have been purchased in a plc they can be sold easily on the stock exchange • May be able to influence the way the business is run by using any voting rights he might have • Rob can spread the risk by buying shares in a range of companies Drawbacks • Dividends may not be paid at all as it is discretionary • If a company was to go into liquidation Rob could lose all of his investment • Rob cannot access his money without selling shares which could cause him to lose money if the share price was lower than when he purchased them • May not be willing to risk losing the money given he has a young family • Shares may need more active management in order to maximise investment • If the shares have been purchased in a Ltd it is harder to sell the shares • Relatively small amount to invest so it is harder to spread the risk • Regular share dealing will incur costs • Inflation could erode the value of the investment","levels":10}},{"q":6,"sub":null,"marks":12,"section":"A","ctx":["James has a full time job earning a monthly salary. He lives near a busy main road. He has","a cat which is 18 months old. The cat was purchased as a kitten at a cost of £450. The cat","is quite adventurous and goes out for long periods of the day.","James has researched four different pet insurance providers. This information is","shown below.","Insurance provider Annual","cost Vet fees cover Loss / stolen","cover Excess*","Ashridge £39 Up to £2 000 per condition None £75","Shirevale £68 Up to £1 000 per condition Up to £400 £60","The Royal Insurance £95 Up to £2 000 per condition Up to £550 £50","Westshire £127 Up to £4 000 per condition Up to £800 £25","*Excess is the amount a pet owner pays towards any insurance claim made."],"ctxb":[{"t":"p","x":"James has a full time job earning a monthly salary. He lives near a busy main road. He has a cat which is 18 months old. The cat was purchased as a kitten at a cost of £450. The cat is quite adventurous and goes out for long periods of the day. James has researched four different pet insurance providers. This information is"},{"t":"cap","x":"shown below. Insurance provider Annual cost Vet fees cover Loss / stolen cover Excess*"},{"t":"cap","x":"Insurance provider Annual cost Vet fees cover Loss / stolen cover Excess*"},{"t":"grid","head":null,"rows":[["Ashridge £39 Up to £2 000 per condition None","£75"],["Shirevale £68 Up to £1 000 per condition Up to","£400","£60"]]},{"t":"p","x":"The Royal Insurance £95 Up to £2 000 per condition Up to £550 £50 Westshire £127 Up to £4 000 per condition Up to £800 £25 *Excess is the amount a pet owner pays towards any insurance claim made."}],"text":"Evaluate which pet insurance provider would be the most suitable for James.","qTotal":12,"ms":{"body":"Ashridge • Cheapest of the four • The vet fee cover is £2 000 • No loss/stolen cover which could be an issue given the location near a busy road and the cat cost £450 • Has the highest excess of £75 Shirevale • Second cheapest • Lowest cover for vet fees of £1 000 • Second lowest loss/stolen cover of £400 which does not cover the original cost of the cat • Second highest excess of £60 The Royal Insurance • Second most expensive • The vet fee cover is £2 000 which is average • Second highest loss/stolen cover of £550 which is more than the original cost of the cat • second lowest excess of £50 Westshire • most expensive • provides best vet fee cover of £4 000 • provides highest loss/stolen cover of £800 which is more than the original cost of the cat • lowest excess of £25\nsome may be lacking support. • Demonstrates the use of logical reasoning, clarity, and appropriate specialist technical language . Level 3 8–10 • Demonstrates accurate and thorough knowledge and understanding of relevant information; any gaps or omissions are minor. • Evidences thorough application containing linkages and interrelationships between factors leading to a judgement/judgements being made. • Displays a well-developed and balanced assessment leading to rationalised judgements on significance. • Demonstrates the use of logical reasoning, clarity, and appropriate specialist technical language.","levels":12}},{"q":7,"sub":null,"marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Identify two features of a debenture.","qTotal":2,"ms":{"body":"Award one mark for each feature identified, up to a maximum of two marks: • Medium-long term source of finance / borrowing (1) • Fixed repayments (1) • Interest is charged/paid (1) • Repayment date is specified (1) • Can be secured against non-current assets (1) • Does not give voting rights (1) • Usually for large amounts (1) • Adds to debt of a company (1) Accept any other appropriate response.","levels":null}},{"q":8,"sub":null,"marks":2,"section":"B","ctx":["Many businesses offer a prompt payment discount to credit customers who pay within a","short period of time."],"ctxb":[{"t":"p","x":"Many businesses offer a prompt payment discount to credit customers who pay within a short period of time."}],"text":"State two effects that a ‘discount allowed’ being offered to customers will have on the accounts of a business.","qTotal":2,"ms":{"body":"Award one mark for each effect up to a maximum of two marks: • Increases expenses (1) • Reduces profit for the year / net profit (1) • Improves cash flow / liquidity (1) • Reduces the risk of debts not being paid (1) Accept any other appropriate response. Do not award a mark where candidates state effects of trade discounts e.g. bulk buying discounts Do not award a mark for increases/decreases revenue","levels":null}},{"q":9,"sub":"i","marks":4,"section":"B","ctx":[],"ctxb":[],"text":"opening inventory (ii) gross profit (iii) heating and lighting expense (iv) profit for the year.","qTotal":14},{"q":9,"sub":"i","marks":5,"section":"B","ctx":[],"ctxb":[],"text":"vehicle cost (ii) equipment depreciation (iii) total net book value (iv) trade receivables (v) net current assets / liabilities.","qTotal":14},{"q":9,"sub":"iii","marks":1,"section":"B","ctx":["Silva","Extract from the Statement of Financial Position at 31 December 2019","Cost Depreciation Net book value","(£) (£) (£)","Non-current assets","Vehicle (i)  (1) 4 500 5 500","Fixtures and fittings 5 000 2 500 2 500","Equipment 9 500 (ii)  (1) 6 000"],"ctxb":[{"t":"p","x":"Silva Extract from the Statement of Financial Position at 31 December 2019"},{"t":"cap","x":"Cost Depreciation Net book value (£) (£) (£) Non-current assets"},{"t":"cap","x":"Cost Depreciation Net book value (£) (£) (£) Non-current assets"},{"t":"grid","head":null,"rows":[["Vehicle","(i)","1","4 500","5 500"],["Fixtures and fittings","5 000","2 500","2 500"],["Equipment","9 500","(ii)","1","6 000"]]}],"text":"","qTotal":14},{"q":9,"sub":"c","marks":3,"section":"B","ctx":["Current assets","Inventory 3 496","Trade receivables (iv)  (1)","Cash at bank 1 540","Cash in hand 160","6 296","Current liabilities","Trade payables 2 624","Net current (v)  (1)","assets/liabilities","Non-current liabilities","Loan 2 100","Net assets 15 572","17","To answer Questions 9(c) and 9(d), you will need to use the information in the:","• Statement of Comprehensive Income","• Extract from the Statement of Financial Position."],"ctxb":[{"t":"cap","x":"Current assets"},{"t":"cap","x":"Current assets"},{"t":"grid","head":null,"rows":[["Inventory","3 496"],["Trade receivables","(iv)","1"],["Cash at bank","1 540"],["Cash in hand","160"]]},{"t":"grid","head":["","6","296"],"rows":[["Trade payables","2 624"],["Net current","(v)","1"]]},{"t":"cap","x":"assets/liabilities Non-current liabilities"},{"t":"cap","x":"assets/liabilities Non-current liabilities"},{"t":"grid","head":null,"rows":[["Loan","2 100"],["Net assets","15 572"]]},{"t":"p","x":"17 To answer Questions 9(c) and 9(d), you will need to use the information in the: • Statement of Comprehensive Income • Extract from the Statement of Financial Position."}],"text":"Calculate the liquid capital ratio.","qTotal":14,"ms":{"body":"Award three marks for the correct response of • 1.07:1 • 1.1:1 Accept without answer being shown as a ratio e.g.: • 1.07 • 1.1 Accept any of the above conventions where the figure is given to a more accurate decimal place (e.g. 1.067073:1) OR Award one mark for the correct formula in words or numbers: • Liquid capital ratio = (Current assets – inventory) / current liabilities Liquid capital ratio = (£6 296 – £3 496) / £2 624 AND Award one mark for the correct calculation of liquid assets of £2 800 NB. £ is not required","levels":null}},{"q":9,"sub":"d","marks":2,"section":"B","ctx":["All of Silva’s purchases are made on credit from its supplier."],"ctxb":[{"t":"p","x":"All of Silva’s purchases are made on credit from its supplier."}],"text":"Calculate the trade payables days ratio.","qTotal":14,"ms":{"body":"Award two marks for the correct response of • 55 days or • 54.7 days or • 54.73 days Accept with or without the label of days Accept any of the above conventions where the figure is given to a more accurate decimal place (e.g. 54.729122) OR Award one mark for the correct formula in words or figures: • Trade payable days = trade payables / credit purchases * 365 £2 624 * 365 £17 500 NB. £ is not required","levels":null}},{"q":10,"sub":"a","marks":4,"section":"B","ctx":["Ruksana is considering selling potted plants to go with the flowers as she believes there","is a potential demand.","She has done some calculations and come up with the following figures.","Annual fixed costs £5 100","Cost of each plant £5.50","Cost of pot and soil required for each plant £2.50","Selling price of each unit £14"],"ctxb":[{"t":"p","x":"Ruksana is considering selling potted plants to go with the flowers as she believes there is a potential demand. She has done some calculations and come up with the following figures."},{"t":"grid","head":null,"rows":[["Annual fixed costs","£5 100"],["Cost of each plant","£5.50"],["Cost of pot and soil required for each plant","£2.50"],["Selling price of each unit","£14"]]}],"text":"Calculate the sales needed to break-even.","qTotal":10,"ms":{"body":"Award four marks for the correct answer of 850 units Accept with or without the label of units OR Award three marks for answer of 444 units (where plant cost (£5.50 missed) Award three marks for answer of 600 units (where pot and soil cost (£2.50 missed) OR Award three marks for 5 100 / £6 OR Award two marks for 5 100 / (£14 – £8) OR\nAward one mark for formula in numbers or words: - Break even = 5 100 / (£14 – (£5.50 + £2.50)) - Break even = Fixed costs / selling price – variable cost - Break even = Fixed costs / contribution per unit AND Award one further mark for the calculation of the variable cost per unit of £8 AND Award one further mark for calculation of the contribution of £6 NB. £ is not required","levels":null}},{"q":10,"sub":"b","marks":3,"section":"B","ctx":["Ruksana is expecting to sell 30 potted plants per week."],"ctxb":[{"t":"p","x":"Ruksana is expecting to sell 30 potted plants per week."}],"text":"Calculate the margin of safety for the year.","qTotal":10,"ms":{"body":"Award three marks for 710 units Accept with or without the label of units OR Award three marks where 1 560 – (candidate’s ECF from 10a) = correct answer (ECF) OR Award one mark for formula in words or numbers: Margin of safety = expected sales – break-even quantity Margin of safety = (30 x 52) – 850 (ECF from 10a) AND Award one mark for correct calculation of expected annual sales of 1 560 NB: Do not accept “sales revenue” as part of the formula in words.\nQuestion number Answer mark 10 (c) Award three marks for £800 OR Award one mark for formula in words: Profit = Revenue – (Total variable costs + Fixed Costs) OR Award one mark for the formula in numbers Profit = £5 000 –(£3 600+£600) AND Award up to one further mark for calculation of total costs of £4 200 NB. £ is not required","levels":null}},{"q":10,"sub":"c","marks":3,"section":"B","ctx":["Ruksana has been offered a contract to supply flowers to a local business. The","contract is worth £5 000 in revenue. She must supply 800 bunches of flowers which","will cost her £3 600.","She will have to pay an additional £600 in fixed costs."],"ctxb":[{"t":"p","x":"Ruksana has been offered a contract to supply flowers to a local business. The contract is worth £5 000 in revenue. She must supply 800 bunches of flowers which will cost her £3 600. She will have to pay an additional £600 in fixed costs."}],"text":"Calculate the amount of profit the order will be worth.","qTotal":10},{"q":11,"sub":null,"marks":6,"section":"B","ctx":["Ruksana has been told she should be using ratio analysis to measure Silva’s","business performance."],"ctxb":[{"t":"p","x":"Ruksana has been told she should be using ratio analysis to measure Silva’s business performance."}],"text":"Discuss the advantages and disadvantages of using ratios as a tool to measure the performance of a business such as Silva.","qTotal":6,"ms":{"body":"Advantages • Provides a systematic approach to analysing performance • Simplifies the interpretation of financial statements • Allows comparison of companies • Allows comparison of business performance over time • Provides summarised data for stakeholders • Enables benchmarking • Identifies the financial strengths and weaknesses of a business Disadvantages • Ratios are quantitative – they do not show qualitative data • Ratios look at the past, not the future • Comparable information is not always available • Financial information can be manipulated • Accounting Standards allow different accounting policies, which impairs comparability Accept any other appropriate response.","levels":6}},{"q":12,"sub":null,"marks":8,"section":"B","ctx":["Ruksana knows that Silva’s most popular bouquet of flowers sells for £13 per bouquet.","The flowers cost her £8 to purchase from her supplier. She has estimated her fixed costs","for next year to be £24 000."],"ctxb":[{"t":"p","x":"Ruksana knows that Silva’s most popular bouquet of flowers sells for £13 per bouquet. The flowers cost her £8 to purchase from her supplier. She has estimated her fixed costs for next year to be £24 000."}],"text":"Analyse why it is important for a small business such as Silva to know the contribution per unit of the products it sells.","qTotal":8,"ms":{"body":"• Allows judgements to be made on the selling price based on contribution – if her most popular product is not selling as well as expected she may need to reduce the price • Allows review of variable cost per unit although control of this is with the supplier • Allows review of variable cost to decide if they should switch supplier • Enables you to calculate break-even point (4 800 for her most popular flowers) • Target setting tool based on break-even point e.g. selling 14 bouquets a day of her most popular flowers would achieve break even • Helps with overall planning by making predictions • The contribution per unit will vary for different products i.e. £5 for her most popular product gives a break-even figure of 4 800 if she only sold this product (or learner may use £6 (OFR) for potted plants from Q10) • Contribution will be affected by sales promotions/trade discounts • Enables comparison of profitability of different products • Enables decisions on introducing/discontinuing products Reward any figures that the learner might have used in the correct context as application to the scenario\n3 5–6 • Demonstrates accurate and thorough knowledge and understanding of relevant information; any gaps or omissions are minor. • Displays a well-developed and balanced discussion, demonstrating a thorough grasp of competing arguments/pros and cons in context. • Logical reasoning evidenced throughout response which is clear and uses specialist technical language consistently.","levels":null}},{"q":13,"sub":null,"marks":10,"section":"B","ctx":["Ruksana has started selling flowers to local businesses. These customers insist on a credit","period of 60 days, which will affect her cash flow.","Ruksana is considering using an invoice discounting company. The company has offered","her 80% of the value of her credit invoices to be paid immediately.","She has produced some new forecast information based on these business customers","and the impact of the invoice discounting.","Extract of forecast financial information","for Silva for the three months to 31 March 2020","January February March","£ £ £","Credit sales 1 260 1 380 1 480","Amount received 1 008 1 104 1 184","Amount payable to","finance company 252 276 296"],"ctxb":[{"t":"p","x":"Ruksana has started selling flowers to local businesses. These customers insist on a credit period of 60 days, which will affect her cash flow. Ruksana is considering using an invoice discounting company. The company has offered her 80% of the value of her credit invoices to be paid immediately. She has produced some new forecast information based on these business customers and the impact of the invoice discounting. Extract of forecast financial information for Silva for the three months to 31 March 2020"},{"t":"grid","head":["","January","February","March"],"rows":[["Credit sales","1 260","1 380","1 480"],["Amount received","1 008","1 104","1 184"],["Amount payable to finance company","252 276 296"]]}],"text":"Assess the impact invoice discounting will have on the business’s profitability and liquidity. Your response should: • provide a careful consideration of the factors that apply to Silva’s situation • identify which factors are the most important • provide a supported conclusion.","qTotal":10,"ms":{"body":"• Cash flow improves because inflow is immediate rather than 60 days delay e.g. after the first two months Silva’s cash flow will be £2 112 (£1 008+£1 104) better off than if she did not do invoice discounting • Once Silva’s cash flow improves it can stop using invoice discounting • Profits will be reduced for each month by the amounts payable to the invoicing discounting company • The charge of 20% on invoices is expensive – it may be cheaper to borrow/use an overdraft to reduce expenses • The improved cash flow could allow Silva to negotiate better deals by paying its suppliers earlier which would improve profitability • May not be accepted as only has limited credit collection experience so may be seen as risky to the business offering invoice discounting • Could be other hidden costs which will further reduce profit and liquidity • Customers do not know about the transaction so are unaffected unlike with debt factoring","levels":8}},{"q":14,"sub":null,"marks":12,"section":"B","ctx":["Silva’s current premises are too small. Ruksana has found a new property that meets","the business’s needs. She has two options for acquiring the property.","Option 1","Renting the property on a five-year lease. The rent is fixed at a cost of £1 000","per month.","Option 2","Buying the property on a 20 year variable rate mortgage. At current interest rates","this will cost £1 800 per month."],"ctxb":[{"t":"p","x":"Silva’s current premises are too small. Ruksana has found a new property that meets the business’s needs. She has two options for acquiring the property. Option 1 Renting the property on a five-year lease. The rent is fixed at a cost of £1 000 per month. Option 2 Buying the property on a 20 year variable rate mortgage. At current interest rates this will cost £1 800 per month."}],"text":"Evaluate whether Silva should lease the property (Option 1) or buy the property (Option 2).","qTotal":12,"ms":{"body":"Advantages of leasing property • £800 a month cheaper than the mortgage repayments • Appropriate for a small company with cash flow issues • Short-term lease could mean the business can leave the property if needed • Lease may be extended beyond the five years Disadvantages of leasing property • At the end of the five-year lease the business could be asked to vacate the premises • Lease costs are likely to increase at the end of the five years • Significant costs of moving the business could have to be paid on multiple occasions • Do not own the property so does not improve the value of the business • Does not give long term stability if the business has to relocate at the end of the lease • Will face additional costs if the business tries to end the lease early Advantages of mortgage property • Property is an asset and shown on the statement of financial position increasing the value of the business • Could benefit from increasing property prices • Provides long-term stability • After 20 years the business will own the property • Relocation costs will be a one-off • Provides flexibility as the property can be sold depending on business needs Disadvantages of mortgage property • £800 a month more expensive although this could change dependent on interest rates • May be more expensive than it can afford • Significant deposit might be required that the business may not have • Could lose the property if it defaults on the mortgage repayments • Property values can decrease","levels":12}}],"msMatched":16},{"id":"U3-2101","unit":3,"key":"2021-01","series":"January 2021","date":"January 2021","title":"Yasin · Shedz · Mike · Palindrone","source":"pearson","kind":"exam","total":80,"parsedTotal":80,"sec":{"A":28,"B":52},"items":[{"q":1,"sub":null,"marks":2,"section":"A","ctx":["Personal Finance"],"ctxb":[{"t":"p","x":"Personal Finance"}],"text":"State two organisations that provide consumer protection in relation to personal finance.","qTotal":2,"ms":{"body":"Award one mark for each correct organisation given, up to a maximum\nof two marks:\n• Financial Conduct Authority (FCA) (1)\n• Financial Ombudsmen Service (FOS) (1) We will accept this\nresponse without the word service.\n• Financial Services Compensation Scheme (FSCS) (1)\nWe can accept either the wording or the abbreviation.\nGraduate","levels":null}},{"q":2,"sub":null,"marks":2,"section":"A","ctx":[],"ctxb":[],"text":"Give two advantages to the consumer of using gilts as a form of saving.","qTotal":2,"ms":{"body":"Award one mark for each advantage for the consumer of using gilts as a\nmethod of saving, up to a maximum of two marks:\n• Fixed interest / earn interest (1)\n• Regular / guaranteed income (1)\n• Low risk (safe/ secure / protected) (1) any mention of low risk\nwill be credited as correct.\n• Know when you will get your investment back (1)\n• Can be sold at any time / savings can be accessed (1)\nAccept any other appropriate response.\nGraduate","levels":null}},{"q":3,"sub":null,"marks":2,"section":"A","ctx":[],"ctxb":[],"text":"Give two ways an investor can financially benefit from buying shares in a business.","qTotal":2,"ms":{"body":"Award one mark for each correct answer given, up to a maximum of\ntwo marks:\n• Share price increasing in value since original purchase (1)\n• Dividends paid by company to the investor (1)\n• Return from an investment could be greater than interest\nreceived from a bank (1)\n• Could receive a bonus issue of shares (1)\n• Could receive discounts on the company’s products / services (1)\nAccept any other appropriate response.\nGraduate","levels":null}},{"q":4,"sub":null,"marks":4,"section":"A","ctx":[],"ctxb":[],"text":"Explain two advantages to the consumer of visiting a bank branch in person.","qTotal":4},{"q":5,"sub":null,"marks":6,"section":"A","ctx":["Stefani often goes on holiday. She has a credit card with an outstanding balance, that","increases when she pays for her holidays. Stefani usually finds an offer that has","0% interest on balance transfers. She then transfers the balance of her existing credit card","account to a new credit card company. These offers usually last for 12 months, then the","interest rate changes to the company’s standard interest rate. There is usually a small fee","charged for the balance transfer.","Stefani has often done this sort of balance transfer in recent years. Moving her credit card","balance has saved her money on interest repayments. However, the credit card balance","has now reached its limit of £8 000. Stefani has saved approximately £1 000 to repay part","of the balance owing. She has saved some of this money by not paying interest."],"ctxb":[{"t":"p","x":"Stefani often goes on holiday. She has a credit card with an outstanding balance, that increases when she pays for her holidays. Stefani usually finds an offer that has 0% interest on balance transfers. She then transfers the balance of her existing credit card account to a new credit card company. These offers usually last for 12 months, then the interest rate changes to the company’s standard interest rate. There is usually a small fee charged for the balance transfer. Stefani has often done this sort of balance transfer in recent years. Moving her credit card balance has saved her money on interest repayments. However, the credit card balance has now reached its limit of £8 000. Stefani has saved approximately £1 000 to repay part of the balance owing. She has saved some of this money by not paying interest."}],"text":"Discuss whether Stefani should continue to transfer her outstanding credit card balance to a new provider.","qTotal":6,"ms":{"body":"Advantages of transferring credit card balances to a new credit card provider\n• Lower interest rates means paying less interest on existing debt. If Stefani can get a 0% card\nshe could get a year’s credit for free (minus any fees)\n• Many providers offer additional incentive to encourage balance transfers\n• Put the money saved from 0% interest into a savings account and earn money on it\n• Consolidate any other debts into one payment\n• May get an increased limit by switching provider which could positively impact on her credit\nscore if payments are maintained\nDisadvantages of transferring credit card balances to a new credit card provider\n• May encourage excessive borrowing if credit limits are increased\n• Inability to find a 0% balance transfer offer could prove very expensive\n• Transfer limit usually applies so she can only transfer so much\n• Credit card provider might try and encourage the purchase of additional products, which she\nmight not need (e.g. fraud protection)\n• Other purchases made on the card may be charged at the standard rate of interest\n• Increasing her credit card balance may affect Stefani’s credit rating/score, which could affect\nher ability to access other products, e.g. mortgages, personal loans\nOther relevant comments\n• Given recent lockdown issues it might mean Stefani has been unable to go on holidays. She\nmay have had the opportunity to reduce the outstanding balance. This could reduce any\nconcerns she might have had about the amount owing. It might also make it easier to get\nhold of a new card if the amount she owes is smaller.\n• What if she is made redundant / furloughed?\n•\nAccept any other appropriate response.\nExpert\n28","levels":6}},{"q":6,"sub":null,"marks":12,"section":"A","ctx":["Yasin is 26 years old and has had a driving licence for six years. Yasin has never had a car","accident and he has never made a claim on his car insurance. His car is now quite old.","Yasin lives in an area where car theft has increased in recent years.","Yasin’s car insurance is due to be renewed. He has used his current insurance provider,","Shirevale, for the last three years. Because Yasin has never made a claim he had expected","the cost of his insurance premiums to decrease, but this has not happened.","Yasin has researched car insurance products from four different providers.","Insurance","provider","Annual premium","£","Excess *","£","Courtesy car No claims","discount","protected **","Ashridge 890 300 Additional","option","£56 extra","Yes","Shirevale 1 045 150 Included Yes","The Royal","Insurance","750 400 Additional","option","£75 extra","No","Westshire 980 200 Included No","* Excess is the compulsory amount Yasin must pay to the insurance company if he","makes a claim.","** No claims discount protected means that if Yasin makes a claim he will still have a no","claims discount for the following year."],"ctxb":[{"t":"p","x":"Yasin is 26 years old and has had a driving licence for six years. Yasin has never had a car accident and he has never made a claim on his car insurance. His car is now quite old. Yasin lives in an area where car theft has increased in recent years. Yasin’s car insurance is due to be renewed. He has used his current insurance provider, Shirevale, for the last three years. Because Yasin has never made a claim he had expected the cost of his insurance premiums to decrease, but this has not happened. Yasin has researched car insurance products from four different providers."},{"t":"flow","x":["Insurance","provider","Annual premium","Excess *","Courtesy car No claims","discount","protected **","Ashridge 890 300 Additional","option","£56 extra","Yes","Shirevale 1 045 150 Included Yes","The Royal","Insurance","750 400 Additional","option","£75 extra","No","Westshire 980 200 Included No"]},{"t":"p","x":"* Excess is the compulsory amount Yasin must pay to the insurance company if he makes a claim. ** No claims discount protected means that if Yasin makes a claim he will still have a no claims discount for the following year."}],"text":"Evaluate which car insurance provider would be the most suitable for Yasin.","qTotal":12,"ms":{"body":"Ashridge\n• Second cheapest of the four\n• Has the second highest excess of £300\n• Courtesy car is an additional cost (but might not want to have this\nfeature)\n• No claims discount is protected – may save money in the future if\nnot made a claim\nShirevale\n• Most expensive\n• Lowest excess of £150\n• Courtesy car included\n• No claims discount is protected\n• Current provider – might not be giving him as good a deal as new\nsupplier trying to get him to switch\n• Whilst Yasin is cancelling the insurance Shirevale could make a\nlower premium offer.\nThe Royal Insurance\n• Cheapest provider\n• Highest excess of £400\n• Courtesy car is an additional cost (but might not want to have this\nfeature)\n• No claims discount is not protected\nWestshire\n• Second most expensive\n• Second lowest excess of £200\n• Courtesy car included\n• No claims discount is not protected despite being second most\nexpensive product\nExpert\n30","levels":12}},{"q":7,"sub":null,"marks":2,"section":"B","ctx":["Business Finance"],"ctxb":[{"t":"p","x":"Business Finance"}],"text":"Give two types of revenue income.","qTotal":2,"ms":{"body":"Award one mark for each type of revenue income identified, up\nto a maximum of two marks:\n• Cash sales (1)\n• Credit sales (1)\n• Rent received (1)\n• Commission received (1)\n• Interest received (1)\n• Discount received (1)\nAward a maximum of 1 mark for sales where the learner has\nnot specified whether it is cash or credit\nAccept any other appropriate response.\nGraduate","levels":null}},{"q":8,"sub":"a","marks":1,"section":"B","ctx":[],"ctxb":[],"text":"State the impact that a discount received would have on the profit for the year in an income statement.","qTotal":2,"ms":{"body":"Award one mark for the following:\nProfit for the year would increase\nGraduate","levels":null}},{"q":8,"sub":"b","marks":1,"section":"B","ctx":[],"ctxb":[],"text":"State one current asset that could be included in a statement of financial position.","qTotal":2,"ms":{"body":"Award one mark for the correct identification of a current asset:\n• Inventory / stock (1)\n• Trade receivables (debtors) (1)\n• Cash (1)\n• Bank (1)\n• Prepaid expense (1)\n• Accrued income (1)\nAccept any other appropriate response.\nGraduate\n32","levels":null}},{"q":9,"sub":null,"marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Explain one advantage to a business of using debentures as a source of income.","qTotal":2,"ms":{"body":"Award one mark for identification of an advantage for the\nbusiness of using a debenture as a source of income and one\nmark for development:\n• The interest rate is fixed (1) so the company does not\nneed to worry about increased interest charges (1)\n• Only interest is paid until the debenture is redeemed (1)\nso lower amounts being paid will improve cash flow (1)\n• Repayments / interest payments are fixed (1) which\nallows the business to plan finances / budget (1)\n• Long-term source of finance (1) which allows the\nbusiness to plan (1)\n• Can borrow a large sum of money (1) which does not\nrequire repayment for a set period of time (1)\nExpert\n27","levels":null}},{"q":10,"sub":"a","marks":3,"section":"B","ctx":["Shedz is a business that sells garden sheds and other wooden buildings. The sheds are","sold online and they are delivered to customers using the company’s vehicles.","The owner, Clare, has given you some information about the financial performance of","the business. She has asked you to analyse this information using ratio analysis.","Extract of Financial Information for Shedz","£","Cost of sales 195 000","Gross profit 65 000","Expenses 13 000","Capital employed 416 000","Opening inventory 42 000","Closing inventory 36 000"],"ctxb":[{"t":"p","x":"Shedz is a business that sells garden sheds and other wooden buildings. The sheds are sold online and they are delivered to customers using the company’s vehicles. The owner, Clare, has given you some information about the financial performance of the business. She has asked you to analyse this information using ratio analysis."},{"t":"cap","x":"Extract of Financial Information for Shedz"},{"t":"cap","x":"Extract of Financial Information for Shedz"},{"t":"grid","head":null,"rows":[["Cost of sales","195 000"],["Gross profit","65 000"],["Expenses","13 000"],["Capital employed","416 000"],["Opening inventory","42 000"],["Closing inventory","36 000"]]}],"text":"Calculate the gross profit margin ratio.","qTotal":15,"ms":{"body":"Award three marks for the correct response of 25%\nAccept with or without percentage sign\nOR\nAward one mark for the correct formula in words or numbers:\n• Gross profit margin = gross profit / sales revenue x 100\n• 65 000 / (65 000 + 195 000) x 100\nAND\nAward one further mark for the correct calculation of revenue of £260 000\nNB. £ is not required\nExpert\nEducation Limited 2015\n28\nQuestion\nnumber\nAnswer\nmark\n10 (c) Award three marks for the correct response of 73 days\nAccept with or without label (i.e.) 73\nOR\nAward two marks for the following:\n39 000 / 195 000 x 365\nOR\nAward one mark for the correct formula in words or numbers:\n• Average inventory / Cost of sales x 365\n• (42 000+ 36000)/ 2) / 195 000 x 365\nAND\nAward one further mark for the correct calculation of average inventory of\n£39 000\nNB. £ is not required\nExpert\n29","levels":null}},{"q":10,"sub":"b","marks":3,"section":"B","ctx":[],"ctxb":[],"text":"Calculate the profit margin ratio.","qTotal":15,"ms":{"body":"Award three marks for the correct response of 20%\nAccept with or without percentage sign\nOR\nAward one mark for the correct formula in words or numbers:\n• Profit margin = profit / sales revenue x 100\n• (65 000 – 13 000) / (65 000 + 195 000) x 100\nAND\nAward one further mark for the correct calculation of profit of £52 000\nNB. £ is not required\nExpert","levels":null}},{"q":10,"sub":"c","marks":3,"section":"B","ctx":[],"ctxb":[],"text":"Calculate the inventory turnover ratio.","qTotal":15},{"q":10,"sub":"d","marks":6,"section":"B","ctx":["Shedz must depreciate the value of the vehicles in its accounts."],"ctxb":[{"t":"p","x":"Shedz must depreciate the value of the vehicles in its accounts."}],"text":"Discuss the advantages and disadvantages of using the reducing balance method to depreciate the value of the vehicles in its accounts.","qTotal":15,"ms":{"body":"Advantages\n• More depreciation in the early life of the asset and less in the\nlater years of the asset’s life, which helps offset greater repair\ncosts as the vehicles age\n• Gives a more realistic valuation of the vehicles as they lose\nmore value in the earlier years.\n• Prevents overstating the vehicles value so would comply with\naccounting concepts\n• Prevents understating the expense / overstating profits so\nwould comply with accounting concepts\n• Give greater tax benefit in early years which would help grow the\nbusiness\nDisadvantages\n• Harder to calculate than the straight line method as you\nwill need to recalculate the expense each year figure based\non the net book value at the end of the previous year\n• It is harder to work out what percentage to use to\ndepreciate over the asset’s lifetime\n• Will produce lower profit figures in the early years in the\nlife of the asset\nAccept any other appropriate response.\nExpert\nEducation Limited 2015\n30","levels":6}},{"q":11,"sub":"a","marks":4,"section":"B","ctx":["Mike owns a small business called Palindrone. He started the business three years ago","making drones to sell to other businesses and the general public.","Mike plans to start making and selling a new type of drone. He predicts that he will sell","60 units per year. Mike has made some financial forecasts and created the following","break-even chart for the new drone.","50 000","40 000","30 000","20 000","10 000","0","0 10 20 30 40 50 60","units","Costs and","revenues","i","iv","iii","ii"],"ctxb":[{"t":"p","x":"Mike owns a small business called Palindrone. He started the business three years ago making drones to sell to other businesses and the general public. Mike plans to start making and selling a new type of drone. He predicts that he will sell 60 units per year. Mike has made some financial forecasts and created the following break-even chart for the new drone."},{"t":"flow","x":["50 000","40 000","30 000","20 000","10 000","0","0 10 20 30 40 50 60","units","Costs and","revenues","i","iv","iii","ii"]}],"text":"Identify the items labelled (i) to (iv) on the break-even chart.","qTotal":31,"ms":{"body":"Award one mark for each correct answer\n(i) Margin of safety\n(ii) Loss\n(iii) Profit\n(iv) Break-even point\nGraduate\n4\n11b Award two marks for the correct answer of £750\nAccept with or without £ sign\nOR\nAward one mark for the formula in either words of figures\nSelling price per unit = break-even revenue / break-even quantity\nSelling price per unit = 30 000 / 40\nGraduate\n2","levels":null}},{"q":11,"sub":"b","marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Calculate the selling price of each drone.","qTotal":31},{"q":11,"sub":"c","marks":3,"section":"B","ctx":[],"ctxb":[],"text":"Calculate the variable cost per unit of each drone.","qTotal":31,"ms":{"body":"Award three marks for the correct answer of £500\nAccept with or without £ sign\nOR\nAward one mark for the formula in either words or figures\nVariable cost per unit = (total costs – fixed costs) / break-even quantity\nVariable cost per unit = (30 000 – 10 000) / 40\nOR\nAward one mark for a rearranged formula in either words or figures\nBreak-even quantity = fixed costs / (selling price per unit -variable cost\nper unit)\n40 = 10 000 / (750 – variable cost per unit)\nAND\nAward one mark for correct calculation of total variable costs of £20 000\n3\nEducation Limited 2015\n32\nExpert\n33","levels":null}},{"q":11,"sub":"d","marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Calculate the margin of safety.","qTotal":31,"ms":{"body":"Award two marks for the correct answer of 20 units\nAccept 20\nOR\nAward one mark for the formula in either words of figures\nMargin of safety = expected output – break-even quantity\nMargin of safety = 60 - 40\nGraduate\n2\nEducation Limited 2015\n34","levels":null}},{"q":11,"sub":"e","marks":8,"section":"B","ctx":["Palindrone has been trading for three years and Mike is looking at the past financial","performance of the business. Mike takes drawings every month for his own personal","use. Palindrone has not purchased or sold any non-current assets in the last three","years. It uses machinery that is outdated compared to the machinery used by many","of its competitors.","Extracts from the statements of financial position for Palindrone for the last three years","31 December 2020 31 December 2019 31 December 2018","£ £ £","Non-current assets 49 537 56 534 62 567","Opening capital 425 567 432 489 438 754","Add profit for the year 52 000 46 567 43 567","Less drawings 61 567 53 489 49 832","Closing capital 416 000 425 567 432 489"],"ctxb":[{"t":"p","x":"Palindrone has been trading for three years and Mike is looking at the past financial performance of the business. Mike takes drawings every month for his own personal use. Palindrone has not purchased or sold any non-current assets in the last three years. It uses machinery that is outdated compared to the machinery used by many of its competitors. Extracts from the statements of financial position for Palindrone for the last three years"},{"t":"grid","head":null,"rows":[["31 December 2020 31 December 2019 31 December","2018"],["£ £ £ Non-current assets","49 537","56 534","62 567"],["Opening capital","425 567 432 489 438 754"],["Add profit for the year","52 000","46 567","43 567"],["Less drawings","61 567","53 489","49 832"],["Closing capital","416 000 425 567 432 489"]]}],"text":"Analyse the possible implications this financial information could have on the future of the business.","qTotal":31,"ms":{"body":"Analysis of the data\n• The value of the business is falling each year\n• Profitability is improving each year\n• Mike is taking more out of the business in drawings each year\n• Drawings are greater than profit each year, which causes the value of the\nbusiness to fall\n• The value of the non-current assets is falling\nCauses\n• Mike may not know the levels of profit at the time he is taking his drawings\nout so may not realise he is taking out more than the business earns\n• Mike might not understand the consequences of drawings being greater than\nlevels of profit\n• Falling value of non-current assets to causes, as working with outdates\nmachinery that is not being renewed / replaced\n•\nConsequences\n• Reducing liquidity\n• Affecting the ability of the firm to reinvest in non-current assets\n• A fall in sales / profitability given that drones will need up-to-date technology\nto build\n• Inability to reinvest and support development of new product lines\nExpert\n35","levels":8}},{"q":11,"sub":"f","marks":12,"section":"B","ctx":["Mike is hoping to expand Palindrone quickly. Its current machinery is becoming","outdated and the business needs to update its technology to remain competitive. The","cost of a new machine is £40 000 and Mike is wondering how to fund this purchase.","He has two options to choose from.","Option 1","Lease a new machine.","Leasing a machine will cost £1 000 per month. This cost includes any repair costs.","The lease is for a minimum of two years. It can be cancelled after this point if two","months’ notice is given. An extra £1 500 fee must be paid for ending the lease early.","The leasing company will deliver and install the machine.","Option 2","Purchase a new machine using a loan with a variable rate of interest over five years.","The loan repayment will be initially £800 per month. The loan will be secured against the","business premises. The delivery and installation of the machine will cost an extra £1 200.","Mike will also have to pay for any repairs once the machine’s three-year guarantee ends."],"ctxb":[{"t":"p","x":"Mike is hoping to expand Palindrone quickly. Its current machinery is becoming outdated and the business needs to update its technology to remain competitive. The cost of a new machine is £40 000 and Mike is wondering how to fund this purchase. He has two options to choose from. Option 1 Lease a new machine. Leasing a machine will cost £1 000 per month. This cost includes any repair costs. The lease is for a minimum of two years. It can be cancelled after this point if two months’ notice is given. An extra £1 500 fee must be paid for ending the lease early. The leasing company will deliver and install the machine. Option 2 Purchase a new machine using a loan with a variable rate of interest over five years. The loan repayment will be initially £800 per month. The loan will be secured against the business premises. The delivery and installation of the machine will cost an extra £1 200. Mike will also have to pay for any repairs once the machine’s three-year guarantee ends."}],"text":"Evaluate whether Mike should lease (Option 1) or use a loan (Option 2) to obtain the machine.","qTotal":31,"ms":{"body":"Option 1\nAdvantages of leasing\n• Includes repair costs so peace of mind knowing that production should\ncontinue\n• Appropriate for a small company with cash flow issues\n• Short- term lease of two years means Mike can return the machine (after\nthe notice period) if he wishes to\n• After two years can get more up-to-date machines if technology changes\n• Can budget for the cost of £1 000 per month as they know it should not\nvary\nDisadvantages of leasing\n• At the end of the lease Mike will have to return the asset\n• Does not own the machine so does not improve the value of the business\n• Will face additional costs of £1500 if the business tries to end the lease\nearly\n• Cost is £10 800* more than the loan over the five-year period (excluding\nrepair costs)","levels":12}}],"msMatched":17},{"id":"U3-2206","unit":3,"key":"2022-06","series":"June 2022","date":"June 2022","title":"Luz · Emilia · Jalen","source":"pearson","kind":"exam","total":80,"parsedTotal":80,"sec":{"A":28,"B":52},"items":[{"q":1,"sub":null,"marks":2,"section":"A","ctx":[],"ctxb":[],"text":"Give two advantages of using a price comparison website when choosing a savings account.","qTotal":2,"ms":{"body":"Award one mark for each advantage identified, up to\na maximum of two marks.\n• Helps the consumer to see a wide range of\naccounts (1)\n• Saves time (1)\n• convenient/available 24/7/easily accessible (1)\n• Key account features can be\nranked/compared/filtered (1)\n• Provides up to date information (1)\nAccept any other reasonable answer.\nGraduate\n2","levels":null}},{"q":2,"sub":null,"marks":2,"section":"A","ctx":[],"ctxb":[],"text":"State two reasons why an individual should consider their expenditure when planning their personal finances.","qTotal":2,"ms":{"body":"Award one mark for each reason identified, up to a\nmaximum of two marks.\n• To avoid getting into debt\n• To control spending/avoid overspending\n• Avoid legal action and/or repossession\n• Remain solvent\n• Maintain a good credit rating\n• Avoid bankruptcy\n• To manage money to fund purchases/budget\n• Set financial targets for spending and saving\nAccept any other reasonable answer.\nGraduate\n2\nBTEC Mark Scheme 2206\nOwner: VQ Assessment Page 5 of 14 Version 1.0\nIssue 1\nDCL1","levels":null}},{"q":3,"sub":null,"marks":2,"section":"A","ctx":[],"ctxb":[],"text":"Explain one disadvantage for a consumer of using cash as a method of payment.","qTotal":2,"ms":{"body":"Award one mark for identification of a disadvantage\nof using cash as a method of payment and one mark\nfor a linked development.\n• Cash can be lost/stolen (1) which will prevent the\nholder from using the cash (1)\n• Threat of counterfeit (1) so may not be accepted\nas payment (1)\n• Cannot be used to pay online (1) limits access to\nsome businesses/products/services(1)\n• Retailers may not accept cash (1) due to current\nhealth concerns (1)\n• Not suitable for large purchases (1) due to\nrisk/volume of carrying cash (1)\n• Cash cannot be tracked (1) so more difficult to\ntrack or evidence spending (1)\nAccept any other reasonable answer.\nExpert\n2","levels":null}},{"q":4,"sub":null,"marks":4,"section":"A","ctx":[],"ctxb":[],"text":"Explain two advantages for a consumer of using an overdraft to borrow money.","qTotal":4,"ms":{"body":"Award one mark for identification of an advantage of\nusing an overdraft and one mark for a linked\ndevelopment, up to a maximum of four marks.\n• Can continue to purchase goods/services (1)\nwhen you don’t have any funds in the account (1)\n• Simple application process (1) so can access the\nfunds quickly (1)\n• Interest is only charged on the sum borrowed for\nthe number of days used (1) which may reduce\nthe cost compared with some other forms of\nborrowing such as a loan (1)\n• Overdraft is cleared when funds are deposited (1)\n/which makes it automatic to repay (1)\n• Can be prearranged (1) so available in a time of\nneed (1)\nAccept any other reasonable answer.\nExpert\n4\nBTEC Mark Scheme 2206\nOwner: VQ Assessment Page 6 of 14 Version 1.0\nIssue 1\nDCL1","levels":null}},{"q":5,"sub":null,"marks":6,"section":"A","ctx":["Luz is getting married this autumn. She has a £110 000 mortgage on a fixed interest","rate with 24 years left. She has £15 000 savings invested in a cash ISA, which earns","2.0% interest. However, she has been advised that the interest rate on the ISA will","be reduced to 1.25% next month and will be 0.5% lower than interest paid on her","mortgage borrowing.","Luz’s friend has suggested that now the ISA interest rate is reducing Luz should use","her savings to pay £10 000 off her mortgage borrowing, which the terms of her","mortgage allow."],"ctxb":[{"t":"p","x":"Luz is getting married this autumn. She has a £110 000 mortgage on a fixed interest rate with 24 years left. She has £15 000 savings invested in a cash ISA, which earns 2.0% interest. However, she has been advised that the interest rate on the ISA will be reduced to 1.25% next month and will be 0.5% lower than interest paid on her mortgage borrowing. Luz’s friend has suggested that now the ISA interest rate is reducing Luz should use her savings to pay £10 000 off her mortgage borrowing, which the terms of her mortgage allow."}],"text":"Discuss the potential advantages and disadvantages for Luz of using her savings to reduce her mortgage borrowing.","qTotal":6,"ms":{"body":"Advantages of using savings to reduce mortgage\nbalance\n• Interest rate on mortgage borrowings is 0.5% higher\nthan the new interest rate for the ISA. Luz will\ntherefore save more in interest avoided on the\nborrowings than she would gain in interest earned on\nher savings\n• Reducing borrowing will improve Luz’s credit\nrating/score. This will help her to obtain funds from\nother sources in the future if required, e.g. personal\nloan\n• The payment will reduce the term of the mortgage if\ncurrent monthly repayment levels are maintained\n• The payment will reduce her monthly mortgage\nrepayments if the mortgage term is fixed/unchanged.\nThis will reduce her regular financial commitments\n• More equity in the property which could be used in the\nfuture towards a move to a more expensive property\nand/or greater security/collateral to support any future\nborrowing\n• Even after reducing the mortgage balance by £10 000\nLuz will still have £5 000 in savings\n• The interest rate on the ISA may reduce further in the\nfuture – the reduction may be the start of a downward\ntrend\nDisadvantages of using savings to reduce mortgage\nbalance\n• Once paid Luz cannot access the funds again (unless\nan offset mortgage)\n• There may be penalties for early repayments\n• Luz is getting married soon – it may not be a good\ntime to reduce her savings\n• It may be prudent to have savings in case something\nunexpected happens, e.g. she could use her savings to\npay her monthly mortgage payment if she lost her\njob/made redundant and/or unexpected car\nrepairs/boiler/emergency in her house\n• The interest rate reduction may only be short-term and\nthe rate may increase again in the future\nExpert\n6","levels":6}},{"q":6,"sub":null,"marks":12,"section":"A","ctx":[],"ctxb":[],"text":"Simon is about to move out of his parents’ home and rent his first flat. Simon’s hobbies include competitive mountain biking and he plans to join a local cycling club. He has a mountain bike worth £2 500. Simon needs to buy contents insurance to protect his belongings and has researched four different insurance providers. The information is shown in the table below. Annual premium Compulsory excess* Amount of cover High value item cover Ashridge £270 £50 £25 000 Yes – up to original purchase cost Shirevale £160 £100 £20 000 Yes – up to £500 The Royal Insurance £200 £50 £17 500 No Westshire £230 £125 Unlimited Yes – up to £2 000 * Compulsory excess is the amount Simon must pay to the insurance company in the event of a claim. Evaluate which contents insurance provider would be most suitable for Simon.","qTotal":12,"ms":{"body":"Ashridge\n• Most expensive premium\n• Joint lowest compulsory excess\n• Second highest amount of cover\n• Bike replacement cover up to original purchase\ncost\nShirevale\n• Cheapest premium\n• Second highest compulsory excess\n• Third highest amount of cover\n• Bike replacement cover up to £500 – would not\ncover original cost of his bike\nThe Royal Insurance\n• Second cheapest annual premium\n• Joint lowest compulsory excess\n• Lowest amount of cover\n• No bike replacement cover so not suited to his\nneeds\nWestshire\n• Second highest annual premium\n• The highest compulsory excess\n• Unlimited cover – peace of mind that all items are\ncovered\n• Bike replacement cover up to £2 000 – would not\nfully cover original cost of his bike\nExpert\n12\nBTEC Mark Scheme 2206\nOwner: VQ Assessment Page 9 of 14 Version 1.0\nIssue 1\nDCL1","levels":12}},{"q":7,"sub":null,"marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Give two types of capital income.","qTotal":2,"ms":{"body":"Award one mark for each type identified, up to a\nmaximum of two marks.\n• Loan (1)\n• Mortgages (1)\n• Shares/Stocks (not stock) (1)\n• Owner’s capital\n• Debentures (1)\n• Crowdfunding (1)\n• Venture capital (1)\n• Grants (1)\nAccept any other appropriate response.\nGraduate\n2","levels":null}},{"q":8,"sub":null,"marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Explain one way that a cash flow forecast may be used by a business.","qTotal":2,"ms":{"body":"Award one mark for identification of a way that\na cash flow forecast may be used and one mark\nfor a linked development.\n• Business planning/decision-making (1) as\nthe cash flow forecast will predict future\ncash inflows and outflows (1)\n• Monitoring performance (1) as actual\nfinancial performance can be compared\nwith the forecasted figures or previous\nyears (1)\n• Control (1) as the figures can be used to\nlimit expenditure (1)\n• Target setting (1) to monitor inflows and\noutflows (1)\n• To show to potential investors/bank (1)\nto secure finance (1)\nAccept any other appropriate response.\nExpert\n2\nBTEC Mark Scheme 2206","levels":null}},{"q":9,"sub":null,"marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Explain one effect of ‘amortisation’ on the final accounts of a business.","qTotal":2,"ms":{"body":"Award one mark for identification of an effect\non the final accounts of a business and one\nmark for a linked development.\n• Reduces profit (1) as amortisation\nincreases the business’s expenses (1)\n• Reduces the net book value of the\nintangible asset in the statement of\nfinancial position (1) as the value of\namortisation has to be deducted (1)\n• Reduces owner’s equity (1) as the\nbusiness assets are now worth less (1)\nAccept any other appropriate response.\nExpert\n2\nBTEC Mark Scheme 2206","levels":null}},{"q":10,"sub":"a","marks":3,"section":"B","ctx":["Emilia is planning to sell a new range of organic ice creams from a dedicated outdoor","stall. The ice creams will include one scoop of ice cream served in a waffle cone. She will","rent the space for the stall from another local business. She has produced the following","information:","Selling price per unit £2.75","Cost of cone per unit 30p","Cost of ice cream per unit 80p","Number of units to break-even 6 500"],"ctxb":[{"t":"p","x":"Emilia is planning to sell a new range of organic ice creams from a dedicated outdoor stall. The ice creams will include one scoop of ice cream served in a waffle cone. She will rent the space for the stall from another local business. She has produced the following information: Selling price per unit £2.75 Cost of cone per unit 30p Cost of ice cream per unit 80p Number of units to break-even 6 500"}],"text":"Calculate the annual fixed costs to operate the ice cream stall.","qTotal":16,"ms":{"body":"Award three marks for the correct response of £10 725\nAccept correct figure without pound sign, i.e. 10 725\nAccept correct answer anywhere in workings box.\nOR\nAward one mark for the formula in words or numbers:\n• Fixed costs = (selling price per unit – variable cost per\nunit) x break-even quantity\n• Fixed costs = contribution x break-even quantity\n• Fixed costs = (2.75 – 1.10) x 6 500\n• Fixed costs = 1.65 x 6 500\n• Break-even quantity = Fixed costs / (selling price –\nvariable cost per unit)\n• Break-even quantity = Fixed costs / contribution per\nunit\n• 6 500 = Fixed costs / (2.75 – (30 + 80))\n• 6 500 = Fixed costs / (2.75 – 1.10)\nAND\nAward one mark for contribution per unit of £1.65\nExpert\n3\nBTEC Mark Scheme 2206","levels":null}},{"q":10,"sub":"b","marks":3,"section":"B","ctx":["Emilia carries out some market research and discovers that several competing","products are sold at a higher price of £3.50"],"ctxb":[{"t":"p","x":"Emilia carries out some market research and discovers that several competing products are sold at a higher price of £3.50"}],"text":"Calculate the change in the break-even point if Emilia increases her selling price to £3.50","qTotal":16,"ms":{"body":"Award three marks for the correct answer of break-even\npoint will reduce/change by 2 031 units (6 500 – 4 469)\nAccept 2031.2 or 2031.25\nOR\nAward two marks for calculating the new break-even\nquantity:\nBreak-even = 10 725 / 2.40 = 4 468.75 units\nAlso accept\n4 469 units\n4 468.8 units\nDo not accept 4 468 units\nOR\nAward one mark for calculating the new contribution:\n3.50 – (30 + 80)\n3.50 – 1.10 = 2.40\nAND\nAward one mark for the break even formula:\nBreak even point = fixed cost/(selling price-variable\ncosts)\nExpert\n3\nBTEC Mark Scheme 2206","levels":null}},{"q":10,"sub":"c","marks":2,"section":"B","ctx":["Emilia’s market research suggests that she will sell 5 000 ice creams each year at the","increased price of £3.50"],"ctxb":[{"t":"p","x":"Emilia’s market research suggests that she will sell 5 000 ice creams each year at the increased price of £3.50"}],"text":"Calculate the margin of safety for the year based on the increased price of £3.50 per ice cream.","qTotal":16,"ms":{"body":"Award two marks for 531 units/ice creams.\nAccept with or without the label of units/ice creams.\nAccept 531.2 units and 531.25 units\nOR\nAward one mark for formula in words or numbers:\n• Margin of safety = expected sales – break-even\nquantity\n• Margin of safety = 5 000 – 4 469\nOR\nAward one mark for:\n• Margin of Safety = 5 000 – 4 468.8\nOR\nAward one mark for:\n• Margin of Safety = 5 000 – 4 468.75\nExpert\n2\nBTEC Mark Scheme 2206","levels":null}},{"q":10,"sub":"d","marks":8,"section":"B","ctx":[],"ctxb":[],"text":"Analyse whether increasing the price of the ice creams will increase the profit made by Emilia’s business.","qTotal":16,"ms":{"body":"Increased profit\n• Contribution per unit will rise from £1.65 to\n£2.40 so each ice cream sold will contribute\nmore greatly towards the fixed costs\n• If the number of units/ice creams sold is\nunchanged by the increase in the selling price\nthe break-even quantity should fall (assuming\ncosts remain unchanged). This will have a\npositive impact on the profitability of Emilia’s\nbusiness\n• Competing products are sold at the higher\nprice of £3.50\n• Emilia’s ice creams are new/organic so\ncustomers may be keen to try them at the\nhigher price.\nReduced profit\n• Emilia’s number of sales may fall at the higher\nprice\n• total revenue may fall (depending on the size of\nthe reduction in the number of units sold)\n• The fall in revenue/sales may be greater than the\nbenefit of the extra contribution\n• Competing products may be worth a ‘higher’ price\nthan Emilia’s ice creams, e.g. brand name, USP or\nadditional toppings\n• Emilia’s ice cream range is new so she is yet to\nbuild up a base of loyal customers\nAccept any other appropriate response.\nExpert\n8\nBTEC Mark Scheme 2206","levels":8}},{"q":11,"sub":"a","marks":6,"section":"B","ctx":["Jalen runs a small business called Vetropak that produces packaging for the food","industry. He has given you the following financial information, which is incomplete."],"ctxb":[{"t":"p","x":"Jalen runs a small business called Vetropak that produces packaging for the food industry. He has given you the following financial information, which is incomplete."}],"text":"Complete the statement of financial position for Vetropak by calculating:","qTotal":30,"ms":{"body":"Award one mark for each correct answer.\ni) 28 973\nii) 10 629\niii) 9 754\niv) 12 184\nv) 20 000 (ECF if wrong answer calculated for 11aiv, but\ncorrect calculation applied)\nvi) 44 911 (ECF if wrong answer calculated for 11avii, but\ncorrect calculation applied)\nvii) 321 211\nExpert\n7\nBTEC Mark Scheme 2206","levels":null}},{"q":11,"sub":"i","marks":1,"section":"B","ctx":[],"ctxb":[],"text":"Accumulated depreciation of machinery (ii) Trade receivables (iii) Short-term bank loan (iv) Net current assets/liabilities (v) Long-term bank loan (vi) Retained profit (vii) Capital employed. 19 Vetropak Statement of financial position as at 31 December 2021 Cost Accumulated depreciation Net book value £ £ £ Non-current assets Machinery 358 000 (i) 329 027","qTotal":30},{"q":11,"sub":"b","marks":1,"section":"B","ctx":["329 027","Current assets","Inventory 25 897","Trade receivables (ii)  (1)","Bank 2 569","Cash 278","39 373","Current liabilities","Trade payables 17 435","Short-term bank loan (iii)  (1)","27 189","Net current assets/liabilities (iv)  (1)","Non-current liabilities","Long-term bank loan (v)  (1)","Net assets 321 211","Financed by","Capital 276 300","Retained profit (vi)  (1)","Capital employed (vii)  (1)","Jalen’s accountant has identified two omissions from Vetropak's statement of","financial position:","– £350 rent which was pre-paid as at 31 December 2020","– £250 electricity which is paid quarterly in arrears."],"ctxb":[{"t":"grid","head":["","329","027"],"rows":[["Inventory","25 897"],["Trade receivables","(ii)","1"],["Bank","2 569"],["Cash","278"]]},{"t":"grid","head":["","39","373"],"rows":[["Trade payables","17 435"],["Short-term bank loan","(iii)","1"],["27 189 Net current assets/liabilities","(iv)","1"],["Non-current liabilities Long-term bank loan","(v)","1"],["Net assets","321 211"],["Financed by Capital","276 300"],["Retained profit","(vi)","1"],["Capital employed","(vii)","1"]]},{"t":"p","x":"Jalen’s accountant has identified two omissions from Vetropak's statement of financial position: – £350 rent which was pre-paid as at 31 December 2020 – £250 electricity which is paid quarterly in arrears."}],"text":"Calculate the revised total current assets in the statement of financial position as at 31 December 2020.","qTotal":30,"ms":{"body":"Award one mark for the correct answer.\n• The pre-paid rent must be added to the current\nassets\n• £39 373 + £350\n• £39 723\nAlternative: If learner has assumed prepaid 31st Dec\n2020 then this prepayment will have been used to pay\nrent in 2021 and so nothing will need to be added.\nAward one mark for £39 373\nGraduate\n1","levels":null}},{"q":11,"sub":"c","marks":1,"section":"B","ctx":[],"ctxb":[],"text":"Calculate the revised total current liabilities in the statement of financial position as at 31 December 2020.","qTotal":30,"ms":{"body":"Award one mark for the correct answer.\n• The accrual must be added to the current\nliabilities\n• £27 189 + £250\n• £27 439\nAlternative: If learner has assumed arrears are from\n2020 and paid quarterly, then each quarter the\narrears would have been paid and would have been\ncleared during 2020. Therefore nothing to add.\nAward one mark for £27 189\nGraduate\n1\nBTEC Mark Scheme 2206","levels":null}},{"q":11,"sub":"d","marks":3,"section":"B","ctx":["Jalen is planning to purchase a second-hand van at a cost of £25 000. He will","depreciate the vehicle by 16.5% each year using the straight line method."],"ctxb":[{"t":"p","x":"Jalen is planning to purchase a second-hand van at a cost of £25 000. He will depreciate the vehicle by 16.5% each year using the straight line method."}],"text":"Calculate the net book value of the van at the end of the second year.","qTotal":30,"ms":{"body":"Award three marks for £16 750\nOR\nAward two marks for the correct formula in numbers\nNBV = £25,000 – £8,250\nOR\nAward two marks for correct depreciation total of £8,250\nOR\nAward one mark for correct formula in words\nNBV = Original asset cost – accumulated depreciation\nAND\nAward one mark for calculating the annual depreciation =\n£4 125\nOR\nAward one mark for £20,875 which is netbook value minus\n£4,125.\nDo not award 1 mark for £4,125 if you are awarding\n2 marks for the correct formula in numbers or the\ncorrect depreciation of £8,250\nAccept correct figure with or without pound sign.\nExpert\n3\nBTEC Mark Scheme 2206","levels":null}},{"q":11,"sub":"e","marks":6,"section":"B","ctx":["A new supplier of wood chips, which are used to produce the packaging, has asked","to look at Vetropak’s statement of financial position to decide whether to offer trade","credit to the business."],"ctxb":[{"t":"p","x":"A new supplier of wood chips, which are used to produce the packaging, has asked to look at Vetropak’s statement of financial position to decide whether to offer trade credit to the business."}],"text":"Discuss the advantages and disadvantages to the supplier of analysing the statement of financial position when making a decision about whether to offer trade credit.","qTotal":30,"ms":{"body":"Advantages\n• Net current assets measure the business’s ability to\nmeet day-to-day expenses, and whether the\nbusiness has sufficient liquid assets to repay any\ntrade credit offered\n• Figures from the statement of financial position can\nbe compared over a number of years to establish\ntrends\n• Figures from the statement of financial position can\nbe compared in relation to other figures, e.g. current\nassets can be measured in relation to current\nliabilities\n• Comparisons can be made to assess how the\nbusiness is performing in relation to its competitors\nwhich will help the supplier consider relative\ncompetitiveness and therefore the stability of the\nbusiness\n• Ratio analysis can be used by the supplier to analyse\nthe financial data in detail\nDisadvantages\n• The statement of financial position presents data for\na set point in time, which limits its value as at other\ntimes of year the situation may differ, especially for\na seasonal business\n• The figures are calculated on past data and therefore\nmay not be a true reflection of the current\nperformance of the business\n• The figures cannot predict future performance and\ntherefore not indicate the future creditworthiness of\nthe business. The figures may even mislead the\nsupplier based on past business success\n• Other qualitative factors may be more valuable\nregarding the business’s worthiness for trade credit,\ne.g. change of senior manager over recent months\nleading to new strategic ideas/direction\n• Accounts could have been window dressed\nAccept any other appropriate response.\nExpert","levels":6}},{"q":11,"sub":"f","marks":12,"section":"B","ctx":["Jalen has developed a new way of packaging food products that is more","environmentally friendly. He has already spent a lot of money on developing the","process but is pleased to have secured an order from a leading food producer.","He now needs to raise additional finance to purchase a new machine that will","cost £65 000.","Jalen is hopeful that the order will be the first of many and is now considering two","options to finance the purchase of the new machine:","Option 1: Venture capital","Option 2: Crowdfunding."],"ctxb":[{"t":"p","x":"Jalen has developed a new way of packaging food products that is more environmentally friendly. He has already spent a lot of money on developing the process but is pleased to have secured an order from a leading food producer. He now needs to raise additional finance to purchase a new machine that will cost £65 000. Jalen is hopeful that the order will be the first of many and is now considering two options to finance the purchase of the new machine: Option 1: Venture capital Option 2: Crowdfunding."}],"text":"Evaluate whether Jalen should use venture capital (Option 1) or crowdfunding (Option 2) to purchase the new machine.","qTotal":30,"ms":{"body":"Advantages of venture capital\n• An experienced business professional may provide the finance and can\noffer mentoring and guidance alongside the financial contribution,\nwhich will increase the chances of success\n• The venture capitalist is willing to take more risks than a bank – there\nis no guarantee that the new way of packaging food will be a success.\nNo track record to consider\n• Speed of decision on venture capital availability may be an advantage\n• Venture capitalist may provide links to a wider customer/supplier base\nfor Jalen\nDisadvantages of venture capital\n• Loss of ownership and control\n• Conflict may arise between Jalen and the venture capitalist as they\nwant to contribute to decision making\n• Some types of venture capital involve giving something away (e.g.\nequity, control, ownership)\n• The cost of venture capital is typically high relative to other sources of\nfinance\n• Too small to attract venture capital\nAdvantages of crowdfunding\n• Can be a quick way to raise finance with no upfront fees\n• Can be a valuable form of marketing and result in media attention\n• Get feedback on your idea and expert guidance on how to improve it\n• Good way to test the public’s reaction to your product/idea\n• Investors can track your progress, which can help to promote the brand\nthrough their networks\n• Ideas that may not appeal to conventional investors can often get\nfinanced more easily • Investors can often become loyal customers\nthrough the financing process\nDisadvantages of crowdfunding\n• Can take a very long time to raise finance\n• Some types of crowdfunding involves giving something away (eg equity\ncrowdfunding involves giving away part of the ownership/control/equity\nof the business in return for funds)\n• Not all projects that apply to crowdfunding platforms get onto them\n• You need to do a lot of work in building up interest before the project\nlaunches\n• If you don’t reach your funding target, any finance that has been\npledged will usually be returned to your investors and you will receive\nnothing\n• Failed projects risk damage to the reputation of your business and\npeople who have pledged money to you\n• Can be difficult to set the rewards for investors - getting the rewards or\nreturns wrong can mean giving away too much of the business to\ninvestors\n• May be too small an amount to consider using crowdfunding\nAccept any other appropriate response.\n12\nBTEC Mark Scheme 2206","levels":12}}],"msMatched":19},{"id":"U3-2301","unit":3,"key":"2023-01","series":"January 2023","date":"January 2023","title":"Morgan · Takudzwa · Ruby · Jisoo","source":"pearson","kind":"exam","total":80,"parsedTotal":80,"sec":{"A":28,"B":52},"items":[{"q":1,"sub":null,"marks":2,"section":"A","ctx":[],"ctxb":[],"text":"Give two functions of money.","qTotal":2,"ms":{"body":"Award 1 mark for each function of money up to a maximum of 2\nmarks.\n• Unit of account\n• Means of exchange / to facilitate buying and selling\n• Store of value / unit or measure of value / can be used to save\nup\n• Legal tender\nAccept any other appropriate answer.","levels":null}},{"q":2,"sub":null,"marks":2,"section":"A","ctx":[],"ctxb":[],"text":"Give two advantages for a consumer of paying for purchases using a contactless card.","qTotal":2,"ms":{"body":"Award 1 mark for each advantage of paying for purchases using a\ncontactless card up to a maximum of 2 marks.\n• You don’t need to remember / enter a pin number (1)\n• It is quicker/saves time/more convenient (1)\n• Less likely to lose your card as you won’t leave it in the card reader\nAccept any other appropriate answer.\nJanuary 2023","levels":null}},{"q":3,"sub":null,"marks":2,"section":"A","ctx":[],"ctxb":[],"text":"Explain one advantage for the consumer of using a cheque to buy goods.","qTotal":2,"ms":{"body":"Award 1 mark for identification of an advantage for the consumer of using\na cheque to buy goods (1) and 1 mark for a linked development.\n• Money stays in your account for longer (1) as cheques can take\nseveral days to clear (1)\n• You don’t need access to the internet (1) meaning you can buy\ngoods even if there is no internet access (1)\n• If a cheque gets lost or stolen it can be cancelled (1 ) meaning\nthat no money is lost unlike cash (1)\n• More secure (1) therefore less chance of fraud/ don’t need to carry\ncash (1)\n• There is no limit to how much you can write a cheque for (1) this\nmakes buying higher value goods easier (1)\nAccept any other appropriate answer.","levels":null}},{"q":4,"sub":null,"marks":4,"section":"A","ctx":[],"ctxb":[],"text":"Explain two advantages of using hire purchase to buy a car.","qTotal":4,"ms":{"body":"Award 1 mark for identification of each advantage up to a max of 2\nmarks /advantages (must be specific to using hire purchase to buy a car)\n(1) and 1 mark for a development linked to each advantage.\n• Low deposit (1) you can get the car quicker as you don’t need to\nsave up (1)\n• Can be lower interest than other funding options such as bank\nloans (1) save money/cheaper (1)\n• They will own the asset after the final installment (1) therefore\nbetter than lease as if they keep no monthly repayments\n• Cost of borrowing is spread (1) making it more affordable (1)\n• Payments are fixed (1) making it easier to budget/manage cash\nflow (1)\n• They may be able to buy a newer/better car (1) as can often\nborrow more on hp than they could access through a personal loan\n•\nAccept any other appropriate answer.\nJanuary 2023","levels":null}},{"q":5,"sub":null,"marks":6,"section":"A","ctx":["Morgan is 23 years old and has a credit card balance of £2 000 at 19.9% APR. He also","has £1 000 left to pay on his car loan over the next 12 months at 7% APR. Morgan is","considering transferring all of his current debts onto a new credit card. He has been","offered a new credit card at 0% interest for the first 12 months, increasing to 29.9% on","any outstanding balance after the 12 month period."],"ctxb":[{"t":"p","x":"Morgan is 23 years old and has a credit card balance of £2 000 at 19.9% APR. He also has £1 000 left to pay on his car loan over the next 12 months at 7% APR. Morgan is considering transferring all of his current debts onto a new credit card. He has been offered a new credit card at 0% interest for the first 12 months, increasing to 29.9% on any outstanding balance after the 12 month period."}],"text":"Discuss whether Mor gan should transfer his debt onto the new credit card offering 0% interest for 12 months.","qTotal":6,"ms":{"body":"Debts currently:\nCar £1000 over 1 year @ 7% £89.17/month – total repayable £1 070 –\ninterest costs him £70\nCredit card: £2000 @ 19.9% = £398 interest per year if he makes monthly\nrepayments of £199.83 per month to clear the debt - £2398 total\nrepayable\nHe would have to pay £250.00 /month to clear the debt in 12 months\nwith the 0% credit card\nAdvantages of consolidating debt onto single 0% credit card\nNo interest to pay for 12 months\nCould be debt free in 12 months time\nCurrent debts will stop growing as no interest added each month\nCould prevent him from spiraling into uncontrollable debt\nMay lead to him having better control of his money\nNot wasting his money on interest\nWould be paying £250 per month rather than £289 per month\nCould help improve credit score as more likely to be able to afford the\nrepayments and less likely to miss payments\nCould help improve credit score\nDisadvantages\nMay end up with an outstanding balance at end of 12 months if he\ndoesn’t pay off all of his debt – then charged 29.9% on the balance\nBecause he is young he may just spend the money he will be saving on\nluxury items which will not benefit his finances in the long term\nCould lead to higher future debts if still has a balance at end of 12\nmonths when interest rate goes up to 29.9%. If he cannot afford the\nmonthly repayments this will negatively impact his credit score.","levels":6}},{"q":6,"sub":null,"marks":12,"section":"A","ctx":["Takudzwa is planning to use all his savings to buy a camper van. He is going to","use the camper van to take his two children on outdoor adventure holidays across","Europe. Takudzwa’s family enjoys diving, kayaking and rock climbing. They each have","a kayak worth £400 and a mobile phone worth £300. Takudzwa has been advised by","a friend to consider taking out a travel insurance policy that includes European Travel.","The policy would help cover the costs of cancellation, theft from the camper van and","medical expenses.","Tak","udzwa has researched the following insurance products.","Insurance","provider","Annual","cost","Cover for","lost or","stolen items","or cash","Cover for","medical","expenses","Emergency","cancellation","or missed","departure","cover","Ashridge","Insurance £262","£1","000","with","a maximum","claim limit of","£200 in cash","Up to £2m NO","Shirevale","Insurance £400","£2","500","with","no limit for","cash within","the £2","500","Up to £3m YES up to","£2","000","The Royal","Insurance £375","£3 000","with","a maximum","claim limit of","£300 in cash","Up to £8m NO","Westshire","Insurance £545","£5","000","with","a maximum","claim limit","of £1","000 in","cash","Up to £10m Y","ES up to","£5 000"],"ctxb":[{"t":"p","x":"Takudzwa is planning to use all his savings to buy a camper van. He is going to use the camper van to take his two children on outdoor adventure holidays across Europe. Takudzwa’s family enjoys diving, kayaking and rock climbing. They each have a kayak worth £400 and a mobile phone worth £300. Takudzwa has been advised by a friend to consider taking out a travel insurance policy that includes European Travel. The policy would help cover the costs of cancellation, theft from the camper van and medical expenses. Tak udzwa has researched the following insurance products."},{"t":"flow","x":["Insurance","provider","Annual","cost","Cover for","lost or","stolen items","or cash","Cover for","medical","expenses","Emergency","cancellation","or missed","departure","cover","Ashridge","Insurance £262","£1","000","with","a maximum","claim limit of","£200 in cash","Up to £2m NO","Shirevale","Insurance £400","£2","500","with","no limit for","cash within","the £2","500","Up to £3m YES up to","£2","000","The Royal","Insurance £375","£3 000","with","a maximum","claim limit of","£300 in cash","Up to £8m NO","Westshire","Insurance £545","£5","000","with","a maximum","claim limit","of £1","000 in","cash","Up to £10m Y","ES up to","£5 000"]}],"text":"Evaluate which insurance product would be the best for Takudzwa to purchase.","qTotal":12,"ms":{"body":"Indicative content\nApplication:\nEquipment and technology for the family totals £2 100, cover for lost or\nstolen items must cover this but does not need to be a lot more than this\nTakudzwa has used all of his savings to buy the campervan meaning he\nwill not have a lot left to pay the annual cost\nThe activity holiday carries a high level of risk making medical cover\nimportant\nWestshire is the most expensive and covers emergency cancellation and\nmissed departure up to the highest value. It is the best for both medical\nexpenses cover and cover for lost or stolen baggage. As his family are very\nactive and travel with expensive technology this is important . Also, their\nequipment and technology total £2 100 which leaves £2 900 for baggage\nand cash– they may not need this extra level of cover. Also there is a\n£1000 limit on cash claims.\nShirevale is £145 cheaper than Westshire with less cover for emergency\ncancellation and medical but pays out up to £2500 for cash losses. Cover\nfor medical expenses are £7 million lower than Westshire and £5 million\nlower than The Royal which is £25 cheaper. However at £2 500 cover for\nlost/stolen items it will cover their £2 100 worth of equipment.\nThe Royal is the second cheapest. However, there is no cover for\ncancellation or missed departure and the maximum claim for lost cash is\n£300. However it will cover their equipment as it covers £3 000.\nAshridge Insurance is the cheapest insurance. However, there is no cover\nfor cancellation or missed departure, very little cover for lost or stolen\nbaggage and only £2 million to cover medical for his entire family,\nHowever, Takudzwa may feel this is enough to cover his financial needs.","levels":12}},{"q":7,"sub":null,"marks":2,"section":"B","ctx":[],"ctxb":[],"text":"State two types of revenue expenditure.","qTotal":2,"ms":{"body":"Award 1 mark for each item of Revenue expenditure identified,\nup to a maximum of 2 marks.\n• Inventory / stock / raw materials\n• rent\n• rates / council tax\n• heating and lighting\n• water\n• insurance\n• administration\n• telephone\n• postage\n• stationery\n• salaries\n• wages / paying employees\n• marketing / advertising / promotions\n• bank charges\n• interest paid\n• straight-line depreciation\n• reducing balance depreciation\n• discount allowed\nAccept any other derived from the list e.g heating and lighting\ncould be utilities or electricity.","levels":null}},{"q":8,"sub":null,"marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Explain what is meant by the term credit purchase.","qTotal":2,"ms":{"body":"Award 1 mark for identification of credit purchase (1) and 1\nmark for a linked development.\n• Pay later / delaying payment (1) for goods received /\nordered / bought (1)\ne.g. Buy now pay later would get 2 marks\nAccept any other appropriate answer.\nJanuary 2023","levels":null}},{"q":9,"sub":null,"marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Explain one advantage of using break-even analysis when planning a new product launch.","qTotal":2,"ms":{"body":"Award 1 mark for identifying advantage of using break even\nanalysis when planning a new product launch (1) and 1 mark for\na linked development.\n• It shows whether a product is worth launching (1)\ntherefore stops businesses wasting time / losing money\n• It estimates how many of the new products a business\nneeds to sell before they break even / make a profit /\nmake a loss (1) helps businesses decide if it is a realistic\nproposal (model “what if” scenarios (1)\n• It shows the amount of revenue a business makes at each\nlevel of output (1) helps to set prices / helps them to\nmanage costs (1)\n• It allows you to calculate your margin of safety (1) which\nmeans you can estimate your level of risk / how much\nsales can fall without making a loss (1)\nAccept any other appropriate answer.\nJanuary 2023","levels":null}},{"q":10,"sub":"a","marks":6,"section":"B","ctx":["Ruby owns a business called Training Treats. Her business makes and sells high quality pet","treats suitable for all breeds of cat and dog.","All of Training Treats credit sales are for 30 days’ credit.","Ruby has produced a Cash Flow Forecast."],"ctxb":[{"t":"p","x":"Ruby owns a business called Training Treats. Her business makes and sells high quality pet treats suitable for all breeds of cat and dog. All of Training Treats credit sales are for 30 days’ credit. Ruby has produced a Cash Flow Forecast."}],"text":"Complete the Cash Flow Forecast for the six months ending 31 December 2023.","qTotal":15,"ms":{"body":"Award 1 mark for each correct answer up to a total of 6 marks.\nCash Flow Forecast for Training Treats for the six months ended 31st December\n2023\nJuly Aug Sept Oct Nov Dec\nOpening\nBalance\n2 300 (iii)2 665\n(ECF)\n2 592 1 183 2 318 57\nInflows\nCredit sales 44 345 40 765 35 555 34 005 40 345 52 656\nCash sales 13 304 12 230 10 667 10 202 12 104 15 797\nTotal inflows 57 649 52 995 46 222 44 207 52 449 68 453\nOutflows\nCash purchases 43 236 39 746 34 666 33 155 39 336 51 340\nAdvertising 7 949 6 933 6 631 7 867 10 268 10 800\nOther expenses 6 099 6 389 6 334 2 050 5 106 5 003\nTotal outflows (i) 57 284 53 068 47 631 43 072 54 710 67 143\nNet Cash Flow 365 (iv) (73) (1 409) 1 135 (v)(2 261) 1 310\nClosing\nBalance\n(ii)2 665\n(ECF)\n2 592 1 183 2 318 57 (vi)1 367\nAllow ECF for (ii) (iii). Accept either minus sign or brackets for negative numbers.\nJanuary 2023","levels":null}},{"q":10,"sub":"b","marks":1,"section":"B","ctx":["Cash Flow Forecast for Training Treats for the six months ending 31 December 2023","July Aug Sept Oct Nov Dec","Opening","balance 2 300 (iii) 2 592 1 183 2 318 57","Inflows","Credit sales 44 345 40 765 35 555 34 005 40 345 52 656","Cash sales 13 304 12 230 10 667 10 202 12 104 15 797","Total inflows 57 649 52 995 46 222 44 207 52 449 68 453","Outflows","Cash","purchases 43 236 39 746 34 666 33 155 39 336 51 340","Advertising 7 949 6 933 6 631 7 867 10 268 10 800","Other","expenses 6 099 6 389 6 334 2 050 5 106 5 003","Total","outflows (i) 53 068 47 631 43 072 54 710 67 143","Net cash flow 365 (iv)","(1 409) 1 135 (v) 1 310","Closing","balance (ii) 2 592 1 183 2 318 57 (vi)","Ruby wants to buy a new packaging machine so that she can increase the output of","her factory by speeding up production. The new machine will cost £2 300 that she","will pay in September."],"ctxb":[{"t":"p","x":"Cash Flow Forecast for Training Treats for the six months ending 31 December 2023"},{"t":"grid","head":["","July","Aug","Sept","Oct","Nov","Dec"],"rows":[["balance","2 300","(iii)","2 592","1 183","2 318","57"],["Inflows Credit sales","44 345","40 765","35 555","34 005","40 345","52 656"],["Cash sales","13 304","12 230","10 667","10 202","12 104","15 797"],["Total inflows","57 649","52 995","46 222","44 207","52 449","68 453"]]},{"t":"cap","x":"Outflows Cash"},{"t":"cap","x":"Outflows Cash"},{"t":"grid","head":null,"rows":[["purchases","43 236","39 746","34 666","33 155","39 336","51 340"],["Advertising","7 949","6 933","6 631","7 867","10 268","10 800"],["Other expenses","6 099","6 389","6 334","2 050","5 106","5 003"],["Total outflows","(i)","53 068","47 631","43 072","54 710","67 143"],["Net cash flow","365","(iv)"],["(1","409","1 135","(v)","1 310"],["Closing balance","(ii)","2 592","1 183","2 318","57","(vi)"]]},{"t":"p","x":"Ruby wants to buy a new packaging machine so that she can increase the output of her factory by speeding up production. The new machine will cost £2 300 that she will pay in September."}],"text":"Calculate the new closing balance for September if Ruby purchases the new machine.","qTotal":15,"ms":{"body":"Award 1 mark for either of the following:\nClosing Balance for September is: (£1117) – with or without £","levels":null}},{"q":10,"sub":"c","marks":2,"section":"B","ctx":["Closing balance for September:"],"ctxb":[{"t":"p","x":"Closing balance for September:"}],"text":"Give two possible ways Ruby could improve the closing balance in her Cash Flow Forecast.","qTotal":15,"ms":{"body":"Award 1 mark for identification of each correct way of improving closing\nbalance (1) up to a maximum of 2 marks.\n• increase sales (cash or credit) (1)\n• increasing selling price (1)\n• getting more outlets to supply her treats (1)\n• sell directly to public online (1)\n• decrease outflows (1)\n• increase inflows (1)\n• spending less on advertising (1)\n• buying cheaper raw materials / ingredients/packaging etc (1)\n• reduce cash purchases from suppliers (1)\n• improve net cash flow (1)\n-\nAccept any other appropriate response in the context of Training Treats\nJanuary 2023","levels":null}},{"q":10,"sub":"d","marks":6,"section":"B","ctx":["Ruby has an overdraft facility with her bank that charges her interest of 30% pa on","outstanding balances. Ruby thinks she may have to use her overdraft if she buys","the new £2 300 machine. Ruby hopes the new machine will improve the production","efficiency of the business."],"ctxb":[{"t":"p","x":"Ruby has an overdraft facility with her bank that charges her interest of 30% pa on outstanding balances. Ruby thinks she may have to use her overdraft if she buys the new £2 300 machine. Ruby hopes the new machine will improve the production efficiency of the business."}],"text":"Discuss the benefits and limitations for Training Treats of using a Cash Flow Forecast.","qTotal":15,"ms":{"body":"Cash Flow Forecast\nBenefits\nShe can use it to model whether she needs to take out a loan or use her overdraft\nShe can spot cash shortages before they affect the business – she can look at the\nimpact of purchasing the new machine and see if she can afford it\nAs it’s a forecast it allows business to make changes - increase inflows or decrease\noutflows - to prevent shortage of cash – she will need to estimate how many extra\npacks of dog treats she can sell and by using a cash flow forecast she will then be\nable to calculate whether the extra inflows from these sales will cover the cost of\nthe machine\nEnsures the business considers all its costs\nIt’s a reality check to consider future feasibility of the business/project – helps her\nto decide whether to buy the machine or not\nLimitations\nIt's an estimate – not reliable\nDoesn’t take into account competitor reactions\nIts only as good as the person who does the forecast – we don’t know how much\nexperience Ruby has in business – for example she may wrongly estimate how\nmany extra packs of treats she will sell meaning incorrect inflows\nInformation on predicted sales may be limited and lead to errors\nNo one can accurately predict the future – changes in external environment may\nlead to inaccurate income or outflows figures\nNote\nUndeveloped assertions such as expensive or takes time should not be rewarded\nwithout reference to the case study or other developments as it’s too generic e.g.\ncould apply to other business concepts","levels":6}},{"q":11,"sub":"a","marks":6,"section":"B","ctx":["Jisoo runs a business called The Circle that sells redesigned and recycled retro clothing","both online and through a small shop. She buys clothing in bulk by weight.","Jisoo has two sewing machines that originally cost a total of £3 250 when she purchased","them on 1 January 2021. She has decided to depreciate all of her non-current assets by","10% using the reducing balance method.","By doing more of the alterations work herself Jisoo has reduced her wage bill by £3","000","in 2022.","She has given you the following two incomplete extracts from the last two statements of","comprehensive income."],"ctxb":[{"t":"p","x":"Jisoo runs a business called The Circle that sells redesigned and recycled retro clothing both online and through a small shop. She buys clothing in bulk by weight. Jisoo has two sewing machines that originally cost a total of £3 250 when she purchased them on 1 January 2021. She has decided to depreciate all of her non-current assets by 10% using the reducing balance method. By doing more of the alterations work herself Jisoo has reduced her wage bill by £3 000 in 2022. She has given you the following two incomplete extracts from the last two statements of comprehensive income."}],"text":"Complete the statement of comprehensive income for The Circle by calculating:","qTotal":31},{"q":11,"sub":"i","marks":1,"section":"B","ctx":[],"ctxb":[],"text":"Purchases for 2021 (ii) Depreciation of the sewing machines for 2021 (iii) Total expenses for 2021 (iv) Opening inventory for 2022 (v) Wages for 2022 (vi) Total expenses for 2022 (vii) Net profit before tax for 2022 The Circle Statement of comprehensive income for the years ending 31 December 2021 and 2022 2021 2022 Sales revenue 64 500 48 760 Opening inventory 13 245 (iv)","qTotal":31},{"q":11,"sub":"b","marks":4,"section":"B","ctx":["Purchases (i) 32 074 (1)","Closing inventory 17 040 26 719","Cost of goods sold 24 395 22 395","Gross profit 40 105 26 365","Expenses","Wages 18 625 (v) (1)","Depreciation of sewing machines (ii) 292.5 (1)","Telephone and postage 1 235 987","Rent and utilities 2 450 2 245","Total expenses (iii) (vi) (1) (1)","Profit for the year before tax 17 470 (vii) (1)"],"ctxb":[{"t":"grid","head":null,"rows":[["Purchases","(i)","32 074","1"],["Closing inventory","17 040","26 719"],["Cost of goods sold","24 395","22 395"],["Gross profit","40 105","26 365"],["Expenses Wages","18 625","(v)","1"],["Depreciation of sewing machines","(ii)","292.5","1"],["Telephone and postage","1 235 987"],["Rent and utilities","2 450","2 245"],["Total expenses","(iii)","(vi)","1","1"],["Profit for the year before tax","17 470","(vii)","1"]]}],"text":"Calculate the difference in the gross profit margin between 2021 and 2022.","qTotal":31,"ms":{"body":"Award 4 marks for the correct answer with or without %, learners do not\nneed to state that this is lower or less or need to use minus sign:\n8.11%\n8.1%\n8%\nAccept any response that is more accurate in terms of decimal places.\nOR\n1 mark for correct Gross Profit % for 2021 of 62.18% also accept 62.2%\nand 62%\nAND\n1 mark for correct Gross Profit % for 2022 of 54.07% also accept 54.1%\nand 54%\nAND\nAward 1 mark for formula in words\nGross Profit margin = Gross Profit / Revenue x 100\nOR\nGross Profit margin = Gross Profit / Sales Revenue x 100\nOR\nGPM = GP / SR x 100\n(accept all other accurate formula – must include x 100)\nNote: Allow answers with or without % sign.\nJanuary 2023","levels":null}},{"q":11,"sub":"c","marks":8,"section":"B","ctx":[],"ctxb":[],"text":"Using the information in 11(a), analyse how the profit for the year before tax could be increased in 2023.","qTotal":31,"ms":{"body":"Analyse how the Profit for the year before tax for the year could be\nincreased in 2023\nIndicative content:\nSales revenue fallen from £64 500 to £48 760\nGross profit fallen from £40 105 to £26 365 (8.1%)\nTotal expenses have fallen from £22 635 to £19 149.5\nProfit for the year before tax fallen £17 470 to £7 215.5 (58.7%)\nIncrease sales /sales revenue:\n• Strategies to help sell more goods – expansion - new shop, new\nwebsite, targeting different segments / older/younger / male /\nfemale / etc\n• Strategies to increase sales – marketing, advertising, promotion\ne.g. loyalty card or trade in schemes similar to M&S Lets Shwop\n• Strategies to increase revenue per item or increasing spend per\ncustomer – such as increased selling prices e.g. focus on selling\nhigher value items such as coats or designer labels, sell add ons\nsuch as bags, shoes, scarves etc - consider impact of increasing\nselling price on level of sales\n• Develop awareness of their USP – recycling green credentials etc\n– use this to gain PR opportunities\nReduce expenses :\n• Lower costs by introducing more cost effective methods of\nAdvertising and promotion e.g. more effective use of social\nmedia/influencers etc – examples specific to The Circle – consider\nimpact on profit of spending on advertising and promotion\n• Lower costs by moving to cheaper premises or methods of\nreducing utility bills, wages, postage, rent, utilities – specific\nexamples such as low energy lightbulbs, trade only online to avoid\nrent , utilities, insurance and wages\n• Reduce raw material costs e.g. encouraging clothing recycling\nschemes from customers, cheaper cotton, zip, buttons, packaging\nmaterials etc\nJanuary 2023","levels":8}},{"q":11,"sub":"d","marks":12,"section":"B","ctx":["Jisoo wants to expand the online side of her business by moving her production","facilities to a £150 000 unit in a Local Enterprise Partnership area that is supported by","the UK Government. There are government grants available of between £10 000 and","£500 000. The government allocates larger grants to businesses that agree to take","workers who have been on the unemployment register for more than six months.","Jisoo is considering two options to finance this move.","Option 1","Applying for a grant from a Local Enterprise Partnership","or","Option 2","Taking out a £150 000 mortgage at a variable interest rate of 6.9% pa repaid","over 25 years"],"ctxb":[{"t":"p","x":"Jisoo wants to expand the online side of her business by moving her production facilities to a £150 000 unit in a Local Enterprise Partnership area that is supported by the UK Government. There are government grants available of between £10 000 and £500 000. The government allocates larger grants to businesses that agree to take workers who have been on the unemployment register for more than six months. Jisoo is considering two options to finance this move. Option 1 Applying for a grant from a Local Enterprise Partnership or Option 2 Taking out a £150 000 mortgage at a variable interest rate of 6.9% pa repaid over 25 years"}],"text":"Evaluate whether Jisoo should apply for a grant (Option 1) or take out a mortgage (Option 2) to pay for the unit.","qTotal":31}],"msMatched":15},{"id":"U3-2306","unit":3,"key":"2023-06","series":"June 2023","date":"Thursday 18 May 2023","title":"Taylor · Luis · Kai · Kim","source":"pearson","kind":"exam","total":80,"parsedTotal":80,"sec":{"A":28,"B":52},"items":[{"q":1,"sub":null,"marks":2,"section":"A","ctx":["Personal Finance"],"ctxb":[{"t":"p","x":"Personal Finance"}],"text":"Give two features of an Individual Savings Account (ISA).","qTotal":2,"ms":{"body":"Award 1 mark for each feature of an Individual Savings Account (ISA) up\nto a maximum of 2 marks.\n• No tax (paid on interest earned)\n• There is an annual maximum you can invest / currently £20 000\n• You don’t pay Capital gains tax\n• ISAs require you to keep your money in for a fixed period\n• There could be a penalty for withdrawing money early before the\nend of the term\n• Everyone in the UK aged 16 + gets an ISA allowance at the start of\neach Tax Year\n• Low risk/secure/safer\nAccept any other appropriate answer.","levels":null}},{"q":2,"sub":null,"marks":2,"section":"A","ctx":[],"ctxb":[],"text":"Give two advantages of setting personal financial targets and goals.","qTotal":2,"ms":{"body":"Award 1 mark for each advantage of setting personal financial targets\nand goals up to a maximum of 2 marks.\n• to avoid getting into debt\n• to control costs /control/monitor spending\n• avoid legal action and/or repossession\n• remain solvent / avoid bankruptcy\n• maintain a good credit rating\n• generate income and savings\n• provide insurance against loss or illness\n• more likely to save money\n• more likely to be financially stable\n• to manage money to fund purchases / make financial\ndecisions\nAccept any other appropriate answer.\n26","levels":null}},{"q":3,"sub":null,"marks":2,"section":"A","ctx":[],"ctxb":[],"text":"Explain one advantage for the consumer of using a standing order to pay bills.","qTotal":2,"ms":{"body":"Award 1 mark for identification of an advantage of using a standing order\nand 1 mark for a linked development.\n• It’s automatic (1) helps prevent late payments (1)\n• Likely to improve credit rating (1) as less missed payments\n• Consumer chooses the amount/date (1) more control over\nyour money (1)\n• Quick and easy to set up/cancel (1) saves time/convenient\n• It is a fixed sum (1) therefore easier to plan/budget (1)\nAccept any other appropriate answer.\nDo not accept “quick and easy” on its own.","levels":null}},{"q":4,"sub":null,"marks":4,"section":"A","ctx":[],"ctxb":[],"text":"Explain two disadvantages for the consumer of using a payday loan to pay for a holiday.","qTotal":4,"ms":{"body":"Award 1 mark for identification of a disadvantage of using a payday loan to\npay for a holiday and 1 mark for a linked development.\n• High rates of interest (1) outgoings/re-payments are higher / may\nget into unmanageable debt /insolvency (1)\n• Very short time to pay back the debt /high risk you can’t pay (1)\nimpact on credit score (1)\n• If you can’t pay on time charges may then be added (1) increasing\nthe debt (1)\nAccept any other appropriate answer.\n27","levels":null}},{"q":5,"sub":null,"marks":6,"section":"A","ctx":["Taylor is 30 years old and has just bought her first property. She has a £150 000 mortgage","but no other debts. Taylor wants to renovate the property and sell it in two years’ time.","Taylor will need to purchase decorating materials and new bathroom equipment for","her property. She estimates that this will cost her £2 500. She has £500 in her savings","account. She is wondering whether to save up the money for the renovations, or to","borrow from a bank."],"ctxb":[{"t":"p","x":"Taylor is 30 years old and has just bought her first property. She has a £150 000 mortgage but no other debts. Taylor wants to renovate the property and sell it in two years’ time. Taylor will need to purchase decorating materials and new bathroom equipment for her property. She estimates that this will cost her £2 500. She has £500 in her savings account. She is wondering whether to save up the money for the renovations, or to borrow from a bank."}],"text":"Discuss whether Taylor should save her own money for the renovations or borrow from a bank.","qTotal":6,"ms":{"body":"Discuss whether Taylor should save her own money for the\nrenovations or borrow from a bank.\nAdvantages of borrowing from bank\n• She has no other debts apart from her mortgage\n• She plans to sell the flat in 2 years’ time – with the renovations she\ncould get the money back when she sells\n• She gets the money sooner than saving so has more time to\nrenovate to a higher standard – property could then be worth more\nDisadvantages of borrowing from bank\n• Interest to pay which she wouldn’t pay if she used her own savings\n• If the mortgage rate goes up she may struggle to pay the loan and\nthe extra mortgage interest\n• It’s another monthly outgoing and she will have lots of other costs\nas she has just moved into her first property\nAdvantages of savings\n• No monthly repayments\n• No interest to pay on a debt\n• May earn interest on savings\n• She doesn’t get into unmanageable debt\nDisadvantages of savings\n• May take many years to save the money for the renovations –\nbathrooms are expensive – won’t get chance to enjoy living in a\nnicer property\n• By the time she has saved the money the cost of the renovation will\nmost likely be higher than if she gets it done now – meaning she\nmay not have enough money\n• No savings available for other things such as unexpected\nbills/holidays","levels":6}},{"q":6,"sub":null,"marks":12,"section":"A","ctx":["Luis is 18 years old and has recently left home to go to university. Luis has moved into","a house share with other students. Luis has arranged to pay his rent by standing order","each term. He pays his other bills, such as phone bill and gaming subscriptions, by direct","debit. Luis enjoys shopping for clothes and games online. He has a student bank account","with a debit card. Luis has realised that after paying for his food, transport and academic","costs there is little money left. He is already worried that he may have to use his overdraft","facility. Jared, Luis’s housemate, has advised him to take out a credit card.","Luis has researched the following credit card providers.","Credit card","provider","Credit","limit","APR","(Interest)","Interest free","purchases","period","Cashback","on","purchases","Penalty charges for","missing the minimum","monthly repayment","Westshire £500 18.9% 56 days 2% £12 per day","Ashridge £1","000 21.9% 30 days 1% £5 per day","Shirevale £750 22% 60 days 0.5%","No charge for the first","3 days rising to £10 per","day after this.","Royal Bank £2","000 26% 90 days 1.5% APR increased to","29.9%"],"ctxb":[{"t":"p","x":"Luis is 18 years old and has recently left home to go to university. Luis has moved into a house share with other students. Luis has arranged to pay his rent by standing order each term. He pays his other bills, such as phone bill and gaming subscriptions, by direct debit. Luis enjoys shopping for clothes and games online. He has a student bank account with a debit card. Luis has realised that after paying for his food, transport and academic costs there is little money left. He is already worried that he may have to use his overdraft facility. Jared, Luis’s housemate, has advised him to take out a credit card. Luis has researched the following credit card providers."},{"t":"flow","x":["Credit card","provider","Credit","limit","APR","(Interest)","Interest free","purchases","period","Cashback","on","purchases","Penalty charges for","missing the minimum","monthly repayment","Westshire £500 18.9% 56 days 2% £12 per day","Ashridge £1","000 21.9% 30 days 1% £5 per day","Shirevale £750 22% 60 days 0.5%","No charge for the first","3 days rising to £10 per"]},{"t":"p","x":"day after this. Royal Bank £2 000 26% 90 days 1.5% APR increased to 29.9%"}],"text":"Evaluate which credit card provider would be the most suitable for Luis.","qTotal":12,"ms":{"body":"Indicative content\nWestshire :\n• Lowest credit limit £500\n• Lowest APR (interest) 18.9%\n• He won’t be able to borrow as much but what he does borrow will be charged\nat a lower % than the other 3 options.\n• Second lowest interest free purchase period at 56 days meaning he only has\nthe first 56 days to spend without being charged interest on those purchases-\nhe likes to shop online so this is a disadvantage compared to Shirevale and\nthe Royal bank which allow more days.\n• However, he gets more cashback on purchases at 2% - this is the highest of\nall the 4 cards. 4 times higher than Shirevale and double Ashridge. He likes to\nshop online – if he uses for all purchases and shopping can offset the APR\nwhich is already the lowest at 18.9%\n• Highest penalty for late payments at £12.day – could very quickly get into\nunmanageable debt e.g. one month of not repaying costs approx. £360 which\nwould then be added to his debt.\nAshridge:\n• Second highest credit limit - £1000 – therefore more money for emergencies\n– less worry about affording other bills e.g. rent\n• Second lowest APR at 21.9%\n• Lowest interest free purchase period 30 days\n• Second lowest cash back on purchases at 1% so less to offset the APR than\nWestshire with 2% cash back\n• However penalty for late payments only £5/day - £7 lower than Westshire-\nover a month (30 days) £150 - £220 less than Westshire – less chance of\nmounting debt\nShirevale:\n• Second lowest credit limit at £750 therefore less available for emergencies –\nhowever less temptation to use the card and get into debt\n• 2nd highest APR at 22% - 3.1% higher than Westshire on £750 over a year this\nis an extra £23.25 more than Westshire and £165 overall.\n• 2nd highest days for interest free purchases at 60\n• Lowest cash back on purchases at 0.5% so less to offset the high APR\n• No charge for the first 3 days if he misses payment – therefore if he forgets\nhe isn’t penalised immediately – however goes up to £10 after this – debt\ncould mount quickly – 30 days will cost £300 in extra debt\n• Royal Bank:\n• Highest credit limit at £2000 – biggest amount to fall back on and to enjoy\nstudent life\n• Highest APR 26% - if uses the full £2000 costs £520 which is added to debt –\ncould become unmanageable – particularly as most students have very little\ndisposable income\n• However highest interest free purchase period 90 days – could help to buy\nbooks and set up home without worrying about adding to debt\n• 2nd highest cash back 1.5% - offsets APR\n• Penalty for late payments could be cheapest depending on balance – APR\nrises to 29.9% from 26% which was already the highest. However even if he\nhas max debt of £2000 this would cost £78 over the year – 21p /day -\ncheapest\n26","levels":12}},{"q":7,"sub":null,"marks":2,"section":"B","ctx":["Business Finance"],"ctxb":[{"t":"p","x":"Business Finance"}],"text":"State two types of revenue income.","qTotal":2,"ms":{"body":"Award 1 mark for each item of Revenue Income identified, up to a\nmaximum of 2 marks.\n• Cash sales\n• Credit sales\n• Rent received\n• Commission received\n• Interest received\n• Discount received\nAward a maximum of 1 mark for sales where the learner has not\nspecified whether it is cash or credit.\nAccept any other appropriate answer","levels":null}},{"q":8,"sub":null,"marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Explain why a business might calculate the margin of safety.","qTotal":2,"ms":{"body":"Award 1 mark for identification of why a business might calculate it’s\nMargin of Safety and 1 mark for a linked development.\n• Helps the business to forecast the amount the estimated sales\ncan fall (1) before a loss is made/the business breaks even (1)\n• The calculation helps a business gauge the level of risk (1) when\nlaunching a new venture/so that they can decide if the venture is\ntoo risky (1)\nAccept any other appropriate answer\n28","levels":null}},{"q":9,"sub":null,"marks":2,"section":"B","ctx":[],"ctxb":[],"text":"State two outflows that could be recorded in a cash flow forecast.","qTotal":2,"ms":{"body":"Award 1 mark for each outflow identified, up to a maximum of 2 marks.\n• Cash purchases\n• Credit purchases\n• Rent\n• Rates\n• Salaries\n• Wages\n• Utilities (electricity, water, internet etc.)\n• Purchase of assets\n• Value Added Tax (VAT)\n• Interest (paid)\n• Loan (repayments)\n• Inventory/stock\nAward 1 mark for purchases where the learner has not used cash\npurchases or credit purchases.\nAccept any other appropriate answer.\n27","levels":null}},{"q":10,"sub":"a","marks":2,"section":"B","ctx":["Kai owns a business called Hole in One that makes and sells high quality doughnuts","throughout the UK.","Kai is introducing a new premium product to his range called The Good One. The Good","One will be gluten free, lactose free and vegan. Kai knows that the specialist ingredients","for this will be twice as expensive as for his current range. He will also need to invest in","a separate production line to prevent cross-contamination of allergens. This investment","will increase his fixed costs as he intends to lease the new production line.","Kai has estimated the following figures for The Good One:","•","variable costs £2 per box","• selling price £5 per box.","He estimates he will sell 1 100 boxes of doughnuts per month in his first year of trading."],"ctxb":[{"t":"p","x":"Kai owns a business called Hole in One that makes and sells high quality doughnuts throughout the UK. Kai is introducing a new premium product to his range called The Good One. The Good One will be gluten free, lactose free and vegan. Kai knows that the specialist ingredients for this will be twice as expensive as for his current range. He will also need to invest in a separate production line to prevent cross-contamination of allergens. This investment will increase his fixed costs as he intends to lease the new production line. Kai has estimated the following figures for The Good One: • variable costs £2 per box • selling price £5 per box. He estimates he will sell 1 100 boxes of doughnuts per month in his first year of trading."}],"text":"Complete the table below.","qTotal":16,"ms":{"body":"Award 1 mark for each correct answer up to a total of 2 marks.\nQuantity 0 500 1000 1500\nFixed Costs (£) 1 200 1 200 1 200 1 200\nTotal Variable\nCosts (£) 0 1 000 2 000 (ii) 3 000\nTotal Costs (£) 1 200 2 200 3 200 4 200\nTotal Revenue\n(£) 0 (i) 2 500 5 000 7 500","levels":null}},{"q":10,"sub":"i","marks":4,"section":"B","ctx":[],"ctxb":[],"text":"Total revenue (ii) Fixed costs (iii) Total costs (iv) Break -even point.","qTotal":16},{"q":10,"sub":"c","marks":4,"section":"B","ctx":["Break-even chart for The Good One","Number of boxes","Revenue/Costs (£)","8000","7000","6000","5000","4000","3000","2000","1000","0","0","100 200 300 400 500 600 700 800 900 1000 1100 1200 1300 1400 1500"],"ctxb":[{"t":"flow","x":["Break-even chart for The Good One","Number of boxes","Revenue/Costs (£)","8000","7000","6000","5000","4000","3000","2000","1000","0","0"]},{"t":"p","x":"100 200 300 400 500 600 700 800 900 1000 1100 1200 1300 1400 1500"}],"text":"Kai had forgotten to include additional factory space in his calculations for fixed costs. These are now £150 higher than he originally thought. Calculate the new break-even point including the new fixed costs.","qTotal":16,"ms":{"body":"Award 4 marks for the correct answer.\n• 450\nOR\nAward 3 marks for the correct formula in numbers\n• 1 350 / 3\n• 1 350 / 5 – 2\nOR\nAward 1 mark for formula in words\n• Break Even = Fixed Cost / (Selling price per unit – Variable cost\nper unit)\n• Break Even = Fixed Cost / Contribution per unit\nAND\nAward 1 mark for calculation of new fixed costs\n• £1 350\nAccept figures without £ sign\nAccept abbreviations in formula such as FC, SP, VC\n29","levels":null}},{"q":10,"sub":"d","marks":6,"section":"B","ctx":["Break-even point  boxes"],"ctxb":[{"t":"p","x":"Break-even point  boxes"}],"text":"Discuss the benefits and drawbacks to Hole in One of using break-even analysis.","qTotal":16,"ms":{"body":"Benefits and drawbacks of using Break Even Analysis\nBenefits\n• The business can use it to model the impact of different selling\nprices/costs on BEP and so potential profit\n• As it’s a forecast it allows the business to predict the likely profit\n/loss\n• Ensures the business considers all its costs\n• It’s a feasibility study /reality check to consider whether it is\npossible to successfully launch the new product\n• The business can estimate the risk as it allows you to also\nconsider Margin of Safety\nDrawbacks\n• It’s an estimate – may not be reliable\n• Doesn’t take into account competitor reactions\n• It’s only as good as the person who prepares it he may wrongly\nestimate costs\n• Doesn’t take into account any changes to the external\nenvironment e.g. Inflation, incomes, consumer\npreferences/uptake\n• Only considers financial factors – Price and cost\n• Information on predicted sales may be limited and lead to errors\nAny other appropriate response","levels":6}},{"q":11,"sub":"a","marks":4,"section":"B","ctx":["Kim runs a business called Kim’s Castles. Kim owns two luxury apartments in one of the","UK’s biggest cities, which she purchased in 2020. Both properties are redecorated once","each year and Kim constantly updates her colour schemes and soft furnishings. This","helps her properties maintain their 4-star rating. She rents out the apartments to tourists","and businesspeople. Customers can book for a single night but if they book for longer","than one week the rate per night will fall."],"ctxb":[{"t":"p","x":"Kim runs a business called Kim’s Castles. Kim owns two luxury apartments in one of the UK’s biggest cities, which she purchased in 2020. Both properties are redecorated once each year and Kim constantly updates her colour schemes and soft furnishings. This helps her properties maintain their 4-star rating. She rents out the apartments to tourists and businesspeople. Customers can book for a single night but if they book for longer than one week the rate per night will fall."}],"text":"Complete the statement of financial position on page 18 for Kim’s Castles:","qTotal":30},{"q":11,"sub":"i","marks":1,"section":"B","ctx":[],"ctxb":[],"text":"Ac cumulated depreciation of machinery (ii) Cash (iii) Net current assets/liabilities (iv) Net assets (v) Capital. Kim’s Castles Statement of financial position for the year ended 31 December 2022 Cost Accumulated depreciation Net book value £ £ £ Non-current assets Property 300 000 300 000 Machinery (drills, IT equipment, sewing machines, etc.) 15 500 (i) 13 097","qTotal":30},{"q":11,"sub":"b","marks":3,"section":"B","ctx":["313 097","Current assets","Inventory (paints, fabrics,","wallpapers, soft furnishings,","toiletries, etc.)","22 200","Trade receivables 7 600","Bank 3 200","Cash (ii) (1)","33 700","Current liabilities","Trade payables 4 300","Tax 3 600","7 900","Net current assets/liabilities (iii) (1)","Non-current liabilities","Long-term borrowing 305 000","Net assets (iv) (1)","Financed by","Capital (v) (1)","Retained profit 21 897","Capital employed 33 897"],"ctxb":[{"t":"cap","x":"313 097"},{"t":"grid","head":["Current assets Inventory (paints, fabrics, wallpapers, soft furnishings, toiletries, etc.)","22","200"],"rows":[["Trade receivables","7 600"],["Bank","3 200"],["Cash","(ii)","1"]]},{"t":"grid","head":["","33","700"],"rows":[["Trade payables","4 300"],["Tax","3 600"],["7 900 Net current assets/liabilities","(iii)","1"],["Non-current liabilities Long-term borrowing","305 000"],["Net assets","(iv)","1"],["Financed by Capital","(v)","1"],["Retained profit","21 897"],["Capital employed","33 897"]]}],"text":"Calculate the liquid capital ratio.","qTotal":30,"ms":{"body":"Award 3 marks for the correct answer of 1.46\nAccept any response that is more accurate in terms of decimal places\ne.g. 1.455 also accept 1.5\nOR\nAward 1 mark for formula in words\nLiquid Capital ratio = (current assets – inventory)\ncurrent liabilities\nOR\n1 mark for formula in numbers\n11 500 / 7 900 OR (33 700 – 22 200) / 7900\nAND\n1 mark for correctly calculating: current assets – inventory as £11 500\nLearners must not be awarded full marks unless they have the\ncorrect answer\n33","levels":null}},{"q":11,"sub":"c","marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Kim has been told that property in the city has increased in value by a total of 8% since she bought her apartments in 2020. Calculate the new value of her non-current assets.","qTotal":30,"ms":{"body":"Award 2 marks for the correct answer of £337 097\nAccept answer with or without £ sign.\nOR\nAward 1 mark for correct calculation of the increase in value of £24 000","levels":null}},{"q":11,"sub":"d","marks":8,"section":"B","ctx":[],"ctxb":[],"text":"Kim thinks that her retained profit is lower than similar businesses in the city. Discuss how K im’s retained profit could be increased in 2023.","qTotal":30,"ms":{"body":"How could retained profit be increased in 2023\nIndicative content:\nIncreasing Revenue\n• Strategies to increase sales – marketing, advertising, promotion\ne.g. loyalty card, new website, targeting different segments /\nmarkets /older/younger\n• Strategies to increase revenue per room or increasing spend per\ncustomer – such as buying add-ons e.g. welcome basket - consider\nimpact of increasing selling price on level of sales\n• Strategies to increase total revenue e.g. discounts for long stays\nmay increase occupancy rates\nReducing Costs\n• Strategies to reduce cost of sales e.g. buying cheaper raw\nmaterials, paint, cushions etc. reduce wage bill, find a cheaper app\nto use than Butterfly – consider impact of doing each of these – e.g.\nlower quality rooms and prices\nReduce expenses\n• Lower expenses by introducing more cost effective methods of\nAdvertising and promotion – examples specific to Kim’s Castles –\nconsider impact on profit of spending on advertising and\npromotion\n• Strategies to reduce other expenses - reducing utility bills, wages,\nrent or mortgage, utilities – specific examples such as low energy\nlightbulbs, insurance\nManagement strategies\n• Introducing financial monitoring and setting targets for costs\nand revenue – setting budgets to avoid excessive costs, paying off\ndebt therefore reducing liabilities e.g. she has £305000 long term\nliabilities.\nIf learners give balanced discussion or balanced analysis reward at Level 3","levels":8}},{"q":11,"sub":"e","marks":12,"section":"B","ctx":["Kim has been using a marketing agency called Butterfly, which allows customers","to book her apartments using the Butterfly app. Kim pays Butterfly 10% of the total","booking price for providing this service.","Kim wants to develop her own Kim’s Castles app. She estimates the cost of developing","and maintaining her own app will be £10 000 in the first year.","Kim is considering two options to finance the Kim’s Castles app:","Option 1: Retained profit","OR","Option 2: Sale of assets","."],"ctxb":[{"t":"p","x":"Kim has been using a marketing agency called Butterfly, which allows customers to book her apartments using the Butterfly app. Kim pays Butterfly 10% of the total booking price for providing this service. Kim wants to develop her own Kim’s Castles app. She estimates the cost of developing and maintaining her own app will be £10 000 in the first year. Kim is considering two options to finance the Kim’s Castles app: Option 1: Retained profit OR Option 2: Sale of assets ."}],"text":"Evaluate whether Kim should use retained profit (Option 1) or sell some of her assets (Option 2) to pay for the development of the app.","qTotal":30,"ms":{"body":"Indicative content: Pay for new app using retained profit or sale of assets\nArgument for Option 1 retained profit\n• Retained profit is £21 897 – so can pay for the app outright and still\nhave profit left for other things\n• She doesn’t have to repay the money - no monthly bill and no interest\nwhich reduces profit\n• Keeps all her assets which she uses in the business e.g. IT equipment,\ndrills and sewing machines etc so still has them available to use\nwhenever she needs them\n• No upfront cost / deposit or fees for fixing or organising a loan\n• She doesn’t give away ownership as she might if she raised money by\nchanging the ownership status of the business and selling shares, or\nusing a venture capitalist so retains full control\nArguments against\n• She can’t use the money for other things e.g. buy other properties and\nhelp the business to grow\n• She isn’t getting the rewards for all her hard work may lose motivation\nArgument for Option 2 sale of assets\n• Machinery is currently worth £13 097 therefore she is likely to be able\nto raise all the money she needs from doing this\n• Won’t appear as depreciation on Statement of comprehensive income\n– benefit to profit\n• Won’t have to pay for maintenance costs\n• If she rents machinery when she needs it she can access the latest\nmodels and technology which may be an advantage\n• Kim will keep ownership and control of the business\nArguments against\n• Might not get all the money as may not be able to sell second hand\nequipment for as much as NBV\n• Cost of payments to hire machines when needed may lead to lower\nprofits\n• She will not have the machinery she needs to run the business / might\nnot be available to hire when she needs it to complete renovations and\nmaintenance – could delay projects which incurs costs\n• She could reduce her inventory – currently £22 200 tied up in inventory\ne.g. wallpaper, paint and toiletries for the apartments – may run out of\nnecessary items if stock held is too low – unsatisfied customers and\ndelays to completing projects which incurs costs","levels":12}}],"msMatched":16},{"id":"U3-2401","unit":3,"key":"2024-01","series":"January 2024","date":"Monday 15 January 2024","title":"Connor · Tia · When Tia · Arjun","source":"pearson","kind":"exam","total":80,"parsedTotal":80,"sec":{"A":28,"B":52},"items":[{"q":1,"sub":null,"marks":2,"section":"A","ctx":[],"ctxb":[],"text":"Identify two impacts on an individual of a rise in the rate of interest in relation to borrowing and saving.","qTotal":2,"ms":{"body":"Identify two impacts on an individual of a\nrise in the rate of interest.\nAward one mark for each impact identified,\nup to a maximum of two marks.\n• Increased repayment costs on borrowing\n/ loans / mortgages /credit cards (1)\n• Increased earnings on savings (1)\n• More likely to save (1)\n• Less/more disposable income (1)\n• More likely to get into uncontrollable\ndebt (1)\n• More likely to default on debt\nrepayments (1)\n• Less willing/unwilling to take out loans\nAccept any other reasonable answer.","levels":null}},{"q":2,"sub":null,"marks":2,"section":"A","ctx":[],"ctxb":[],"text":"State two ways an individual can maintain a good credit rating.","qTotal":2,"ms":{"body":"State two ways an individual can maintain a\ngood credit rating.\nAward one mark for each way a consumer\ncan maintain their credit rating up to a\nmaximum of two marks.\n• Register on the electoral role (1)\n• Pay bills/loans/credit cards on time (1)\n• Avoid County Court\njudgements/bankruptcy/insolvency (1)\n• Avoid unmanageable/high levels of\ndebt/applying for too much credit (1)\n• Do not move home regularly (1)\n• Get a credit builder credit card/apply for\ncredit (1)\nAccept any other appropriate answer.","levels":null}},{"q":3,"sub":null,"marks":2,"section":"A","ctx":[],"ctxb":[],"text":"Explain one advantage for an individual of using electronic transfer as a method of payment.","qTotal":2,"ms":{"body":"Award one mark for identification of an\nadvantage of using electronic transfer as a\nmethod of payment and one mark for a\nlinked development.\n• It’s instant (1) therefore saves time (1)\n• You don’t need a bank card (1)\ntherefore more secure (1)\n• Eliminates risk of losing cash or cards\n(1) so less chance of financial loss (1)\n• Payments can be made remotely (1) no\nneed to travel or be present (1)\n• Available 24/7 (1) which means\npayments can be made at any time (1)\nDo not accept quick and easy or convenient\non their own.\nAccept any other reasonable answer.","levels":null}},{"q":4,"sub":null,"marks":4,"section":"A","ctx":[],"ctxb":[],"text":"Explain two advantages for an individual of planning expenditure.","qTotal":4,"ms":{"body":"Award one mark for identification of an\nadvantage to an individual of planning\nexpenditure and one mark for a linked\ndevelopment, up to a maximum of four\nmarks\n• Avoid getting into debt (1) therefore\navoiding legal\naction/Bankruptcy/maintain a good credit\nrating (1)\n• More likely to achieve personal financial\ngoals (1) as more control of expenses (1)\n• Avoid overspending (1) as more aware of\noutgoings (1)\n• More likely to have savings (1) which\ncould mean money is earned in interest\n• To make sure expenses are paid on time\n(1) therefore no interest/additional costs\nAccept any other reasonable answer.","levels":null}},{"q":5,"sub":null,"marks":6,"section":"A","ctx":["Connor is 26 years old. He lives alone in a house that he bought five years ago. He was","made redundant from his job eight months ago. He has no savings and owes £4 000 to","the bank for missed mortgage payments. Connor also owes £2 000 for utility bills and","he has credit card debts of £4 500. He recently sought help from Citizens Advice who","suggested that he consider applying for an Individual Voluntary Arrangement (IVA)."],"ctxb":[{"t":"p","x":"Connor is 26 years old. He lives alone in a house that he bought five years ago. He was made redundant from his job eight months ago. He has no savings and owes £4 000 to the bank for missed mortgage payments. Connor also owes £2 000 for utility bills and he has credit card debts of £4 500. He recently sought help from Citizens Advice who suggested that he consider applying for an Individual Voluntary Arrangement (IVA)."}],"text":"Discuss the advantages and disadvantages to Connor of applying for an Individual Voluntary Arrangement (IVA).","qTotal":6,"ms":{"body":"Advantages of applying for an IVA\n• Having an IVA is a way of avoiding\nbankruptcy\n• Some of Connor’s debts may be written off\n• Connor will have one fixed monthly\nrepayment as all his debt repayments will be\ncombined\n• Supports budgeting due to monthly fixed\nrepayment\n• The interest on Connor’s debts will be frozen\nas at the date of the creditors meeting\nconvened to approve the IVA\n• Legal action by Connor’s creditors will be\nstopped\n• Most IVAs enable the individual to be debt-\nfree in five/six years\n• Due to the fees involved an IVA is only\nsuitable for debts over £10 000 Connor’s\ndebts are £10 500\n• An IVA protects your home and allows\nConnor to continue living in it and making\nhis mortgage payments as normal.\nDisadvantages of applying for an IVA\n• Connor’s credit rating will be adversely\naffected throughout the IVA, and possibly for\na period afterwards\n• Some debts cannot be included in an IVA,\ne.g. court fines\n• If Connor benefits from any unexpected\nfunds, he may be expected to pay the funds\ninto the IVA\n• The IVA may have to be disclosed to any\nfuture creditors/employers which may affect\nConnor’s ability to find a new home/borrow\nin the future/find employment in certain\nsectors e.g. finance, legal etc.\n• An IVA can only be set up by a professional\nsolicitor or accountant and will usually\ninvolve fees (approximately £5 000)","levels":6}},{"q":6,"sub":null,"marks":12,"section":"A","ctx":["Tia is 28 and works as a supply teacher. As such Tia’s earnings are often unpredictable.","When Tia has paid her utility bills and her living expenses each month, she has between","£100 and £400 left over. She would like to save this money. She has £1 500 in her","current account. Her personal goals are to buy her own home and to save money for","emergencies and for travelling. Tia has researched the following savings options available","through her bank.","Account AER % Term Minimum","deposit","Maximum","monthly","deposit","Instant","access to","money","Regular","saver","5% Variable","rate 12 months £1 000 £200 Yes","Deposit","account","3.5% Fixed","rate 3 years £2 000 £7 000 No","Cash ISA 2.75% Fixed","rate 2 years £1 £20 000 per","year","Yes but lose","6 months’","interest","Current","account","1.5% on","credit","balances","N/A £1 No limit Yes"],"ctxb":[{"t":"p","x":"Tia is 28 and works as a supply teacher. As such Tia’s earnings are often unpredictable. When Tia has paid her utility bills and her living expenses each month, she has between £100 and £400 left over. She would like to save this money. She has £1 500 in her current account. Her personal goals are to buy her own home and to save money for emergencies and for travelling. Tia has researched the following savings options available through her bank."},{"t":"flow","x":["Account AER % Term Minimum","deposit","Maximum","monthly","deposit","Instant","access to","money","Regular","saver","5% Variable","rate 12 months £1 000 £200 Yes","Deposit","account","3.5% Fixed","rate 3 years £2 000 £7 000 No","Cash ISA 2.75% Fixed","rate 2 years £1 £20 000 per","year","Yes but lose","6 months’","interest","Current","account","1.5% on","credit","balances","N/A £1 No limit Yes"]}],"text":"Evaluate which option would be the most suitable for Tia.","qTotal":12,"ms":{"body":"Regular saver\nHighest interest at 5%\nOnly need to keep money in the account for 12\nmonths\nHave to have £1 000 to open account she has £1\n500 so can open this account\nMaximum monthly deposit is £200 – this might not\nbe suitable as Tia has between £100 and £400\nmost months\nInstant access to savings so if doesn’t get work as\na supply teacher can access her savings\nDeposit account\n2nd highest interest at 3.5%\nNeed to keep money in account for 3 years\nNeeds £2 000 to open this account – at the\nmoment she doesn’t have enough money\nMaximum monthly deposit is £7 000 this will easily\nbe enough for Tia\nDoes not have instant access to savings therefore\nif doesn’t get work as supply teacher she may\nstruggle\nAlso if she wants to use savings to travel she can’t\nCash ISA\n3rd highest interest at 2.75%\nNeed to keep money in account for 2 years\nOnly needs £1 to open the account so can do it\nstraight away\nMaximum deposit is £20 000 per year this is\nenough for Tia as she has between £1 200 and £4\n800 per year\nInstant access to savings which is good as supply\nteacher however she will lose the interest\nCurrent account\nLowest interest at 1.5%\nNot tied to keep money in account for any period\nAlready has the account open so easiest option as\ndoes not need to do anything\nNo limit on what she can deposit\nInstant access to savings which is good as her\nincome is not guaranteed as a supply teacher","levels":12}},{"q":7,"sub":null,"marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Give two external sources of finance.","qTotal":2,"ms":{"body":"Give two external sources of finance.\nAward one mark for each source identified, up to\na maximum of two marks.\n• Loans/ debentures (1)\n• overdraft (1)\n• owner’s capital (1)\n• crowd-funding (1)\n• mortgages (1)\n• venture capital/ business angel (1)\n• debt factoring (1)\n• hire purchase (1)\n• leasing (1)\n• trade credit (1)\n• grants (1)\n• donations (1)\n• peer to peer lending (1)\n• invoice discounting (1)\nAccept any other appropriate response.","levels":null}},{"q":8,"sub":null,"marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Explain one impact of a rise in Value Added Tax (VAT) on a cash flow forecast.","qTotal":2,"ms":{"body":"Explain one impact of a rise in Value Added Tax\non a cash flow forecast.\nAward one mark for a correct impact identified,\nand one for a developed point.\n• Outflows would increase (1) leading to lower\nnet cash flow/closing balance (1)\n• Lower inflows (1) leading to lower net cash\nflow/closing balance (1)\n• Higher inflows (1) leading to higher net cash\nflow/closing balance (1)\nAccept any other appropriate response.","levels":null}},{"q":9,"sub":null,"marks":2,"section":"B","ctx":[],"ctxb":[],"text":"State two current assets.","qTotal":2,"ms":{"body":"State two current assets\nAward one mark for each current asset\nidentified, up to a maximum of two marks.\n• Stock/Inventory (1)\n• Debtors/Trade receivables (1)\n• Bank (1)\n• Cash (1)\n• Prepayments (1)\nAccept any other appropriate response.","levels":null}},{"q":10,"sub":"a","marks":6,"section":"B","ctx":["Arjun and Sai run a business called Home Office Creations. They make furniture for small","businesses and people who regularly work from home. The owners have prepared a cash","flow forecast for the first three months of 2024."],"ctxb":[{"t":"p","x":"Arjun and Sai run a business called Home Office Creations. They make furniture for small businesses and people who regularly work from home. The owners have prepared a cash flow forecast for the first three months of 2024."}],"text":"Complete the cash flow forecast for Home Office Creations.","qTotal":16,"ms":{"body":"Award one mark for each correct answer.\nJanuary February March\n£ £ £\nInflows\nCredit sales 1 890 953 509\nCash sales 20 068 (ii) 16 780 13 276\nBank interest 98\nTotal inflows 21 958 17 831 13 785\nOutflows\nPurchase of\nassets\n15 500\nRent 1 500 1 500 1 500\nWages 6 890 6 200 8 578\nUtilities 470 510 (v) 380\nOther outflows 2 349 2 489 4 495\nTotal\noutflows\n11 209 26 199 14 953\nNet cash flow 10 749 (iii) (8 368) (1 168)\nOpening\nbalance\n(i) (7 389) (iv) 3 360 (5 008)\nClosing\nbalance\n3 360 (5 008) (vi) (6 176)\nAnswers must correctly state if the figure is positive or\nnegative","levels":null}},{"q":10,"sub":"b","marks":2,"section":"B","ctx":["Cash flow forecast for Home Office Creations for the three months","ending 31 March 2024","January February March","£ £ £","Inflows","Credit sales 1 890 953 509","Cash sales 20 068 (ii) 13 276","Bank interest 98","Total inflows 21 958 17 831 13 785","Outflows","Purchase of assets 15 500","Rent 1 500 1 500 1 500","Wages 6 890 6 200 8 578","Utilities 470 510 (v)","Other outflows 2 349 2 489 4 495","Total outflows 11 209 26 199 14 953","Net cash flow 10 749 (iii)","(1 168)","Opening balance (i) (iv) (5 008)","Closing balance 3 360 (5 008) (vi)","13","In February 2024 Arjun and Sai intend to purchase a wood cutting machine for","£15 500.","This amount is shown as Purchase of assets in the cash flow forecast. They","have just discovered that if they buy the machine they will reduce staff wages by","25% per month."],"ctxb":[{"t":"p","x":"Cash flow forecast for Home Office Creations for the three months"},{"t":"flow","x":["ending 31 March 2024","January February March","£ £ £","Inflows","Credit sales 1 890 953 509","Cash sales 20 068 (ii) 13 276","Bank interest 98","Total inflows 21 958 17 831 13 785","Outflows","Purchase of assets 15 500","Rent 1 500 1 500 1 500","Wages 6 890 6 200 8 578","Utilities 470 510 (v)","Other outflows 2 349 2 489 4 495","Total outflows 11 209 26 199 14 953","Net cash flow 10 749 (iii)","(1 168)","Opening balance (i) (iv) (5 008)","Closing balance 3 360 (5 008) (vi)","13"]},{"t":"p","x":"In February 2024 Arjun and Sai intend to purchase a wood cutting machine for £15 500. This amount is shown as Purchase of assets in the cash flow forecast. They have just discovered that if they buy the machine they will reduce staff wages by 25% per month."}],"text":"Calculate the new closing balance for February 2024 if Arjun and Sai purchase the wood cutting machine.","qTotal":16,"ms":{"body":"Award two marks for the correct response of (£3 458)\nAccept correct answer anywhere in workings box either\nwith or without the £ sign\nOR\nAward one mark for giving the correct formula in words\nClosing Balance = Opening Balance + Inflows –Outflows\nOR\nClosing Balance = Opening Balance + Net Cash Flow\nOR\nAward one mark for recalculating the new figure for\nwages at £4 650\nOR\nAward one mark for calculating the 25% reduction in\nwages at £1 550","levels":null}},{"q":10,"sub":"c","marks":2,"section":"B","ctx":["£"],"ctxb":[],"text":"State one benefit and one limitation of using a cash flow forecast.","qTotal":16,"ms":{"body":"Award one mark for correctly identifying a benefit\nand one mark for a correct limitation of using a Cash\nFlow Forecast – a maximum of two marks overall\nBenefits\n• aware of all your inflows/outflows (1)\n• good for planning ahead/budgeting (1)\n• you can see if you will go into deficit/overdraft\n• can try to take action to avoid deficits (1)\n• can use to secure finance (1)\nLimitations\n• it’s a prediction so not always accurate (1)\n• can’t predict inflows/outflows accurately (1)\n• business owners may lack the experience to\ninterpret it accurately (1)\n• may make business decisions based on\ninaccurate information (1)\nDo not accept “time could be spent doing other\nthings” or similar","levels":null}},{"q":10,"sub":"d","marks":6,"section":"B","ctx":["Benefit","Limitation"],"ctxb":[{"t":"p","x":"Benefit Limitation"}],"text":"Discuss actions that Arjun and Sai could take to improve the closing balances in the cash flow forecast in the first three months of 2024.","qTotal":16,"ms":{"body":"Actions which could be taken to improve closing\nbalances in first 3 months of 2024\nIncrease inflows by:\n• increasing selling price – would only increase\ninflows if same number of customers –\ndisadvantage – customers may not buy at higher\nprice\n• advertising/promotion – may cause worse cash\nflow in short term – long term if generates more\nrevenue than the promotion cost then it would\nincrease closing balance\n• reduce period of credit sales allowed to customers\n– will bring payments forward so higher closing\nbalances – however it may have been used as a\nsales tool – if so customers may not buy at all\nleading to less sales and lower closing balances\n• other appropriate methods of increasing inflows\ne.g., reducing selling price, wider product range\netc with relevant discussion of\nadvantages/disadvantages\nDecrease outflows by:\n• not buying the wood cutting machine or delay the\npurchase of the machine – this increases closing\nbalance in short term by £15 500 however in long\nterm closing balance will be higher as no savings\non wages\n• renting cheaper premises – however cost of\nrelocating could be high\n• reducing other outflows\n• buy the assets using HP or leasing or other forms\nof credit to spread the cost\nAccept any other appropriate response.","levels":6}},{"q":11,"sub":"a","marks":4,"section":"B","ctx":["Farida runs a business called Camping Cuisine. The business manufactures and sells","camping stoves.","Farida has a delivery van that was purchased for £15 650 on the 1st of January 2022.","She has decided to depreciate this by 10% using the straight-line method."],"ctxb":[{"t":"p","x":"Farida runs a business called Camping Cuisine. The business manufactures and sells camping stoves. Farida has a delivery van that was purchased for £15 650 on the 1st of January 2022. She has decided to depreciate this by 10% using the straight-line method."}],"text":"Complete the statement of comprehensive income for Camping Cuisine by calculating:","qTotal":30},{"q":11,"sub":"i","marks":1,"section":"B","ctx":[],"ctxb":[],"text":"Closing inventory for 2022 (ii) Gross profit for 2022 (iii) Depreciation for 2022 (iv) Sales revenue for 2023 (v) Pr ofit/loss for the year 2023 Camping Cuisine Statement of comprehensive income for the years ending 31 December 2022 and 31 December 2023 2022 2023 Sales revenue 38 267 (iv)","qTotal":30},{"q":11,"sub":"b","marks":2,"section":"B","ctx":["Opening inventory 2 853 3 791","Purchases 18 523 47 913","Closing inventory (i) 8 326 (1)","Cost of goods sold 17 585 43 378","Gross profit (ii) 12 547 (1)","Expenses","Wages 9 737 20 631","D","epreciation of delivery","van (iii) 1 565 (1)","Telephone 2 700 6 398","Utilities 4 902 10 263","Total expenses 18 904 38 857","Profit/loss for the year 1 778 (v) (1)","17","Farida has forgotten to add sales revenue of £3 000 to her figures for 2022."],"ctxb":[{"t":"grid","head":null,"rows":[["Opening inventory","2 853","3 791"],["Purchases","18 523","47 913"],["Closing inventory","(i)","8 326","1"],["Cost of goods sold","17 585","43 378"],["Gross profit","(ii)","12 547","1"],["Expenses Wages","9 737","20 631"]]},{"t":"cap","x":"D epreciation of delivery"},{"t":"cap","x":"D epreciation of delivery"},{"t":"grid","head":null,"rows":[["van","(iii)","1 565","1"],["Telephone","2 700","6 398"],["Utilities","4 902","10 263"],["Total expenses","18 904","38 857"],["Profit/loss for the year","1 778","(v)","1"]]},{"t":"p","x":"17 Farida has forgotten to add sales revenue of £3 000 to her figures for 2022."}],"text":"Calculate Farida’s new profit/loss for the year.","qTotal":30,"ms":{"body":"Award two marks for the correct response of £4 778\nOR\nAward one mark for the correct formula in\nwords/numbers\nProfit = Gross Profit – Expenses\nOR\n£23 682 – £18 904\nOR\nAward one mark for correctly calculating the new sales\nrevenue of £38 267 + £3 000 = £41 267\nOR\nAward one mark for correctly calculating the new gross\nprofit of £23 682","levels":null}},{"q":11,"sub":"c","marks":3,"section":"B","ctx":["£"],"ctxb":[],"text":"Calculate the mark-up in 2023.","qTotal":30,"ms":{"body":"Award three marks for the correct response of 28.9%\neither with or without %\nAccept responses which are more accurate in terms of\ndecimal places e.g. 28.92%\nOR\nAward two marks for the correct formula in numbers\n(£12 547 / £43 378) x 100\nOR\nAward one mark for the correct formula in words\nMark-up = (gross profit/cost of sales) × 100","levels":null}},{"q":11,"sub":"d","marks":8,"section":"B","ctx":["Farida’s sales revenue has increased since 2022 but she feels disappointed with","the overall performance of the business in 2023."],"ctxb":[{"t":"p","x":"Farida’s sales revenue has increased since 2022 but she feels disappointed with the overall performance of the business in 2023."}],"text":"Using the data from 11(a) and any relevant calculations and financial ratios, analyse how Farida might improve the performance of the business in 2023 compared with 2022.","qTotal":30,"ms":{"body":"Possible figures: 2022 compared to 2023\n2022 2023 Difference\n%\nDifference\nSales\nrevenue\n38 267 55 925 Up 17\n658\nUp 46%\nCost of\ngoods\nsold\n17 585 43 378 Up 25\n793\nUp\n146%\nGross\nProfit\n20 682 12 547 Down\n8 135\nDown\n40%\nExpenses\n18 904 38 857 Up 19\n953\nUp\n105%\nProfit/\nloss\n1 778 (26\n310)\nDown\n28 088\nDown\n1 580%\nGPM 54% 22.4%\nFarida could do any of the following:\nIncrease Sales Revenue\nIncrease mark-up\nIncrease selling price\nReduce selling price\nReduce cost of sales\nSpend less on purchases or hold less inventory\nBuy cheaper raw materials\nBulk buy\nReduce Expenses\nSell delivery van\nReduce wages\nReduce telephone bill\nReduce utility bills\nAccept any other appropriate response.","levels":8}},{"q":11,"sub":"e","marks":12,"section":"B","ctx":["Farida has operated her business for five years. She has raised most of the finance she","needed by using her own capital. However, she has an outstanding loan of £15 000 at","12% interest. Repayment of this loan is due before the end of 2024. Farida currently","keeps all the profit she makes from Camping Cuisine.","One of the machines that Farida uses to package her camping stoves keeps breaking","down. She needs to replace the machine at a cost of £25 000 and is considering","two options:","Option 1","Taking out a bank loan for £25 000 at 15% interest over five years","OR","Option 2","Obtaining £40 000 from a venture capitalist in return for 50% of the profit","for the next 10 years. £40 000 will cover both her existing debts and the","new machine."],"ctxb":[{"t":"p","x":"Farida has operated her business for five years. She has raised most of the finance she needed by using her own capital. However, she has an outstanding loan of £15 000 at 12% interest. Repayment of this loan is due before the end of 2024. Farida currently keeps all the profit she makes from Camping Cuisine. One of the machines that Farida uses to package her camping stoves keeps breaking down. She needs to replace the machine at a cost of £25 000 and is considering two options: Option 1 Taking out a bank loan for £25 000 at 15% interest over five years OR Option 2 Obtaining £40 000 from a venture capitalist in return for 50% of the profit for the next 10 years. £40 000 will cover both her existing debts and the new machine."}],"text":"Evaluate whether Farida should raise the money she needs by taking the bank loan (Option 1) or obtaining £40 000 from a venture capitalist in return for 50% of the profit for the next 10 years (Option 2).","qTotal":30,"ms":{"body":"Compare 1. Taking out a bank loan for £25 000 at 15% interest over\nfive years OR 2. Obtaining £40 000 from a venture capitalist in\nreturn for 50% of the profit for the next 10 years. This will cover both\nher existing debts and the new machine.\nPossible figures for option 1 bank loan:\nExisting debt £15 000 @ 12% over 12 months\n= £1 800 interest £16 800 total to repay £1 400 per month\n£25 000 loan for machine @ 15% over 5 years\n= £3 750 interest in year 1 would cost £312.50 per month in\ninterest plus approx. £416.67 per month to repay the capital = £729\nper month to repay for 5 years\nTaking out the loan would mean repaying the 2 together in year 1\n= £1 400 + £729 per month = £ 2 129 per month\nThis would possibly worsen the losses which in 2023 were (£26 310)\nAdvantages of bank loan\n• Farida retains status as majority shareholder\n• Farida keeps control of the business\n• She doesn’t give away any more of her profit – she would lose\n50%\n• After year 1 she would only be paying approx. £729 / month or\n• £8 748 per year for the next 4 years – could be better off doing\nthis than giving away 50%\nDisadvantages of bank loan\n• It’s another monthly cost to the business\n• She made a loss in 2023 and this would mean she has to make\nan extra £25 548 in the next 12 months just to cover the 2 loan\nrepayments\n• She may become insolvent if she can’t keep up repayments\n• She may lose the business altogether if she can’t manage her\ncash flow\nAdvantages of venture capitalist\n• Farida does not have monthly outgoings to pay for her existing\nloan and the new loan\n• Farida will get her machine straight away\n• venture capitalist may be able to help and advise her in running\nthe business\n• venture capitalist is more likely to give her the money as they are\nless risk averse than banks\nDisadvantages of venture capitalist\n• Farida will be giving away 50% of the profit for the next 10\nyears.\n• Farida may not meet personal objectives associated with being\nher own boss\n• Farida may have conflict with the venture capitalist","levels":12}}],"msMatched":17},{"id":"U3-2406","unit":3,"key":"2024-06","series":"June 2024","date":"Thursday 16 May 2024","title":"Fatima · Philip · Lalisa · Candy","source":"pearson","kind":"exam","total":80,"parsedTotal":80,"sec":{"A":28,"B":52},"items":[{"q":1,"sub":null,"marks":2,"section":"A","ctx":["Personal Finance"],"ctxb":[{"t":"p","x":"Personal Finance"}],"text":"Identify two methods of payment.","qTotal":2,"ms":{"body":"Identify two methods of payment.\nAward one mark for each method identified, up to a\nmaximum of two marks.\n• cash\n• debit card\n• credit card\n• cheque\n• electronic transfer / online transaction\n• direct debit\n• standing order\n• pre-paid cards\n• contactless cards\n• charge cards\n• store cards\n• mobile banking / mobile payment services (e.g.\nApple Pay, Google Pay, PayPal)\n• Banker’s Automated Clearing Services (BACS)\n• Faster Payments Service (FPS)\n• Clearing House Automated Payment System\n(CHAPS)\nAccept any other reasonable answer.","levels":null}},{"q":2,"sub":null,"marks":2,"section":"A","ctx":[],"ctxb":[],"text":"Give two advantages for an individual of a premium current account.","qTotal":2,"ms":{"body":"Give two advantages for an individual of a premium\ncurrent account\nAward one mark for each advantage identified, up to a\nmaximum of two marks.\n• Lower or waived fees on overdrafts/foreign\nexchange\n• Travel insurance\n• Mobile phone insurance\n• Vehicle breakdown cover\n• Discounted loan rates\n• Free financial advice\n• Access preferential rates on linked products\n• Other perks such as gourmet club cards/cinema\ntickets\n• Can withdraw more cash at one time\nAccept any other reasonable answer.","levels":null}},{"q":3,"sub":null,"marks":2,"section":"A","ctx":[],"ctxb":[],"text":"Explain one advantage for an individual of using an overdraft to borrow money.","qTotal":2,"ms":{"body":"Award one mark for identification of an advantage of\nusing an overdraft and one mark for a linked\ndevelopment, up to a maximum of two marks.\n• Can continue to purchase goods/services (1) when\nyou don’t have any funds in the account (1)\n• Can be prearranged (1) so can access the funds\nquickly (1)\n• Interest is only charged on the sum borrowed for the\nnumber of days used (1) which may reduce the cost\ncompared with some other forms of borrowing such\nas a loan (1)\n• Overdraft is reduced when funds are deposited (1)\nwhich makes it automatic to repay (1)\nAccept any other reasonable answer.","levels":null}},{"q":4,"sub":null,"marks":4,"section":"A","ctx":[],"ctxb":[],"text":"Explain two advantages for an individual of using an independent financial advisor (IFA).","qTotal":4,"ms":{"body":"Award one mark for identification of an advantage for\nan individual of using an independent financial advisor\nand one mark for a linked development, up to a\nmaximum of four marks.\n• They can provide impartial/unbiased advice (1) as\nfinancial products from the whole market not just\nfrom one financial provider are considered (1)\n• You have more choice (1) therefore more likely to\nget a product suited to your personal financial\nsituation (1)\n• They are regulated by the Financial Conduct\nAuthority (1) therefore your money is protected (1)\n• They will gather information from you about your\npersonal current financial situation (1) and can help\nyou to achieve your financial goals (1)\n• IFAs are qualified professionals or experts (1)\ntherefore advice given is reliable/good quality/up to\ndate (1)\nAccept any other reasonable answer.","levels":null}},{"q":5,"sub":null,"marks":6,"section":"A","ctx":["Fatima is 23 years old and lives with her two friends in a flat. The three friends share","responsibility for all bills, including rent. Fatima has booked a holiday to Ibiza with her","two friends. The cost of the holiday is £1 500 for each friend. She paid half of the £1 500","when the holiday was booked in January. However, in the four months since January","she has only saved £400 towards the cost of the holiday. The holiday is in four weeks’","time and by then Fatima needs to have paid the balance of £750. Fatima cannot pay the","balance by credit card because she has already reached her credit limit of £2 000. Fatima","is concerned that she will have to cancel her holiday. One of Fatima’s friends has advised","her that she could qualify for a payday loan."],"ctxb":[{"t":"p","x":"Fatima is 23 years old and lives with her two friends in a flat. The three friends share responsibility for all bills, including rent. Fatima has booked a holiday to Ibiza with her two friends. The cost of the holiday is £1 500 for each friend. She paid half of the £1 500 when the holiday was booked in January. However, in the four months since January she has only saved £400 towards the cost of the holiday. The holiday is in four weeks’ time and by then Fatima needs to have paid the balance of £750. Fatima cannot pay the balance by credit card because she has already reached her credit limit of £2 000. Fatima is concerned that she will have to cancel her holiday. One of Fatima’s friends has advised her that she could qualify for a payday loan."}],"text":"Discuss whether Fatima should apply for a payday loan.","qTotal":6,"ms":{"body":"Advantages of applying for payday loan\n• She can get the money straight away- often within one\nhour so is able to go on the holiday\n• Most people qualify for a payday loan so it is likely that\nFatima will be able to get the money she needs\n• The amount she pays back cannot be more than\ndouble the original amount borrowed therefore the\nmaximum she will repay is £700 (2 x £350)\n• Payday loans are capped under the law, which is\nregulated by the FCA, meaning there is a limit on the\namount of interest and default fees you can be\ncharged\nDisadvantages of applying for a payday loan\n• Some payday loans have very high interest rates so\nFatima could end up paying a large amount of money\nback\n• As Fatima was unable to save the £750 she needed for\nthe holiday in four months it is unlikely that she will be\nable to afford the monthly repayments of the payday\nloan\n• Fatima was only able to save £100 per month. It is\nlikely that the interest on the loan on its own could be\nmore than this\n• She already owes £2 000 on her credit card which\nneeds to be repaid – so it is unlikely she can afford\nboth a payday loan and to make the repayments on\nthe credit card\n• It is likely that Fatima will not be able to afford her\nother bills if she repays the loan, which could lead to\nher defaulting on these leading to penalties/charges\nand a bad credit rating\n• She could end up in uncontrollable debt leading to an\nIVA or bankruptcy","levels":6}},{"q":6,"sub":null,"marks":12,"section":"A","ctx":["Philip is a student and has just bought a rescue puppy from a local charity. The puppy","was abandoned so Philip does not know its medical history. Philip has discovered that","the average annual pet insurance claim in the UK is over £750 and that an operation can","cost over £3 000. Philip predicts that he will spend £58 per month on dog food once the","puppy is fully grown. Philip has researched the following insurance options for his puppy.","Insurance","provider","Cost","per","month","Cover for","accidents/","illnesses/","*pre-existing","conditions","Maximum claim","value","Access to","text-chat","with qualified","veterinary","nurses at any","time","Excess","Shirevale","Insurance","£10 Accidents only £500 per accident up","to £2 000 per year","No £150","Ashridge","Insurance","£38 Accidents only £5 000 per year No £80","Westshire","Insurance","£108 Accidents, illnesses","and pre-existing","conditions","Up to £25 000 per","year","Yes £50","Royal","Insurance","£52 Accidents and","illnesses","£2 000 per condition","up to £10 000 per","year","Yes £200","*pre-existing conditions – illnesses, injuries or health conditions that existed before the","start of an insurance policy"],"ctxb":[{"t":"p","x":"Philip is a student and has just bought a rescue puppy from a local charity. The puppy was abandoned so Philip does not know its medical history. Philip has discovered that the average annual pet insurance claim in the UK is over £750 and that an operation can cost over £3 000. Philip predicts that he will spend £58 per month on dog food once the puppy is fully grown. Philip has researched the following insurance options for his puppy."},{"t":"flow","x":["Insurance","provider","Cost","per","month","Cover for","accidents/","illnesses/","*pre-existing","conditions","Maximum claim","value","Access to","text-chat","with qualified","veterinary","nurses at any","time","Excess","Shirevale","Insurance","£10 Accidents only £500 per accident up","to £2 000 per year","No £150","Ashridge","Insurance","£38 Accidents only £5 000 per year No £80","Westshire","Insurance","£108 Accidents, illnesses","and pre-existing","conditions","Up to £25 000 per","year","Yes £50","Royal","Insurance","£52 Accidents and","illnesses","£2 000 per condition","up to £10 000 per","year","Yes £200"]},{"t":"p","x":"*pre-existing conditions – illnesses, injuries or health conditions that existed before the start of an insurance policy"}],"text":"Evaluate which option would be most suitable for Philip.","qTotal":12,"ms":{"body":"Considerations of cost vs benefits offered\nApplication\nLearners should consider the following:\n• Philip is a student and therefore unlikely to have a lot of\nmoney\n• Philip already knows that food will cost £58 per month\n• The puppy is a rescue and may have pre -existing\nconditions which may not be covered by some insurers\n• The average insurance claim in the UK is £750 therefore\nhe should look for a policy that is at least this per\ncondition\n• An operation if needed will cost over £3 000","levels":12}},{"q":7,"sub":null,"marks":2,"section":"B","ctx":["Business Finance"],"ctxb":[{"t":"p","x":"Business Finance"}],"text":"Give two examples of non-current assets.","qTotal":2,"ms":{"body":"Give two examples of non-current assets.\nAward one mark for each non-current asset identified, up to\na maximum of two marks.\n• land\n• buildings and premises\n• machinery and equipment\n• vehicles\n• fixtures and fittings\n• goodwill\n• patents\n• trademarks\n• brand names\nAccept any other appropriate response.\nDo not accept “tangible” and “intangible” as these are not\nexamples of non-current assets.","levels":null}},{"q":8,"sub":null,"marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Explain one impact of debt factoring on a small business.","qTotal":2,"ms":{"body":"Explain one impact of debt factoring on a small business.\nAward one mark for a correct impact identified, and one for a\ndeveloped point.\n• Money received will be less than the value of the\noriginal invoice (1) therefore less inflows/lower\nprofit/lower net cash flow/lower closing balance (1)\n• Money will be received quicker (1) therefore helps\nmanage cash flow (1)\n• Saves time chasing the debt (1) allowing you to get\non with running your business (1)\n• You are guaranteed to receive at least some money\nfor the debt (1) therefore preventing business\nfailure/bankruptcy (1)\nAccept any other reasonable response.\nDo not accept “quicker” or “easier” on their own.","levels":null}},{"q":9,"sub":null,"marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Give two purposes of accounting.","qTotal":2,"ms":{"body":"Give two purposes of accounting.\nAward one mark for each purpose identified, up to a\nmaximum of two marks.\n• Recording transactions\n• Planning\n• Monitoring\n• Controlling\n• Compliance with law and regulations\n• Preventing fraud\n• Measuring performance\nAccept any other reasonable response.","levels":null}},{"q":10,"sub":"a","marks":4,"section":"B","ctx":["Lalisa owns a takeaway restaurant, Lettuce by Lalisa. The restaurant sells a range of","boxed salads. The restaurant has enough tables and chairs for 25 customers. Lalisa is","considering expanding her business by opening a second branch of the restaurant in a","new location. She has estimated that she will have the following costs and revenue in the","first six months of opening her new business.","Estimated cost/","revenue","June July Aug Sept Oct Nov","Number of sales 500 (iii) 1 000 1 000 1 250 1 500","Total revenue (£) 2 500 3 750 5 000 5 000 (iv) 7 500","Fixed costs (£) 3 010 3 010 3 010 3 010 3 010 3 010","Total variable","costs (£) (i) 1 125 1 500 1 500 1 875 2 250","Total costs (£) (ii) 4 135 4 510 4 510 4 885 5 260"],"ctxb":[{"t":"p","x":"Lalisa owns a takeaway restaurant, Lettuce by Lalisa. The restaurant sells a range of boxed salads. The restaurant has enough tables and chairs for 25 customers. Lalisa is considering expanding her business by opening a second branch of the restaurant in a new location. She has estimated that she will have the following costs and revenue in the first six months of opening her new business."},{"t":"grid","head":["Estimated cost/ revenue","June","July","Aug","Sept","Oct","Nov"],"rows":[["Number of sales","500","(iii)","1 000","1 000","1 250","1 500"],["Total revenue","2 500","3 750","5 000","5 000","(iv)","7 500"],["Fixed costs","3 010","3 010","3 010","3 010","3 010","3 010"],["Total variable costs","(i)","1 125","1 500","1 500","1 875","2 250"],["Total costs","(ii)","4 135","4 510","4 510","4 885","5 260"]]}],"text":"Calculate the figures missing from the table above.","qTotal":16,"ms":{"body":"Award one mark for each correct answer.\n(i) 750\n(ii) 3 760 (ECF) Addition of (i) + fixed costs\n(iii) 750\n(iv) 6 250\nEstimated\ncost/revenue\nJune Jul Aug Sept Oct Nov","levels":null}},{"q":10,"sub":"b","marks":4,"section":"B","ctx":["Lalisa’s new takeaway restaurant will be in the city centre. Therefore, both costs and","revenue will be higher than her current estimates."],"ctxb":[{"t":"p","x":"Lalisa’s new takeaway restaurant will be in the city centre. Therefore, both costs and revenue will be higher than her current estimates."}],"text":"Calculate the break-even point per month for Lalisa’s new takeaway restaurant if she has: • variable costs of £2 • selling price of £6 • fixed costs of £5 500.","qTotal":16,"ms":{"body":"Calculate the break-even point.\nAward four marks for the correct response of 1 375 boxes\nper month.\nAccept 1 375 with or without the word ‘boxes’\nOR\nAward three marks for the correct formula in numbers.\nBEP = 5 500 / 4\nBEP = 5 500 / (6-2)\nOR\nAward one mark for calculating the correct contribution of\n£4\nAND\nAward one mark for giving the correct formula in words.\nBreak Even Point = Fixed Costs\n(Selling Price – Variable Costs)\nBEP = FC / (SP-VC)\nBEP = FC / CPU","levels":null}},{"q":10,"sub":"c","marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Calculate the margin of safety in November for Lalisa’s new takeaway restaurant.","qTotal":16,"ms":{"body":"Calculate the Margin of Safety in November.\nAward two marks for the correct response of 125 boxes per\nmonth.\nAccept with or without the word ‘boxes’.\nApply ECF using break-even point answer from 10b.\nOR\nAward one mark for giving the correct formula in words.\nMargin Of Safety = Estimated Sales/Output – Break-Even\nPoint\nMOS = ES – BEP\nOR\nAward one mark for correct formula in numbers\nMOS = 1 500 – 1 375 (ECF use BEP 10b)","levels":null}},{"q":10,"sub":"d","marks":6,"section":"B","ctx":[],"ctxb":[],"text":"Discuss the actions that Lalisa could take to improve the break-even point per month of her new business.","qTotal":16,"ms":{"body":"Actions that could be taken to improve the break-even point\nper month of her new business.\nImprove break-even point by:\n• increasing selling price – therefore contribution per\nunit higher. Disadvantage – customers may not buy\nat the higher price\n• reducing variable costs (any relevant suggestions e.g.\ncheaper ingredients or packaging) – therefore\nincreasing contribution – however quality may suffer,\nwhich leads to loss of reputation/sales\n• reducing fixed costs (any relevant suggestion, e.g.\nnot locating in the city centre) – therefore fewer costs\nto cover through contribution – however could be\ndrawbacks such as less staff/advertising or fewer\ncustomers outside the city centre etc, which could be\ndetrimental to the long-term success\n• learner acknowledges both advantages and\ndisadvantages of the above in the context of a\nnew/expanded business that may be unable to reduce\ncosts initially as they will have start- up costs which\ncan be very high\n• learner may acknowledge that the estimated sales in\nJune to October are below the break- even point of\n1 375 boxes\n• learner may discuss that it would not be\npossible/unwise to attempt to lower the BEP and\naccept that aims for a new business are often to break\neven in the longer term\nAccept any other appropriate response.","levels":6}},{"q":11,"sub":"a","marks":2,"section":"B","ctx":["Candy owns a business called Candy’s Creative. The business composes music and","ringtones for software and gaming companies. The business has been operating for","three years.","You have been hired by Candy to help with the finances of the business. Candy has","provided you with some financial information.","Extract of financial information for Candy’s Creative in 2023","£","Current assets 12 000","Current liabilities 10 000","Total revenue 175 000","Cost of sales 63 000","Expenses 45 000","Average selling price 5 000","Trade receivables 19 200","Credit sales 32 000"],"ctxb":[{"t":"p","x":"Candy owns a business called Candy’s Creative. The business composes music and ringtones for software and gaming companies. The business has been operating for three years. You have been hired by Candy to help with the finances of the business. Candy has provided you with some financial information."},{"t":"cap","x":"Extract of financial information for Candy’s Creative in 2023"},{"t":"grid","head":null,"rows":[["Current assets","12 000"],["Current liabilities","10 000"],["Total revenue","175 000"],["Cost of sales","63 000"],["Expenses","45 000"],["Average selling price","5 000"],["Trade receivables","19 200"],["Credit sales","32 000"]]}],"text":"Calculate the current ratio.","qTotal":30,"ms":{"body":"Calculate the current ratio\nAward two marks for the correct response of 1.2:1\nAccept correct answer anywhere in workings box.\nAccept 1.2\nOR\nAward one mark for giving the correct formula in words.\nCurrent ratio = current assets / current liabilities\nOR\nAward one mark for correct formula in numbers.\n12 000/ 10 000\nALTERNATIVE APPROACH\nAward two marks for the correct response of 3.12:1\n2 3–4 • Demonstrates accurate knowledge and\nunderstanding of relevant information with a\nfew gaps or omissions.\n• Discussion is partially developed, but will be\nimbalanced.\nEvidences the weighing up of competing\narguments/pros and cons in context.\n• Demonstrates the use of logical reasoning,\nclarity, and appropriate specialist technical\nlanguage.\n3 5–6 • Demonstrates accurate and thorough knowledge\nand understanding of relevant information; any\ngaps or omissions\nare minor.\n• Displays a well-developed and balanced\ndiscussion, demonstrating a thorough\ngrasp of competing arguments/pros and\ncons in context.\n• Logical reasoning evidenced throughout\nresponse which is clear and uses specialist\ntechnical language consistently.\nAccept correct answer anywhere in workings box.\nAccept 3.12\nOR\nAward one mark for giving the correct formula in words.\nCurrent ratio = current assets / current liabilities\nOR\nAward one mark for correct formula in numbers.\n31 200/ 10 000","levels":null}},{"q":11,"sub":"b","marks":3,"section":"B","ctx":[],"ctxb":[],"text":"Calculate the gross profit margin.","qTotal":30,"ms":{"body":"Calculate the gross profit margin.\nAward three marks for the correct response of 64%.\nAccept 64 with or without the % sign.\nOR\nAward two marks for correct formula in numbers.\nGPM = 112 000 / 175 000 X 100\nOR\nAward one mark for giving the correct formula in words.\nGross profit margin = gross profit / revenue X 100\nOR\nAward one mark for correctly calculating the gross profit of\n£112 000","levels":null}},{"q":11,"sub":"c","marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Calculate the trade receivable days.","qTotal":30,"ms":{"body":"Calculate the trade receivable days.\nAward two marks for the correct response of 219 days.\nAccept 219 with or without ‘days’ after.\nAward one mark for correct formula in numbers.\n19 200 / 32 000 X 365\nOR\nAward one mark for giving the correct formula in words.\nTrade receivable days = (Trade receivable/credit sales) × 365","levels":null}},{"q":11,"sub":"d","marks":3,"section":"B","ctx":[],"ctxb":[],"text":"Calculate Candy’s profit margin in 2023.","qTotal":30,"ms":{"body":"Calculate Candy’s profit margin in 2023.\nAward three marks for the correct response of 38.29%\nAccept 38 / 38.2 / 38.3 with or without % sign.\nAccept any of the above conventions where the figure is\ngiven to a more accurate decimal place.\nOR\nAward two marks for correct formula in numbers.\nPM = 67 000 / 175 000 X 100\nOR\nAward one mark for giving the correct formula in words.\nProfit margin = profit / revenue X 100\nOR\nAward one mark for correctly calculating the profit of\n£67 000","levels":null}},{"q":11,"sub":"e","marks":8,"section":"B","ctx":["Candy’s Creative is projected to increase its sales revenue by 20% in the next","12","months. Candy also aims to expand the business by moving into bigger, more","expensive studios. Candy is concerned that she will not be able to afford the move."],"ctxb":[{"t":"p","x":"Candy’s Creative is projected to increase its sales revenue by 20% in the next 12 months. Candy also aims to expand the business by moving into bigger, more expensive studios. Candy is concerned that she will not be able to afford the move."}],"text":"Analyse the limitations of ratio analysis to Candy in deciding whether she can afford to expand.","qTotal":30,"ms":{"body":"Analyse the limitations of ratio analysis to Candy in deciding\nwhether she can afford to expand.\nPossible figures:\nGross profit margin 64%\nProfit margin 38%\nCurrent ratio 1.2: 1\nTrade receivable days 219 days\nLearners may analyse the benefits and drawbacks of\ncalculating individual ratios or the value of ratios overall in\nanalysing current/past/future likely performance.\nBenefits of ratio analysis\nCan compare current performance with past performance so\nuseful for Candy in predicting likely success of the expansion\nShe can compare her business performance with competitors\nto consider what they may be doing that may be giving them\nbetter figures\nRatios will help her to monitor and identify issues that can be\nhighlighted and resolved meaning that she can avoid past\nmistakes in the new business and enhance performance\noverall\nDrawbacks of ratio analysis\nInformation is historic and may not be relevant in the future\nRatio analysis does not take into account factors such as\nworldwide recession and other economic/social political\nchanges that can affect the business in addition to changes in\nsupply chains, competitor and customer changes, which it will\nnot predict and could prevent Candy from making the right\ndecisions\nIf single ratios are used in isolation, it will prevent Candy from\ndrawing the right conclusions about overall performance\nActual figures may be more important/relevant than %, e.g.\nthe actual profit figure £67 000 may be very low but as a net\nprofit % it may be high which could mislead Candy\nAlthough it may be an indication of likely future performance\nand highlight possible areas for improvement it does not help\nCandy to create solutions to issues\nAccept any other reasonable response.\nAllow analysis of learner’s own calculated figures even\nif they are different than those above.","levels":8}},{"q":11,"sub":"f","marks":12,"section":"B","ctx":["Candy has decided to move into the new studio. Rent will be 40% higher than here","xisting premises. However, she will have more studio space which will enable her","to attract bigger contracts. Some of Candy’s new customers will be large software","corporations which will insist on contracts with long credit periods before they pay","Candy. Candy has predicted that her monthly revenue could increase by £15 000 if","she is able to attract these bigger contracts.","Candy feels that offering 60 days’ credit to her customers has been important in","increasing sales. Many of her competitors offer 30 days’ credit and she is wondering","if she should do the same, as she has noticed that the business goes overdrawn","frequently. She has negotiated an agreed £10 000 overdraft with her bank. The","interest rate on the overdraft is 17% APR with no other fees charged."],"ctxb":[{"t":"p","x":"Candy has decided to move into the new studio. Rent will be 40% higher than here xisting premises. However, she will have more studio space which will enable her to attract bigger contracts. Some of Candy’s new customers will be large software corporations which will insist on contracts with long credit periods before they pay Candy. Candy has predicted that her monthly revenue could increase by £15 000 if she is able to attract these bigger contracts. Candy feels that offering 60 days’ credit to her customers has been important in increasing sales. Many of her competitors offer 30 days’ credit and she is wondering if she should do the same, as she has noticed that the business goes overdrawn frequently. She has negotiated an agreed £10 000 overdraft with her bank. The interest rate on the overdraft is 17% APR with no other fees charged."}],"text":"Evaluate whether Candy should reduce her customers’ credit period from 60 days to 30 days or continue to use an overdraft in order to manage her cash flow.","qTotal":30,"ms":{"body":"Evaluate whether Candy should reduce her customers\ncredit period from 60 days to 30 days or continue to use\nan overdraft in order to manage her cash flow.\nBenefits of reducing the credit period\n• Less risk of bad debts as not waiting as long for\ncustomer payment\n• Improved cash flow as payment now received 30 days\nquicker – therefore possible 30 days less overdraft\ninterest at 17% APR\n• May improve cash flow as she may avoid being late\nwith any payments if funds are not available e.g.\nrent which is now 40% higher in the new studio\nDrawbacks of reducing the credit period\n• May lose sales as the credit period might be a strong\nUSP for her customers\n• Large software corporations may not use her\nbusiness – inflows of £15 000 / month could be\nlost – leaving her struggling to pay increased\ncosts such as 40% increase in rent\n• Offering 30 days credit will still have a negative\nimpact on cash flow\n• May still need to use overdraft incurring interest\nas credit sales are currently £32 000\n• Existing customers who have been allowed 60\ndays credit may not use her business – this could\nmake cash flow worse\nBenefits of using the overdraft\n• Only paying interest on the amount which Candy\ngoes overdrawn\n• Flexibility of overdraft being used when needed\n• Business retains USP of offering 60-day credit\nperiod – retains existing customers and more\nlikely to attract business from large corporate\nclients – adding a potential £15 000 to inflows.\n• Could be a cheaper option for managing cashflow\nthan other short-term sources of finance e.g.,\ncredit card or emergency loan\nDrawbacks of using bank overdraft\n• Agreed overdraft may not to be enough for her\nneeds – only\n£10 000 agreed overdraft – estimated new sales will\nbe £15 000 – existing credit sales £32 000\n• Repayable on demand\n• Interest rates of 17% APR\nAccept any other reasonable response.","levels":12}}],"msMatched":19},{"id":"U3-R1","unit":3,"key":"9901","series":"RA10 practice","date":"RA10 practice paper","title":"Sunrise Sandwiches · Orchard Studio","source":"ra10","kind":"exam","total":80,"sec":{"A":28,"B":52},"items":[{"q":1,"sub":null,"marks":2,"section":"A","ctx":[],"ctxb":[],"text":"Identify two benefits of paying by contactless card.","qTotal":null,"ms":{"body":"Award one mark for each benefit identified, up to a maximum of two marks.\n• Quick / saves time (1)\n• No PIN needed for small amounts (1)\n• Reduces handling of cash (1)\n• Can be used with phones/wearables (1)\n• Hygienic – no contact (1)\n• Accept any other appropriate response.","levels":null}},{"q":2,"sub":null,"marks":2,"section":"A","ctx":[],"ctxb":[],"text":"Give two features of a student current account.","qTotal":null,"ms":{"body":"Award one mark for each feature, up to a maximum of two marks.\n• Interest-free overdraft (1)\n• No monthly fee (1)\n• Railcard/discount perks (1)\n• Overdraft reduces after graduation (1)","levels":null}},{"q":3,"sub":null,"marks":2,"section":"A","ctx":[],"ctxb":[],"text":"Explain one advantage for an individual of borrowing from a credit union.","qTotal":null,"ms":{"body":"Award one mark for an advantage and one mark for a linked development.\n• Loans are low cost / capped interest (1) so repayments are more affordable (1)\n• Not-for-profit / member-owned (1) so profits are returned to members or kept low cost (1)\n• Considers people with poor credit histories (1) giving access to borrowing that other lenders refuse (1)\n• Accept any other reasonable answer.","levels":null}},{"q":4,"sub":null,"marks":4,"section":"A","ctx":[],"ctxb":[],"text":"Explain two disadvantages for an individual of using a store card.","qTotal":null,"ms":{"body":"Award one mark for each disadvantage and one for a linked development, up to four marks.\n• High interest rate / APR (1) so unpaid balances become expensive (1)\n• Can only be used in one retailer/group (1) so limited usefulness (1)\n• Encourages overspending through offers (1) leading to debt (1)\n• Missed payments harm credit rating (1) making future borrowing harder (1)","levels":null}},{"q":5,"sub":null,"marks":6,"section":"A","ctx":[],"ctxb":[{"t":"p","x":"Amir is 24 and works as an apprentice electrician. He needs a van costing £6,000 to get to jobs. He has £800 in savings. His bank offers a personal loan at 9.9% APR over three years with fixed monthly repayments of about £190. A dealer offers hire purchase: a £600 deposit and 36 payments of £175. Amir’s take-home pay is £1,350 a month and his rent and bills are £900."}],"text":"Discuss whether Amir should use a personal loan or hire purchase to buy the van.","qTotal":null,"ms":{"body":"• Personal loan: he owns the van immediately; fixed repayments of about £190 (£6,840 total) – compare to HP total £600 + 36 × £175 = £6,900; interest rate stated and can be compared; lender may check credit rating; early settlement fees\n• Hire purchase: lower monthly payment (£175) which suits a tight budget (£450 spare per month); deposit £600 of his £800 savings leaves little reserve; he does not own the van until the final payment and it can be repossessed; slightly higher total cost\n• Context: after bills £450 is available – either option is affordable but leaves little for emergencies; tools/van needed for work\n• Judgement: weigh ownership and total cost against the lower monthly payment and cash reserve\n(6)","levels":6}},{"q":6,"sub":null,"marks":12,"section":"A","ctx":[],"ctxb":[{"t":"p","x":"Priya is 27 and wants to save £5,000 for a deposit on a flat in two years. She does not want to risk losing her money. She has researched the following options."},{"t":"grid","head":["Option","Interest / return","Access","Other features"],"rows":[["Easy-access saver","2.1% AER variable","Instant","Protected by FSCS"],["1-year fixed bond","4.2% AER fixed","No access for 12 months","FSCS protected; minimum £1,000"],["Cash ISA","3.9% AER variable","Instant (withdrawals may reduce allowance)","Tax-free; FSCS protected"],["Premium Bonds","No interest – monthly prizes","Withdraw any time","Backed by the Treasury; no guaranteed return"]]}],"text":"Evaluate which option would be most suitable for Priya.","qTotal":null,"ms":{"body":"• Easy-access saver: instant access useful for a deposit, FSCS protected, but lowest interest (2.1%) and variable – £5,000 earns about £105 in a year; could reduce if base rate falls\n• Fixed bond: highest rate (4.2% = £210 on £5,000 for a year) and certainty; but money locked in for 12 months; she needs funds in 2 years so could re-invest; not suitable if she needs the cash sooner\n• Cash ISA: 3.9% tax-free (£195), access if needed; tax benefit depends on her tax position (personal savings allowance means many basic-rate taxpayers pay no tax anyway); variable rate\n• Premium Bonds: no guaranteed return – average prize rate may be lower than interest and she wants low risk; inflation erodes value\n• Context: low risk, 2-year timescale, deposit target £5,000\n• Recommendation (e.g. cash ISA, or split between fixed bond and easy-access) with reasons why each alternative is less suitable\n(12)","levels":12}},{"q":7,"sub":null,"marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Give two examples of revenue expenditure.","qTotal":null,"ms":{"body":"Award one mark for each example, up to a maximum of two marks.\n• Wages / salaries (1)\n• Rent / rates (1)\n• Utilities (1)\n• Insurance (1)\n• Marketing (1)\n• Inventory purchases (1)\n• Do not accept purchase of machinery or vehicles (capital expenditure).","levels":null}},{"q":8,"sub":null,"marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Explain one impact of leasing equipment on a small business.","qTotal":null,"ms":{"body":"Award one mark for an impact and one mark for a linked development.\n• No large initial outlay (1) so cash is available for other purposes (1)\n• The business does not own the asset (1) so cannot sell it or use it as security (1)\n• Regular lease payments (1) increase fixed costs over the long term (1)","levels":null}},{"q":9,"sub":null,"marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Give two sources of internal finance.","qTotal":null,"ms":{"body":"Award one mark for each source, up to a maximum of two marks.\n• Retained profit (1)\n• Sale of assets (1)\n• Net current assets / working capital (1)\n• Do not accept bank loan or overdraft.","levels":null}},{"q":10,"sub":"a","marks":4,"section":"B","ctx":[],"ctxb":[{"t":"p","x":"Zainab owns Sunrise Sandwiches, a takeaway café with seating for 18 customers. She is considering opening a second branch near the university. She has estimated the following costs and revenue for the first six months of opening."},{"t":"grid","head":["Estimated cost/ revenue","Mar","Apr","May","Jun","Jul","Aug"],"rows":[["Number of sales","400","(iii)","900","1 000","1 200","1 300"],["Total revenue (£)","2 000","3 500","4 500","5 000","(iv)","6 500"],["Fixed costs (£)","3 600","3 600","3 600","3 600","3 600","3 600"],["Total variable costs (£)","(i)","1 400","1 800","2 000","2 400","2 600"],["Total costs (£)","(ii)","5 000","5 400","5 600","6 000","6 200"]]}],"text":"Calculate the figures missing from the table above.","qTotal":null,"ms":{"body":"Award one mark for each correct answer.\n• (i) 800\n• (ii) 4 400 (ECF) Addition of (i) + fixed costs\n• (iii) 700\n• (iv) 6 000\n(4)","levels":null}},{"q":10,"sub":"b","marks":4,"section":"B","ctx":[],"ctxb":[{"t":"p","x":"The new branch will be near the university, where rent is higher, so fixed costs will be higher than the estimates above."}],"text":"Calculate the break-even point per month for the new café if it has: variable costs of £2 per sandwich; a selling price of £5; fixed costs of £5,400. Show your workings.","qTotal":null,"ms":{"body":"Award four marks for the correct response of 1 800 sandwichs per month. Accept with or without the unit.\n• OR Award three marks for the correct formula in numbers: BEP = 5 400 / (5 – 2) (3)\n• OR Award one mark for the correct contribution of £3 AND one mark for the formula in words: Break-even point = fixed costs ÷ (selling price – variable cost) (2)\n(4)","levels":null}},{"q":10,"sub":"c","marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Calculate the margin of safety in the final month for the new café, which expects to sell 2 400 sandwichs. Show your workings.","qTotal":null,"ms":{"body":"Award two marks for the correct response of 600 sandwichs. Apply ECF using the break-even point from 10(b).\n• OR Award one mark for the formula in words: margin of safety = expected sales – break-even point (1)\n• OR one mark for the formula in numbers: 2 400 – 1 800 (1)\n(2)","levels":null}},{"q":10,"sub":"d","marks":6,"section":"B","ctx":[],"ctxb":[],"text":"Discuss the actions Zainab could take to improve the break-even point of the new branch.","qTotal":null,"ms":{"body":"• Raise the selling price – increases contribution per sandwich, but students are price-sensitive and may buy elsewhere\n• Reduce variable costs – cheaper ingredients or packaging raise contribution but may reduce quality and reputation\n• Reduce fixed costs – smaller premises or shorter opening hours; may reduce customers or sales\n• Context: new branch has start-up costs; forecast sales in early months are below break-even so initial losses are likely; aim to break even in the longer term\n• Balanced conclusion – likely combination\n(6)","levels":6}},{"q":11,"sub":"a","marks":2,"section":"B","ctx":[],"ctxb":[{"t":"p","x":"Orchard Studio designs wedding stationery and has been trading for four years. You have been hired to help with its finances and have been given the following information."},{"t":"cap","x":"Extract of financial information for Orchard Studio Ltd"},{"t":"grid","head":["","£"],"rows":[["Current assets","21 000"],["Current liabilities","14 000"],["Total revenue","180 000"],["Cost of sales","72 000"],["Expenses","61 000"],["Trade receivables","24 000"],["Credit sales","60 000"]]}],"text":"Calculate the current ratio. Show your workings.","qTotal":null,"ms":{"body":"Award two marks for the correct response of 1.5 : 1. Accept 1.5.\n• OR award one mark for the formula in words: current ratio = current assets ÷ current liabilities (1)\n• Accept the correct answer anywhere in the workings box. A ratio of the two numbers (e.g. 21 000:14 000) is not worth marks.\n(2)","levels":null}},{"q":11,"sub":"b","marks":3,"section":"B","ctx":[],"ctxb":[],"text":"Calculate the gross profit margin. Show your workings.","qTotal":null,"ms":{"body":"Award three marks for the correct response of 60.0%.\n• Gross profit = 180 000 – 72 000 = 108 000 (1)\n• Formula: (gross profit ÷ revenue) × 100 (1)\n• Answer 60.0% (1)\n(3)","levels":null}},{"q":11,"sub":"c","marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Calculate the trade receivable days. Show your workings.","qTotal":null,"ms":{"body":"Award two marks for the correct response of 146.0 days (accept 146).\n• OR one mark for the formula: (trade receivables ÷ credit sales) × 365 (1)\n(2)","levels":null}},{"q":11,"sub":"d","marks":3,"section":"B","ctx":[],"ctxb":[],"text":"Calculate the profit margin for the year. Show your workings.","qTotal":null,"ms":{"body":"Award three marks for the correct response of 26.1%.\n• Profit = gross profit – expenses = 108 000 – 61 000 = 47 000 (1)\n• Formula: (profit ÷ revenue) × 100 (1)\n• Answer 26.1% (1)\n(3)","levels":null}},{"q":11,"sub":"e","marks":8,"section":"B","ctx":[],"ctxb":[{"t":"p","x":"The business predicts a 25% rise in revenue over the next 12 months if it takes on a second studio. Rent will be 50% higher and the new studio will employ two extra staff."}],"text":"Analyse the limitations of ratio analysis to Orchard Studio in deciding whether it can afford to take on a second studio.","qTotal":null,"ms":{"body":"• Ratios use historical data – the new studio’s rent, wages and revenue will change the figures\n• Only four years of trading so limited trend data; seasonal wedding business means year-end ratios may hide swings\n• Ratios do not show non-financial factors (reputation, quality, staff skills, demand for the new location)\n• Need comparison with similar businesses; different accounting policies\n• Cash flow forecasts and break-even are also needed; ratios do not show the cash needed for fit-out\n• Focus on limitations of ratios – not whether to expand\n(8)","levels":8}},{"q":11,"sub":"f","marks":12,"section":"B","ctx":[],"ctxb":[{"t":"p","x":"Orchard Studio has retained profit of £22,000 and a bank balance of £9,000. The second studio needs £40,000 for fit-out and equipment. A bank loan of £40,000 at 8% a year would cost about £3,200 interest in the first year. The owner is worried about falling bookings if the economy slows."}],"text":"Evaluate whether Orchard Studio should finance the second studio by using retained profit or by taking out a five-year bank loan of £40,000 at 8% interest.","qTotal":null,"ms":{"body":"• Retained profit: no interest, no repayment, no security, owner keeps control; but only £22,000 so not enough alone and would drain reserves leaving little cash for wages/supplies\n• Bank loan: provides the full £40,000, spreads repayments, can combine with retained profit; interest cost (about £3,200 in year 1, more in total), regular repayments increase fixed costs and break-even, security may be required\n• Context: seasonal wedding business and possible fall in bookings raises risk of repayment problems; current ratio 1.5 and receivable days (146) show cash is tied up\n• Alternatives: leasing equipment, grant, crowd-funding, partial loan + retained profit\n• Justified recommendation with risks managed (e.g. smaller loan, cash flow forecast)\n(12)","levels":12}}],"minutes":120},{"id":"U3-R2","unit":3,"key":"9902","series":"RA10 practice","date":"RA10 practice paper","title":"Street Eats · Lopez Garden Services","source":"ra10","kind":"exam","total":80,"sec":{"A":28,"B":52},"items":[{"q":1,"sub":null,"marks":2,"section":"A","ctx":[],"ctxb":[],"text":"Identify two benefits of paying by contactless card.","qTotal":null,"ms":{"body":"Award one mark for each benefit identified, up to a maximum of two marks.\n• Quick / saves time (1)\n• No PIN needed for small amounts (1)\n• Reduces handling of cash (1)\n• Can be used with phones/wearables (1)\n• Hygienic – no contact (1)\n• Accept any other appropriate response.","levels":null}},{"q":2,"sub":null,"marks":2,"section":"A","ctx":[],"ctxb":[],"text":"Give two features of a student current account.","qTotal":null,"ms":{"body":"Award one mark for each feature, up to a maximum of two marks.\n• Interest-free overdraft (1)\n• No monthly fee (1)\n• Railcard/discount perks (1)\n• Overdraft reduces after graduation (1)","levels":null}},{"q":3,"sub":null,"marks":2,"section":"A","ctx":[],"ctxb":[],"text":"Explain one advantage for an individual of borrowing from a credit union.","qTotal":null,"ms":{"body":"Award one mark for an advantage and one mark for a linked development.\n• Loans are low cost / capped interest (1) so repayments are more affordable (1)\n• Not-for-profit / member-owned (1) so profits are returned to members or kept low cost (1)\n• Considers people with poor credit histories (1) giving access to borrowing that other lenders refuse (1)\n• Accept any other reasonable answer.","levels":null}},{"q":4,"sub":null,"marks":4,"section":"A","ctx":[],"ctxb":[],"text":"Explain two disadvantages for an individual of using a store card.","qTotal":null,"ms":{"body":"Award one mark for each disadvantage and one for a linked development, up to four marks.\n• High interest rate / APR (1) so unpaid balances become expensive (1)\n• Can only be used in one retailer/group (1) so limited usefulness (1)\n• Encourages overspending through offers (1) leading to debt (1)\n• Missed payments harm credit rating (1) making future borrowing harder (1)","levels":null}},{"q":5,"sub":null,"marks":6,"section":"A","ctx":[],"ctxb":[{"t":"p","x":"Dev is 19 and has just started a university course. He has a student account with an interest-free overdraft of £1,500 and a maintenance loan paid each term. His laptop broke and he needs £700 for a replacement before an assignment deadline next week. A friend suggests he uses a payday loan; his bank offers to increase his overdraft; his parents could lend him £400."}],"text":"Discuss whether Dev should use his overdraft or a payday loan to pay for the laptop.","qTotal":null,"ms":{"body":"• Overdraft: interest-free up to £1,500 so no extra cost for the £700; instant; flexible repayment when the loan arrives; risk of using too much of the buffer and graduating with an overdraft that becomes costly\n• Payday loan: very high APR and fees; full repayment due quickly; risk of debt spiral and damage to credit rating; no benefit when he has a free overdraft\n• Context: student with irregular income; deadline gives urgency; parents could supplement; need a laptop for study\n• Judgement: the overdraft is clearly cheaper – discuss when a payday loan could be considered\n(6)","levels":6}},{"q":6,"sub":null,"marks":12,"section":"A","ctx":[],"ctxb":[{"t":"p","x":"Hannah and Sam are 32 and have a baby. They want life and health protection and are comparing four policies. Their budget is £60 a month."},{"t":"grid","head":["Policy","Cost per month","Life cover","Critical illness cover","Excess/Notes"],"rows":[["SafeStart Basic","£18","£100,000 for 20 years","No","No payout if the term ends"],["FamilyGuard","£36","£200,000 for 25 years","No","Premiums fixed for the term"],["LifeShield Plus","£58","£200,000 for 25 years","£50,000","Premiums fixed; payout once"],["WholeLife Gold","£95","£150,000 for life","£30,000","Premiums can rise every 5 years"]]}],"text":"Evaluate which policy would be most suitable for Hannah and Sam.","qTotal":null,"ms":{"body":"• SafeStart Basic: cheapest and affordable, but only £100,000 for 20 years – may not cover a mortgage and childcare; no critical illness cover; term ends before the child is independent\n• FamilyGuard: £36 is within budget; £200,000 for 25 years protects the family until the baby is an adult; no critical illness cover\n• LifeShield Plus: £58 is within £60 budget; includes critical illness £50,000 – covers loss of income if either is ill; leaves little spare budget\n• WholeLife Gold: £95 exceeds budget; cover for life but premiums rise; shorter-term needs\n• Context: young family, mortgage, baby, budget £60\n• Recommendation (FamilyGuard or LifeShield Plus) with reasons for rejecting the others\n(12)","levels":12}},{"q":7,"sub":null,"marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Give two examples of revenue expenditure.","qTotal":null,"ms":{"body":"Award one mark for each example, up to a maximum of two marks.\n• Wages / salaries (1)\n• Rent / rates (1)\n• Utilities (1)\n• Insurance (1)\n• Marketing (1)\n• Inventory purchases (1)\n• Do not accept purchase of machinery or vehicles (capital expenditure).","levels":null}},{"q":8,"sub":null,"marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Explain one impact of leasing equipment on a small business.","qTotal":null,"ms":{"body":"Award one mark for an impact and one mark for a linked development.\n• No large initial outlay (1) so cash is available for other purposes (1)\n• The business does not own the asset (1) so cannot sell it or use it as security (1)\n• Regular lease payments (1) increase fixed costs over the long term (1)","levels":null}},{"q":9,"sub":null,"marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Give two sources of internal finance.","qTotal":null,"ms":{"body":"Award one mark for each source, up to a maximum of two marks.\n• Retained profit (1)\n• Sale of assets (1)\n• Net current assets / working capital (1)\n• Do not accept bank loan or overdraft.","levels":null}},{"q":10,"sub":"a","marks":4,"section":"B","ctx":[],"ctxb":[{"t":"p","x":"Lena runs Street Eats, a food stall that sells noodle boxes at markets. She plans to open a permanent unit in a food hall. She has estimated these costs and revenue for the first six months."},{"t":"grid","head":["Estimated cost/ revenue","Jun","Jul","Aug","Sep","Oct","Nov"],"rows":[["Number of sales","250","(iii)","600","650","800","900"],["Total revenue (£)","1 500","2 700","3 600","3 900","(iv)","5 400"],["Fixed costs (£)","2 800","2 800","2 800","2 800","2 800","2 800"],["Total variable costs (£)","(i)","675","900","975","1 200","1 350"],["Total costs (£)","(ii)","3 475","3 700","3 775","4 000","4 150"]]}],"text":"Calculate the figures missing from the table above.","qTotal":null,"ms":{"body":"Award one mark for each correct answer.\n• (i) 375\n• (ii) 3 175 (ECF) Addition of (i) + fixed costs\n• (iii) 450\n• (iv) 4 800\n(4)","levels":null}},{"q":10,"sub":"b","marks":4,"section":"B","ctx":[],"ctxb":[{"t":"p","x":"The food-hall unit will have higher rent and an extra member of staff, so costs will differ from the estimates above."}],"text":"Calculate the break-even point per month for the new food stall if it has: variable costs of £2 per portion; a selling price of £7; fixed costs of £4,500. Show your workings.","qTotal":null,"ms":{"body":"Award four marks for the correct response of 900 portions per month. Accept with or without the unit.\n• OR Award three marks for the correct formula in numbers: BEP = 4 500 / (7 – 2) (3)\n• OR Award one mark for the correct contribution of £5 AND one mark for the formula in words: Break-even point = fixed costs ÷ (selling price – variable cost) (2)\n(4)","levels":null}},{"q":10,"sub":"c","marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Calculate the margin of safety in the final month for the new food stall, which expects to sell 1 200 portions. Show your workings.","qTotal":null,"ms":{"body":"Award two marks for the correct response of 300 portions. Apply ECF using the break-even point from 10(b).\n• OR Award one mark for the formula in words: margin of safety = expected sales – break-even point (1)\n• OR one mark for the formula in numbers: 1 200 – 900 (1)\n(2)","levels":null}},{"q":10,"sub":"d","marks":6,"section":"B","ctx":[],"ctxb":[],"text":"Discuss the actions Lena could take to improve the break-even point of the food-hall unit.","qTotal":null,"ms":{"body":"• Raise the price – increases contribution per portion; risk of fewer customers in a competitive food hall\n• Reduce variable costs (bulk buying, simpler packaging) – but quality/brand\n• Reduce fixed costs (negotiate rent, fewer staff hours) – may reduce service/opening hours\n• Context: new unit; early sales below break-even; may accept loss initially\n• Balanced conclusion\n(6)","levels":6}},{"q":11,"sub":"a","marks":2,"section":"B","ctx":[],"ctxb":[{"t":"p","x":"Lopez Garden Services has operated for three years providing landscaping to homeowners and small businesses. The owner has given you the following information."},{"t":"cap","x":"Extract of financial information for Lopez Garden Services"},{"t":"grid","head":["","£"],"rows":[["Current assets","18 000"],["Current liabilities","15 000"],["Total revenue","210 000"],["Cost of sales","84 000"],["Expenses","96 000"],["Trade receivables","26 000"],["Credit sales","70 000"]]}],"text":"Calculate the current ratio. Show your workings.","qTotal":null,"ms":{"body":"Award two marks for the correct response of 1.2 : 1. Accept 1.2.\n• OR award one mark for the formula in words: current ratio = current assets ÷ current liabilities (1)\n• Accept the correct answer anywhere in the workings box. A ratio of the two numbers (e.g. 18 000:15 000) is not worth marks.\n(2)","levels":null}},{"q":11,"sub":"b","marks":3,"section":"B","ctx":[],"ctxb":[],"text":"Calculate the gross profit margin. Show your workings.","qTotal":null,"ms":{"body":"Award three marks for the correct response of 60.0%.\n• Gross profit = 210 000 – 84 000 = 126 000 (1)\n• Formula: (gross profit ÷ revenue) × 100 (1)\n• Answer 60.0% (1)\n(3)","levels":null}},{"q":11,"sub":"c","marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Calculate the trade receivable days. Show your workings.","qTotal":null,"ms":{"body":"Award two marks for the correct response of 135.6 days (accept 136).\n• OR one mark for the formula: (trade receivables ÷ credit sales) × 365 (1)\n(2)","levels":null}},{"q":11,"sub":"d","marks":3,"section":"B","ctx":[],"ctxb":[],"text":"Calculate the profit margin for the year. Show your workings.","qTotal":null,"ms":{"body":"Award three marks for the correct response of 14.3%.\n• Profit = gross profit – expenses = 126 000 – 96 000 = 30 000 (1)\n• Formula: (profit ÷ revenue) × 100 (1)\n• Answer 14.3% (1)\n(3)","levels":null}},{"q":11,"sub":"e","marks":8,"section":"B","ctx":[],"ctxb":[{"t":"p","x":"The owner expects revenue to rise by 30% next year with the extra capacity. Fuel and wages would rise, and new commercial customers usually pay after 60 days."}],"text":"Analyse the limitations of ratio analysis to Lopez Garden Services in deciding whether it can afford to buy a second van and hire two more staff.","qTotal":null,"ms":{"body":"• Past figures may not represent the effect of new staff, fuel costs and longer credit\n• Three years of data only; garden business is seasonal so year-end ratios may mislead\n• No information on non-financial factors (demand, weather, quality)\n• Ratios need comparison with competitors and industry averages\n• Does not show cash flow timing or break-even for the new van; forecasts needed\n• Focus on limitations\n(8)","levels":8}},{"q":11,"sub":"f","marks":12,"section":"B","ctx":[],"ctxb":[{"t":"p","x":"The van costs £24,000. Hire purchase requires a £4,000 deposit and 36 payments of £650. Leasing costs £480 a month for 36 months including maintenance, but the business will not own the van at the end. The business has £9,000 in the bank."}],"text":"Evaluate whether Lopez Garden Services should buy the van with hire purchase or lease it.","qTotal":null,"ms":{"body":"• Hire purchase: owns the van at the end (asset on statement of financial position), deposit £4,000 of £9,000 cash; total cost £4,000 + 36 × £650 = £27,400; depreciation; maintenance extra\n• Leasing: no deposit, lower monthly cost (£17,280 over 36 months), maintenance included so costs predictable; never owns the van; may have mileage limits; lease continues as a fixed cost\n• Context: limited cash; seasonal revenue; expected growth of 30%; fixed costs raise break-even\n• Alternatives: buy outright with loan, buy second-hand\n• Justified recommendation referring to cash flow, ownership and risk\n(12)","levels":12}}],"minutes":120},{"id":"U3-R3","unit":3,"key":"9903","series":"RA10 practice","date":"RA10 practice paper","title":"Crumb & Co · Greenfield Print Studio","source":"ra10","kind":"exam","total":80,"sec":{"A":28,"B":52},"items":[{"q":1,"sub":null,"marks":2,"section":"A","ctx":[],"ctxb":[],"text":"Identify two benefits of paying by contactless card.","qTotal":null,"ms":{"body":"Award one mark for each benefit identified, up to a maximum of two marks.\n• Quick / saves time (1)\n• No PIN needed for small amounts (1)\n• Reduces handling of cash (1)\n• Can be used with phones/wearables (1)\n• Hygienic – no contact (1)\n• Accept any other appropriate response.","levels":null}},{"q":2,"sub":null,"marks":2,"section":"A","ctx":[],"ctxb":[],"text":"Give two features of a student current account.","qTotal":null,"ms":{"body":"Award one mark for each feature, up to a maximum of two marks.\n• Interest-free overdraft (1)\n• No monthly fee (1)\n• Railcard/discount perks (1)\n• Overdraft reduces after graduation (1)","levels":null}},{"q":3,"sub":null,"marks":2,"section":"A","ctx":[],"ctxb":[],"text":"Explain one advantage for an individual of borrowing from a credit union.","qTotal":null,"ms":{"body":"Award one mark for an advantage and one mark for a linked development.\n• Loans are low cost / capped interest (1) so repayments are more affordable (1)\n• Not-for-profit / member-owned (1) so profits are returned to members or kept low cost (1)\n• Considers people with poor credit histories (1) giving access to borrowing that other lenders refuse (1)\n• Accept any other reasonable answer.","levels":null}},{"q":4,"sub":null,"marks":4,"section":"A","ctx":[],"ctxb":[],"text":"Explain two disadvantages for an individual of using a store card.","qTotal":null,"ms":{"body":"Award one mark for each disadvantage and one for a linked development, up to four marks.\n• High interest rate / APR (1) so unpaid balances become expensive (1)\n• Can only be used in one retailer/group (1) so limited usefulness (1)\n• Encourages overspending through offers (1) leading to debt (1)\n• Missed payments harm credit rating (1) making future borrowing harder (1)","levels":null}},{"q":5,"sub":null,"marks":6,"section":"A","ctx":[],"ctxb":[{"t":"p","x":"Layla is 26 and works as a nurse. Her take-home pay is £1,900 a month and her rent and bills are £1,300. Her car has failed its test and she needs a reliable car for her community placements. A suitable used car costs £4,200 and she has £500 saved. A credit union offers a loan of £4,200 over 36 months at 8.9% APR with payments of about £133 a month (about £4,790 in total). A bank offers a credit card with 0% interest for 15 months, a £4,500 limit, and then 22.9% APR."}],"text":"Discuss whether Layla should use a credit union loan or a 0% credit card to buy the car.","qTotal":null,"ms":{"body":"• Credit union loan: fixed payments of about £133 are affordable (£600 spare each month) and certain; total repayment about £4,790 so interest about £590; ethical lender; she knows the cost from the start; loan reduces future borrowing capacity\n• 0% credit card: no interest if she repays £4,200 within 15 months (£280 a month, which is affordable from £600 spare); much cheaper than the loan if she clears it on time; but if she misses the deadline she pays 22.9% interest on the remainder; temptation to spend more on the card\n• Context: stable income as a nurse; needs a car for work; has £500 savings which could reduce borrowing\n• Judgement: the 0% card is cheaper if she is disciplined; the loan is safer if she is concerned about budgeting\n(6)","levels":6}},{"q":6,"sub":null,"marks":12,"section":"A","ctx":[],"ctxb":[{"t":"p","x":"Jamal is 19 and starting an apprenticeship. His pay is £1,050 a month. He wants a current account to receive his wages and manage everyday spending. He sometimes runs short at the end of the month and wants to avoid expensive charges."},{"t":"grid","head":["Account","Monthly fee","Overdraft","Other features"],"rows":[["Basic Plus","£0","No overdraft","Debit card; no credit check required"],["Young Saver","£0","£500 interest-free for 12 months, then 39.9% EAR","Mobile app; savings pots"],["Packaged Gold","£14","£1,500 at 19.9% EAR","Travel and phone insurance; breakdown cover"],["Digital Smart","£0","£300 at 29.9% EAR","App with spending alerts; instant notifications"]]}],"text":"Evaluate which account would be most suitable for Jamal.","qTotal":null,"ms":{"body":"• Basic Plus: no fees or overdraft so no risk of charges, but no flexibility if he runs short; meets need for simple account\n• Young Saver: £500 interest-free overdraft for a year covers month-end shortages; free; app and pots help budgeting; interest of 39.9% after 12 months means he must clear it\n• Packaged Gold: £14 a month (£168 a year) is expensive on £1,050 pay; insurance he is unlikely to need; overdraft more expensive than needed\n• Digital Smart: free with alerts but overdraft interest at 29.9% on £300 is costly if he uses it\n• Context: apprentice, young, low income, wants to avoid charges\n• Recommended account (likely Young Saver) with reasons for rejecting others\n(12)","levels":12}},{"q":7,"sub":null,"marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Give two examples of revenue expenditure.","qTotal":null,"ms":{"body":"Award one mark for each example, up to a maximum of two marks.\n• Wages / salaries (1)\n• Rent / rates (1)\n• Utilities (1)\n• Insurance (1)\n• Marketing (1)\n• Inventory purchases (1)\n• Do not accept purchase of machinery or vehicles (capital expenditure).","levels":null}},{"q":8,"sub":null,"marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Explain one impact of leasing equipment on a small business.","qTotal":null,"ms":{"body":"Award one mark for an impact and one mark for a linked development.\n• No large initial outlay (1) so cash is available for other purposes (1)\n• The business does not own the asset (1) so cannot sell it or use it as security (1)\n• Regular lease payments (1) increase fixed costs over the long term (1)","levels":null}},{"q":9,"sub":null,"marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Give two sources of internal finance.","qTotal":null,"ms":{"body":"Award one mark for each source, up to a maximum of two marks.\n• Retained profit (1)\n• Sale of assets (1)\n• Net current assets / working capital (1)\n• Do not accept bank loan or overdraft.","levels":null}},{"q":10,"sub":"a","marks":4,"section":"B","ctx":[],"ctxb":[{"t":"p","x":"Nadia owns Crumb & Co, a bakery that sells sourdough loaves to cafés and at a local market. She is thinking of opening a small shop. She has estimated the following costs and revenue for the first six months."},{"t":"grid","head":["Estimated cost/ revenue","Jan","Feb","Mar","Apr","May","Jun"],"rows":[["Number of sales","500","(iii)","1 000","1 200","1 400","1 500"],["Total revenue (£)","2 000","3 200","4 000","4 800","(iv)","6 000"],["Fixed costs (£)","3 000","3 000","3 000","3 000","3 000","3 000"],["Total variable costs (£)","(i)","1 120","1 400","1 680","1,960.00","2 100"],["Total costs (£)","(ii)","4 120","4 400","4 680","4 960","5 100"]]}],"text":"Calculate the figures missing from the table above.","qTotal":null,"ms":{"body":"Award one mark for each correct answer.\n• (i) 700\n• (ii) 3 700 (ECF) Addition of (i) + fixed costs\n• (iii) 800\n• (iv) 5 600\n(4)","levels":null}},{"q":10,"sub":"b","marks":4,"section":"B","ctx":[],"ctxb":[{"t":"p","x":"The shop would be in a busier location with higher rent, so the costs will differ from the earlier estimates."}],"text":"Calculate the break-even point per month for the new bakery if it has: variable costs of £1.60 per loaf; a selling price of £4.50; fixed costs of £4,200. Show your workings.","qTotal":null,"ms":{"body":"Award four marks for the correct response of 1,448.28 loafs per month. Accept with or without the unit.\n• OR Award three marks for the correct formula in numbers: BEP = 4 200 / (4.50 – 1.60) (3)\n• OR Award one mark for the correct contribution of £2.90 AND one mark for the formula in words: Break-even point = fixed costs ÷ (selling price – variable cost) (2)\n(4)","levels":null}},{"q":10,"sub":"c","marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Calculate the margin of safety in the final month for the new bakery, which expects to sell 1 900 loafs. Show your workings.","qTotal":null,"ms":{"body":"Award two marks for the correct response of 451.72 loafs. Apply ECF using the break-even point from 10(b).\n• OR Award one mark for the formula in words: margin of safety = expected sales – break-even point (1)\n• OR one mark for the formula in numbers: 1 900 – 1,448.28 (1)\n(2)","levels":null}},{"q":10,"sub":"d","marks":6,"section":"B","ctx":[],"ctxb":[],"text":"Discuss the actions Nadia could take to improve the break-even point of the new shop.","qTotal":null,"ms":{"body":"• Raise price – increases contribution per loaf, but a busy high street has competition from supermarkets\n• Reduce variable costs – cheaper flour or less packaging; may reduce quality and the product’s reputation\n• Reduce fixed costs – shorter opening hours or smaller premises; may reduce customers\n• Context: new shop with initial low sales; early losses are likely, so the break-even point may take several months\n• Balanced conclusion – a combination of actions\n(6)","levels":6}},{"q":11,"sub":"a","marks":2,"section":"B","ctx":[],"ctxb":[{"t":"p","x":"Greenfield Print Studio prints posters and leaflets for local businesses. It has been trading for five years. You have been given the following information about the last financial year."},{"t":"cap","x":"Extract of financial information for Greenfield Print Studio"},{"t":"grid","head":["","£"],"rows":[["Current assets","25 000"],["Current liabilities","16 000"],["Total revenue","210 000"],["Cost of sales","88 000"],["Expenses","76 000"],["Trade receivables","33 000"],["Credit sales","90 000"]]}],"text":"Calculate the current ratio. Show your workings.","qTotal":null,"ms":{"body":"Award two marks for the correct response of 1.56 : 1. Accept 1.56.\n• OR award one mark for the formula in words: current ratio = current assets ÷ current liabilities (1)\n• Accept the correct answer anywhere in the workings box. A ratio of the two numbers (e.g. 25 000:16 000) is not worth marks.\n(2)","levels":null}},{"q":11,"sub":"b","marks":3,"section":"B","ctx":[],"ctxb":[],"text":"Calculate the gross profit margin. Show your workings.","qTotal":null,"ms":{"body":"Award three marks for the correct response of 58.1%.\n• Gross profit = 210 000 – 88 000 = 122 000 (1)\n• Formula: (gross profit ÷ revenue) × 100 (1)\n• Answer 58.1% (1)\n(3)","levels":null}},{"q":11,"sub":"c","marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Calculate the trade receivable days. Show your workings.","qTotal":null,"ms":{"body":"Award two marks for the correct response of 133.8 days (accept 134).\n• OR one mark for the formula: (trade receivables ÷ credit sales) × 365 (1)\n(2)","levels":null}},{"q":11,"sub":"d","marks":3,"section":"B","ctx":[],"ctxb":[],"text":"Calculate the profit margin for the year. Show your workings.","qTotal":null,"ms":{"body":"Award three marks for the correct response of 21.9%.\n• Profit = gross profit – expenses = 122 000 – 76 000 = 46 000 (1)\n• Formula: (profit ÷ revenue) × 100 (1)\n• Answer 21.9% (1)\n(3)","levels":null}},{"q":11,"sub":"e","marks":8,"section":"B","ctx":[],"ctxb":[{"t":"p","x":"The owner expects revenue to rise by 20% with a second press, but the press would add £30,000 to costs and need an extra operator."}],"text":"Analyse the limitations of ratio analysis to Greenfield Print Studio in deciding whether it can afford a second printing press.","qTotal":null,"ms":{"body":"• Past ratios may not predict the effect of the new press, extra costs and extra revenue\n• Only five years of data; may not show trends or seasonality\n• Ratios do not measure non-financial factors – demand, customer loyalty, print quality, staff skills\n• Need comparison with similar businesses and industry averages\n• Does not show cash flow; forecasts and break-even are also needed\n• Focus on limitations not on the decision\n(8)","levels":8}},{"q":11,"sub":"f","marks":12,"section":"B","ctx":[],"ctxb":[{"t":"p","x":"The press costs £36,000. A bank loan of £36,000 over five years at 8% would cost about £8,200 interest in total. Hire purchase requires a £4,000 deposit and 48 payments of £780. Greenfield has £11,000 in the bank."}],"text":"Evaluate whether Greenfield Print Studio should finance the second press with a bank loan or hire purchase.","qTotal":null,"ms":{"body":"• Loan: borrows the full £36,000 so cash is preserved; interest about £8,200 in total; may need security; fixed repayments increase break-even\n• Hire purchase: deposit £4,000 of £11,000 cash; total cost £4,000 + 48 × £780 = £41,440; the business owns the press only after the last payment; lender can repossess\n• Context: modest cash reserves; receivables are 131 days so cash flow is tight\n• Alternatives: leasing, second-hand press, smaller loan with retained profit\n• Justified recommendation with consideration of cost, cash and risk\n(12)","levels":12}}],"minutes":120},{"id":"U3-R4","unit":3,"key":"9904","series":"RA10 practice","date":"RA10 practice paper","title":"Tara’s Juice Bar · Kingsley Cleaning Services","source":"ra10","kind":"exam","total":80,"sec":{"A":28,"B":52},"items":[{"q":1,"sub":null,"marks":2,"section":"A","ctx":[],"ctxb":[],"text":"Identify two benefits of paying by contactless card.","qTotal":null,"ms":{"body":"Award one mark for each benefit identified, up to a maximum of two marks.\n• Quick / saves time (1)\n• No PIN needed for small amounts (1)\n• Reduces handling of cash (1)\n• Can be used with phones/wearables (1)\n• Hygienic – no contact (1)\n• Accept any other appropriate response.","levels":null}},{"q":2,"sub":null,"marks":2,"section":"A","ctx":[],"ctxb":[],"text":"Give two features of a student current account.","qTotal":null,"ms":{"body":"Award one mark for each feature, up to a maximum of two marks.\n• Interest-free overdraft (1)\n• No monthly fee (1)\n• Railcard/discount perks (1)\n• Overdraft reduces after graduation (1)","levels":null}},{"q":3,"sub":null,"marks":2,"section":"A","ctx":[],"ctxb":[],"text":"Explain one advantage for an individual of borrowing from a credit union.","qTotal":null,"ms":{"body":"Award one mark for an advantage and one mark for a linked development.\n• Loans are low cost / capped interest (1) so repayments are more affordable (1)\n• Not-for-profit / member-owned (1) so profits are returned to members or kept low cost (1)\n• Considers people with poor credit histories (1) giving access to borrowing that other lenders refuse (1)\n• Accept any other reasonable answer.","levels":null}},{"q":4,"sub":null,"marks":4,"section":"A","ctx":[],"ctxb":[],"text":"Explain two disadvantages for an individual of using a store card.","qTotal":null,"ms":{"body":"Award one mark for each disadvantage and one for a linked development, up to four marks.\n• High interest rate / APR (1) so unpaid balances become expensive (1)\n• Can only be used in one retailer/group (1) so limited usefulness (1)\n• Encourages overspending through offers (1) leading to debt (1)\n• Missed payments harm credit rating (1) making future borrowing harder (1)","levels":null}},{"q":5,"sub":null,"marks":6,"section":"A","ctx":[],"ctxb":[{"t":"p","x":"Marcus is 30 and a self-employed plumber. His income varies between £1,800 and £3,200 a month. He needs a new set of professional tools costing £1,500. He has £300 saved. A tool shop offers store finance: £150 deposit and 12 payments of £125 (no interest). His credit card has a £2,000 limit with 21.9% APR and he already owes £600 on it."}],"text":"Discuss whether Marcus should use store finance or his credit card to buy the tools.","qTotal":null,"ms":{"body":"• Store finance: 0% interest, total £150 + 12 × £125 = £1,650 (so about £150 more than the cash price but fixed); predictable payments for 12 months; may require a credit check; tools may be repossessed if payments are missed\n• Credit card: flexible repayment, but 21.9% APR makes it expensive if not repaid quickly; he already owes £600 so £1,500 more would use almost the limit; may reduce his credit score\n• Context: irregular income – a fixed payment of £125 may be difficult in low months, but tools are needed to earn; deposit uses half his savings\n• Judgement: weigh certainty of store finance against flexibility and high interest of the card\n(6)","levels":6}},{"q":6,"sub":null,"marks":12,"section":"A","ctx":[],"ctxb":[{"t":"p","x":"Chloe and Dan are 29 and have just moved into a rented flat. They own a laptop, a TV and other items worth about £9,000. They have a budget of £15 a month for contents insurance and want to cover accidental damage and theft."},{"t":"grid","head":["Insurer","Monthly premium","Contents cover","Excess","Accidental damage"],"rows":[["SafeHome Basic","£7","£15,000","£250","Not included"],["SecureNest","£13","£20,000","£100","Included"],["Premier Cover","£24","£50,000","£50","Included; plus bicycles and gadgets away from home"],["QuickPolicy","£10","£10,000","£400","Included"]]}],"text":"Evaluate which insurance policy would be most suitable for Chloe and Dan.","qTotal":null,"ms":{"body":"• SafeHome Basic: cheapest (£7) but no accidental damage; £250 excess; may not meet their needs\n• SecureNest: £13 fits the £15 budget; £20,000 covers their £9,000 of belongings; low £100 excess; accidental damage included\n• Premier Cover: £24 exceeds budget; cover far above their needs\n• QuickPolicy: £10 but £10,000 cover only just above the value of belongings and a high £400 excess – claims would be costly\n• Context: young couple, rented flat, modest budget\n• Recommendation (likely SecureNest) with reasons for rejecting others\n(12)","levels":12}},{"q":7,"sub":null,"marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Give two examples of revenue expenditure.","qTotal":null,"ms":{"body":"Award one mark for each example, up to a maximum of two marks.\n• Wages / salaries (1)\n• Rent / rates (1)\n• Utilities (1)\n• Insurance (1)\n• Marketing (1)\n• Inventory purchases (1)\n• Do not accept purchase of machinery or vehicles (capital expenditure).","levels":null}},{"q":8,"sub":null,"marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Explain one impact of leasing equipment on a small business.","qTotal":null,"ms":{"body":"Award one mark for an impact and one mark for a linked development.\n• No large initial outlay (1) so cash is available for other purposes (1)\n• The business does not own the asset (1) so cannot sell it or use it as security (1)\n• Regular lease payments (1) increase fixed costs over the long term (1)","levels":null}},{"q":9,"sub":null,"marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Give two sources of internal finance.","qTotal":null,"ms":{"body":"Award one mark for each source, up to a maximum of two marks.\n• Retained profit (1)\n• Sale of assets (1)\n• Net current assets / working capital (1)\n• Do not accept bank loan or overdraft.","levels":null}},{"q":10,"sub":"a","marks":4,"section":"B","ctx":[],"ctxb":[{"t":"p","x":"Tara runs a juice bar at a market stall. She is considering opening a permanent juice bar in a gym foyer. She has estimated the following costs and revenue for the first six months."},{"t":"grid","head":["Estimated cost/ revenue","Apr","May","Jun","Jul","Aug","Sep"],"rows":[["Number of sales","300","(iii)","650","800","950","1 000"],["Total revenue (£)","1 500","2 500","3 250","4 000","(iv)","5 000"],["Fixed costs (£)","2 400","2 400","2 400","2 400","2 400","2 400"],["Total variable costs (£)","(i)","900","1 170","1 440","1 710","1 800"],["Total costs (£)","(ii)","3 300","3 570","3 840","4 110","4 200"]]}],"text":"Calculate the figures missing from the table above.","qTotal":null,"ms":{"body":"Award one mark for each correct answer.\n• (i) 540\n• (ii) 2 940 (ECF) Addition of (i) + fixed costs\n• (iii) 500\n• (iv) 4 750\n(4)","levels":null}},{"q":10,"sub":"b","marks":4,"section":"B","ctx":[],"ctxb":[{"t":"p","x":"The gym foyer unit charges a fixed monthly fee and requires one extra member of staff, so costs will be different from the market stall."}],"text":"Calculate the break-even point per month for the new juice bar if it has: variable costs of £1.90 per juice; a selling price of £5.50; fixed costs of £3,600. Show your workings.","qTotal":null,"ms":{"body":"Award four marks for the correct response of 1 000 juices per month. Accept with or without the unit.\n• OR Award three marks for the correct formula in numbers: BEP = 3 600 / (5.50 – 1.90) (3)\n• OR Award one mark for the correct contribution of £3.60 AND one mark for the formula in words: Break-even point = fixed costs ÷ (selling price – variable cost) (2)\n(4)","levels":null}},{"q":10,"sub":"c","marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Calculate the margin of safety in the final month for the new juice bar, which expects to sell 1 500 juices. Show your workings.","qTotal":null,"ms":{"body":"Award two marks for the correct response of 500 juices. Apply ECF using the break-even point from 10(b).\n• OR Award one mark for the formula in words: margin of safety = expected sales – break-even point (1)\n• OR one mark for the formula in numbers: 1 500 – 1 000 (1)\n(2)","levels":null}},{"q":10,"sub":"d","marks":6,"section":"B","ctx":[],"ctxb":[],"text":"Discuss the actions Tara could take to improve the break-even point of the gym juice bar.","qTotal":null,"ms":{"body":"• Raise the price – higher contribution per juice; but gym customers may compare prices and some are price-sensitive\n• Reduce variable costs – buy fruit in bulk or cheaper cups; may reduce quality\n• Reduce fixed costs – negotiate the fee, cut staff hours; may reduce service during peak times\n• Context: new unit; low sales initially; seasonal demand for cold juices\n• Balanced conclusion\n(6)","levels":6}},{"q":11,"sub":"a","marks":2,"section":"B","ctx":[],"ctxb":[{"t":"p","x":"Kingsley Cleaning Services provides regular office cleaning for small businesses and has traded for four years. You have been given this information about last year."},{"t":"cap","x":"Extract of financial information for Kingsley Cleaning Services"},{"t":"grid","head":["","£"],"rows":[["Current assets","14 000"],["Current liabilities","12 000"],["Total revenue","168 000"],["Cost of sales","66 000"],["Expenses","64 000"],["Trade receivables","21 000"],["Credit sales","72 000"]]}],"text":"Calculate the current ratio. Show your workings.","qTotal":null,"ms":{"body":"Award two marks for the correct response of 1.17 : 1. Accept 1.17.\n• OR award one mark for the formula in words: current ratio = current assets ÷ current liabilities (1)\n• Accept the correct answer anywhere in the workings box. A ratio of the two numbers (e.g. 14 000:12 000) is not worth marks.\n(2)","levels":null}},{"q":11,"sub":"b","marks":3,"section":"B","ctx":[],"ctxb":[],"text":"Calculate the gross profit margin. Show your workings.","qTotal":null,"ms":{"body":"Award three marks for the correct response of 60.7%.\n• Gross profit = 168 000 – 66 000 = 102 000 (1)\n• Formula: (gross profit ÷ revenue) × 100 (1)\n• Answer 60.7% (1)\n(3)","levels":null}},{"q":11,"sub":"c","marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Calculate the trade receivable days. Show your workings.","qTotal":null,"ms":{"body":"Award two marks for the correct response of 106.5 days (accept 106).\n• OR one mark for the formula: (trade receivables ÷ credit sales) × 365 (1)\n(2)","levels":null}},{"q":11,"sub":"d","marks":3,"section":"B","ctx":[],"ctxb":[],"text":"Calculate the profit margin for the year. Show your workings.","qTotal":null,"ms":{"body":"Award three marks for the correct response of 22.6%.\n• Profit = gross profit – expenses = 102 000 – 64 000 = 38 000 (1)\n• Formula: (profit ÷ revenue) × 100 (1)\n• Answer 22.6% (1)\n(3)","levels":null}},{"q":11,"sub":"e","marks":8,"section":"B","ctx":[],"ctxb":[{"t":"p","x":"A large contract would add 40% to revenue but would require two additional vehicles and six extra staff, and the client would pay after 60 days."}],"text":"Analyse the limitations of ratio analysis to Kingsley Cleaning Services in deciding whether it can afford to win a large new contract.","qTotal":null,"ms":{"body":"• Ratios show past performance, not the effect of the new contract on costs and cash\n• Four years of data; cannot show how a larger scale might change margins\n• Do not consider non-financial factors – reliability, staff, reputation, risk of dependence on one client\n• Need comparison with similar businesses; different accounting methods\n• Cash flow forecast is needed because of 60-day payment and upfront costs\n• Focus on limitations\n(8)","levels":8}},{"q":11,"sub":"f","marks":12,"section":"B","ctx":[],"ctxb":[{"t":"p","x":"Buying two vans costs £28,000 using a bank loan at 9%. Leasing costs £520 a month for both vans for 36 months including maintenance. The business has £6,500 in the bank."}],"text":"Evaluate whether Kingsley Cleaning Services should lease or buy two vehicles for the new contract.","qTotal":null,"ms":{"body":"• Buying: owns assets that keep value, but needs £28,000 financed by loan (interest about £3,800 over 3 years plus maintenance); increases fixed costs and gearing\n• Leasing: no large outlay, predictable £520 a month (£18,720 over 36 months), maintenance included; never owns the vans; contract may limit mileage\n• Context: limited cash; large client pays late; risk if contract ends\n• Alternatives: buy one and lease one; hire purchase\n• Justified recommendation referring to cash flow and risk\n(12)","levels":12}}],"minutes":120},{"id":"U3-R5","unit":3,"key":"9905","series":"RA10 practice","date":"RA10 practice paper","title":"Dylan’s Burger Van · Bright Path Tutors","source":"ra10","kind":"exam","total":80,"sec":{"A":28,"B":52},"items":[{"q":1,"sub":null,"marks":2,"section":"A","ctx":[],"ctxb":[],"text":"Identify two benefits of paying by contactless card.","qTotal":null,"ms":{"body":"Award one mark for each benefit identified, up to a maximum of two marks.\n• Quick / saves time (1)\n• No PIN needed for small amounts (1)\n• Reduces handling of cash (1)\n• Can be used with phones/wearables (1)\n• Hygienic – no contact (1)\n• Accept any other appropriate response.","levels":null}},{"q":2,"sub":null,"marks":2,"section":"A","ctx":[],"ctxb":[],"text":"Give two features of a student current account.","qTotal":null,"ms":{"body":"Award one mark for each feature, up to a maximum of two marks.\n• Interest-free overdraft (1)\n• No monthly fee (1)\n• Railcard/discount perks (1)\n• Overdraft reduces after graduation (1)","levels":null}},{"q":3,"sub":null,"marks":2,"section":"A","ctx":[],"ctxb":[],"text":"Explain one advantage for an individual of borrowing from a credit union.","qTotal":null,"ms":{"body":"Award one mark for an advantage and one mark for a linked development.\n• Loans are low cost / capped interest (1) so repayments are more affordable (1)\n• Not-for-profit / member-owned (1) so profits are returned to members or kept low cost (1)\n• Considers people with poor credit histories (1) giving access to borrowing that other lenders refuse (1)\n• Accept any other reasonable answer.","levels":null}},{"q":4,"sub":null,"marks":4,"section":"A","ctx":[],"ctxb":[],"text":"Explain two disadvantages for an individual of using a store card.","qTotal":null,"ms":{"body":"Award one mark for each disadvantage and one for a linked development, up to four marks.\n• High interest rate / APR (1) so unpaid balances become expensive (1)\n• Can only be used in one retailer/group (1) so limited usefulness (1)\n• Encourages overspending through offers (1) leading to debt (1)\n• Missed payments harm credit rating (1) making future borrowing harder (1)","levels":null}},{"q":5,"sub":null,"marks":6,"section":"A","ctx":[],"ctxb":[{"t":"p","x":"Aisha is 21 and an apprentice electrician earning £1,200 a month. Her rent and bills are £800. She needs a £900 laptop for her college course. She has £400 saved. A retailer offers “buy now, pay later”: pay in four instalments of £225 every two weeks. Her bank offers an arranged overdraft of £500 at 39.9% EAR."}],"text":"Discuss whether Aisha should use “buy now, pay later” or her savings and overdraft to buy the laptop.","qTotal":null,"ms":{"body":"• Buy now, pay later: no interest if she pays on time; instalments of £225 every two weeks cost her about £450 a month, which is more than her £400 spare income, so she could not afford them without cutting other spending; late payments can lead to fees and affect credit file\n• Savings plus overdraft: £400 savings plus £500 overdraft; overdraft interest expensive if used for several months; but flexible\n• Context: low income; essential for study; limited emergency fund if she uses all savings\n• Alternatives: refurbished laptop, college loan scheme, student discount; judgement should recommend an option with justification\n(6)","levels":6}},{"q":6,"sub":null,"marks":12,"section":"A","ctx":[],"ctxb":[{"t":"p","x":"Ben is 24 and wants to build an emergency fund of £3,000 over two years. He saves £120 a month and does not want to lose his money. He has researched the following accounts."},{"t":"grid","head":["Account","Interest (AER)","Access","Other features"],"rows":[["Regular Saver","6.0% fixed for 12 months","No withdrawals; one deposit each month up to £150","Account ends after 12 months"],["Easy Access Saver","3.4% variable","Instant","FSCS protected"],["Notice Account","4.0% variable","60 days’ notice","FSCS protected; minimum £500"],["Stocks and Shares ISA","No guaranteed return","Within 5 working days","Investments can fall in value"]]}],"text":"Evaluate which option would be most suitable for Ben.","qTotal":null,"ms":{"body":"• Regular Saver: highest rate (6% on average balance gives about £47 on £1,440); ideal for monthly saving but no access for 12 months; account ends after a year so he needs another account; low emergency access\n• Easy Access: instant access suits an emergency fund; lower interest (3.4%) and variable\n• Notice account: 4% but 60 days’ notice not suitable for emergencies\n• Stocks and shares ISA: risk of loss, not suitable for a short-term emergency fund\n• Context: emergency fund, low risk, regular deposits of £120\n• Recommendation (e.g. easy access, or part in each) with reasons\n(12)","levels":12}},{"q":7,"sub":null,"marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Give two examples of revenue expenditure.","qTotal":null,"ms":{"body":"Award one mark for each example, up to a maximum of two marks.\n• Wages / salaries (1)\n• Rent / rates (1)\n• Utilities (1)\n• Insurance (1)\n• Marketing (1)\n• Inventory purchases (1)\n• Do not accept purchase of machinery or vehicles (capital expenditure).","levels":null}},{"q":8,"sub":null,"marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Explain one impact of leasing equipment on a small business.","qTotal":null,"ms":{"body":"Award one mark for an impact and one mark for a linked development.\n• No large initial outlay (1) so cash is available for other purposes (1)\n• The business does not own the asset (1) so cannot sell it or use it as security (1)\n• Regular lease payments (1) increase fixed costs over the long term (1)","levels":null}},{"q":9,"sub":null,"marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Give two sources of internal finance.","qTotal":null,"ms":{"body":"Award one mark for each source, up to a maximum of two marks.\n• Retained profit (1)\n• Sale of assets (1)\n• Net current assets / working capital (1)\n• Do not accept bank loan or overdraft.","levels":null}},{"q":10,"sub":"a","marks":4,"section":"B","ctx":[],"ctxb":[{"t":"p","x":"Dylan runs a burger van at local events. He plans to expand by opening a second van that will trade at a retail park. He has estimated the following costs and revenue for the first six months."},{"t":"grid","head":["Estimated cost/ revenue","May","Jun","Jul","Aug","Sep","Oct"],"rows":[["Number of sales","300","(iii)","700","850","900","950"],["Total revenue (£)","1 950","3 380","4 550","5 525","(iv)","6 175"],["Fixed costs (£)","2 600","2 600","2 600","2 600","2 600","2 600"],["Total variable costs (£)","(i)","1 144","1,540.00","1,870.00","1,980.00","2 090"],["Total costs (£)","(ii)","3 744","4 140","4 470","4 580","4 690"]]}],"text":"Calculate the figures missing from the table above.","qTotal":null,"ms":{"body":"Award one mark for each correct answer.\n• (i) 660\n• (ii) 3 260 (ECF) Addition of (i) + fixed costs\n• (iii) 520\n• (iv) 5 850\n(4)","levels":null}},{"q":10,"sub":"b","marks":4,"section":"B","ctx":[],"ctxb":[{"t":"p","x":"The retail-park pitch has a higher fee and Dylan will need another member of staff, so costs will be different."}],"text":"Calculate the break-even point per month for the new burger van if it has: variable costs of £2.30 per burger; a selling price of £7; fixed costs of £3,900. Show your workings.","qTotal":null,"ms":{"body":"Award four marks for the correct response of 829.79 burgers per month. Accept with or without the unit.\n• OR Award three marks for the correct formula in numbers: BEP = 3 900 / (7 – 2.30) (3)\n• OR Award one mark for the correct contribution of £4.70 AND one mark for the formula in words: Break-even point = fixed costs ÷ (selling price – variable cost) (2)\n(4)","levels":null}},{"q":10,"sub":"c","marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Calculate the margin of safety in the final month for the new burger van, which expects to sell 1 400 burgers. Show your workings.","qTotal":null,"ms":{"body":"Award two marks for the correct response of 570.21 burgers. Apply ECF using the break-even point from 10(b).\n• OR Award one mark for the formula in words: margin of safety = expected sales – break-even point (1)\n• OR one mark for the formula in numbers: 1 400 – 829.79 (1)\n(2)","levels":null}},{"q":10,"sub":"d","marks":6,"section":"B","ctx":[],"ctxb":[],"text":"Discuss the actions Dylan could take to improve the break-even point of the second van.","qTotal":null,"ms":{"body":"• Raise price – increases contribution; may reduce customers where there is competition\n• Cut variable costs – bulk buying, simpler menu; may affect quality\n• Reduce fixed costs – shorter trading days, negotiate pitch fee; may reduce sales\n• Context: new pitch; sales build slowly; weather affects takings\n• Balanced conclusion\n(6)","levels":6}},{"q":11,"sub":"a","marks":2,"section":"B","ctx":[],"ctxb":[{"t":"p","x":"Bright Path Tutors provides home tuition and has traded for three years. The owner has given you the following information."},{"t":"cap","x":"Extract of financial information for Bright Path Tutors"},{"t":"grid","head":["","£"],"rows":[["Current assets","9 500"],["Current liabilities","8 000"],["Total revenue","96 000"],["Cost of sales","38 000"],["Expenses","41 000"],["Trade receivables","8 000"],["Credit sales","36 000"]]}],"text":"Calculate the current ratio. Show your workings.","qTotal":null,"ms":{"body":"Award two marks for the correct response of 1.19 : 1. Accept 1.19.\n• OR award one mark for the formula in words: current ratio = current assets ÷ current liabilities (1)\n• Accept the correct answer anywhere in the workings box. A ratio of the two numbers (e.g. 9 500:8 000) is not worth marks.\n(2)","levels":null}},{"q":11,"sub":"b","marks":3,"section":"B","ctx":[],"ctxb":[],"text":"Calculate the gross profit margin. Show your workings.","qTotal":null,"ms":{"body":"Award three marks for the correct response of 60.4%.\n• Gross profit = 96 000 – 38 000 = 58 000 (1)\n• Formula: (gross profit ÷ revenue) × 100 (1)\n• Answer 60.4% (1)\n(3)","levels":null}},{"q":11,"sub":"c","marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Calculate the trade receivable days. Show your workings.","qTotal":null,"ms":{"body":"Award two marks for the correct response of 81.1 days (accept 81).\n• OR one mark for the formula: (trade receivables ÷ credit sales) × 365 (1)\n(2)","levels":null}},{"q":11,"sub":"d","marks":3,"section":"B","ctx":[],"ctxb":[],"text":"Calculate the profit margin for the year. Show your workings.","qTotal":null,"ms":{"body":"Award three marks for the correct response of 17.7%.\n• Profit = gross profit – expenses = 58 000 – 41 000 = 17 000 (1)\n• Formula: (profit ÷ revenue) × 100 (1)\n• Answer 17.7% (1)\n(3)","levels":null}},{"q":11,"sub":"e","marks":8,"section":"B","ctx":[],"ctxb":[{"t":"p","x":"The owner expects to double revenue with a centre, but rent, equipment and extra tutors will increase costs substantially."}],"text":"Analyse the limitations of ratio analysis to Bright Path Tutors in deciding whether to open a tuition centre.","qTotal":null,"ms":{"body":"• Past ratios do not predict future performance after a major change\n• Only three years of data\n• Do not show non-financial factors such as reputation and demand\n• Need comparison with similar businesses\n• Cash flow forecast needed for rent and set-up costs\n• Focus on limitations\n(8)","levels":8}},{"q":11,"sub":"f","marks":12,"section":"B","ctx":[],"ctxb":[{"t":"p","x":"The centre needs £30,000. A partner would invest £30,000 for a 40% share of profits. A bank loan of £30,000 at 8.5% would cost about £2,550 interest in the first year. The owner currently has £4,500 in the bank."}],"text":"Evaluate whether Bright Path Tutors should finance the centre by taking on a business partner or by taking a bank loan.","qTotal":null,"ms":{"body":"• Partner: no interest or repayments and shares the risk; brings skills; but loses 40% of profits and some control; disagreements possible\n• Bank loan: owner keeps all profits and control; interest £2,550 in year 1 and fixed repayments increase break-even; may need security\n• Context: small cash reserves; new centre is uncertain; sole trader with unlimited liability\n• Alternatives: smaller centre, leasing equipment, grant\n• Justified recommendation\n(12)","levels":12}}],"minutes":120},{"id":"U3-R6","unit":3,"key":"9906","series":"RA10 practice","date":"RA10 practice paper","title":"Kofi’s Barbers · Hartley Event Hire","source":"ra10","kind":"exam","total":80,"sec":{"A":28,"B":52},"items":[{"q":1,"sub":null,"marks":2,"section":"A","ctx":[],"ctxb":[],"text":"Identify two benefits of paying by contactless card.","qTotal":null,"ms":{"body":"Award one mark for each benefit identified, up to a maximum of two marks.\n• Quick / saves time (1)\n• No PIN needed for small amounts (1)\n• Reduces handling of cash (1)\n• Can be used with phones/wearables (1)\n• Hygienic – no contact (1)\n• Accept any other appropriate response.","levels":null}},{"q":2,"sub":null,"marks":2,"section":"A","ctx":[],"ctxb":[],"text":"Give two features of a student current account.","qTotal":null,"ms":{"body":"Award one mark for each feature, up to a maximum of two marks.\n• Interest-free overdraft (1)\n• No monthly fee (1)\n• Railcard/discount perks (1)\n• Overdraft reduces after graduation (1)","levels":null}},{"q":3,"sub":null,"marks":2,"section":"A","ctx":[],"ctxb":[],"text":"Explain one advantage for an individual of borrowing from a credit union.","qTotal":null,"ms":{"body":"Award one mark for an advantage and one mark for a linked development.\n• Loans are low cost / capped interest (1) so repayments are more affordable (1)\n• Not-for-profit / member-owned (1) so profits are returned to members or kept low cost (1)\n• Considers people with poor credit histories (1) giving access to borrowing that other lenders refuse (1)\n• Accept any other reasonable answer.","levels":null}},{"q":4,"sub":null,"marks":4,"section":"A","ctx":[],"ctxb":[],"text":"Explain two disadvantages for an individual of using a store card.","qTotal":null,"ms":{"body":"Award one mark for each disadvantage and one for a linked development, up to four marks.\n• High interest rate / APR (1) so unpaid balances become expensive (1)\n• Can only be used in one retailer/group (1) so limited usefulness (1)\n• Encourages overspending through offers (1) leading to debt (1)\n• Missed payments harm credit rating (1) making future borrowing harder (1)","levels":null}},{"q":5,"sub":null,"marks":6,"section":"A","ctx":[],"ctxb":[{"t":"p","x":"Owen is 45 and a delivery driver. He has a credit card debt of £4,000 at 24.9% APR and £2,500 in savings earning 3%. He has £250 a month spare after bills. He is considering using his savings to repay the debt, or paying the debt gradually from his spare income."}],"text":"Discuss whether Owen should use his savings to repay his credit card debt.","qTotal":null,"ms":{"body":"• Using savings: reduces debt to £1,500 immediately and saves interest at 24.9% (about £620 a year on £2,500) compared with earning about £75 interest; improves credit rating; but leaves no emergency fund\n• Paying from income: £250 a month would clear £4,000 in about 18 months but costs substantial interest (roughly £450 in total)\n• Context: 45, in steady employment but with little other protection against unexpected costs; savings provide security\n• Judgement: probably use most of the savings but keep a small emergency fund; consider balance transfer\n(6)","levels":6}},{"q":6,"sub":null,"marks":12,"section":"A","ctx":[],"ctxb":[{"t":"p","x":"Priya is 22 and has just started work. She is choosing a mobile phone contract. She wants a good camera and 20GB of data but her budget is £35 a month."},{"t":"grid","head":["Deal","Monthly cost","Data","Contract length","Other"],"rows":[["Contract A","£28","15GB","24 months","Mid-range handset"],["Contract B","£34","25GB","24 months","Phone with excellent camera"],["Contract C","£42","Unlimited","36 months","Latest flagship phone; cost rises with inflation each year"],["SIM-only D","£12","20GB","1 month rolling","She would buy her own phone (£480)"]]}],"text":"Evaluate which deal would be most suitable for Priya.","qTotal":null,"ms":{"body":"• Contract A: £28, but only 15GB (below 20GB wanted); mid-range camera\n• Contract B: £34 is within budget; 25GB exceeds need; excellent camera; 24-month commitment\n• Contract C: £42 exceeds budget; 36 months is long; cost rises\n• SIM-only D: £12 a month but £480 for a phone (equivalent to £20 a month over 24 months → £32 a month total); flexible; she owns the phone\n• Context: new job, budget £35, wants camera and data\n• Recommendation (B or D) with reasons for rejecting the others\n(12)","levels":12}},{"q":7,"sub":null,"marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Give two examples of revenue expenditure.","qTotal":null,"ms":{"body":"Award one mark for each example, up to a maximum of two marks.\n• Wages / salaries (1)\n• Rent / rates (1)\n• Utilities (1)\n• Insurance (1)\n• Marketing (1)\n• Inventory purchases (1)\n• Do not accept purchase of machinery or vehicles (capital expenditure).","levels":null}},{"q":8,"sub":null,"marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Explain one impact of leasing equipment on a small business.","qTotal":null,"ms":{"body":"Award one mark for an impact and one mark for a linked development.\n• No large initial outlay (1) so cash is available for other purposes (1)\n• The business does not own the asset (1) so cannot sell it or use it as security (1)\n• Regular lease payments (1) increase fixed costs over the long term (1)","levels":null}},{"q":9,"sub":null,"marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Give two sources of internal finance.","qTotal":null,"ms":{"body":"Award one mark for each source, up to a maximum of two marks.\n• Retained profit (1)\n• Sale of assets (1)\n• Net current assets / working capital (1)\n• Do not accept bank loan or overdraft.","levels":null}},{"q":10,"sub":"a","marks":4,"section":"B","ctx":[],"ctxb":[{"t":"p","x":"Kofi owns a one-chair barber shop. He is considering opening a second shop in a nearby town. He has estimated the following costs and revenue for the first six months."},{"t":"grid","head":["Estimated cost/ revenue","Jan","Feb","Mar","Apr","May","Jun"],"rows":[["Number of sales","110","(iii)","230","270","300","320"],["Total revenue (£)","1 650","2 700","3 450","4 050","(iv)","4 800"],["Fixed costs (£)","3 200","3 200","3 200","3 200","3 200","3 200"],["Total variable costs (£)","(i)","540","690","810","900","960"],["Total costs (£)","(ii)","3 740","3 890","4 010","4 100","4 160"]]}],"text":"Calculate the figures missing from the table above.","qTotal":null,"ms":{"body":"Award one mark for each correct answer.\n• (i) 330\n• (ii) 3 530 (ECF) Addition of (i) + fixed costs\n• (iii) 180\n• (iv) 4 500\n(4)","levels":null}},{"q":10,"sub":"b","marks":4,"section":"B","ctx":[],"ctxb":[{"t":"p","x":"The second shop will need two barbers and a larger unit, so costs will be higher than the estimates above."}],"text":"Calculate the break-even point per month for the new barber shop if it has: variable costs of £3.50 per haircut; a selling price of £16; fixed costs of £4,500. Show your workings.","qTotal":null,"ms":{"body":"Award four marks for the correct response of 360 haircuts per month. Accept with or without the unit.\n• OR Award three marks for the correct formula in numbers: BEP = 4 500 / (16 – 3.50) (3)\n• OR Award one mark for the correct contribution of £12.50 AND one mark for the formula in words: Break-even point = fixed costs ÷ (selling price – variable cost) (2)\n(4)","levels":null}},{"q":10,"sub":"c","marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Calculate the margin of safety in the final month for the new barber shop, which expects to sell 420 haircuts. Show your workings.","qTotal":null,"ms":{"body":"Award two marks for the correct response of 60 haircuts. Apply ECF using the break-even point from 10(b).\n• OR Award one mark for the formula in words: margin of safety = expected sales – break-even point (1)\n• OR one mark for the formula in numbers: 420 – 360 (1)\n(2)","levels":null}},{"q":10,"sub":"d","marks":6,"section":"B","ctx":[],"ctxb":[],"text":"Discuss the actions Kofi could take to improve the break-even point of the new shop.","qTotal":null,"ms":{"body":"• Increase haircut price – more contribution per customer; may lose price-sensitive customers\n• Reduce variable costs (supplies, products) – small saving; quality risk\n• Reduce fixed costs (smaller unit, shorter hours, one barber at first) – limits capacity\n• Context: new town, no established customer base; early losses\n• Balanced conclusion\n(6)","levels":6}},{"q":11,"sub":"a","marks":2,"section":"B","ctx":[],"ctxb":[{"t":"p","x":"Hartley Event Hire rents out marquees, tables and chairs for weddings and parties. It has traded for six years. You have been given this information about last year."},{"t":"cap","x":"Extract of financial information for Hartley Event Hire"},{"t":"grid","head":["","£"],"rows":[["Current assets","30 000"],["Current liabilities","22 000"],["Total revenue","240 000"],["Cost of sales","84 000"],["Expenses","112 000"],["Trade receivables","46 000"],["Credit sales","120 000"]]}],"text":"Calculate the current ratio. Show your workings.","qTotal":null,"ms":{"body":"Award two marks for the correct response of 1.36 : 1. Accept 1.36.\n• OR award one mark for the formula in words: current ratio = current assets ÷ current liabilities (1)\n• Accept the correct answer anywhere in the workings box. A ratio of the two numbers (e.g. 30 000:22 000) is not worth marks.\n(2)","levels":null}},{"q":11,"sub":"b","marks":3,"section":"B","ctx":[],"ctxb":[],"text":"Calculate the gross profit margin. Show your workings.","qTotal":null,"ms":{"body":"Award three marks for the correct response of 65.0%.\n• Gross profit = 240 000 – 84 000 = 156 000 (1)\n• Formula: (gross profit ÷ revenue) × 100 (1)\n• Answer 65.0% (1)\n(3)","levels":null}},{"q":11,"sub":"c","marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Calculate the trade receivable days. Show your workings.","qTotal":null,"ms":{"body":"Award two marks for the correct response of 139.9 days (accept 140).\n• OR one mark for the formula: (trade receivables ÷ credit sales) × 365 (1)\n(2)","levels":null}},{"q":11,"sub":"d","marks":3,"section":"B","ctx":[],"ctxb":[],"text":"Calculate the profit margin for the year. Show your workings.","qTotal":null,"ms":{"body":"Award three marks for the correct response of 18.3%.\n• Profit = gross profit – expenses = 156 000 – 112 000 = 44 000 (1)\n• Formula: (profit ÷ revenue) × 100 (1)\n• Answer 18.3% (1)\n(3)","levels":null}},{"q":11,"sub":"e","marks":8,"section":"B","ctx":[],"ctxb":[{"t":"p","x":"Demand is highly seasonal, with 70% of revenue between May and September. New marquees would cost £50,000."}],"text":"Analyse the limitations of ratio analysis to Hartley Event Hire in deciding whether it can afford to buy more marquees.","qTotal":null,"ms":{"body":"• Annual ratios hide seasonal fluctuations in cash and liquidity\n• Past figures may not predict demand for the new marquees\n• Non-financial factors such as weather, wedding trends and competitors not included\n• Need comparison with competitors\n• Cash flow and break-even analysis also needed\n• Focus on limitations\n(8)","levels":8}},{"q":11,"sub":"f","marks":12,"section":"B","ctx":[],"ctxb":[{"t":"p","x":"The marquees cost £50,000. A bank loan at 8.5% over five years would cost about £11,400 in interest. Leasing costs £1,150 a month for 48 months, including repairs. The business has £14,000 in the bank."}],"text":"Evaluate whether Hartley Event Hire should lease or buy the new marquees.","qTotal":null,"ms":{"body":"• Buy with loan: owns assets, can resell; interest about £11,400; repair costs; fixed repayments in quiet winter months\n• Lease: £1,150 × 48 = £55,200, no large outlay, repairs included; but pays during low-season months; no ownership\n• Context: seasonal business, only £14,000 cash\n• Alternatives: hire from other suppliers during peaks, buy second-hand\n• Justified recommendation\n(12)","levels":12}}],"minutes":120},{"id":"U3-R7","unit":3,"key":"9907","series":"RA10 practice","date":"RA10 practice paper","title":"Enzo’s Pizza · Redwood Joinery","source":"ra10","kind":"exam","total":80,"sec":{"A":28,"B":52},"items":[{"q":1,"sub":null,"marks":2,"section":"A","ctx":[],"ctxb":[],"text":"Identify two benefits of paying by contactless card.","qTotal":null,"ms":{"body":"Award one mark for each benefit identified, up to a maximum of two marks.\n• Quick / saves time (1)\n• No PIN needed for small amounts (1)\n• Reduces handling of cash (1)\n• Can be used with phones/wearables (1)\n• Hygienic – no contact (1)\n• Accept any other appropriate response.","levels":null}},{"q":2,"sub":null,"marks":2,"section":"A","ctx":[],"ctxb":[],"text":"Give two features of a student current account.","qTotal":null,"ms":{"body":"Award one mark for each feature, up to a maximum of two marks.\n• Interest-free overdraft (1)\n• No monthly fee (1)\n• Railcard/discount perks (1)\n• Overdraft reduces after graduation (1)","levels":null}},{"q":3,"sub":null,"marks":2,"section":"A","ctx":[],"ctxb":[],"text":"Explain one advantage for an individual of borrowing from a credit union.","qTotal":null,"ms":{"body":"Award one mark for an advantage and one mark for a linked development.\n• Loans are low cost / capped interest (1) so repayments are more affordable (1)\n• Not-for-profit / member-owned (1) so profits are returned to members or kept low cost (1)\n• Considers people with poor credit histories (1) giving access to borrowing that other lenders refuse (1)\n• Accept any other reasonable answer.","levels":null}},{"q":4,"sub":null,"marks":4,"section":"A","ctx":[],"ctxb":[],"text":"Explain two disadvantages for an individual of using a store card.","qTotal":null,"ms":{"body":"Award one mark for each disadvantage and one for a linked development, up to four marks.\n• High interest rate / APR (1) so unpaid balances become expensive (1)\n• Can only be used in one retailer/group (1) so limited usefulness (1)\n• Encourages overspending through offers (1) leading to debt (1)\n• Missed payments harm credit rating (1) making future borrowing harder (1)","levels":null}},{"q":5,"sub":null,"marks":6,"section":"A","ctx":[],"ctxb":[{"t":"p","x":"Sofia is 23 and works in a call centre earning £1,450 a month. Her rent and bills are £1,050. Her washing machine has broken and a replacement costs £450. She has £100 saved. A friend offers to lend her £450 for six months; a payday lender offers £450 with £135 interest for one month; her bank offers a £500 overdraft at 39.9% EAR."}],"text":"Discuss whether Sofia should borrow from her friend, use the payday loan or use her overdraft.","qTotal":null,"ms":{"body":"• Friend: no interest so cheapest; flexibility; but could damage the friendship if repayment is late; no formal agreement\n• Payday loan: £135 interest (30% in a month, an APR of several thousand per cent); repayment of £585 is more than her spare £400; risk of debt spiral\n• Overdraft: 39.9% EAR on £450 is about £15 a month; flexible; bank may charge fees if she exceeds limit\n• Context: spare income £400; need replacement quickly; modest savings\n• Judgement: friend or overdraft is much cheaper than payday loan\n(6)","levels":6}},{"q":6,"sub":null,"marks":12,"section":"A","ctx":[],"ctxb":[{"t":"p","x":"Sofia and Marco are saving £6,000 for their wedding in 18 months. They can save £300 a month and want security for their money."},{"t":"grid","head":["Option","Interest (AER)","Access","Features"],"rows":[["Cash ISA","4.1% variable","Instant","Tax-free; FSCS protected"],["18-month fixed bond","4.8% fixed","None until maturity","Minimum £1,000 lump sum"],["Regular Saver","5.5% fixed for 12 months","No withdrawals","Maximum £300 a month"],["Premium Bonds","No interest – monthly prizes","Instant","Backed by the Treasury; value may not keep up with inflation"]]}],"text":"Evaluate which option would be most suitable for Sofia and Marco.","qTotal":null,"ms":{"body":"• Cash ISA: instant access and safe; tax-free (little benefit if under the personal savings allowance); 4.1% variable\n• Fixed bond: higher rate but needs a lump sum – they save monthly so cannot deposit £1,000 at once; no access\n• Regular saver: 5.5% on regular deposits matches £300 monthly saving; but only for 12 months; no withdrawals\n• Premium Bonds: no guaranteed return; not suitable for fixed goal\n• Context: 18 months, monthly saving, low risk\n• Recommendation (regular saver then ISA, or ISA) with justification\n(12)","levels":12}},{"q":7,"sub":null,"marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Give two examples of revenue expenditure.","qTotal":null,"ms":{"body":"Award one mark for each example, up to a maximum of two marks.\n• Wages / salaries (1)\n• Rent / rates (1)\n• Utilities (1)\n• Insurance (1)\n• Marketing (1)\n• Inventory purchases (1)\n• Do not accept purchase of machinery or vehicles (capital expenditure).","levels":null}},{"q":8,"sub":null,"marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Explain one impact of leasing equipment on a small business.","qTotal":null,"ms":{"body":"Award one mark for an impact and one mark for a linked development.\n• No large initial outlay (1) so cash is available for other purposes (1)\n• The business does not own the asset (1) so cannot sell it or use it as security (1)\n• Regular lease payments (1) increase fixed costs over the long term (1)","levels":null}},{"q":9,"sub":null,"marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Give two sources of internal finance.","qTotal":null,"ms":{"body":"Award one mark for each source, up to a maximum of two marks.\n• Retained profit (1)\n• Sale of assets (1)\n• Net current assets / working capital (1)\n• Do not accept bank loan or overdraft.","levels":null}},{"q":10,"sub":"a","marks":4,"section":"B","ctx":[],"ctxb":[{"t":"p","x":"Enzo runs a pizza stall at a farmers’ market and festivals. He is thinking of opening a small pizza takeaway unit. He has estimated these costs and revenue for the first six months."},{"t":"grid","head":["Estimated cost/ revenue","Mar","Apr","May","Jun","Jul","Aug"],"rows":[["Number of sales","260","(iii)","560","650","700","720"],["Total revenue (£)","2 340","3 780","5 040","5 850","(iv)","6 480"],["Fixed costs (£)","2 800","2 800","2 800","2 800","2 800","2 800"],["Total variable costs (£)","(i)","1 344","1 792","2 080","2 240","2 304"],["Total costs (£)","(ii)","4 144","4 592","4 880","5 040","5 104"]]}],"text":"Calculate the figures missing from the table above.","qTotal":null,"ms":{"body":"Award one mark for each correct answer.\n• (i) 832\n• (ii) 3 632 (ECF) Addition of (i) + fixed costs\n• (iii) 420\n• (iv) 6 300\n(4)","levels":null}},{"q":10,"sub":"b","marks":4,"section":"B","ctx":[],"ctxb":[{"t":"p","x":"The takeaway unit has higher rent and needs extra staff, so the costs will differ from the stall."}],"text":"Calculate the break-even point per month for the new pizza stall if it has: variable costs of £3.40 per pizza; a selling price of £9.50; fixed costs of £5,200. Show your workings.","qTotal":null,"ms":{"body":"Award four marks for the correct response of 852.46 pizzas per month. Accept with or without the unit.\n• OR Award three marks for the correct formula in numbers: BEP = 5 200 / (9.50 – 3.40) (3)\n• OR Award one mark for the correct contribution of £6.10 AND one mark for the formula in words: Break-even point = fixed costs ÷ (selling price – variable cost) (2)\n(4)","levels":null}},{"q":10,"sub":"c","marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Calculate the margin of safety in the final month for the new pizza stall, which expects to sell 1 250 pizzas. Show your workings.","qTotal":null,"ms":{"body":"Award two marks for the correct response of 397.54 pizzas. Apply ECF using the break-even point from 10(b).\n• OR Award one mark for the formula in words: margin of safety = expected sales – break-even point (1)\n• OR one mark for the formula in numbers: 1 250 – 852.46 (1)\n(2)","levels":null}},{"q":10,"sub":"d","marks":6,"section":"B","ctx":[],"ctxb":[],"text":"Discuss the actions Enzo could take to improve the break-even point of the pizza takeaway.","qTotal":null,"ms":{"body":"• Raise the price – increases contribution; may reduce demand; competitors\n• Reduce variable costs – cheaper ingredients; quality risk\n• Reduce fixed costs – lower rent, fewer staff hours; limits capacity\n• Context: new location; early customers few; seasonal demand\n• Balanced conclusion\n(6)","levels":6}},{"q":11,"sub":"a","marks":2,"section":"B","ctx":[],"ctxb":[{"t":"p","x":"Redwood Joinery makes and fits kitchens and windows and has traded for seven years. You have been given the following information about last year."},{"t":"cap","x":"Extract of financial information for Redwood Joinery"},{"t":"grid","head":["","£"],"rows":[["Current assets","44 000"],["Current liabilities","40 000"],["Total revenue","310 000"],["Cost of sales","140 000"],["Expenses","132 000"],["Trade receivables","62 000"],["Credit sales","155 000"]]}],"text":"Calculate the current ratio. Show your workings.","qTotal":null,"ms":{"body":"Award two marks for the correct response of 1.1 : 1. Accept 1.1.\n• OR award one mark for the formula in words: current ratio = current assets ÷ current liabilities (1)\n• Accept the correct answer anywhere in the workings box. A ratio of the two numbers (e.g. 44 000:40 000) is not worth marks.\n(2)","levels":null}},{"q":11,"sub":"b","marks":3,"section":"B","ctx":[],"ctxb":[],"text":"Calculate the gross profit margin. Show your workings.","qTotal":null,"ms":{"body":"Award three marks for the correct response of 54.8%.\n• Gross profit = 310 000 – 140 000 = 170 000 (1)\n• Formula: (gross profit ÷ revenue) × 100 (1)\n• Answer 54.8% (1)\n(3)","levels":null}},{"q":11,"sub":"c","marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Calculate the trade receivable days. Show your workings.","qTotal":null,"ms":{"body":"Award two marks for the correct response of 146.0 days (accept 146).\n• OR one mark for the formula: (trade receivables ÷ credit sales) × 365 (1)\n(2)","levels":null}},{"q":11,"sub":"d","marks":3,"section":"B","ctx":[],"ctxb":[],"text":"Calculate the profit margin for the year. Show your workings.","qTotal":null,"ms":{"body":"Award three marks for the correct response of 12.3%.\n• Profit = gross profit – expenses = 170 000 – 132 000 = 38 000 (1)\n• Formula: (profit ÷ revenue) × 100 (1)\n• Answer 12.3% (1)\n(3)","levels":null}},{"q":11,"sub":"e","marks":8,"section":"B","ctx":[],"ctxb":[{"t":"p","x":"A larger workshop would cost £70,000 to fit out and raise rent by £1,800 a month but allow revenue to increase by 35%."}],"text":"Analyse the limitations of ratio analysis to Redwood Joinery in deciding whether it can afford a larger workshop.","qTotal":null,"ms":{"body":"• Historic ratios do not reflect new rent and fit-out costs\n• Construction demand is cyclical and depends on the economy\n• Do not include non-financial factors – order book, skills, reputation\n• Need comparison with others\n• Cash flow and break-even also required\n• Focus on limitations\n(8)","levels":8}},{"q":11,"sub":"f","marks":12,"section":"B","ctx":[],"ctxb":[{"t":"p","x":"A bank loan of £70,000 over seven years at 8% would cost about £22,000 interest in total. An investor would pay £70,000 for a 30% share of the company. Redwood has £18,000 in the bank."}],"text":"Evaluate whether Redwood Joinery should use a bank loan or sell shares to a new investor to finance the new workshop.","qTotal":null,"ms":{"body":"• Loan: owner keeps control and all profits; interest about £22,000; fixed repayments increase break-even; security needed\n• Investor: no interest; shares risk; but gives away 30% of profits and some control; dividends\n• Context: current ratio 1.1 means weak liquidity; construction cycles\n• Alternatives: partial loan, grant\n• Justified recommendation\n(12)","levels":12}}],"minutes":120},{"id":"U3-R8","unit":3,"key":"9908","series":"RA10 practice","date":"RA10 practice paper","title":"Mei’s Bubble Tea · Marlow Photography","source":"ra10","kind":"exam","total":80,"sec":{"A":28,"B":52},"items":[{"q":1,"sub":null,"marks":2,"section":"A","ctx":[],"ctxb":[],"text":"Identify two benefits of paying by contactless card.","qTotal":null,"ms":{"body":"Award one mark for each benefit identified, up to a maximum of two marks.\n• Quick / saves time (1)\n• No PIN needed for small amounts (1)\n• Reduces handling of cash (1)\n• Can be used with phones/wearables (1)\n• Hygienic – no contact (1)\n• Accept any other appropriate response.","levels":null}},{"q":2,"sub":null,"marks":2,"section":"A","ctx":[],"ctxb":[],"text":"Give two features of a student current account.","qTotal":null,"ms":{"body":"Award one mark for each feature, up to a maximum of two marks.\n• Interest-free overdraft (1)\n• No monthly fee (1)\n• Railcard/discount perks (1)\n• Overdraft reduces after graduation (1)","levels":null}},{"q":3,"sub":null,"marks":2,"section":"A","ctx":[],"ctxb":[],"text":"Explain one advantage for an individual of borrowing from a credit union.","qTotal":null,"ms":{"body":"Award one mark for an advantage and one mark for a linked development.\n• Loans are low cost / capped interest (1) so repayments are more affordable (1)\n• Not-for-profit / member-owned (1) so profits are returned to members or kept low cost (1)\n• Considers people with poor credit histories (1) giving access to borrowing that other lenders refuse (1)\n• Accept any other reasonable answer.","levels":null}},{"q":4,"sub":null,"marks":4,"section":"A","ctx":[],"ctxb":[],"text":"Explain two disadvantages for an individual of using a store card.","qTotal":null,"ms":{"body":"Award one mark for each disadvantage and one for a linked development, up to four marks.\n• High interest rate / APR (1) so unpaid balances become expensive (1)\n• Can only be used in one retailer/group (1) so limited usefulness (1)\n• Encourages overspending through offers (1) leading to debt (1)\n• Missed payments harm credit rating (1) making future borrowing harder (1)","levels":null}},{"q":5,"sub":null,"marks":6,"section":"A","ctx":[],"ctxb":[{"t":"p","x":"Kian is 19 and studying at university. He has a student account with a £1,000 interest-free overdraft and a student loan paid each term. He wants to buy a second-hand motorbike for £1,800 to travel to a part-time job. He has £300 saved. A bank offers a student credit card with a £1,000 limit at 29.9% APR. His uncle has offered to lend £1,000 interest-free."}],"text":"Discuss how Kian should finance the motorbike.","qTotal":null,"ms":{"body":"• Overdraft: interest-free so cheapest immediately; but limit £1,000 and needed for everyday spending; interest-free period ends after studies; credit file\n• Credit card: 29.9% APR is expensive; builds credit history if repaid in full; limit £1,000\n• Uncle: interest-free; flexible; may be a family obligation; informal\n• Savings: £300 reduces borrowing\n• Context: student with limited income; part-time job helps repay; ongoing costs of insurance and tax\n• Judgement: combination (savings + uncle + some overdraft) is cheapest\n(6)","levels":6}},{"q":6,"sub":null,"marks":12,"section":"A","ctx":[],"ctxb":[{"t":"p","x":"Kian also needs motorbike insurance. He is 19 and has held a licence for six months. He has compared four quotes."},{"t":"grid","head":["Insurer","Annual premium","Cover","Excess","Other"],"rows":[["LowCost Bikes","£780","Third party only","£150","No cover for theft"],["TrustMoto","£1,150","Third party, fire and theft","£250","Breakdown cover included"],["Comprehensive Plus","£1,490","Fully comprehensive","£100","Helmet and clothing cover; legal helpline"],["PayMonthly Insure","£1,320 (or £130 a month for 12 months)","Third party, fire and theft","£400","Monthly payments add interest"]]}],"text":"Evaluate which insurance policy would be most suitable for Kian.","qTotal":null,"ms":{"body":"• LowCost Bikes: cheapest at £780 but no theft cover – risk for a motorbike worth £1,800; legal minimum only\n• TrustMoto: £1,150 gives theft cover and breakdown; moderate excess £250\n• Comprehensive Plus: £1,490 gives the most cover but expensive for a student; may exceed what he can afford\n• PayMonthly: spreads cost but monthly instalments total £1,560 (£240 more); high excess\n• Context: young, new rider; high risk group; limited income; bike used for work\n• Recommendation (likely TrustMoto) with reasons\n(12)","levels":12}},{"q":7,"sub":null,"marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Give two examples of revenue expenditure.","qTotal":null,"ms":{"body":"Award one mark for each example, up to a maximum of two marks.\n• Wages / salaries (1)\n• Rent / rates (1)\n• Utilities (1)\n• Insurance (1)\n• Marketing (1)\n• Inventory purchases (1)\n• Do not accept purchase of machinery or vehicles (capital expenditure).","levels":null}},{"q":8,"sub":null,"marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Explain one impact of leasing equipment on a small business.","qTotal":null,"ms":{"body":"Award one mark for an impact and one mark for a linked development.\n• No large initial outlay (1) so cash is available for other purposes (1)\n• The business does not own the asset (1) so cannot sell it or use it as security (1)\n• Regular lease payments (1) increase fixed costs over the long term (1)","levels":null}},{"q":9,"sub":null,"marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Give two sources of internal finance.","qTotal":null,"ms":{"body":"Award one mark for each source, up to a maximum of two marks.\n• Retained profit (1)\n• Sale of assets (1)\n• Net current assets / working capital (1)\n• Do not accept bank loan or overdraft.","levels":null}},{"q":10,"sub":"a","marks":4,"section":"B","ctx":[],"ctxb":[{"t":"p","x":"Mei runs a bubble tea stall at student events. She is considering opening a kiosk in a shopping centre. She has estimated the following costs and revenue for the first six months."},{"t":"grid","head":["Estimated cost/ revenue","Jun","Jul","Aug","Sep","Oct","Nov"],"rows":[["Number of sales","500","(iii)","1 100","1 300","1 450","1 500"],["Total revenue (£)","2 250","3 825","4 950","5 850","(iv)","6 750"],["Fixed costs (£)","3 000","3 000","3 000","3 000","3 000","3 000"],["Total variable costs (£)","(i)","1 615","2 090","2 470","2 755","2 850"],["Total costs (£)","(ii)","4 615","5 090","5 470","5 755","5 850"]]}],"text":"Calculate the figures missing from the table above.","qTotal":null,"ms":{"body":"Award one mark for each correct answer.\n• (i) 950\n• (ii) 3 950 (ECF) Addition of (i) + fixed costs\n• (iii) 850\n• (iv) 6 525\n(4)","levels":null}},{"q":10,"sub":"b","marks":4,"section":"B","ctx":[],"ctxb":[{"t":"p","x":"The shopping-centre kiosk will charge higher rent and require two staff, so the fixed costs are higher than the stall."}],"text":"Calculate the break-even point per month for the new bubble tea kiosk if it has: variable costs of £2 per drink; a selling price of £5; fixed costs of £4,800. Show your workings.","qTotal":null,"ms":{"body":"Award four marks for the correct response of 1 600 drinks per month. Accept with or without the unit.\n• OR Award three marks for the correct formula in numbers: BEP = 4 800 / (5 – 2) (3)\n• OR Award one mark for the correct contribution of £3 AND one mark for the formula in words: Break-even point = fixed costs ÷ (selling price – variable cost) (2)\n(4)","levels":null}},{"q":10,"sub":"c","marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Calculate the margin of safety in the final month for the new bubble tea kiosk, which expects to sell 2 000 drinks. Show your workings.","qTotal":null,"ms":{"body":"Award two marks for the correct response of 400 drinks. Apply ECF using the break-even point from 10(b).\n• OR Award one mark for the formula in words: margin of safety = expected sales – break-even point (1)\n• OR one mark for the formula in numbers: 2 000 – 1 600 (1)\n(2)","levels":null}},{"q":10,"sub":"d","marks":6,"section":"B","ctx":[],"ctxb":[],"text":"Discuss the actions Mei could take to improve the break-even point of the kiosk.","qTotal":null,"ms":{"body":"• Raise the price per drink – higher contribution; students may be price-sensitive\n• Reduce variable costs – cheaper ingredients; quality risk\n• Reduce fixed costs – negotiate rent, reduce staff hours; may reduce service\n• Context: new site, uncertain footfall; summer v winter demand\n• Balanced conclusion\n(6)","levels":6}},{"q":11,"sub":"a","marks":2,"section":"B","ctx":[],"ctxb":[{"t":"p","x":"Marlow Photography Ltd takes wedding and portrait photographs and has been trading for four years. You have been given this information about last year."},{"t":"cap","x":"Extract of financial information for Marlow Photography Ltd"},{"t":"grid","head":["","£"],"rows":[["Current assets","19 000"],["Current liabilities","13 000"],["Total revenue","132 000"],["Cost of sales","41 000"],["Expenses","58 000"],["Trade receivables","22 000"],["Credit sales","64 000"]]}],"text":"Calculate the current ratio. Show your workings.","qTotal":null,"ms":{"body":"Award two marks for the correct response of 1.46 : 1. Accept 1.46.\n• OR award one mark for the formula in words: current ratio = current assets ÷ current liabilities (1)\n• Accept the correct answer anywhere in the workings box. A ratio of the two numbers (e.g. 19 000:13 000) is not worth marks.\n(2)","levels":null}},{"q":11,"sub":"b","marks":3,"section":"B","ctx":[],"ctxb":[],"text":"Calculate the gross profit margin. Show your workings.","qTotal":null,"ms":{"body":"Award three marks for the correct response of 68.9%.\n• Gross profit = 132 000 – 41 000 = 91 000 (1)\n• Formula: (gross profit ÷ revenue) × 100 (1)\n• Answer 68.9% (1)\n(3)","levels":null}},{"q":11,"sub":"c","marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Calculate the trade receivable days. Show your workings.","qTotal":null,"ms":{"body":"Award two marks for the correct response of 125.5 days (accept 125).\n• OR one mark for the formula: (trade receivables ÷ credit sales) × 365 (1)\n(2)","levels":null}},{"q":11,"sub":"d","marks":3,"section":"B","ctx":[],"ctxb":[],"text":"Calculate the profit margin for the year. Show your workings.","qTotal":null,"ms":{"body":"Award three marks for the correct response of 25.0%.\n• Profit = gross profit – expenses = 91 000 – 58 000 = 33 000 (1)\n• Formula: (profit ÷ revenue) × 100 (1)\n• Answer 25.0% (1)\n(3)","levels":null}},{"q":11,"sub":"e","marks":8,"section":"B","ctx":[],"ctxb":[{"t":"p","x":"The owner believes a studio would allow more portrait bookings but would bring monthly mortgage and utility costs."}],"text":"Analyse the limitations of ratio analysis to Marlow Photography Ltd in deciding whether to buy a studio.","qTotal":null,"ms":{"body":"• Ratios are based on past figures, not future studio costs\n• Limited trading history; wedding seasonality\n• Do not show non-financial factors – reputation, skills, demand for portraits\n• Need comparison with similar businesses\n• Cash flow needed for mortgage payments\n• Focus on limitations\n(8)","levels":8}},{"q":11,"sub":"f","marks":12,"section":"B","ctx":[],"ctxb":[{"t":"p","x":"Studio equipment costs £18,000. Retained profit is £12,000. A loan of £18,000 over four years at 8% would cost about £3,000 interest. Cash in the bank is £7,000."}],"text":"Evaluate whether Marlow Photography Ltd should buy equipment for the studio using retained profit or a bank loan.","qTotal":null,"ms":{"body":"• Retained profit: no interest; but reduces cash reserves and may not be enough\n• Loan: full £18,000, preserves cash; interest about £3,000; repayments increase fixed costs\n• Context: cash £7,000; seasonal income; current ratio 1.46\n• Alternatives: partial retained profit and smaller loan; leasing\n• Justified recommendation\n(12)","levels":12}}],"minutes":120},{"id":"U3-R9","unit":3,"key":"9909","series":"RA10 practice","date":"RA10 practice paper","title":"Gianna’s Ice-Cream · Summit Fitness Studio","source":"ra10","kind":"exam","total":80,"sec":{"A":28,"B":52},"items":[{"q":1,"sub":null,"marks":2,"section":"A","ctx":[],"ctxb":[],"text":"Identify two benefits of paying by contactless card.","qTotal":null,"ms":{"body":"Award one mark for each benefit identified, up to a maximum of two marks.\n• Quick / saves time (1)\n• No PIN needed for small amounts (1)\n• Reduces handling of cash (1)\n• Can be used with phones/wearables (1)\n• Hygienic – no contact (1)\n• Accept any other appropriate response.","levels":null}},{"q":2,"sub":null,"marks":2,"section":"A","ctx":[],"ctxb":[],"text":"Give two features of a student current account.","qTotal":null,"ms":{"body":"Award one mark for each feature, up to a maximum of two marks.\n• Interest-free overdraft (1)\n• No monthly fee (1)\n• Railcard/discount perks (1)\n• Overdraft reduces after graduation (1)","levels":null}},{"q":3,"sub":null,"marks":2,"section":"A","ctx":[],"ctxb":[],"text":"Explain one advantage for an individual of borrowing from a credit union.","qTotal":null,"ms":{"body":"Award one mark for an advantage and one mark for a linked development.\n• Loans are low cost / capped interest (1) so repayments are more affordable (1)\n• Not-for-profit / member-owned (1) so profits are returned to members or kept low cost (1)\n• Considers people with poor credit histories (1) giving access to borrowing that other lenders refuse (1)\n• Accept any other reasonable answer.","levels":null}},{"q":4,"sub":null,"marks":4,"section":"A","ctx":[],"ctxb":[],"text":"Explain two disadvantages for an individual of using a store card.","qTotal":null,"ms":{"body":"Award one mark for each disadvantage and one for a linked development, up to four marks.\n• High interest rate / APR (1) so unpaid balances become expensive (1)\n• Can only be used in one retailer/group (1) so limited usefulness (1)\n• Encourages overspending through offers (1) leading to debt (1)\n• Missed payments harm credit rating (1) making future borrowing harder (1)","levels":null}},{"q":5,"sub":null,"marks":6,"section":"A","ctx":[],"ctxb":[{"t":"p","x":"Tara is 38 and has just joined a company with a workplace pension. She can choose to pay 3%, 5% or 8% of her £30,000 salary into the pension. The employer matches contributions up to 5%. She has a mortgage, two children and £150 a month spare after bills."}],"text":"Discuss how much Tara should contribute to her workplace pension.","qTotal":null,"ms":{"body":"• 3% (£900 a year): lower cost but receives less employer match (3% = £900); loses part of match\n• 5% (£1,500): receives full match of £1,500 – effectively doubles contribution; costs about £125 a month before tax relief; manageable with tax relief\n• 8% (£2,400): no extra employer match above 5% but more tax relief; higher cost may not be affordable with £150 spare\n• Context: family commitments, long time until retirement (compound growth); risk of investment falls\n• Judgement: at least 5% to get the full match; higher if affordable\n(6)","levels":6}},{"q":6,"sub":null,"marks":12,"section":"A","ctx":[],"ctxb":[{"t":"p","x":"Tara’s partner Idris is 40 and has received an £8,000 bonus. He wants to invest it for at least ten years for their children’s university costs. He is willing to accept some risk but does not want to lose the money."},{"t":"grid","head":["Option","Expected return","Risk","Features"],"rows":[["Cash ISA","4.0% variable","Very low","Tax-free; instant access; FSCS protected"],["Stocks and Shares ISA (global fund)","Average 6% (not guaranteed)","Medium–high","Tax-free; value can fall as well as rise"],["Fixed-rate bond (5 years)","4.6% fixed","Very low","No access for 5 years"],["Premium Bonds","Prizes only","Very low","Instant access; no guaranteed return"]]}],"text":"Evaluate which option would be most suitable for Idris.","qTotal":null,"ms":{"body":"• Cash ISA: safe, instant, tax-free; 4% may not keep up with inflation over ten years\n• Stocks and shares ISA: higher expected return over ten years but risk of falls; suits long time horizon and moderate risk appetite\n• Fixed bond: certain return but 5 years only and inflexible beyond\n• Premium Bonds: no guaranteed return\n• Context: ten-year horizon, children’s education, some risk acceptable\n• Recommendation (e.g. stocks and shares ISA or split with cash ISA) with reasons\n(12)","levels":12}},{"q":7,"sub":null,"marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Give two examples of revenue expenditure.","qTotal":null,"ms":{"body":"Award one mark for each example, up to a maximum of two marks.\n• Wages / salaries (1)\n• Rent / rates (1)\n• Utilities (1)\n• Insurance (1)\n• Marketing (1)\n• Inventory purchases (1)\n• Do not accept purchase of machinery or vehicles (capital expenditure).","levels":null}},{"q":8,"sub":null,"marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Explain one impact of leasing equipment on a small business.","qTotal":null,"ms":{"body":"Award one mark for an impact and one mark for a linked development.\n• No large initial outlay (1) so cash is available for other purposes (1)\n• The business does not own the asset (1) so cannot sell it or use it as security (1)\n• Regular lease payments (1) increase fixed costs over the long term (1)","levels":null}},{"q":9,"sub":null,"marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Give two sources of internal finance.","qTotal":null,"ms":{"body":"Award one mark for each source, up to a maximum of two marks.\n• Retained profit (1)\n• Sale of assets (1)\n• Net current assets / working capital (1)\n• Do not accept bank loan or overdraft.","levels":null}},{"q":10,"sub":"a","marks":4,"section":"B","ctx":[],"ctxb":[{"t":"p","x":"Gianna runs an ice-cream van during the summer. She is considering opening an ice-cream parlour on the seafront. She has estimated the following costs and revenue for the first six months."},{"t":"grid","head":["Estimated cost/ revenue","Apr","May","Jun","Jul","Aug","Sep"],"rows":[["Number of sales","500","(iii)","1 300","1 700","1 800","1 600"],["Total revenue (£)","1 900","3 420","4 940","6 460","(iv)","6 080"],["Fixed costs (£)","3 400","3 400","3 400","3 400","3 400","3 400"],["Total variable costs (£)","(i)","1 080","1 560","2 040","2 160","1 920"],["Total costs (£)","(ii)","4 480","4 960","5 440","5 560","5 320"]]}],"text":"Calculate the figures missing from the table above.","qTotal":null,"ms":{"body":"Award one mark for each correct answer.\n• (i) 600\n• (ii) 4 000 (ECF) Addition of (i) + fixed costs\n• (iii) 900\n• (iv) 6 840\n(4)","levels":null}},{"q":10,"sub":"b","marks":4,"section":"B","ctx":[],"ctxb":[{"t":"p","x":"The parlour will have higher rent and need additional staff, so costs will be higher than the van."}],"text":"Calculate the break-even point per month for the new ice-cream parlour if it has: variable costs of £1.30 per cone; a selling price of £4.20; fixed costs of £5,600. Show your workings.","qTotal":null,"ms":{"body":"Award four marks for the correct response of 1,931.03 cones per month. Accept with or without the unit.\n• OR Award three marks for the correct formula in numbers: BEP = 5 600 / (4.20 – 1.30) (3)\n• OR Award one mark for the correct contribution of £2.90 AND one mark for the formula in words: Break-even point = fixed costs ÷ (selling price – variable cost) (2)\n(4)","levels":null}},{"q":10,"sub":"c","marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Calculate the margin of safety in the final month for the new ice-cream parlour, which expects to sell 2 600 cones. Show your workings.","qTotal":null,"ms":{"body":"Award two marks for the correct response of 668.97 cones. Apply ECF using the break-even point from 10(b).\n• OR Award one mark for the formula in words: margin of safety = expected sales – break-even point (1)\n• OR one mark for the formula in numbers: 2 600 – 1,931.03 (1)\n(2)","levels":null}},{"q":10,"sub":"d","marks":6,"section":"B","ctx":[],"ctxb":[],"text":"Discuss the actions Gianna could take to improve the break-even point of the parlour.","qTotal":null,"ms":{"body":"• Raise prices – higher contribution; may reduce demand if competitors are cheaper\n• Reduce variable costs – supplier discounts; quality concerns\n• Reduce fixed costs – shorter season or hours; lower capacity\n• Context: seasonal demand; parlour closed in winter; weather risk\n• Balanced conclusion\n(6)","levels":6}},{"q":11,"sub":"a","marks":2,"section":"B","ctx":[],"ctxb":[{"t":"p","x":"Summit Fitness Studio runs classes and personal training and has traded for four years. You have been given the following information about last year."},{"t":"cap","x":"Extract of financial information for Summit Fitness Studio"},{"t":"grid","head":["","£"],"rows":[["Current assets","27 000"],["Current liabilities","18 000"],["Total revenue","190 000"],["Cost of sales","52 000"],["Expenses","98 000"],["Trade receivables","15 000"],["Credit sales","80 000"]]}],"text":"Calculate the current ratio. Show your workings.","qTotal":null,"ms":{"body":"Award two marks for the correct response of 1.5 : 1. Accept 1.5.\n• OR award one mark for the formula in words: current ratio = current assets ÷ current liabilities (1)\n• Accept the correct answer anywhere in the workings box. A ratio of the two numbers (e.g. 27 000:18 000) is not worth marks.\n(2)","levels":null}},{"q":11,"sub":"b","marks":3,"section":"B","ctx":[],"ctxb":[],"text":"Calculate the gross profit margin. Show your workings.","qTotal":null,"ms":{"body":"Award three marks for the correct response of 72.6%.\n• Gross profit = 190 000 – 52 000 = 138 000 (1)\n• Formula: (gross profit ÷ revenue) × 100 (1)\n• Answer 72.6% (1)\n(3)","levels":null}},{"q":11,"sub":"c","marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Calculate the trade receivable days. Show your workings.","qTotal":null,"ms":{"body":"Award two marks for the correct response of 68.4 days (accept 68).\n• OR one mark for the formula: (trade receivables ÷ credit sales) × 365 (1)\n(2)","levels":null}},{"q":11,"sub":"d","marks":3,"section":"B","ctx":[],"ctxb":[],"text":"Calculate the profit margin for the year. Show your workings.","qTotal":null,"ms":{"body":"Award three marks for the correct response of 21.1%.\n• Profit = gross profit – expenses = 138 000 – 98 000 = 40 000 (1)\n• Formula: (profit ÷ revenue) × 100 (1)\n• Answer 21.1% (1)\n(3)","levels":null}},{"q":11,"sub":"e","marks":8,"section":"B","ctx":[],"ctxb":[{"t":"p","x":"A second studio would cost £60,000 to fit out and would need a manager, but the owner expects membership to rise by 60%."}],"text":"Analyse the limitations of ratio analysis to Summit Fitness Studio in deciding whether it can afford to open a second studio.","qTotal":null,"ms":{"body":"• Ratios are historical and do not take account of fit-out costs and the manager\n• Gyms have high fixed costs; membership cancellation rates change profits\n• Non-financial factors – location, competitors, reputation\n• Need comparison with other studios\n• Cash flow forecast and break-even needed\n• Focus on limitations\n(8)","levels":8}},{"q":11,"sub":"f","marks":12,"section":"B","ctx":[],"ctxb":[{"t":"p","x":"The second studio needs £60,000. A bank loan at 8.5% over five years would cost about £13,500 in interest. A crowd-funding campaign would raise £60,000 if successful by offering members lifetime discounts and a share of profits. The studio has £10,000 in the bank."}],"text":"Evaluate whether Summit Fitness Studio should finance the second studio with a bank loan or crowd funding.","qTotal":null,"ms":{"body":"• Bank loan: certain if approved; interest £13,500; repayments increase fixed costs; may need security\n• Crowd funding: builds community and no interest; but may fail to reach target; discounts and profit share reduce future income; time and marketing costs\n• Context: small cash balance; loyal members; membership business\n• Alternatives: smaller studio, leasing equipment, partner\n• Justified recommendation\n(12)","levels":12}}],"minutes":120},{"id":"U3-R10","unit":3,"key":"9910","series":"RA10 practice","date":"RA10 practice paper","title":"Mina’s Flowers · Eastgate Garage","source":"ra10","kind":"exam","total":80,"sec":{"A":28,"B":52},"items":[{"q":1,"sub":null,"marks":2,"section":"A","ctx":[],"ctxb":[],"text":"Identify two benefits of paying by contactless card.","qTotal":null,"ms":{"body":"Award one mark for each benefit identified, up to a maximum of two marks.\n• Quick / saves time (1)\n• No PIN needed for small amounts (1)\n• Reduces handling of cash (1)\n• Can be used with phones/wearables (1)\n• Hygienic – no contact (1)\n• Accept any other appropriate response.","levels":null}},{"q":2,"sub":null,"marks":2,"section":"A","ctx":[],"ctxb":[],"text":"Give two features of a student current account.","qTotal":null,"ms":{"body":"Award one mark for each feature, up to a maximum of two marks.\n• Interest-free overdraft (1)\n• No monthly fee (1)\n• Railcard/discount perks (1)\n• Overdraft reduces after graduation (1)","levels":null}},{"q":3,"sub":null,"marks":2,"section":"A","ctx":[],"ctxb":[],"text":"Explain one advantage for an individual of borrowing from a credit union.","qTotal":null,"ms":{"body":"Award one mark for an advantage and one mark for a linked development.\n• Loans are low cost / capped interest (1) so repayments are more affordable (1)\n• Not-for-profit / member-owned (1) so profits are returned to members or kept low cost (1)\n• Considers people with poor credit histories (1) giving access to borrowing that other lenders refuse (1)\n• Accept any other reasonable answer.","levels":null}},{"q":4,"sub":null,"marks":4,"section":"A","ctx":[],"ctxb":[],"text":"Explain two disadvantages for an individual of using a store card.","qTotal":null,"ms":{"body":"Award one mark for each disadvantage and one for a linked development, up to four marks.\n• High interest rate / APR (1) so unpaid balances become expensive (1)\n• Can only be used in one retailer/group (1) so limited usefulness (1)\n• Encourages overspending through offers (1) leading to debt (1)\n• Missed payments harm credit rating (1) making future borrowing harder (1)","levels":null}},{"q":5,"sub":null,"marks":6,"section":"A","ctx":[],"ctxb":[{"t":"p","x":"Ibrahim is 52 and has four debts: a credit card (£3,200 at 22.9% APR), a store card (£1,100 at 29.9% APR), a personal loan (£2,400 at 11% APR) and an overdraft (£800 at 39.9% EAR). His total monthly payments are £420. A bank offers a debt-consolidation loan of £7,500 at 12.9% APR over five years with payments of £170 a month."}],"text":"Discuss whether Ibrahim should take out the debt-consolidation loan.","qTotal":null,"ms":{"body":"• For: one payment instead of four; lower monthly payments (£170 v £420) free money; average interest rate falls because the 22.9% to 39.9% debts are replaced by 12.9%; fixed term\n• Against: total repaid over five years may be higher (£10,200 v shorter debts); the loan may include fees; he may be tempted to run up the cleared cards again; secured loans risk his home\n• Context: age 52, has four debts; wants to reduce payments; credit rating\n• Judgement: consolidation can help if he stops using credit and keeps payments high\n(6)","levels":6}},{"q":6,"sub":null,"marks":12,"section":"A","ctx":[],"ctxb":[{"t":"p","x":"Ibrahim has also received a £10,000 inheritance. He wants to use some of it to repay debts and save the rest for retirement in 12 years."},{"t":"grid","head":["Option","Return","Risk","Features"],"rows":[["Repay the 29.9% store card and 39.9% overdraft","Saves interest equivalent to a return of 29.9%–39.9%","None","Reduces debts by £1,900"],["Cash ISA","4.1% variable","Very low","Tax-free; instant access"],["Workplace pension top-up","Employer match plus tax relief","Medium (investments)","Not accessible until 57 or later"],["Premium Bonds","Prizes only","Very low","Instant access; no guaranteed return"]]}],"text":"Evaluate how Ibrahim should use the £10,000 inheritance.","qTotal":null,"ms":{"body":"• Repaying expensive debt: guaranteed saving far above any savings rate; removes high interest on £1,900\n• Pay off more debt (credit card 22.9%) – the risk-free “return” is higher than any saving account\n• Cash ISA: safe for emergency fund but 4.1% is much lower than debt interest\n• Pension: tax relief and employer match; long time horizon of 12 years; locked in\n• Premium Bonds: no guaranteed return\n• Context: debts, 12 years to retirement; balanced recommendation, e.g. repay high-interest debts first, keep a small emergency fund, and add to the pension\n(12)","levels":12}},{"q":7,"sub":null,"marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Give two examples of revenue expenditure.","qTotal":null,"ms":{"body":"Award one mark for each example, up to a maximum of two marks.\n• Wages / salaries (1)\n• Rent / rates (1)\n• Utilities (1)\n• Insurance (1)\n• Marketing (1)\n• Inventory purchases (1)\n• Do not accept purchase of machinery or vehicles (capital expenditure).","levels":null}},{"q":8,"sub":null,"marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Explain one impact of leasing equipment on a small business.","qTotal":null,"ms":{"body":"Award one mark for an impact and one mark for a linked development.\n• No large initial outlay (1) so cash is available for other purposes (1)\n• The business does not own the asset (1) so cannot sell it or use it as security (1)\n• Regular lease payments (1) increase fixed costs over the long term (1)","levels":null}},{"q":9,"sub":null,"marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Give two sources of internal finance.","qTotal":null,"ms":{"body":"Award one mark for each source, up to a maximum of two marks.\n• Retained profit (1)\n• Sale of assets (1)\n• Net current assets / working capital (1)\n• Do not accept bank loan or overdraft.","levels":null}},{"q":10,"sub":"a","marks":4,"section":"B","ctx":[],"ctxb":[{"t":"p","x":"Mina runs an online flower business from home. She is considering opening a florist kiosk in a hospital foyer. She has estimated the following costs and revenue for the first six months."},{"t":"grid","head":["Estimated cost/ revenue","Jan","Feb","Mar","Apr","May","Jun"],"rows":[["Number of sales","140","(iii)","300","330","360","380"],["Total revenue (£)","3 080","5 060","6 600","7 260","(iv)","8 360"],["Fixed costs (£)","2 900","2 900","2 900","2 900","2 900","2 900"],["Total variable costs (£)","(i)","1 610","2 100","2 310","2 520","2 660"],["Total costs (£)","(ii)","4 510","5 000","5 210","5 420","5 560"]]}],"text":"Calculate the figures missing from the table above.","qTotal":null,"ms":{"body":"Award one mark for each correct answer.\n• (i) 980\n• (ii) 3 880 (ECF) Addition of (i) + fixed costs\n• (iii) 230\n• (iv) 7 920\n(4)","levels":null}},{"q":10,"sub":"b","marks":4,"section":"B","ctx":[],"ctxb":[{"t":"p","x":"The hospital kiosk charges a monthly licence fee and requires a part-time assistant, so costs are higher than those of her online business."}],"text":"Calculate the break-even point per month for the new florist kiosk if it has: variable costs of £8 per bouquet; a selling price of £24; fixed costs of £4,800. Show your workings.","qTotal":null,"ms":{"body":"Award four marks for the correct response of 300 bouquets per month. Accept with or without the unit.\n• OR Award three marks for the correct formula in numbers: BEP = 4 800 / (24 – 8) (3)\n• OR Award one mark for the correct contribution of £16 AND one mark for the formula in words: Break-even point = fixed costs ÷ (selling price – variable cost) (2)\n(4)","levels":null}},{"q":10,"sub":"c","marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Calculate the margin of safety in the final month for the new florist kiosk, which expects to sell 420 bouquets. Show your workings.","qTotal":null,"ms":{"body":"Award two marks for the correct response of 120 bouquets. Apply ECF using the break-even point from 10(b).\n• OR Award one mark for the formula in words: margin of safety = expected sales – break-even point (1)\n• OR one mark for the formula in numbers: 420 – 300 (1)\n(2)","levels":null}},{"q":10,"sub":"d","marks":6,"section":"B","ctx":[],"ctxb":[],"text":"Discuss the actions Mina could take to improve the break-even point of the kiosk.","qTotal":null,"ms":{"body":"• Increase price – higher contribution; customers visiting a hospital are less price-sensitive, but cheaper supermarket bouquets exist\n• Reduce variable costs – cheaper stems, less wastage; quality and freshness matter\n• Reduce fixed costs – negotiate the licence, reduce hours; may reduce sales\n• Context: new site; uncertain footfall; wastage of unsold flowers\n• Balanced conclusion\n(6)","levels":6}},{"q":11,"sub":"a","marks":2,"section":"B","ctx":[],"ctxb":[{"t":"p","x":"Eastgate Garage Ltd services and repairs cars and has traded for nine years. You have been given the following information about last year."},{"t":"cap","x":"Extract of financial information for Eastgate Garage Ltd"},{"t":"grid","head":["","£"],"rows":[["Current assets","52 000"],["Current liabilities","46 000"],["Total revenue","380 000"],["Cost of sales","151 000"],["Expenses","170 000"],["Trade receivables","21 000"],["Credit sales","96 000"]]}],"text":"Calculate the current ratio. Show your workings.","qTotal":null,"ms":{"body":"Award two marks for the correct response of 1.13 : 1. Accept 1.13.\n• OR award one mark for the formula in words: current ratio = current assets ÷ current liabilities (1)\n• Accept the correct answer anywhere in the workings box. A ratio of the two numbers (e.g. 52 000:46 000) is not worth marks.\n(2)","levels":null}},{"q":11,"sub":"b","marks":3,"section":"B","ctx":[],"ctxb":[],"text":"Calculate the gross profit margin. Show your workings.","qTotal":null,"ms":{"body":"Award three marks for the correct response of 60.3%.\n• Gross profit = 380 000 – 151 000 = 229 000 (1)\n• Formula: (gross profit ÷ revenue) × 100 (1)\n• Answer 60.3% (1)\n(3)","levels":null}},{"q":11,"sub":"c","marks":2,"section":"B","ctx":[],"ctxb":[],"text":"Calculate the trade receivable days. Show your workings.","qTotal":null,"ms":{"body":"Award two marks for the correct response of 79.8 days (accept 80).\n• OR one mark for the formula: (trade receivables ÷ credit sales) × 365 (1)\n(2)","levels":null}},{"q":11,"sub":"d","marks":3,"section":"B","ctx":[],"ctxb":[],"text":"Calculate the profit margin for the year. Show your workings.","qTotal":null,"ms":{"body":"Award three marks for the correct response of 15.5%.\n• Profit = gross profit – expenses = 229 000 – 170 000 = 59 000 (1)\n• Formula: (profit ÷ revenue) × 100 (1)\n• Answer 15.5% (1)\n(3)","levels":null}},{"q":11,"sub":"e","marks":8,"section":"B","ctx":[],"ctxb":[{"t":"p","x":"The garage would need £45,000 of equipment and training. The owner expects more customers with electric vehicles, but this is uncertain."}],"text":"Analyse the limitations of ratio analysis to Eastgate Garage Ltd in deciding whether it can afford to invest in electric-vehicle repair equipment.","qTotal":null,"ms":{"body":"• Ratios use past data; they do not show future demand for EV repairs\n• Do not take account of training costs or changes in technology\n• Non-financial: skills, reputation, trends in EV adoption\n• Need comparison with similar garages\n• Cash flow and investment appraisal needed\n• Focus on limitations\n(8)","levels":8}},{"q":11,"sub":"f","marks":12,"section":"B","ctx":[],"ctxb":[{"t":"p","x":"A bank loan of £45,000 at 8.5% over six years would cost about £12,000 interest. Leasing costs £820 a month for 60 months, including upgrades. The garage has £16,000 in the bank."}],"text":"Evaluate whether Eastgate Garage Ltd should buy the equipment using a bank loan or by leasing it.","qTotal":null,"ms":{"body":"• Loan: owns equipment, which may become outdated; interest about £12,000; fixed repayments\n• Lease: £820 × 60 = £49,200; no large outlay; upgrades included, important for changing technology; never owns equipment\n• Context: technology changes quickly; moderate cash\n• Alternatives: buy used equipment, share equipment with another garage\n• Justified recommendation\n(12)","levels":12}}],"minutes":120}];
